window.SG={"파트":["반응식","물질·성상","계산","시설·법령"],"문항":[{"id":"2019-1-01","y":2019,"r":1,"n":1,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"다음 할로젠화합물 소화설비의 방사압력을 쓰시오.\n가. 하론 2402\n나. 하론 1211","a":"가. 0.1MPa 이상\n나. 0.2MPa 이상","h":"할로젠화합물 소화설비 방사압력은 하론 2402가 0.1MPa 이상, 하론 1211이 0.2MPa 이상이다. 하론 1301은 0.9MPa 이상으로 셋 중 가장 높다. 세 값을 한 줄로 묶어 두면 서로 바뀌지 않는다.","t":"kan","칸":[{"a":"0.1MPa","syn":["0.1","0.1 MPa","0.1메가파스칼"],"l":"가"},{"a":"0.2MPa","syn":["0.2","0.2 MPa","0.2메가파스칼"],"l":"나"}],"순서무관":false},{"id":"2019-1-02","y":2019,"r":1,"n":2,"p":"반응식","kw":"물과 반응","pt":5,"q":"인화알루미늄과 물의 화학반응식을 쓰시오.","a":"AlP + 3H2O → Al(OH)3 + PH3","h":"인화알루미늄은 물과 반응해 수산화알루미늄과 포스핀(PH3)을 낸다. Al과 P가 각각 1개씩이라 H2O 계수만 맞추면 되고, 수소는 양쪽 6개로 일치한다. 인화칼슘은 같은 방식으로 포스핀과 수산화칼슘이 나온다고 함께 정리한다.","t":"kan","칸":[{"a":"AlP+3H2O→Al(OH)3+PH3","syn":["AlP+3H2O->Al(OH)3+PH3","AlP+3H2O=Al(OH)3+PH3","AlP+3H2O⟶Al(OH)3+PH3","AlP+3H2O→PH3+Al(OH)3","AlP+3H2O->PH3+Al(OH)3"]}],"순서무관":false},{"id":"2019-1-03","y":2019,"r":1,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제5류 위험물 중 트라이나이트로톨루엔(TNT)에 대한 다음 물음에 답하시오.\n가. 제조방법\n나. 구조식","a":"가. 톨루엔에 진한 질산과 진한 황산의 혼산을 작용시켜 나이트로화한다.\n나. 벤젠고리의 2, 4, 6번 자리에 NO2 세 개, 1번 자리에 CH3 한 개가 붙은 구조","h":"TNT는 톨루엔의 수소 세 개를 NO2로 바꾼 물질이다. 반응식은 C6H5CH3 + 3HNO3 → C6H2(NO2)3CH3 + 3H2O이고, 황산은 탈수제로 작용한다. 페놀에 같은 방식으로 반응시키면 피크린산이 된다는 점도 같이 알아 둔다.","ai":"2019-1-03_a.svg","t":"kan","칸":[{"a":"톨루엔에 진한 질산과 진한 황산의 혼산을 작용시켜 나이트로화한다","k":[["톨루엔","toluene","메틸벤젠"],["질산","황산","혼산","나이트로","니트로","HNO3","H2SO4"]],"l":"가"}],"순서무관":false},{"id":"2019-1-04","y":2019,"r":1,"n":4,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"위험물안전관리법령상 옥외탱크저장소 보유공지 기준에 알맞게 빈칸에 들어갈 값을 쓰시오.\n지정수량의 500배 이하 → ( 가 ) 이상\n지정수량의 500배 초과 1,000배 이하 → ( 나 ) 이상\n지정수량의 1,000배 초과 2,000배 이하 → ( 다 ) 이상\n지정수량의 2,000배 초과 3,000배 이하 → ( 라 ) 이상\n지정수량의 3,000배 초과 4,000배 이하 → ( 마 ) 이상","a":"가. 3m\n나. 5m\n다. 9m\n라. 12m\n마. 15m","h":"옥외탱크저장소 보유공지는 지정수량 500배 이하 3m, 1,000배 이하 5m, 2,000배 이하 9m, 3,000배 이하 12m, 4,000배 이하 15m 이상이다. 배수 구간이 한 칸씩 올라갈 때 공지가 커진다. 4,000배를 넘는 구간은 이 문제 범위 밖이다.","t":"kan","칸":[{"a":"3m","syn":["3","3 m","3미터"],"l":"가"},{"a":"5m","syn":["5","5 m","5미터"],"l":"나"},{"a":"9m","syn":["9","9 m","9미터"],"l":"다"},{"a":"12m","syn":["12","12 m","12미터"],"l":"라"},{"a":"15m","syn":["15","15 m","15미터"],"l":"마"}],"순서무관":false},{"id":"2019-1-05","y":2019,"r":1,"n":5,"p":"반응식","kw":"연소 반응","pt":5,"q":"황린의 완전연소 반응식을 쓰시오.","a":"P4 + 5O2 → 2P2O5","h":"황린이 완전연소하면 오산화인(P2O5)이 생긴다. P가 4개이므로 P2O5 계수는 2, 산소는 O 10개가 필요해 O2 계수는 5가 된다. 불완전연소와 구별하려면 생성물이 P2O5인지 먼저 확인한다.","t":"kan","칸":[{"a":"P4+5O2→2P2O5","syn":["P4+5O2->2P2O5","P4+5O2=2P2O5","4P+5O2→2P2O5","4P+5O2->2P2O5","4P+5O2=2P2O5","4P+5O2→P4O10","P4+5O2→P4O10"]}],"순서무관":false},{"id":"2019-1-06","y":2019,"r":1,"n":6,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"에틸렌과 산소를 CuCl2 촉매하에서 생성된 물질로 인화점이 -38℃, 비점이 21℃, 연소범위가 4.1~57%인 특수인화물에 대하여 다음 물음에 답하시오 (단, 공기의 평균분자량은 약 29이다).\n가. 화학식\n나. 증기비중","a":"가. CH3CHO\n나. 44/29 = 1.52","h":"에틸렌을 CuCl2 촉매로 산화시켜 얻고 연소범위가 4.1~57%인 특수인화물은 아세트알데하이드다. 분자량은 12+3+12+1+16 = 44이고 증기비중은 44/29 = 1.517이므로 1.52이다. 이 값을 이황화탄소·다이에틸에터의 증기비중과 섞지 않도록 한다.","t":"kan","칸":[{"a":"CH3CHO","syn":["아세트알데하이드","아세트알데히드","아세트알데이드","C2H4O","CH3CH=O","acetaldehyde"],"l":"가"},{"a":"1.52","e":0.01,"l":"나"}],"순서무관":false},{"id":"2019-1-07","y":2019,"r":1,"n":7,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"질산암모늄 800g이 열분해되는 경우 발생기체의 부피(L)는 표준상태에서 전부 얼마인지 구하시오.","a":"① NH4NO3 800g, 분자량 80, 표준상태\n② 2NH4NO3 → 2N2 + O2 + 4H2O (2몰에서 기체 7몰)\n③ V = (800×0.082×273)/(1×80) × 7/2\n④ 783.51L","h":"질산암모늄 2몰이 분해되면 N2 2몰, O2 1몰, 수증기 4몰이 나오므로 기체는 모두 7몰이다. 문제가 '전부'라고 했으니 물도 기체로 합산한다. 계수비 7/2를 곱하는 부분이 가장 자주 빠진다.","tp":"W01","t":"calc","e":2,"ka":"783.51"},{"id":"2019-1-08","y":2019,"r":1,"n":8,"p":"계산","kw":"지정수량 배수","pt":5,"q":"황 100kg, 인화칼슘 600kg, 알루미늄분 500kg의 지정수량 배수의 합을 구하시오.","a":"① 황 100kg(지정수량 100kg), 인화칼슘 600kg(300kg), 알루미늄분 500kg(500kg)\n② 배수 = 저장량/지정수량의 합\n③ 100/100 + 600/300 + 500/500 = 1 + 2 + 1\n④ 4배","h":"각 품명의 지정수량으로 저장량을 나눈 값을 모두 더한다. 인화칼슘은 제3류 금속인화합물이라 300kg, 알루미늄분은 제2류 금속분이라 500kg이다. 품명이 어느 유별인지 먼저 확인해야 지정수량이 맞게 잡힌다.","t":"calc","ka":"4"},{"id":"2019-1-09","y":2019,"r":1,"n":9,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제4류 위험물로서 흡입 시 시신경을 마비시키는 것으로 인화점 11℃, 발화점 464℃인 위험물에 대하여 다음 물음에 답하시오.\n가. 위험물의 명칭\n나. 지정수량","a":"가. 메틸알코올\n나. 400L","h":"시신경을 해치고 인화점 11℃, 발화점 464℃인 제4류 위험물은 메틸알코올이다. 알코올류라서 지정수량은 400L이다. 같은 알코올류인 에틸알코올과는 독성이 다르다는 점으로 구별한다.","t":"kan","칸":[{"a":"메틸알코올","syn":["메탄올","메틸알콜","메틸 알코올","메틸 알콜","CH3OH","methanol"],"l":"가"},{"a":"400","syn":["400L","400 L","400리터"],"l":"나"}],"순서무관":false},{"id":"2019-1-10","y":2019,"r":1,"n":10,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"다음 위험물을 옥외저장탱크 중 압력탱크 외의 탱크에 저장할 때의 온도를 쓰시오.\n가. 다이에틸에터\n나. 아세트알데하이드\n다. 산화프로필렌","a":"가. 30℃ 이하\n나. 15℃ 이하\n다. 30℃ 이하","h":"압력탱크가 아닌 탱크에서는 산화프로필렌과 다이에틸에터가 30℃ 이하, 아세트알데하이드가 15℃ 이하다. 압력탱크에 넣으면 아세트알데하이드와 다이에틸에터 모두 40℃ 이하로 올라간다. 15℃ 이하는 아세트알데하이드 하나뿐이라고 기억한다.","t":"kan","칸":[{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"가"},{"a":"15℃","syn":["15","15도","15℃ 이하","15도 이하"],"l":"나"},{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"다"}],"순서무관":false},{"id":"2019-1-11","y":2019,"r":1,"n":11,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"제6류 위험물과 혼재가 가능한 위험물은 제 몇 류 위험물인지 쓰시오 (단, 지정수량 10배의 위험물을 혼재하는 경우이다).","a":"제1류 위험물","h":"지정수량 1/10을 넘는 경우 제6류는 제1류하고만 같이 실을 수 있다. 혼재 표에서 4류는 2·3·5류, 5류는 2·4류, 6류는 1류와 짝이 된다. 이 표를 외워 두면 혼재 문제는 대부분 풀린다.","t":"word","syn":["1류","제1류 위험물","1류 위험물","제 1류","제1류위험물","제일류"],"ka":"제1류"},{"id":"2019-1-12","y":2019,"r":1,"n":12,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"황화인의 종류를 화학식으로 모두 쓰시오.","a":"P4S3, P2S5, P4S7","h":"황화인은 삼황화인(P4S3), 오황화인(P2S5), 칠황화인(P4S7) 세 가지이며 제2류 위험물로 지정수량은 100kg이다. 인과 황의 원자 수를 표기 그대로 외워야 하고, 삼황화인은 P4S3으로 쓴다는 점을 놓치기 쉽다.","t":"kan","칸":[{"a":"P4S3","syn":["삼황화사인","삼황화인","삼황화4인"]},{"a":"P2S5","syn":["오황화이인","오황화인","오황화2인"]},{"a":"P4S7","syn":["칠황화사인","칠황화인","칠황화4인"]}],"순서무관":true,"nc":3},{"id":"2019-1-13","y":2019,"r":1,"n":13,"p":"반응식","kw":"물과 반응","pt":5,"q":"탄화칼슘에 대하여 다음 물음에 답하시오.\n가. 물과의 반응식을 쓰시오.\n나. 물과의 반응 시 생성되는 기체의 완전연소 반응식을 쓰시오.","a":"가. CaC2 + 2H2O → Ca(OH)2 + C2H2\n나. 2C2H2 + 5O2 → 4CO2 + 2H2O","h":"탄화칼슘은 물과 만나 수산화칼슘과 아세틸렌을 내고, 이 아세틸렌이 연소하면 이산화탄소와 물이 된다. 탄화알루미늄은 물과 반응해 메테인이 나오므로 아세틸렌과 구별한다. 아세틸렌 연소식은 산소가 2.5몰 필요해 양변에 2를 곱한다.","t":"kan","칸":[{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"가"},{"a":"2C2H2+5O2→4CO2+2H2O","syn":["2C2H2+5O2->4CO2+2H2O","2C2H2+5O2=4CO2+2H2O","C2H2+5/2O2→2CO2+H2O","C2H2+5/2O2->2CO2+H2O","C2H2+2.5O2→2CO2+H2O"],"l":"나"}],"순서무관":false},{"id":"2019-2-01","y":2019,"r":2,"n":1,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 지정수량을 쓰시오.\n가. 중유\n나. 경유\n다. 다이에틸에터\n라. 아세톤","a":"가. 2,000L\n나. 1,000L\n다. 50L\n라. 400L","h":"중유는 제3석유류 비수용성이라 2,000L, 경유는 제2석유류 비수용성이라 1,000L이다. 다이에틸에터는 특수인화물 50L, 아세톤은 제1석유류 수용성 400L다. 같은 석유류라도 수용성이면 지정수량이 두 배가 된다.","t":"kan","칸":[{"a":"2000","syn":["2,000","2000L","2,000L","2000리터","2,000 L"],"l":"가"},{"a":"1000","syn":["1,000","1000L","1,000L","1000리터","1,000 L"],"l":"나"},{"a":"50","syn":["50L","50 L","50리터"],"l":"다"},{"a":"400","syn":["400L","400 L","400리터"],"l":"라"}],"순서무관":false},{"id":"2019-2-02","y":2019,"r":2,"n":2,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"20kg의 황린이 표준상태에서 완전연소할 때 필요한 공기의 부피는 몇 m3인가? (단, 공기 중 산소의 양은 21vol%, 황린 분자량은 124이다)","a":"① P4 20kg, 분자량 124, 표준상태, 공기 중 산소 21%\n② P4 + 5O2 → 2P2O5\n③ V = (20×0.082×273)/(1×124) × 5 ÷ 0.21\n④ 85.97m3","h":"황린 1kmol을 태우는 데 산소 5kmol이 든다. 이렇게 구한 산소 부피를 21%로 나눠야 공기 부피가 된다. 산소 부피에서 멈추면 틀린다.","tp":"W01","t":"calc","e":1,"ka":"85.97"},{"id":"2019-2-03","y":2019,"r":2,"n":3,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에 따른 고인화점위험물의 정의를 쓰시오.","a":"인화점이 100℃ 이상인 제4류 위험물","h":"고인화점위험물은 제4류 위험물 가운데 인화점이 100℃ 이상인 것을 말한다. 제4류가 아닌 위험물에는 쓰지 않는 용어다.","t":"kan","칸":[{"a":"인화점이 100℃ 이상인 제4류 위험물","k":[["100"],["제4류","4류","인화성액체"]]}],"순서무관":false},{"id":"2019-2-04","y":2019,"r":2,"n":4,"p":"반응식","kw":"연소 반응","pt":5,"q":"트라이에틸알루미늄의 완전연소 반응식을 쓰시오.","a":"2(C2H5)3Al + 21O2 → 12CO2 + 15H2O + Al2O3","h":"트라이에틸알루미늄이 타면 이산화탄소, 물, 산화알루미늄이 생긴다. 탄소는 6개씩, 수소는 15개씩이라 1몰 기준 계수가 분수가 되므로 양변에 2를 곱한다. 계수를 맞춘 뒤 산소 원자 수가 42개로 일치하는지 확인한다.","t":"kan","칸":[{"a":"2(C2H5)3Al+21O2→12CO2+15H2O+Al2O3","syn":["2(C2H5)3Al+21O2->12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2=12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2→Al2O3+12CO2+15H2O","2(C2H5)3Al+21O2->Al2O3+12CO2+15H2O"]}],"순서무관":false},{"id":"2019-2-05","y":2019,"r":2,"n":5,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"제4류 위험물 저장량이 지정수량의 1/10 초과일 때 혼재 불가능한 위험물을 모두 쓰시오.","a":"제1류 위험물, 제6류 위험물","h":"제4류는 2류·3류·5류와 혼재할 수 있으므로 혼재할 수 없는 것은 1류와 6류다. 문제가 불가능한 쪽을 물으면 가능한 쪽을 먼저 적고 나머지를 고르면 된다.","t":"kan","칸":[{"a":"제1류","syn":["1류","제1류 위험물","1류 위험물","제 1류","제일류"]},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류","제육류"]}],"순서무관":true},{"id":"2019-2-06","y":2019,"r":2,"n":6,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"옥내저장소에서 위험물을 저장하는 경우이다. 각 물음에 답을 쓰시오.\n가. 기계에 의하여 하역하는 구조로 된 용기만을 겹쳐 쌓는 경우 몇 m를 초과하지 못하는가?\n나. 제4류 위험물 중 제3석유류를 수납하는 용기만을 겹쳐 쌓는 경우 몇 m를 초과하지 못하는가?\n다. 제4류 위험물 중 동식물유류를 수납하는 용기만을 겹쳐 쌓는 경우 몇 m를 초과하지 못하는가?","a":"가. 6m\n나. 4m\n다. 4m","h":"옥내저장소 용기 적재 높이는 기계 하역 구조 6m, 제3석유류·제4석유류·동식물유류 4m, 그 밖의 경우 3m 이하다. 제3석유류와 동식물유류가 같은 4m 칸에 들어간다.","t":"kan","칸":[{"a":"6","syn":["6m","6 m","6미터"],"l":"가"},{"a":"4","syn":["4m","4 m","4미터"],"l":"나"},{"a":"4","syn":["4m","4 m","4미터"],"l":"다"}],"순서무관":false},{"id":"2019-2-07","y":2019,"r":2,"n":7,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제4류 위험물 중 위험등급이 II등급에 해당하는 위험물의 품명 2가지를 쓰시오.","a":"제1석유류, 알코올류","h":"제4류 위험물 중 특수인화물은 I등급, 제1석유류와 알코올류는 II등급, 제2·3·4석유류와 동식물유류는 III등급이다. 인화점이 낮은 쪽일수록 등급이 높다고 보면 된다.","t":"kan","칸":[{"a":"제1석유류","syn":["1석유류","제 1석유류","제일석유류"]},{"a":"알코올류","syn":["알콜류","알코올","알콜"]}],"순서무관":true},{"id":"2019-2-08","y":2019,"r":2,"n":8,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"질산암모늄이 열분해되는 경우 다음 물음에 답하시오.\n가. 질산암모늄이 분해되어 N2, O2, H2O를 발생하는 분해반응식을 쓰시오.\n나. 질산암모늄 1몰이 0.9기압, 300℃에서 분해될 때 생성되는 H2O의 부피(L)를 구하시오.","a":"가. 2NH4NO3 → 2N2 + O2 + 4H2O\n나. ① NH4NO3 1몰, 0.9atm, 300℃(573K)\n② 1몰에서 H2O 2몰 생성 (4/2)\n③ V = (1×0.082×573)/0.9 × 2\n④ 104.41L","h":"질산암모늄은 N2, O2, 수증기로 분해하며 계수는 2:2:1:4다. 1몰이 분해하면 물이 2몰 나오므로 계수비 4/2를 곱해 부피를 구한다. 온도는 섭씨에 273을 더해 켈빈으로 바꿔 넣는다.","tp":"W01","t":"kan","칸":[{"a":"2NH4NO3→2N2+O2+4H2O","syn":["2NH4NO3->2N2+O2+4H2O","2NH4NO3=2N2+O2+4H2O","NH4NO3→N2+1/2O2+2H2O","NH4NO3->N2+1/2O2+2H2O","NH4NO3→N2+0.5O2+2H2O"],"l":"가"},{"a":"104.41","e":1.5,"l":"나"}],"순서무관":false},{"id":"2019-2-09","y":2019,"r":2,"n":9,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 [보기]에서 설명하는 위험물에 대하여 답하시오.\n[보기]\n• 휘발성이 있는 투명한 액체이다.\n• 화장품과 소독약의 원료로 사용된다.\n• 아이오딘폼 반응을 한다.\n• 증기는 마취성이 있고 물에 잘 녹는다.\n• 산화하면 아세트알데하이드가 된다.\n가. 이 물질의 화학식을 쓰시오.\n나. 이 물질의 지정수량을 쓰시오.\n다. 진한황산과 축합중합반응하여 생성되는 제4류 위험물의 화학식을 쓰시오.","a":"가. C2H5OH\n나. 400L\n다. C2H5OC2H5","h":"아이오딘폼 반응을 하고 산화하면 아세트알데하이드가 되는 알코올류는 에탄올이다. 지정수량은 400L이다. 에탄올 2분자가 물 한 분자를 잃고 축합하면 다이에틸에터가 된다.","t":"kan","칸":[{"a":"C2H5OH","syn":["에탄올","에틸알코올","에틸알콜","에틸 알코올","에틸 알콜","CH3CH2OH","ethanol"],"l":"가"},{"a":"400","syn":["400L","400 L","400리터"],"l":"나"},{"a":"C2H5OC2H5","syn":["다이에틸에터","디에틸에터","다이에틸에테르","디에틸에테르","에틸에터","에틸에테르","에터","에테르","C2H5-O-C2H5","(C2H5)2O","CH3CH2OCH2CH3","diethyl ether"],"l":"다"}],"순서무관":false},{"id":"2019-2-10","y":2019,"r":2,"n":10,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"다음 [보기] 중 불활성가스 소화설비에 적응성이 있는 위험물 2가지의 기호를 쓰시오 (단, 없으면 없음이라 쓰시오).\n[보기]\n① 제1류 위험물  ② 제2류 위험물 중 인화성고체  ③ 제3류 위험물\n④ 제4류 위험물  ⑤ 제5류 위험물  ⑥ 제6류 위험물","a":"②, ④","h":"불활성가스 소화설비는 질식소화이므로 제2류의 인화성고체와 제4류 위험물에 쓴다. 제1류의 알칼리금속 과산화물과 제3류 금수성 물질은 주수금지이고, 제5류·제6류는 주수소화 대상이라 해당하지 않는다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)","ㄴ"]},{"a":"④","syn":["4","4번","(4)"]}],"순서무관":true,"nc":2},{"id":"2019-2-11","y":2019,"r":2,"n":11,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물안전관리법령에서 정한 저장에 관한 중요 기준 중, 유별을 달리 하는 위험물은 동일한 저장소에 저장하지 아니하여야 한다. 단, 옥내저장소 또는 옥외저장소 있어서 적절한 조치를 한 경우에는 저장이 가능하다. 옥내저장소에서 동일한 실에 저장할 수 있는 유별을 바르게 연결한 것을 골라 기호를 쓰시오.\n[보기]\n① 과산화나트륨 - 과산화벤조일\n② 질산염류 - 과염소산\n③ 황린 - 제1류 위험물\n④ 인화성고체 - 제1석유류\n⑤ 황 - 제4류 위험물","a":"②, ③, ④","h":"옥내저장소에서 1m 이상 띄우면 같이 둘 수 있는 조합은 제1류(알칼리금속 과산화물 제외)와 제5류, 제1류와 제6류, 제1류와 황린, 인화성고체와 제4류 등이다. ① 과산화나트륨은 알칼리금속의 과산화물이라 제5류와 둘 수 없고, ⑤ 황은 제2류인데 인화성고체가 아니라서 제4류와 둘 수 없다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"]},{"a":"③","syn":["3","3번","(3)"]},{"a":"④","syn":["4","4번","(4)"]}],"순서무관":true},{"id":"2019-2-12","y":2019,"r":2,"n":12,"p":"시설·법령","kw":"운송·이동탱크","pt":5,"q":"위험물안전관리법령에 따른 이동탱크저장소의 주입설비 설치기준에 대하여 다음 물음에 답하시오.\n가. 위험물이 ( ① ) 우려가 없고 화재 예방상 안전한 구조로 할 것\n나. 주입설비의 길이는 ( ② ) 이내로 하고, 그 끝부분에 축적되는 ( ③ )를 유효하게 제거할 수 있는 장치를 할 것\n다. 분당 배출량은 ( ④ ) 이하로 할 것","a":"가. ① 샐\n나. ② 50m, ③ 정전기\n다. ④ 200L","h":"이동탱크저장소의 주입설비는 위험물이 샐 우려가 없는 구조여야 하고, 길이 50m 이내에 끝부분의 정전기를 제거하는 장치를 달아야 한다. 분당 배출량은 200L 이하다.","t":"kan","칸":[{"a":"샐","syn":["새","새는","새어","새어나갈","새어 나갈","누설","누출","샐 우려"],"l":"①"},{"a":"50m","syn":["50","50 m","50미터"],"l":"②"},{"a":"정전기","syn":["정전기 전하","static","정전하"],"l":"③"},{"a":"200L","syn":["200","200 L","200리터"],"l":"④"}],"순서무관":false},{"id":"2019-2-13","y":2019,"r":2,"n":13,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 표의 위험물 유별 및 지정수량을 쓰시오.\n품명 / 유별 / 지정수량\n칼륨 ① ②\n질산염류 ③ ④\n나이트로화합물 ⑤ ⑥\n황린 ⑦ ⑧","a":"① 제3류 위험물, ② 10kg\n③ 제1류 위험물, ④ 300kg\n⑤ 제5류 위험물, ⑥ 제1종 10kg, 제2종 100kg\n⑦ 제3류 위험물, ⑧ 20kg","h":"칼륨은 제3류 10kg, 질산염류는 제1류 300kg, 나이트로화합물은 제5류 제1종 10kg·제2종 100kg, 황린은 제3류 20kg이다. 제3류에서 10kg은 칼륨·나트륨·알킬알루미늄·알킬리튬이고 황린만 20kg이다.","t":"kan","칸":[{"a":"제3류","syn":["3류","제3류 위험물","3류 위험물","제 3류"],"l":"①"},{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"②"},{"a":"제1류","syn":["1류","제1류 위험물","1류 위험물","제 1류"],"l":"③"},{"a":"300kg","syn":["300","300 kg","300킬로그램"],"l":"④"},{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"⑤"},{"a":"제1종 10kg, 제2종 100kg","k":[["1종"],["2종"],["100"]],"l":"⑥"},{"a":"제3류","syn":["3류","제3류 위험물","3류 위험물","제 3류"],"l":"⑦"},{"a":"20kg","syn":["20","20 kg","20킬로그램"],"l":"⑧"}],"순서무관":false},{"id":"2019-4-01","y":2019,"r":4,"n":1,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"위험물 옥내저장소에 다음 위험물을 저장할 때 하나의 저장창고의 바닥면적은 몇 m2 이하로 하여야 하는지 쓰시오.\n가. 염소산염류\n나. 제2석유류\n다. 유기과산화물","a":"가. 1,000m2 이하\n나. 2,000m2 이하\n다. 1,000m2 이하","h":"옥내저장소 한 창고의 바닥면적은 위험등급 I 위험물과 제4류의 I·II등급을 저장하면 1,000m2, 위험등급 II·III와 제4류 III등급이면 2,000m2 이하다. 염소산염류와 유기과산화물은 I등급, 제2석유류는 III등급이다.","t":"kan","칸":[{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"가"},{"a":"2000","syn":["2,000","2000m2","2,000m2","2000㎡","2,000㎡","2000m2 이하","2,000m2 이하"],"l":"나"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"다"}],"순서무관":false},{"id":"2019-4-02","y":2019,"r":4,"n":2,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"다음 위험물을 옥외저장탱크 중 압력탱크 외의 탱크에 저장할 때의 온도를 쓰시오.\n가. 산화프로필렌 및 다이에틸에터\n나. 아세트알데하이드","a":"가. 30℃ 이하\n나. 15℃ 이하","h":"압력탱크가 아닌 탱크에서 산화프로필렌·다이에틸에터는 30℃ 이하, 아세트알데하이드는 15℃ 이하다. 압력탱크는 둘 다 40℃ 이하로 바뀐다.","t":"kan","칸":[{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"가"},{"a":"15℃","syn":["15","15도","15℃ 이하","15도 이하"],"l":"나"}],"순서무관":false},{"id":"2019-4-03","y":2019,"r":4,"n":3,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"톨루엔의 증기비중을 구하시오.\n[계산과정]\n[답]","a":"① C6H5CH3 분자량 = 12×6+1×5+12+1×3 = 92\n② 증기비중 = 분자량/29\n③ 92/29 = 3.172\n④ 3.17","h":"증기비중은 분자량을 공기의 평균 분자량 29로 나눈 값이다. 톨루엔은 C7H8이라 분자량 92이고, 결과는 3.17로 공기보다 무겁다. 탄소 수를 6개로만 세지 않도록 메틸기 탄소 1개를 더한다.","t":"calc","e":0.03,"ka":"3.17"},{"id":"2019-4-04","y":2019,"r":4,"n":4,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"산화성액체의 산화성 시험방법 및 판정기준이다. 다음 빈칸에 알맞은 말을 쓰시오.\n( 가 ), ( 나 ) 90% 수용액 및 시험물품을 사용하여 온도 20℃, 습도 50%, 1기압의 실내에서 제2항 및 제3항의 방법에 의하여 실시한다.\n연소시간의 평균치를 ( 나 ) 90% 수용액과 ( 가 )과의 혼합물의 연소시간으로 할 것","a":"가. 목분\n나. 질산","h":"산화성 액체의 시험은 목분과 질산 90% 수용액을 시험물품과 각각 섞어 연소시간을 비교한다. 온도 20℃, 습도 50%, 1기압의 실내에서 한다. 연소시간 평균은 질산 90% 수용액과 목분을 섞은 것을 기준으로 삼는다.","t":"kan","칸":[{"a":"목분","syn":["목분말","나무가루","톱밥","wood powder"],"l":"가"},{"a":"질산","syn":["HNO3","질산 90%","nitric acid"],"l":"나"}],"순서무관":false},{"id":"2019-4-05","y":2019,"r":4,"n":5,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"주유취급소에서 \"주유중엔진정지\" 게시판에 대한 물음에 답하시오.\n가. 바탕색\n나. 글자색","a":"가. 황색\n나. 흑색","h":"'주유중엔진정지' 게시판은 황색 바탕에 흑색 문자다. 화기엄금은 적색 바탕에 백색 문자, 물기엄금은 청색 바탕에 백색 문자로 서로 다르다.","t":"kan","칸":[{"a":"황색","syn":["노란색","노랑","노랑색","황","yellow"],"l":"가"},{"a":"흑색","syn":["검정색","검정","검은색","검은 색","검정 색","black"],"l":"나"}],"순서무관":false},{"id":"2019-4-06","y":2019,"r":4,"n":6,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"트라이에틸알루미늄 228g이 물과 반응할 때의 식과 발생하는 가연성 가스의 부피는 표준상태에서 몇 L인지 쓰시오.\n가. 물과의 반응식\n나. 가연성 가스의 부피","a":"가. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n나. ① (C2H5)3Al 228g, 분자량 114, 표준상태\n② 1몰에서 C2H6 3몰 생성\n③ V = (228×0.082×273)/(1×114) × 3\n④ 134.32L","h":"트라이에틸알루미늄은 물과 반응해 수산화알루미늄과 에테인 3몰을 낸다. 228g은 2몰이므로 에테인 6몰, 부피로 134.32L가 된다. 트라이메틸알루미늄은 같은 형태로 메테인이 나온다.","tp":"W01","t":"kan","칸":[{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"가"},{"a":"134.32","e":1,"l":"나"}],"순서무관":false},{"id":"2019-4-07","y":2019,"r":4,"n":7,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"과산화나트륨과 이산화탄소의 반응식을 쓰시오.","a":"2Na2O2 + 2CO2 → 2Na2CO3 + O2","h":"과산화나트륨은 이산화탄소를 만나면 탄산나트륨과 산소를 낸다. 산소가 1/2 나오므로 양변에 2를 곱해 계수를 정수로 만든다. 물과 반응할 때는 수산화나트륨과 산소가 나온다는 점이 다르다.","t":"kan","칸":[{"a":"2Na2O2+2CO2→2Na2CO3+O2","syn":["2Na2O2+2CO2->2Na2CO3+O2","2Na2O2+2CO2=2Na2CO3+O2","Na2O2+CO2→Na2CO3+1/2O2","Na2O2+CO2->Na2CO3+1/2O2"]}],"순서무관":false},{"id":"2019-4-08","y":2019,"r":4,"n":8,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 [보기] 중 운반 시 방수성 및 차광성 덮개로 모두 덮어야 하는 위험물 품명을 고르시오.\n유기과산화물, 질산, 알칼리금속과산화물, 염소산염류","a":"알칼리금속과산화물","h":"방수성과 차광성 덮개를 모두 요구하는 것은 제1류 중 알칼리금속의 과산화물이다. 유기과산화물(제5류)·질산(제6류)·염소산염류(제1류 일반)는 차광성 덮개만 쓴다.","t":"word","syn":["알칼리금속의 과산화물","알칼리 금속 과산화물","알칼리금속 과산화물","알칼리금속의과산화물"],"ka":"알칼리금속과산화물"},{"id":"2019-4-09","y":2019,"r":4,"n":9,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 [보기]에 물질을 연소 형태에 맞도록 나열하시오.\n나트륨, TNT, 에탄올, 금속분, 다이에틸에터, 피크린산\n가. 표면연소 :\n나. 증발연소 :\n다. 자기연소 :","a":"가. 표면연소 : 나트륨, 금속분\n나. 증발연소 : 에탄올, 다이에틸에터\n다. 자기연소 : TNT, 피크린산","h":"금속은 표면에서 타는 표면연소, 제4류 액체는 증기가 타는 증발연소, 제5류 고체는 자기 산소로 타는 자기연소로 분류한다. 보기 물질의 유별만 알면 연소 형태가 정해진다.","t":"kan","칸":[{"a":"나트륨, 금속분","k":[["나트륨","Na"],["금속분","금속"]],"l":"가"},{"a":"에탄올, 다이에틸에터","k":[["에탄올","에틸알코올","에틸알콜"],["다이에틸에터","디에틸에터","다이에틸에테르","디에틸에테르","에터","에테르"]],"l":"나"},{"a":"TNT, 피크린산","k":[["TNT","트라이나이트로톨루엔","트리니트로톨루엔"],["피크린산","트라이나이트로페놀","트리니트로페놀","TNP"]],"l":"다"}],"순서무관":false},{"id":"2019-4-10","y":2019,"r":4,"n":10,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량이 227이며 폭약의 원료이며, 햇빛에 다갈색으로 변하고, 물에 안 녹고 벤젠과 아세톤에 녹는 물질에 대하여 답하시오.\n가. 화학식\n나. 지정수량\n다. 사용원료 중심으로 제조방법","a":"가. C6H2(NO2)3CH3\n나. 10kg\n다. 톨루엔에 질산과 황산을 반응시킨다.","h":"분자량 227이고 벤젠·아세톤에 녹는 폭약 원료는 TNT다. 트라이나이트로페놀은 분자량이 229라 227과 구별된다. 제5류 나이트로화합물 제1종이라 지정수량은 10kg이다.","t":"kan","칸":[{"a":"C6H2(NO2)3CH3","syn":["C6H2CH3(NO2)3","CH3C6H2(NO2)3","C7H5N3O6","트라이나이트로톨루엔","트리니트로톨루엔","TNT","C6H2(CH3)(NO2)3"],"l":"가"},{"a":"10","syn":["10kg","10 kg","10킬로그램"],"l":"나"},{"a":"톨루엔에 질산과 황산을 반응시킨다","k":[["톨루엔","toluene"],["질산","황산","혼산","나이트로","니트로"]],"l":"다"}],"순서무관":false},{"id":"2019-4-11","y":2019,"r":4,"n":11,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 [보기]의 위험물을 인화점이 낮은 것부터 높은 순으로 번호를 나열하시오.\n① 초산에틸  ② 메탄올  ③ 에틸렌글리콜  ④ 나이트로벤젠","a":"① - ② - ④ - ③","h":"제4류는 품명이 석유류 번호 순서대로 인화점이 높아지고, 같은 품명이면 비수용성이 수용성보다 낮다. 초산에틸 -4℃, 메탄올 11℃, 나이트로벤젠 88℃, 에틸렌글리콜 111℃ 순이다.","t":"word","syn":["①-②-④-③","①,②,④,③","①→②→④→③","①>②>④>③","①<②<④<③","1-2-4-3","1,2,4,3","1243","1→2→4→3","1<2<4<3","1>2>4>3"],"ka":"①②④③"},{"id":"2019-4-12","y":2019,"r":4,"n":12,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제3류 위험물 중 지정수량이 50kg인 품명을 모두 쓰시오.","a":"알칼리금속 및 알칼리토금속, 유기금속화합물","h":"제3류 위험물에서 지정수량 50kg은 알칼리금속·알칼리토금속과 유기금속화합물이다. 알킬알루미늄·칼륨·알킬리튬·나트륨은 10kg, 황린은 20kg, 나머지는 300kg이다.","t":"kan","칸":[{"a":"알칼리금속 및 알칼리토금속","syn":["알칼리금속","알칼리토금속","알칼리금속 알칼리토금속","알칼리금속, 알칼리토금속","알칼리금속및알칼리토금속"]},{"a":"유기금속화합물","syn":["유기금속 화합물","유기금속"]}],"순서무관":true},{"id":"2019-4-13","y":2019,"r":4,"n":13,"p":"반응식","kw":"열분해","pt":5,"q":"ABC분말소화기 중 오르토인산이 생성되는 1차 열분해 반응식을 쓰시오.","a":"NH4H2PO4 → H3PO4 + NH3","h":"제3종 분말(인산암모늄)은 1차로 오르토인산(H3PO4)과 암모니아로 분해되고, 2차에서 메타인산(HPO3), 암모니아, 물이 된다. 제1종과 제2종은 탄산염, 이산화탄소, 물로 분해되어 형태가 다르다.","t":"kan","칸":[{"a":"NH4H2PO4→H3PO4+NH3","syn":["NH4H2PO4->H3PO4+NH3","NH4H2PO4=H3PO4+NH3","NH4H2PO4→NH3+H3PO4","NH4H2PO4->NH3+H3PO4","NH4H2PO4⟶H3PO4+NH3"]}],"순서무관":false},{"id":"2020-1-01","y":2020,"r":1,"n":1,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"이황화탄소 100kg이 완전연소할 때 발생하는 이산화황의 부피(m3)를 구하시오 (단, 압력은 800mmHg, 기준온도 30℃이다).","a":"① CS2 100kg, 분자량 76, 800mmHg(1.0526atm), 303K\n② CS2 + 3O2 → CO2 + 2SO2\n③ V = (100×0.082×303)/(1.0526×76) × 2\n④ 62.12m3","h":"이황화탄소 1몰이 타면 이산화황 2몰이 나온다. 압력은 800/760 = 1.0526atm으로 환산하고, 질량이 kg이므로 분자량도 kg/kmol로 맞춘다.","tp":"W01","t":"calc","e":0.6,"ka":"62.12"},{"id":"2020-1-02","y":2020,"r":1,"n":2,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"제1류 위험물인 염소산칼륨에 관한 내용이다. 다음 각 물음에 답을 쓰시오.\n가. 완전분해 반응식\n나. 염소산칼륨 1kg이 표준상태에서 완전 분해 시 생성되는 산소의 부피(m3) (단, 염소산칼륨의 분자량은 123이다)","a":"가. 2KClO3 → 2KCl + 3O2\n나. ① KClO3 1kg, 분자량 123, 표준상태\n② 2kmol에서 O2 3kmol\n③ V = (1×0.082×273)/(1×123) × 3/2\n④ 0.27m3","h":"염소산칼륨은 분해되어 염화칼륨과 산소가 되고 계수비는 2:2:3이다. 산소 부피는 KClO3 부피에 3/2를 곱해서 구한다.","tp":"W01","t":"kan","칸":[{"a":"2KClO3→2KCl+3O2","syn":["2KClO3->2KCl+3O2","2KClO3=2KCl+3O2","KClO3→KCl+3/2O2","KClO3->KCl+3/2O2"],"l":"가"},{"a":"0.27","e":0.01,"l":"나"}],"순서무관":false},{"id":"2020-1-03","y":2020,"r":1,"n":3,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"과산화나트륨의 완전분해 반응식과 과산화나트륨 1kg이 표준상태에서 산소의 부피(L)를 구하시오.","a":"완전분해 반응식 : 2Na2O2 → 2Na2O + O2\n산소의 부피 : ① Na2O2 1,000g, 분자량 78\n② 2몰에서 O2 1몰\n③ V = (1,000×0.082×273)/(1×78) × 1/2\n④ 143.5L","h":"과산화나트륨이 분해하면 산화나트륨과 산소가 생기며 산소 계수는 1이다. 계수비가 1/2이므로 단순 몰수의 반만 산소가 된다.","tp":"W01","t":"kan","칸":[{"a":"2Na2O2→2Na2O+O2","syn":["2Na2O2->2Na2O+O2","2Na2O2=2Na2O+O2","Na2O2→Na2O+1/2O2","Na2O2->Na2O+1/2O2","2Na2O2→2Na2O+O2↑"],"l":"반응식"},{"a":"143.5","e":1.5,"l":"부피"}],"순서무관":false},{"id":"2020-1-04","y":2020,"r":1,"n":4,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"알루미늄에 대한 다음 각 물음에 알맞은 답을 하시오.\n가. 염산과 반응식\n나. 연소반응식\n다. 물과 반응식","a":"가. 2Al + 6HCl → 2AlCl3 + 3H2\n나. 4Al + 3O2 → 2Al2O3\n다. 2Al + 6H2O → 2Al(OH)3 + 3H2","h":"알루미늄은 염산과 반응해 염화알루미늄과 수소, 산소와는 산화알루미늄, 물과는 수산화알루미늄과 수소를 낸다. 세 반응 모두 알루미늄 계수가 2나 4로 짝수라 마지막에 원자 수를 한 번 검산한다.","t":"kan","칸":[{"a":"2Al+6HCl→2AlCl3+3H2","syn":["2Al+6HCl->2AlCl3+3H2","2Al+6HCl=2AlCl3+3H2","Al+3HCl→AlCl3+3/2H2"],"l":"가"},{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3"],"l":"나"},{"a":"2Al+6H2O→2Al(OH)3+3H2","syn":["2Al+6H2O->2Al(OH)3+3H2","2Al+6H2O=2Al(OH)3+3H2","Al+3H2O→Al(OH)3+3/2H2"],"l":"다"}],"순서무관":false},{"id":"2020-1-05","y":2020,"r":1,"n":5,"p":"반응식","kw":"물과 반응","pt":5,"q":"위험물안전관리법령에서 정한 제2류 위험물 중 황화인에 대한 내용이다. 다음 물음에 알맞은 답을 쓰시오.\n가. 오황화인과 물이 반응하는 반응식\n나. 오황화인이 물과 반응하여 생성되는 기체의 완전연소 반응식","a":"가. P2S5 + 8H2O → 2H3PO4 + 5H2S\n나. 2H2S + 3O2 → 2SO2 + 2H2O","h":"오황화인은 물과 반응해 인산과 황화수소를 내고, 황화수소가 타면 이산화황과 물이 된다. 황화수소 연소는 산소 1.5몰이 필요해 양변에 2를 곱한다.","t":"kan","칸":[{"a":"P2S5+8H2O→2H3PO4+5H2S","syn":["P2S5+8H2O->2H3PO4+5H2S","P2S5+8H2O=2H3PO4+5H2S","P2S5+8H2O→5H2S+2H3PO4","P2S5+8H2O->5H2S+2H3PO4"],"l":"가"},{"a":"2H2S+3O2→2SO2+2H2O","syn":["2H2S+3O2->2SO2+2H2O","2H2S+3O2=2SO2+2H2O","H2S+3/2O2→SO2+H2O"],"l":"나"}],"순서무관":false},{"id":"2020-1-06","y":2020,"r":1,"n":6,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"위험물안전관리법령에서 정한 다음 옥내소화전 수원의 수량을 구하시오.\n가. 옥내소화전이 1층에 1개, 2층에 3개 설치\n나. 옥내소화전이 1층에 1개, 2층에 6개 설치","a":"가. ① 한 층의 최대 개수 3개\n② 수원 = 개수(최대 5개)×7.8m3\n③ 3×7.8\n④ 23.4m3\n나. ① 한 층의 최대 개수 6개 → 5개 적용\n② 수원 = 5×7.8\n③ 5×7.8\n④ 39m3","h":"옥내소화전 수원은 한 층에 설치된 가장 많은 개수(5개를 넘으면 5개)에 7.8m3를 곱한다. 가는 3개, 나는 6개이지만 5개로 제한해 39m3다. 1층과 2층의 개수를 더하지 않는다.","t":"kan","칸":[{"a":"23.4","e":0.1,"l":"가"},{"a":"39","e":0.1,"l":"나"}],"순서무관":false},{"id":"2020-1-07","y":2020,"r":1,"n":7,"p":"반응식","kw":"물과 반응","pt":5,"q":"제3류 위험물 중 다음 물질이 물과 반응하는 반응식을 쓰시오.\n가. 수소화리튬알루미늄\n나. 수소화칼륨\n다. 수소화칼슘","a":"가. LiAlH4 + 4H2O → LiOH + Al(OH)3 + 4H2\n나. KH + H2O → KOH + H2\n다. CaH2 + 2H2O → Ca(OH)2 + 2H2","h":"금속수소화합물은 물과 만나 해당 금속의 수산화물과 수소를 낸다. 수소화리튬알루미늄은 수산화물이 두 가지(LiOH, Al(OH)3) 생기고 수소가 4몰이다. 수소화칼슘은 칼슘 2가라서 물 2몰이 필요하다.","t":"kan","칸":[{"a":"LiAlH4+4H2O→LiOH+Al(OH)3+4H2","syn":["LiAlH4+4H2O->LiOH+Al(OH)3+4H2","LiAlH4+4H2O=LiOH+Al(OH)3+4H2","LiAlH4+4H2O→Al(OH)3+LiOH+4H2","LiAlH4+4H2O->Al(OH)3+LiOH+4H2"],"l":"가"},{"a":"KH+H2O→KOH+H2","syn":["KH+H2O->KOH+H2","KH+H2O=KOH+H2"],"l":"나"},{"a":"CaH2+2H2O→Ca(OH)2+2H2","syn":["CaH2+2H2O->Ca(OH)2+2H2","CaH2+2H2O=Ca(OH)2+2H2"],"l":"다"}],"순서무관":false},{"id":"2020-1-08","y":2020,"r":1,"n":8,"p":"반응식","kw":"물과 반응","pt":5,"q":"제3류 위험물인 나트륨에 대한 다음 물음에 답하시오.\n가. 나트륨과 물의 반응식\n나. 나트륨의 연소반응식\n다. 나트륨이 연소할 때 불꽃의 색상","a":"가. 2Na + 2H2O → 2NaOH + H2\n나. 4Na + O2 → 2Na2O\n다. 노란색","h":"나트륨은 물과 반응해 수산화나트륨과 수소를 내고, 연소하면 산화나트륨이 된다. 불꽃색은 나트륨이 노란색, 칼륨은 보라색이다.","t":"kan","칸":[{"a":"2Na+2H2O→2NaOH+H2","syn":["2Na+2H2O->2NaOH+H2","2Na+2H2O=2NaOH+H2","Na+H2O→NaOH+1/2H2"],"l":"가"},{"a":"4Na+O2→2Na2O","syn":["4Na+O2->2Na2O","4Na+O2=2Na2O"],"l":"나"},{"a":"노란색","syn":["황색","노랑","노랑색","노란 색","yellow"],"l":"다"}],"순서무관":false},{"id":"2020-1-09","y":2020,"r":1,"n":9,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 저장할 때 사용하는 보호액을 쓰시오.\n가. 황린\n나. 칼륨\n다. CS2","a":"가. pH9의 물\n나. 등유, 경유, 유동파라핀\n다. 물","h":"황린은 pH9 정도의 물속에 둔다. 강알칼리 물에서는 포스핀이 생기기 때문이다. 칼륨은 등유·경유·파라핀에, 이황화탄소는 가연성 증기를 누르려고 물속에 둔다.","t":"kan","칸":[{"a":"pH9의 물","syn":["pH9","pH 9","pH9 물","pH 9 물","pH 9의 물","pH9의물","물","약알칼리성 물","알칼리성 물"],"l":"가"},{"a":"등유, 경유, 유동파라핀","k":[["등유","경유","파라핀","석유"]],"l":"나"},{"a":"물","syn":["수","water"],"l":"다"}],"순서무관":false},{"id":"2020-1-10","y":2020,"r":1,"n":10,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령상 동식물유류에 관한 물음에 답을 쓰시오.\n가. 아이오딘값의 정의\n나. 동식물유류 아이오딘값에 따른 분류와 범위","a":"가. 유지 100g에 흡수되는 아이오딘의 g수\n나. 건성유 : 130 이상\n반건성유 : 100 이상 130 미만\n불건성유 : 100 미만","h":"아이오딘값은 기름 100g과 반응하는 아이오딘(I2)의 g수이며, 값이 클수록 이중결합이 많아 공기 중에서 굳기 쉽다. 130 이상이 건성유, 100~130 미만이 반건성유, 100 미만이 불건성유다.","t":"kan","칸":[{"a":"유지 100g에 흡수되는 아이오딘의 g수","k":[["100"],["아이오딘","요오드","요오드값","옥소","I2"]],"l":"가"},{"a":"130 이상","syn":["130이상","130","130이상이다"],"l":"건성유"},{"a":"100 이상 130 미만","k":[["100"],["130"]],"l":"반건성유"},{"a":"100 미만","syn":["100미만","100","100이하"],"l":"불건성유"}],"순서무관":false},{"id":"2020-1-11","y":2020,"r":1,"n":11,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"보기가 설명하는 물질에 대한 다음 물음에 알맞은 답을 쓰시오.\n• 인화점이 -37℃이다.\n• 무색투명한 액체로서 분자량이 58이다.\n• 수용성이다.\n• 구리, 은, 수은, 마그네슘과 반응하여 폭발성 아세틸라이드를 생성한다.\n가. 물질의 화학식\n나. 물질의 지정수량\n다. 다음 물질을 저장하는 탱크에 공기가 차 있으면 어떻게 조치하여야 하는지 쓰시오.","a":"가. OCH2CHCH3\n나. 50L\n다. 불활성기체 주입","h":"인화점 -37℃, 분자량 58인 수용성 특수인화물은 산화프로필렌이다. 구리·은·수은·마그네슘과 반응해 폭발성 물질이 생기므로 이 금속으로 설비를 만들지 않는다. 탱크에 공기가 차 있으면 불활성기체를 넣어 치환한다.","t":"kan","칸":[{"a":"OCH2CHCH3","syn":["CH3CHCH2O","CH3CH(O)CH2","CH2CHCH3O","CH3CHOCH2","C3H6O","CH3OCHCH2","CH2OCHCH3","CH3CH-O-CH2","산화프로필렌","프로필렌옥사이드","프로필렌옥시드","프로필렌 옥사이드","propylene oxide"],"l":"가"},{"a":"50","syn":["50L","50 L","50리터"],"l":"나"},{"a":"불활성기체 주입","k":[["불활성","불연성","질소","N2","아르곤","Ar","이산화탄소","CO2"],["주입","봉입","치환","채우","충전","채워","넣"]],"l":"다"}],"순서무관":false},{"id":"2020-1-12","y":2020,"r":1,"n":12,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"인화점 측정방법(방식) 3가지를 쓰시오.","a":"태그밀폐식, 신속평형법, 클리브랜드 개방컵","h":"인화점 측정기는 태그밀폐식(시료 50cm3), 신속평형법(시료 2mL), 클리브랜드 개방컵(시료컵 표선까지)으로 나뉜다. 개방컵만 뚜껑이 없는 방식이다.","t":"kan","칸":[{"a":"태그밀폐식","syn":["태그 밀폐식","태그밀폐","태그식","태그밀폐식시험","tag"]},{"a":"신속평형법","syn":["신속평형","신속 평형법","신속평형법시험"]},{"a":"클리브랜드개방컵","syn":["클리브랜드 개방컵","클리블랜드개방컵","클리블랜드 개방컵","클리브랜드개방식","클리블랜드개방식","클리브랜드","클리블랜드","클리브랜드개방컵시험"]}],"순서무관":true,"nc":3},{"id":"2020-1-13","y":2020,"r":1,"n":13,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물을 운반할 때 각 운반용기 외부에 표시하여야 하는 주의사항을 쓰시오.\n가. 제1류 위험물 중 알칼리금속의 과산화물\n나. 제3류 위험물 중 자연발화성 물질\n다. 제5류 위험물","a":"가. 화기·충격주의, 물기엄금, 가연물접촉주의\n나. 화기엄금, 공기접촉엄금\n다. 화기엄금, 충격주의","h":"제1류 알칼리금속 과산화물은 가연물접촉주의·화기충격주의·물기엄금, 제3류 자연발화성 물질은 화기엄금·공기접촉엄금, 제5류는 화기엄금·충격주의를 붙인다. 물과 닿으면 안 되는 것에는 물기엄금이 들어간다.","t":"kan","칸":[{"a":"화기·충격주의, 물기엄금, 가연물접촉주의","k":[["충격"],["물기"],["가연물"]],"l":"가"},{"a":"화기엄금, 공기접촉엄금","k":[["화기"],["공기접촉","공기"]],"l":"나","no":["물기","가연물","충격"]},{"a":"화기엄금, 충격주의","k":[["화기"],["충격"]],"l":"다","no":["물기","가연물","공기"]}],"순서무관":false},{"id":"2020-1-14","y":2020,"r":1,"n":14,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제4류 위험물 인화점에 관한 내용이다. 다음 빈칸을 채우시오.\n• 특수인화물 : 발화점이 섭씨 ( 가 )도 이하인 것 또는 인화점이 섭씨 영하 20도 이하이고 비점이 섭씨 40도 이하\n• 제1석유류 : 인화점이 섭씨 ( 나 )도 미만\n• 제2석유류 : 인화점이 섭씨 ( 나 )도 이상 ( 다 )도 미만\n• 제3석유류 : 인화점이 섭씨 ( 다 )도 이상 섭씨 ( 라 )도 미만\n• 제4석유류 : 인화점이 섭씨 ( 라 )도 이상 섭씨 ( 마 )도 미만","a":"가. 100\n나. 21\n다. 70\n라. 200\n마. 250","h":"특수인화물은 발화점 100℃ 이하이거나 인화점 -20℃ 이하에 비점 40℃ 이하인 것이다. 석유류 구분선은 21, 70, 200, 250℃이고 한 구간의 위쪽 값이 다음 구간의 아래쪽 값이 된다.","t":"kan","칸":[{"a":"100","syn":["100도","100℃"],"l":"가"},{"a":"21","syn":["21도","21℃"],"l":"나"},{"a":"70","syn":["70도","70℃"],"l":"다"},{"a":"200","syn":["200도","200℃"],"l":"라"},{"a":"250","syn":["250도","250℃"],"l":"마"}],"순서무관":false},{"id":"2020-1-15","y":2020,"r":1,"n":15,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"크실렌 이성질체 3가지에 대한 명칭과 구조식을 쓰시오.","a":"o-크실렌, m-크실렌, p-크실렌\n(벤젠고리에 CH3 두 개가 각각 1,2 / 1,3 / 1,4 자리에 붙은 구조)","h":"크실렌은 벤젠에 메틸기 두 개가 붙은 물질로 위치에 따라 오르토(1,2), 메타(1,3), 파라(1,4) 세 이성질체가 있다. 구조식은 벤젠고리를 그리고 메틸기 위치만 달리하면 된다.","ai":"2020-1-15_a.svg","t":"kan","칸":[{"a":"o-크실렌","syn":["오르토크실렌","오르쏘크실렌","ortho-xylene","o-자일렌","오르토자일렌","1,2-크실렌","1,2-다이메틸벤젠","오르토-크실렌","o크실렌","o-xylene"]},{"a":"m-크실렌","syn":["메타크실렌","meta-xylene","m-자일렌","메타자일렌","1,3-크실렌","1,3-다이메틸벤젠","메타-크실렌","m크실렌","m-xylene"]},{"a":"p-크실렌","syn":["파라크실렌","para-xylene","p-자일렌","파라자일렌","1,4-크실렌","1,4-다이메틸벤젠","파라-크실렌","p크실렌","p-xylene"]}],"순서무관":true,"nc":3},{"id":"2020-1-16","y":2020,"r":1,"n":16,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에서 정한 안전관리자에 대한 내용이다. 다음 물음에 답하시오.\n가. 안전관리자를 선임하여야 하는 대상을 보기에서 1가지 고르시오 (단, 없으면 없음이라 표기하시오).\n   제조소등의 관계인, 제조소등의 설치자, 소방서장, 소방청장, 시, 도지사\n나. 안전관리자 해임 후 재선임 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).\n다. 안전관리자 퇴직 후 재선임 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).\n라. 안전관리자 선임 후 신고 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).\n마. 안전관리자가 여행, 질병 그 밖의 사유로 인하여 일시적으로 직무를 수행할 수 없을 때 직무를 대행하는 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).","a":"가. 제조소등의 관계인\n나. 30일\n다. 30일\n라. 14일\n마. 30일","h":"안전관리자 선임 의무는 제조소등의 관계인에게 있다. 해임·퇴직 후 재선임은 30일 이내, 선임 후 신고는 14일 이내, 대리자 직무 대행은 30일을 넘길 수 없다. 30일 셋과 14일 하나로 정리한다.","t":"kan","칸":[{"a":"제조소등의 관계인","syn":["관계인","제조소 등의 관계인","제조소등 관계인"],"l":"가"},{"a":"30일","syn":["30","30일 이내"],"l":"나"},{"a":"30일","syn":["30","30일 이내"],"l":"다"},{"a":"14일","syn":["14","14일 이내"],"l":"라"},{"a":"30일","syn":["30","30일 이내"],"l":"마"}],"순서무관":false},{"id":"2020-1-17","y":2020,"r":1,"n":17,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"제6류 위험물 중 한 물질이 하이드라진과 만나면 격렬히 반응하고 폭발한다. 다음 각 물음에 답을 쓰시오.\n가. 위험물일 조건\n나. 하이드라진과의 폭발반응식","a":"가. 36중량퍼센트 이상\n나. 2H2O2 + N2H4 → N2 + 4H2O","h":"하이드라진과 격렬히 반응하는 제6류 위험물은 과산화수소이며, 농도 36중량퍼센트 이상이어야 위험물이다. 반응하면 질소와 물이 생기고 계수는 2:1:1:4다.","t":"kan","칸":[{"a":"36중량퍼센트 이상","syn":["36","36wt%","36wt%이상","36중량%","36중량%이상","36중량퍼센트","36%","36% 이상","36 중량퍼센트 이상"],"l":"가"},{"a":"2H2O2+N2H4→N2+4H2O","syn":["2H2O2+N2H4->N2+4H2O","2H2O2+N2H4=N2+4H2O","N2H4+2H2O2→N2+4H2O","N2H4+2H2O2->N2+4H2O"],"l":"나"}],"순서무관":false},{"id":"2020-1-18","y":2020,"r":1,"n":18,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"제조소등에서 위험물의 저장 및 취급에 관한 기준에 관한 내용이다. 다음 빈칸을 채우시오.\n가. 위험물을 저장 또는 취급하는 건축물 그 밖의 공작물 또는 설비는 당해 위험물의 성질에 따라 차광 또는 ( )를 실시하여야 한다.\n나. 위험물은 온도계, 습도계, 압력계 그 밖의 계기를 감시하여 당해 위험물의 성질에 맞는 적정한 온도, 습도 또는 ( )을 유지하도록 저장 또는 취급하여야 한다.\n다. 위험물을 용기에 수납하여 저장 또는 취급할 때에는 그 용기는 당해 위험물의 성질에 적응하고 파손·( )·균열 등이 없는 것으로 하여야 한다.\n라. ( )의 액체·증기 또는 가스가 새거나 체류할 우려가 있는 장소 또는 가연성의 미분이 현저하게 부유할 우려가 있는 장소에서는 전선과 전기기구를 완전히 접속하고 불꽃을 발하는 기계·기구·공구·신발 등을 사용하지 아니하여야 한다.\n마. 위험물을 ( ) 중에 보존하는 경우에는 당해 위험물이 보호액으로부터 노출되지 아니하도록 하여야 한다.","a":"가. 환기\n나. 압력\n다. 부식\n라. 가연성\n마. 보호액","h":"저장·취급 공통 기준은 차광·환기, 온도·습도·압력 유지, 용기의 파손·부식·균열 방지, 가연성 증기 체류 장소에서의 불꽃 금지, 보호액 속 보존 시 노출 방지다. 문장 흐름 그대로 빈칸 단어를 채운다.","t":"kan","칸":[{"a":"환기","l":"가"},{"a":"압력","l":"나"},{"a":"부식","l":"다"},{"a":"가연성","syn":["가연성 증기","가연성가스"],"l":"라"},{"a":"보호액","l":"마"}],"순서무관":false},{"id":"2020-1-19","y":2020,"r":1,"n":19,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에서 정한 완공검사에 대한 내용이다. 다음 물음에 답하시오.\n가. 위험물을 저장 또는 취급하는 탱크로서 대통령령이 정하는 탱크가 있는 제조소등의 설치, 변경에 관하여 완공검사를 받기 전에 받아야 하는 검사는 무엇인지 쓰시오.\n나. 다음 시설의 완공검사 신청시기를 쓰시오.\n • 이동탱크저장소\n • 지하탱크가 있는 제조소등\n다. 완공검사를 실시한 결과 당해 제조소등이 규정에 의한 기술기준에 적합하다고 인정하는 때에 시·도지사는 어떤 서류를 교부해야 하는지 쓰시오.","a":"가. 탱크안전성능검사\n나. 이동탱크저장소 : 이동저장탱크를 완공하고 상치장소를 확보한 후\n   지하탱크가 있는 제조소등 : 지하탱크를 매설하기 전\n다. 완공검사합격확인증","h":"탱크가 있는 제조소등은 완공검사 전에 탱크안전성능검사를 받는다. 신청 시기는 지하탱크는 매설하기 전, 이동탱크는 탱크를 완공하고 상치장소를 확보한 뒤다. 합격하면 시·도지사가 완공검사합격확인증을 준다.","t":"kan","칸":[{"a":"탱크안전성능검사","syn":["탱크 안전성능검사","탱크안전성능","탱크안전성능 검사"],"l":"가"},{"a":"이동저장탱크를 완공하고 상치장소를 확보한 후","k":[["상치"],["완공","확보"]],"l":"나-이동탱크"},{"a":"지하탱크를 매설하기 전","k":[["매설","묻"],["전"]],"l":"나-지하탱크"},{"a":"완공검사합격확인증","syn":["완공검사합격증","완공검사 합격확인증","합격확인증","완공검사확인증"],"l":"다"}],"순서무관":false},{"id":"2020-1-20","y":2020,"r":1,"n":20,"p":"반응식","kw":"열분해","pt":5,"q":"위험물안전관리법령상 제5류 위험물에 대한 내용이다. [보기]에 대하여 다음 물음에 답하시오.\n[보기]\n나이트로글리세린, 트라이나이트로톨루엔, 트라이나이트로페놀, 과산화벤조일, 다이나이트로벤젠\n가. 질산에스터류에 속하는 위험물을 모두 고르시오.\n나. 상온에서는 액체이고 영하의 온도에서는 고체인 위험물의 분해반응식을 쓰시오.","a":"가. 나이트로글리세린\n나. 4C3H5(ONO2)3 → 12CO2 + 10H2O + 6N2 + O2","h":"질산에스터류는 보기 중 나이트로글리세린 하나뿐이다. 나머지는 나이트로화합물(TNT·피크린산·다이나이트로벤젠)과 유기과산화물(과산화벤조일)이다. 나이트로글리세린은 상온에서 액체이고 분해하면 이산화탄소, 물, 질소, 산소가 나온다.","t":"kan","칸":[{"a":"나이트로글리세린","syn":["니트로글리세린","나이트로글리세롤","니트로글리세롤","NG","nitroglycerin","나이트로 글리세린"],"l":"가"},{"a":"4C3H5(ONO2)3→12CO2+10H2O+6N2+O2","syn":["4C3H5(ONO2)3->12CO2+10H2O+6N2+O2","4C3H5(ONO2)3=12CO2+10H2O+6N2+O2","4C3H5(ONO2)3→12CO2+6N2+O2+10H2O","4C3H5(ONO2)3->12CO2+6N2+O2+10H2O","4C3H5N3O9→12CO2+10H2O+6N2+O2"],"l":"나"}],"순서무관":false},{"id":"2020-2-01","y":2020,"r":2,"n":1,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"탄화칼슘 32g이 물과 반응하여 생성되는 기체가 완전 연소하기 위한 산소의 부피(L)를 구하시오.","a":"① CaC2 32g, 분자량 64 → 0.5몰, C2H2 0.5몰 생성\n② 2C2H2 + 5O2 → 4CO2 + 2H2O\n③ V = (32×0.082×273)/(1×64) × 5/2 = 11.193 × 5/2\n④ 27.98L","h":"탄화칼슘 1몰에서 아세틸렌 1몰이 나오고, 아세틸렌 2몰을 태우는 데 산소 5몰이 든다. 아세틸렌 부피에 5/2를 곱해 산소 부피를 구한다.","tp":"W01","t":"calc","e":0.5,"ka":"27.98"},{"id":"2020-2-02","y":2020,"r":2,"n":2,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"위험물안전관리법령에서 정한 농도가 36wt% 미만일 경우 위험물에서 제외되는 제6류 위험물에 대하여 다음 물음에 답하시오.\n가. 산소가 생성되는 반응식\n나. 운반용기 외부에 표시하여야 할 주의사항\n다. 위험등급","a":"가. 2H2O2 → 2H2O + O2\n나. 가연물접촉주의\n다. I등급","h":"36중량퍼센트 미만이면 위험물에서 빠지는 제6류는 과산화수소다. MnO2 촉매로 분해되어 물과 산소가 나온다. 제6류 위험물은 모두 I등급이고 운반 시 가연물접촉주의를 표시한다.","t":"kan","칸":[{"a":"2H2O2→2H2O+O2","syn":["2H2O2->2H2O+O2","2H2O2=2H2O+O2","H2O2→H2O+1/2O2","H2O2->H2O+1/2O2"],"l":"가"},{"a":"가연물접촉주의","syn":["가연물 접촉주의","가연물접촉 주의","가연물접촉","가연물 접촉 주의"],"l":"나"},{"a":"I등급","syn":["Ⅰ등급","1등급","I","Ⅰ","1","I 등급","1급","Ⅰ급"],"l":"다"}],"순서무관":false},{"id":"2020-2-03","y":2020,"r":2,"n":3,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"벤젠(C6H6) 16g이 완전 증발 시 1atm, 90℃에서 부피는 몇 L인지 쓰시오.","a":"① C6H6 16g, 분자량 78, 1atm, 90℃(363K)\n② V = wRT/PM\n③ V = (16×0.082×363)/(1×78)\n④ 6.11L","h":"화학반응이 없는 경우라 이상기체 상태방정식에 질량·분자량·온도를 그대로 넣는다. 온도는 90+273 = 363K다.","t":"calc","e":0.05,"ka":"6.11"},{"id":"2020-2-04","y":2020,"r":2,"n":4,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제4류 위험물 중 분자량이 27, 끓는점이 26℃이며 맹독성인 물질이다. 안정제로는 무기산을 사용한다. 이 위험물에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 증기비중","a":"가. HCN\n나. 0.93","h":"분자량 27, 끓는점 26℃인 맹독성 제4류 위험물은 사이안화수소다. 분자량 27을 공기 29로 나누면 0.93으로 공기보다 약간 가볍다.","t":"kan","칸":[{"a":"HCN","syn":["사이안화수소","시안화수소","청산","사이안화 수소","시안화 수소","CHN","H-C≡N","HC≡N"],"l":"가"},{"a":"0.93","e":0.01,"l":"나"}],"순서무관":false},{"id":"2020-2-05","y":2020,"r":2,"n":5,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"적린과 염소산칼륨이 혼촉 시 폭발의 위험이 있다. 다음 물음에 답하시오.\n가. 적린과 염소산칼륨이 혼촉하여 폭발반응하는 반응식\n나. 위 반응에서 생성되는 기체가 물과 반응하여 생성되는 물질의 명칭","a":"가. 6P + 5KClO3 → 3P2O5 + 5KCl\n나. 인산","h":"적린과 염소산칼륨이 섞이면 오산화인과 염화칼륨이 생기며 폭발한다. 오산화인은 물과 반응해 인산(H3PO4)이 된다. 이때 P2O5 + 3H2O → 2H3PO4다.","t":"kan","칸":[{"a":"6P+5KClO3→3P2O5+5KCl","syn":["6P+5KClO3->3P2O5+5KCl","6P+5KClO3=3P2O5+5KCl","6P+5KClO3→5KCl+3P2O5","6P+5KClO3->5KCl+3P2O5"],"l":"가"},{"a":"인산","syn":["H3PO4","오르토인산","인산염","phosphoric acid"],"l":"나"}],"순서무관":false},{"id":"2020-2-06","y":2020,"r":2,"n":6,"p":"반응식","kw":"물과 반응","pt":5,"q":"제3류 위험물인 물질이 물과 반응하여 가연성의 기체를 발생시키는 반응식을 쓰시오.\n가. 트라이메틸알루미늄과 물\n나. 트라이에틸알루미늄과 물","a":"가. (CH3)3Al + 3H2O → Al(OH)3 + 3CH4\n나. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6","h":"알킬알루미늄은 물과 반응해 수산화알루미늄과 알케인 3몰을 낸다. 메틸은 메테인(CH4), 에틸은 에테인(C2H6)이 나오므로 알킬기 이름으로 기체를 구별한다.","t":"kan","칸":[{"a":"(CH3)3Al+3H2O→Al(OH)3+3CH4","syn":["(CH3)3Al+3H2O->Al(OH)3+3CH4","(CH3)3Al+3H2O=Al(OH)3+3CH4","(CH3)3Al+3H2O→3CH4+Al(OH)3","(CH3)3Al+3H2O->3CH4+Al(OH)3"],"l":"가"},{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"나"}],"순서무관":false},{"id":"2020-2-07","y":2020,"r":2,"n":7,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"트라이나이트로페놀에 대한 다음 물음에 답하시오.\n가. 구조식\n나. 품명\n다. 지정수량","a":"가. 벤젠고리의 2, 4, 6번 자리에 NO2 세 개, 1번 자리에 OH 한 개가 붙은 구조\n나. 나이트로화합물\n다. 제1종 10kg","h":"트라이나이트로페놀(피크린산)은 페놀의 2, 4, 6번 수소를 NO2로 바꾼 물질이다. 같은 자리에 CH3가 붙으면 TNT다. 제5류 나이트로화합물이고 제1종이라 지정수량은 10kg이다.","ai":"2020-2-07_a.svg","t":"kan","칸":[{"a":"나이트로화합물","syn":["니트로화합물","나이트로 화합물","니트로 화합물","nitro화합물"],"l":"나"},{"a":"제1종 10kg","syn":["10kg","10","제1종","1종","1종 10kg","10킬로그램","제1종10kg","10kg(제1종)"],"l":"다"}],"순서무관":false},{"id":"2020-2-08","y":2020,"r":2,"n":8,"p":"반응식","kw":"열분해","pt":5,"q":"다음 물질이 열분해하여 산소를 발생하는 반응식을 쓰시오.\n가. 아염소산나트륨\n나. 염소산나트륨\n다. 과염소산나트륨","a":"가. NaClO2 → NaCl + O2\n나. 2NaClO3 → 2NaCl + 3O2\n다. NaClO4 → NaCl + 2O2","h":"아염소산·염소산·과염소산 나트륨이 열분해하면 모두 염화나트륨과 산소가 나온다. 식 하나당 산소는 NaClO2에서 1분자, NaClO3에서 1.5분자, NaClO4에서 2분자이며, 염소산은 정수로 맞추려고 2NaClO3 → 2NaCl + 3O2로 쓴다.","t":"kan","칸":[{"a":"NaClO2→NaCl+O2","syn":["NaClO2->NaCl+O2","NaClO2=NaCl+O2","2NaClO2→2NaCl+2O2","2NaClO2->2NaCl+2O2"],"l":"가"},{"a":"2NaClO3→2NaCl+3O2","syn":["2NaClO3->2NaCl+3O2","2NaClO3=2NaCl+3O2","NaClO3→NaCl+3/2O2","NaClO3->NaCl+3/2O2"],"l":"나"},{"a":"NaClO4→NaCl+2O2","syn":["NaClO4->NaCl+2O2","NaClO4=NaCl+2O2"],"l":"다"}],"순서무관":false},{"id":"2020-2-09","y":2020,"r":2,"n":9,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제5류 위험물에 대하여 다음 [보기]의 물질을 보고 해당 위험등급별로 구분하시오 (단, 없으면 없음이라 표기하시오).\n[보기]\n하이드라진 유도체, 질산에스터류, 나이트로화합물, 아조화합물, 유기과산화물, 하이드록실아민\n가. I등급 :\n나. II등급 :\n다. III등급 :","a":"가. I등급 : 지정수량 10kg인 제5류 위험물(제1종)\n나. II등급 : 지정수량 10kg 외의 제5류 위험물(제2종)\n다. III등급 : 없음","h":"제5류에는 III등급이 없다. 품명 표에서 질산에스터류부터 하이드라진 유도체까지가 모두 제1종(I등급, 10kg)과 제2종(II등급, 100kg)에 걸쳐 있어서, 등급은 품명이 아니라 지정수량으로 가른다. 10kg이면 I등급, 10kg이 아닌 것은 II등급이다.","t":"kan","칸":[{"a":"지정수량 10kg인 제5류 위험물(제1종)","k":[["제1종","1종","10kg인","10kg이","유기과산화물","질산에스터","질산에스테르"]],"l":"가"},{"a":"지정수량 10kg 외의 제5류 위험물(제2종)","k":[["제2종","2종","10kg 외","10kg외","하이드라진","아조","하이드록실","나이트로화합물","니트로화합물"]],"l":"나"},{"a":"없음","syn":["없다","해당없음","해당 없음","없음.","-","x"],"l":"다"}],"순서무관":false},{"id":"2020-2-10","y":2020,"r":2,"n":10,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물안전관리법에서 정한 위험물 운반에 관한 기준이다. 지정수량의 10배 이상을 취급하는 경우 위험물의 혼재에 관하여 다음 빈칸에 ○, ×표를 하시오.\n| 위험물의 구분 | 제1류 | 제2류 | 제3류 | 제4류 | 제5류 | 제6류 |\n| 제1류 | — |   |   |   |   |\n| 제2류 |   | — |   |   |   |\n| 제3류 |   |   | — |   |   |\n| 제4류 |   |   |   | — |   |\n| 제5류 |   |   |   |   | — |\n| 제6류 |   |   |   |   |   | — |","a":"제1류 : 제6류만 ○ (제2·3·4·5류 ×)\n제2류 : 제4류, 제5류 ○ (제1·3·6류 ×)\n제3류 : 제4류만 ○ (제1·2·5·6류 ×)\n제4류 : 제2류, 제3류, 제5류 ○ (제1·6류 ×)\n제5류 : 제2류, 제4류 ○ (제1·3·6류 ×)\n제6류 : 제1류만 ○ (제2·3·4·5류 ×)","h":"지정수량의 1/10을 넘으면 혼재 가능 조합은 4류-2·3류, 5류-2·4류, 6류-1류뿐이다. 표는 대칭이므로 한쪽만 채우고 거울처럼 옮기면 된다."},{"id":"2020-2-11","y":2020,"r":2,"n":11,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"위험물안전관리법령에 따른 소화설비 적응성에 관한 내용이다. 다음 소화설비의 적응성이 있는 경우 빈칸에 ○표를 하시오.\n| 소화설비의 구분 | 제1류 알칼리금속 과산화물등 | 제1류 그 밖의 것 | 제2류 철분·금속분·마그네슘등 | 제2류 인화성고체 | 제2류 그 밖의 것 | 제3류 금수성물질 | 제3류 그 밖의 것 | 제4류 | 제5류 | 제6류 |\n| 옥내소화전 또는 옥외소화전설비 |   |   |   |   |   |   |   |   |   |\n| 물분무등소화설비 : 물분무소화설비 |   |   |   |   |   |   |   |   |   |\n| 물분무등소화설비 : 포소화설비 |   |   |   |   |   |   |   |   |   |\n| 물분무등소화설비 : 불활성가스소화설비 |   |   |   |   |   |   |   |   |   |\n| 물분무등소화설비 : 할로젠화합물소화설비 |   |   |   |   |   |   |   |   |   |","a":"옥내·옥외소화전설비 : 제1류 그 밖의 것, 제2류 인화성고체, 제2류 그 밖의 것, 제3류 그 밖의 것, 제5류, 제6류\n물분무소화설비·포소화설비 : 제1류 그 밖의 것, 제2류 인화성고체, 제2류 그 밖의 것, 제3류 그 밖의 것, 제4류, 제5류, 제6류\n불활성가스소화설비·할로젠화합물소화설비 : 제2류 인화성고체, 제4류","h":"소화전은 물로 끄는 방식이라 제4류에는 쓰지 않고, 물분무와 포는 질식 효과가 있어 제4류까지 포함한다. 불활성가스와 할로젠화합물은 질식·억제 소화라 제2류 인화성고체와 제4류만 해당한다."},{"id":"2020-2-12","y":2020,"r":2,"n":12,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물인 아세트알데하이드에 대하여 다음 물음에 답하시오.\n가. 옥외저장탱크 중 압력탱크 외의 탱크에 저장할 경우 저장소의 온도를 쓰시오.\n나. 아세트알데하이드의 연소범위가 4.1~57%일 경우 위험도를 구하시오.\n다. 아세트알데하이드가 공기 중에서 산화 시 생성되는 물질의 명칭을 쓰시오.","a":"가. 15℃ 이하\n나. 위험도 = (57-4.1)/4.1 = 12.9\n다. 초산(아세트산)","h":"압력탱크가 아닌 옥외저장탱크에 아세트알데하이드를 두는 온도는 15℃ 이하다. 위험도는 (상한-하한)/하한으로 구한다. 산화하면 아세트산이 되고 에탄올이 한 단계 앞이다.","t":"kan","칸":[{"a":"15℃","syn":["15","15도","15℃ 이하","15도 이하"],"l":"가"},{"a":"12.9","e":0.1,"l":"나"},{"a":"초산","syn":["아세트산","아세틱애시드","CH3COOH","acetic acid","아세트 산","초산(아세트산)","아세트산(초산)"],"l":"다"}],"순서무관":false},{"id":"2020-2-13","y":2020,"r":2,"n":13,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령에 따른 위험물 저장·취급기준이다. 다음 빈칸을 채우시오.\n가. ( ) 위험물은 불티·불꽃·고온체와의 접근이나 과열·충격 또는 마찰을 피하여야 한다.\n나. ( ) 위험물은 가연물과의 접촉·혼합이나 분해를 촉진하는 물품과의 접근 또는 과열을 피하여야 한다.\n다. ( ) 위험물은 불티·불꽃·고온체와의 접근 또는 과열을 피하고, 함부로 증기를 발생시키지 아니하여야 한다.","a":"가. 제5류\n나. 제6류\n다. 제4류","h":"불티·불꽃·고온체 접근과 과열·충격·마찰을 피하는 쪽은 제5류, 가연물 접촉과 분해 촉진 물품을 피하는 쪽은 제6류, 증기를 함부로 내지 않는 쪽은 제4류다. 제1류도 가연물 접촉을 피하지만 충격·마찰이 함께 들어간다.","t":"kan","칸":[{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"가"},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"나"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"다"}],"순서무관":false},{"id":"2020-2-14","y":2020,"r":2,"n":14,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 품명, 지정수량을 쓰시오.\n가. KIO3\n나. AgNO3\n다. KMnO4","a":"가. 아이오딘산염류, 300kg\n나. 질산염류, 300kg\n다. 과망가니즈산염류, 1,000kg","h":"KIO3는 아이오딘산염류(300kg), AgNO3는 질산염류(300kg), KMnO4는 과망가니즈산염류(1,000kg)이며 모두 제1류다. 과망가니즈산염류가 지정수량이 가장 크다.","t":"kan","칸":[{"a":"아이오딘산염류, 300kg","k":[["아이오딘","요오드","옥소"],["300"]],"l":"가"},{"a":"질산염류, 300kg","k":[["질산염","질산 염"],["300"]],"l":"나"},{"a":"과망가니즈산염류, 1000kg","k":[["과망가","과망간","퍼망"],["1000","1,000"]],"l":"다"}],"순서무관":false},{"id":"2020-2-15","y":2020,"r":2,"n":15,"p":"계산","kw":"소요단위","pt":5,"q":"위험물안전관리법령에서 정한 소화설비의 소요단위에 관한 내용이다. 다음 내용을 보고 물음에 답하시오.\n옥내저장소\n• 내화구조\n• 연면적 150m2\n• 에탄올 1,000L, 등유 1,500L, 동식물유류 20,000L, 특수인화물 500L\n가. 옥내저장소의 소요단위\n나. 위 위험물을 저장할 경우 소요단위","a":"가. ① 내화구조 저장소는 150m2가 1소요단위\n② 소요단위 = 연면적/150\n③ 150/150\n④ 1소요단위\n나. ① 1소요단위 = 지정수량×10\n② 에탄올 400L, 등유 1,000L, 동식물유류 10,000L, 특수인화물 50L\n③ 1,000/4,000 + 1,500/10,000 + 20,000/100,000 + 500/500 = 0.25+0.15+0.2+1 = 1.6\n④ 1.6소요단위","h":"저장소 건축물은 내화구조 150m2, 비내화구조 75m2가 1소요단위이고 위험물은 지정수량의 10배가 1소요단위다. 품명마다 나눈 값을 더하면 1.6이고, 법령(시행규칙 별표 17)에 올림 규정이 없어 1.6을 그대로 쓴다. 특수인화물 한 항목이 1을 차지한다.","tp":"W06","t":"kan","칸":[{"a":"1","e":0.01,"l":"가"},{"a":"1.6","e":0.05,"l":"나"}],"순서무관":false},{"id":"2020-2-16","y":2020,"r":2,"n":16,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물 중 비수용성인 위험물을 보기에서 고르시오.\n[보기]\n이황화탄소, 아세트알데하이드, 아세톤, 스틸렌, 클로로벤젠","a":"이황화탄소, 스틸렌, 클로로벤젠","h":"아세트알데하이드와 아세톤은 물에 녹는 수용성이고, 이황화탄소·스틸렌·클로로벤젠은 물에 녹지 않는다. 특수인화물 중에서도 이황화탄소는 비수용성이다.","t":"kan","칸":[{"a":"이황화탄소","syn":["CS2","이황화 탄소"]},{"a":"스틸렌","syn":["스타이렌","스티렌","스타이렌","스틸렌(스타이렌)","styrene"]},{"a":"클로로벤젠","syn":["클로로벤젠","염화벤젠","클로로 벤젠","클로르벤젠"]}],"순서무관":true},{"id":"2020-2-17","y":2020,"r":2,"n":17,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령에서 정한 인화점 측정 방법이다. 다음 내용을 보고 해당하는 인화점 측정 시험방법의 종류를 쓰시오.\n가. ( )인화점측정기\n • 시험장소는 1기압, 무풍의 장소로 할 것\n • 시료컵을 설정온도까지 가열 또는 냉각하여 시험물품 2mL를 시료컵에 넣고 즉시 뚜껑 및 개폐기를 닫을 것\n • 시험불꽃을 점화하고 화염의 크기를 직경 4mm가 되도록 조정할 것\n나. ( )인화점측정기\n • 시험장소는 1기압, 무풍의 장소로 할 것\n • 시료컵에 시험물품 50cm3를 넣고 시험물품의 표면의 기포를 제거한 후 뚜껑을 덮을 것\n • 시험불꽃을 점화하고 화염의 크기를 직경이 4mm가 되도록 조정할 것\n다. ( )인화점측정기\n • 시험장소는 1기압, 무풍의 장소로 할 것\n • 시료컵의 표선(標線)까지 시험물품을 채우고 시험물품의 표면의 기포를 제거할 것\n • 시험불꽃을 점화하고 화염의 크기를 직경이 4mm가 되도록 조정할 것","a":"가. 신속평형법\n나. 태그밀폐식\n다. 클리브랜드 개방컵","h":"시료량이 2mL면 신속평형법, 50cm3면 태그밀폐식, 시료컵 표선까지 채우면 클리브랜드 개방컵이다. 시료량 숫자로 구별한다.","t":"kan","칸":[{"a":"신속평형법","syn":["신속평형","신속 평형법","신속평형법 인화점측정기"],"l":"가"},{"a":"태그밀폐식","syn":["태그 밀폐식","태그밀폐","태그식","tag"],"l":"나"},{"a":"클리브랜드개방컵","syn":["클리브랜드 개방컵","클리블랜드개방컵","클리블랜드 개방컵","클리브랜드개방식","클리블랜드개방식","클리브랜드","클리블랜드"],"l":"다"}],"순서무관":false},{"id":"2020-2-18","y":2020,"r":2,"n":18,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"제1종 판매취급소 중 위험물을 배합하는 실에 관한 내용이다. 다음 빈칸을 채우시오.\n가. 바닥면적은 ( )m2 이상 ( )m2 이하로 할 것\n나. ( ) 또는 ( )의 벽으로 구획할 것\n다. 바닥은 위험물이 침투하지 아니하는 구조로 하여 적당한 경사를 두고 ( )를 할 것\n라. 출입구에는 수시로 열 수 있는 자동폐쇄식의 ( )을 설치할 것\n마. 출입구 문턱의 높이는 바닥면으로부터 ( )m 이상으로 할 것","a":"가. 6, 15\n나. 내화구조, 불연재료\n다. 집유설비\n라. 60분+ 방화문 또는 60분 방화문\n마. 0.1","h":"배합하는 실은 바닥면적 6m2 이상 15m2 이하, 내화구조 또는 불연재료 벽으로 구획하며, 바닥은 침투가 없게 하고 집유설비를 둔다. 출입구에는 자동폐쇄식 방화문을 달고 문턱은 0.1m 이상으로 한다.","t":"kan","칸":[{"a":"6","syn":["6m2","6㎡"],"l":"가-하한"},{"a":"15","syn":["15m2","15㎡"],"l":"가-상한"},{"a":"내화구조, 불연재료","k":[["내화구조","내화"],["불연재료","불연"]],"l":"나"},{"a":"집유설비","syn":["집유 설비","집유"],"l":"다"},{"a":"60분+방화문","syn":["60분+ 방화문","60분 방화문","60분방화문","방화문","갑종방화문","60분+방화문 또는 60분방화문","60분+방화문·60분방화문","60분+방화문 60분방화문"],"l":"라"},{"a":"0.1","syn":["0.1m","0.1미터","10cm"],"l":"마"}],"순서무관":false},{"id":"2020-2-19","y":2020,"r":2,"n":19,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에 따른 자체소방대에 관한 내용이다. 다음 물음에 알맞은 답을 쓰시오.\n가. 자체소방대를 두어야 하는 경우를 [보기]에서 모두 쓰시오.\n [보기]\n ① 염소산염류 250톤 제조소\n ② 염소산염류 250톤 일반취급소\n ③ 특수인화물 250kL 제조소\n ④ 특수인화물 250kL 충전하는 일반취급소\n나. 자체소방대에 두는 화학소방자동차 1대당 필요한 소방대원 인원수는 몇 명인지 쓰시오.\n다. 다음 중 틀린 것을 고르시오 (단, 없으면 없음이라고 표기하시오).\n [보기]\n ① 다른 사업소 등과 상호협정을 체결한 경우 그 모든 사업소를 하나의 사업소로 본다.\n ② 포수용액 방사차에는 소화약액탱크 및 소화약액혼합장치를 비치할 것\n ③ 포수용액 방사차는 자체 소방차 대수의 2/3 이상이어야 하고 포수용액의 방사능력은 3,000L 이상일 것\n ④ 10만L 이상의 포수용액을 방사할 수 있는 양의 소화약제를 비치할 것\n라. 자체소방대를 설치하지 않은 제조소등의 관계인의 벌칙을 쓰시오.","a":"가. ③\n나. 5명\n다. ③\n라. 1년 이하의 징역 또는 1천만원 이하의 벌금","h":"자체소방대는 제4류 위험물 최대수량이 지정수량 3천배 이상인 제조소·일반취급소에 둔다. ③은 특수인화물 250kL가 5,000배라 해당하고 ①②는 제1류, ④는 충전하는 일반취급소라 제외다. 포수용액 방사차의 방사능력은 매분 2,000L 이상이므로 ③이 틀리고, 화학소방차 1대에 대원 5명이다.","t":"kan","칸":[{"a":"③","syn":["3","3번","(3)"],"l":"가"},{"a":"5","syn":["5명","5인","5명 이상"],"l":"나"},{"a":"③","syn":["3","3번","(3)"],"l":"다"},{"a":"1년 이하의 징역 또는 1천만원 이하의 벌금","k":[["1년"],["1천만","1000만","1,000만","천만"]],"l":"라"}],"순서무관":false},{"id":"2020-2-20","y":2020,"r":2,"n":20,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음은 방유제 내에 옥외탱크저장소의 설치된 그림이다. 다음 물음에 알맞은 답을 쓰시오.\n㉠ 내용적 5천만L에 휘발유를 3천만L 저장하는 옥외저장탱크\n㉡ 내용적 1억2천만L에 경유를 8천만L 저장하는 옥외저장탱크\n가. ㉠ 탱크의 최대용량\n나. ㉠, ㉡ 탱크 2기를 설치한 해당 방유제의 용량(공간용적 10/100)\n다. ㉢의 명칭","a":"가. ① ㉠ 내용적 5천만L, 공간용적 최소 5%\n② 최대용량 = 내용적×(1-0.05)\n③ 50,000,000×0.95\n④ 4,750만L\n나. ① ㉡ 내용적 1억 2천만L, 공간용적 10%\n② 방유제 용량 = 최대탱크용량×1.1\n③ 120,000,000×0.9×1.1\n④ 1억 1천 880만L\n다. 간막이둑","h":"탱크 최대용량은 내용적에서 공간용적(5~10%)을 뺀 값이고, 용량을 크게 잡으려면 공간용적을 5%로 둔다. 방유제 용량은 가장 큰 탱크 용량의 110% 이상이라 ㉡ 기준으로 계산한다. 용량 1,000만L 이상 탱크에는 간막이둑을 설치한다.","img":["2020-2-20.svg"],"tp":"W04","t":"kan","칸":[{"a":"47500000","syn":["47,500,000","4750만","4,750만","4750만L","4,750만L","47500kL","47,500kL","4천750만","4천 750만","4천750만L","47500000L","47,500,000L"],"l":"가"},{"a":"118800000","syn":["118,800,000","11880만","11,880만","1억1880만","1억 1천 880만","1억1천880만","1억1880만L","118800kL","118,800kL","118800000L","118,800,000L","11880만L","1억 1천880만"],"l":"나"},{"a":"간막이둑","syn":["간막이 둑","칸막이둑","칸막이 둑","간막이"],"l":"다"}],"순서무관":false},{"id":"2020-3-01","y":2020,"r":3,"n":1,"p":"반응식","kw":"열분해","pt":5,"q":"제1종 분말소화약제의 각 온도에서 분해반응식을 쓰시오.\n가. 270℃\n나. 850℃","a":"가. 2NaHCO3 → Na2CO3 + CO2 + H2O\n나. 2NaHCO3 → Na2O + 2CO2 + H2O","h":"제1종 분말(탄산수소나트륨)은 270℃에서 탄산나트륨, 이산화탄소, 물로 분해되고, 850℃에서는 산화나트륨, 이산화탄소 2몰, 물로 분해된다. 고온에서는 이산화탄소 계수가 2로 늘어난다.","t":"kan","칸":[{"a":"2NaHCO3→Na2CO3+CO2+H2O","syn":["2NaHCO3->Na2CO3+CO2+H2O","2NaHCO3=Na2CO3+CO2+H2O","2NaHCO3→Na2CO3+H2O+CO2","2NaHCO3->Na2CO3+H2O+CO2"],"l":"가"},{"a":"2NaHCO3→Na2O+2CO2+H2O","syn":["2NaHCO3->Na2O+2CO2+H2O","2NaHCO3=Na2O+2CO2+H2O","2NaHCO3→Na2O+H2O+2CO2","2NaHCO3->Na2O+H2O+2CO2"],"l":"나"}],"순서무관":false},{"id":"2020-3-02","y":2020,"r":3,"n":2,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 보기의 동식물유를 건성유( 가 ), 반건성유( 나 ), 불건성유( 다 )로 구분하시오.\n쌀겨기름, 목화씨기름, 피마자유, 아마인유, 야자유, 들기름","a":"가. 건성유 : 아마인유, 들기름\n나. 반건성유 : 쌀겨기름, 목화씨기름\n다. 불건성유 : 야자유, 피마자유","h":"동식물유류는 아이오딘값 130 이상이 건성유(아마인유, 들기름), 100~130 미만이 반건성유(쌀겨기름, 목화씨기름), 100 미만이 불건성유(야자유, 피마자유)다. 지정수량은 모두 10,000L다.","t":"kan","칸":[{"a":"아마인유, 들기름","k":[["아마인","아마"],["들기름","들깨"]],"l":"가"},{"a":"쌀겨기름, 목화씨기름","k":[["쌀겨","미강"],["목화씨","면실","목화"]],"l":"나"},{"a":"야자유, 피마자유","k":[["야자"],["피마자","아주까리"]],"l":"다"}],"순서무관":false},{"id":"2020-3-03","y":2020,"r":3,"n":3,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음과 같은 원통형 탱크가 있다. 물음에 답하시오.\n(가로형 원통형 탱크 : 반지름 3m, 몸통 8m, 양쪽 경판 2m씩)\n가. 탱크의 내용적(m3)\n나. 공간용적 10%일 때, 탱크의 용량(m3)","a":"가. ① 반지름 3m, 몸통 l=8m, 경판 l1=l2=2m\n② 내용적 = πr2(l + (l1+l2)/3)\n③ π×3²×(8 + (2+2)/3)\n④ 263.89m3\n나. ① 공간용적 10%\n② 용량 = 내용적×(1-0.1)\n③ 263.89×0.9\n④ 237.50m3","h":"양쪽이 볼록한 횡치 원통형 탱크의 내용적은 πr2(l+(l1+l2)/3)로 구한다. 경판 길이는 3으로 나눠 더한다. 용량은 여기에 (1-공간용적 비율)을 곱한다.","img":["2020-3-03.svg"],"tp":"W04","t":"kan","칸":[{"a":"263.89","e":0.5,"l":"가"},{"a":"237.5","e":0.5,"l":"나"}],"순서무관":false},{"id":"2020-3-04","y":2020,"r":3,"n":4,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 화학식과 지정수량을 쓰시오.\n가. 벤조일퍼옥사이드\n나. 과망가니즈산암모늄\n다. 인화아연","a":"가. (C6H5CO)2O2, 100kg\n나. NH4MnO4, 1,000kg\n다. Zn3P2, 300kg","h":"벤조일퍼옥사이드는 제5류 유기과산화물 제2종(100kg), 과망가니즈산암모늄은 제1류 과망가니즈산염류(1,000kg), 인화아연은 제3류 금속인화합물(300kg)이다. 유별부터 정하면 지정수량이 따라온다.","t":"kan","칸":[{"a":"(C6H5CO)2O2","syn":["C14H10O4","(C6H5CO)2O2","C6H5CO-O-O-COC6H5","(C6H5CO-O)2","C6H5COOOCOC6H5"],"l":"가-화학식"},{"a":"100kg","syn":["100","100 kg"],"l":"가-지정수량"},{"a":"NH4MnO4","syn":["NH4(MnO4)","과망가니즈산암모늄"],"l":"나-화학식"},{"a":"1000kg","syn":["1000","1,000","1,000kg","1000 kg"],"l":"나-지정수량"},{"a":"Zn3P2","syn":["Zn3 P2","Zn3(P)2"],"l":"다-화학식"},{"a":"300kg","syn":["300","300 kg"],"l":"다-지정수량"}],"순서무관":false},{"id":"2020-3-05","y":2020,"r":3,"n":5,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물이 물과 반응할 시 화학반응식을 쓰시오.\n가. K2O2(제1류 위험물)\n나. Mg(제2류 위험물)\n다. Na(제3류 위험물)","a":"가. 2K2O2 + 2H2O → 4KOH + O2\n나. Mg + 2H2O → Mg(OH)2 + H2\n다. 2Na + 2H2O → 2NaOH + H2","h":"과산화칼륨은 물과 반응해 수산화칼륨과 산소를 내고, 마그네슘과 나트륨은 수산화물과 수소를 낸다. 산소가 나오는 쪽은 제1류 알칼리금속 과산화물뿐이고 나머지는 수소다.","t":"kan","칸":[{"a":"2K2O2+2H2O→4KOH+O2","syn":["2K2O2+2H2O->4KOH+O2","2K2O2+2H2O=4KOH+O2","K2O2+H2O→2KOH+1/2O2","K2O2+H2O->2KOH+1/2O2"],"l":"가"},{"a":"Mg+2H2O→Mg(OH)2+H2","syn":["Mg+2H2O->Mg(OH)2+H2","Mg+2H2O=Mg(OH)2+H2"],"l":"나"},{"a":"2Na+2H2O→2NaOH+H2","syn":["2Na+2H2O->2NaOH+H2","2Na+2H2O=2NaOH+H2","Na+H2O→NaOH+1/2H2"],"l":"다"}],"순서무관":false},{"id":"2020-3-06","y":2020,"r":3,"n":6,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 반응의 화학반응식을 쓰시오.\n가. 트라이메틸알루미늄과 물\n나. 트라이메틸알루미늄과 산소\n다. 트라이에틸알루미늄과 물\n라. 트라이에틸알루미늄과 산소","a":"가. (CH3)3Al + 3H2O → Al(OH)3 + 3CH4\n나. 2(CH3)3Al + 12O2 → 6CO2 + 9H2O + Al2O3\n다. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n라. 2(C2H5)3Al + 21O2 → 12CO2 + 15H2O + Al2O3","h":"알킬알루미늄은 물과 반응하면 수산화알루미늄과 알킬기에 대응하는 알케인이 나오고, 산소와는 이산화탄소·물·산화알루미늄이 된다. 연소식은 수소 원자 수가 홀수(9, 15)라 앞에 2를 붙인다. 메틸은 산소 12, 에틸은 산소 21을 쓴다.","t":"kan","칸":[{"a":"(CH3)3Al+3H2O→Al(OH)3+3CH4","syn":["(CH3)3Al+3H2O->Al(OH)3+3CH4","(CH3)3Al+3H2O=Al(OH)3+3CH4","(CH3)3Al+3H2O→3CH4+Al(OH)3","(CH3)3Al+3H2O->3CH4+Al(OH)3"],"l":"가"},{"a":"2(CH3)3Al+12O2→6CO2+9H2O+Al2O3","syn":["2(CH3)3Al+12O2->6CO2+9H2O+Al2O3","2(CH3)3Al+12O2=6CO2+9H2O+Al2O3","2(CH3)3Al+12O2→Al2O3+6CO2+9H2O","2(CH3)3Al+12O2->Al2O3+6CO2+9H2O"],"l":"나"},{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"다"},{"a":"2(C2H5)3Al+21O2→12CO2+15H2O+Al2O3","syn":["2(C2H5)3Al+21O2->12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2=12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2→Al2O3+12CO2+15H2O","2(C2H5)3Al+21O2->Al2O3+12CO2+15H2O"],"l":"라"}],"순서무관":false},{"id":"2020-3-07","y":2020,"r":3,"n":7,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"질산칼륨에 대하여 다음 물음에 답하시오.\n가. 위험등급\n나. 지정수량\n다. 품명\n라. 제조소에 설치하여야 하는 주의사항 게시판\n마. 열분해반응식","a":"가. II\n나. 300kg\n다. 질산염류\n라. 없음\n마. 2KNO3 → 2KNO2 + O2","h":"질산칼륨은 제1류 질산염류로 위험등급 II, 지정수량 300kg이다. 제1류 중 알칼리금속 과산화물만 물기엄금 게시판이 필요하므로 이 물질은 제조소 주의사항 게시판이 없다. 열분해하면 아질산칼륨과 산소가 나온다.","t":"kan","칸":[{"a":"II","syn":["Ⅱ","2","II등급","Ⅱ등급","2등급","II 등급","Ⅱ 등급","Ⅱ급","2급"],"l":"가"},{"a":"300kg","syn":["300","300 kg"],"l":"나"},{"a":"질산염류","syn":["질산염","질산 염류"],"l":"다"},{"a":"없음","syn":["없다","해당없음","해당 없음","-","없음."],"l":"라"},{"a":"2KNO3→2KNO2+O2","syn":["2KNO3->2KNO2+O2","2KNO3=2KNO2+O2","KNO3→KNO2+1/2O2","KNO3->KNO2+1/2O2"],"l":"마"}],"순서무관":false},{"id":"2020-3-08","y":2020,"r":3,"n":8,"p":"반응식","kw":"연소 반응","pt":5,"q":"탄화알루미늄과 물이 반응하여 생성되는 기체에 대하여 다음 물음에 답하시오.\n가. 연소반응식\n나. 연소범위\n다. 위험도","a":"가. CH4 + 2O2 → CO2 + 2H2O\n나. 5~15%\n다. 위험도 = (15-5)/5 = 2","h":"탄화알루미늄은 물과 반응해 수산화알루미늄과 메테인을 낸다(Al4C3 + 12H2O → 4Al(OH)3 + 3CH4). 메테인 연소식은 이산화탄소와 물이 나오고 계수가 1:2:1:2다. 연소범위는 5~15%이므로 위험도는 2다.","t":"kan","칸":[{"a":"CH4+2O2→CO2+2H2O","syn":["CH4+2O2->CO2+2H2O","CH4+2O2=CO2+2H2O"],"l":"가"},{"a":"5~15%","syn":["5-15","5~15","5∼15","5-15%","5~15 %","5% ~ 15%","5%~15%","5에서 15","5부터 15","5 ~ 15%","5 - 15%"],"l":"나"},{"a":"2","e":0.01,"l":"다"}],"순서무관":false},{"id":"2020-3-09","y":2020,"r":3,"n":9,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"다음 소화적응성이 있는 위험물을 보기에서 고르시오.\n[보기]\n• 제1류 위험물 중 알칼리금속의 과산화물\n• 제2류 위험물 중 인화성고체\n• 제3류 위험물(금수성물질 제외)\n• 제4류 위험물\n• 제5류 위험물\n• 제6류 위험물\n가. 불활성가스소화설비\n나. 옥외소화전설비\n다. 포소화설비","a":"가. 제2류 위험물 중 인화성고체, 제4류 위험물\n나. 제2류 위험물 중 인화성고체, 제3류 위험물(금수성물질 제외), 제5류 위험물, 제6류 위험물\n다. 제2류 위험물 중 인화성고체, 제3류 위험물(금수성물질 제외), 제4류 위험물, 제5류 위험물, 제6류 위험물","h":"불활성가스는 질식소화만 하므로 인화성고체와 제4류에 쓴다. 옥외소화전은 물을 쓰는 설비라 제4류와 금수성 물질, 알칼리금속 과산화물에는 쓰지 않는다. 포는 물과 질식 두 효과가 있어 옥외소화전 대상에 제4류가 더해진다.","t":"kan","칸":[{"a":"제2류 위험물 중 인화성고체, 제4류 위험물","k":[["인화성고체","인화성 고체"],["제4류","4류"]],"l":"가","no":["3류","5류","6류"]},{"a":"제2류 위험물 중 인화성고체, 제3류 위험물(금수성물질 제외), 제5류 위험물, 제6류 위험물","k":[["인화성고체","인화성 고체"],["제3류","3류"],["제5류","5류"],["6류"]],"l":"나","no":["4류"]},{"a":"제2류 위험물 중 인화성고체, 제3류 위험물(금수성물질 제외), 제4류 위험물, 제5류 위험물, 제6류 위험물","k":[["인화성고체","인화성 고체"],["제4류","4류"],["제5류","5류"],["3류"],["6류"]],"l":"다"}],"순서무관":false},{"id":"2020-3-10","y":2020,"r":3,"n":10,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물 중에서 수용성인 물질을 모두 고르시오.\n아세톤, 아세트알데하이드, 벤젠, 톨루엔, 휘발유, 메탄올, 클로로벤젠","a":"아세톤, 아세트알데하이드, 메탄올","h":"보기 중 물에 녹는 것은 아세톤, 아세트알데하이드, 메탄올이다. 벤젠·톨루엔·휘발유·클로로벤젠은 비수용성이다.","t":"kan","칸":[{"a":"아세톤","syn":["Acetone","CH3COCH3","디메틸케톤"]},{"a":"아세트알데하이드","syn":["아세트알데히드","아세트알데이드","CH3CHO"]},{"a":"메탄올","syn":["메틸알코올","메틸알콜","CH3OH"]}],"순서무관":true},{"id":"2020-3-11","y":2020,"r":3,"n":11,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"이산화탄소를 저장하는 저압용기에 대하여 빈칸에 알맞은 말을 쓰시오.\n• 이산화탄소를 방사하는 분사헤드 중 고압식의 방사압력은 ( 가 )MPa 이상, 저압식의 경우 ( 나 )MPa 이상일 것\n• 저압식 저장용기에는 액면계 및 압력계와 ( 다 )MPa 이상 ( 라 )MPa 이하의 압력에서 작동하는 압력경보장치를 설치할 것\n• 저압식 저장용기에는 용기내부의 온도를 영하 ( 마 )℃ 이상, 영하 ( 바 )℃ 이하로 유지할 수 있는 자동냉동기를 설치할 것","a":"가. 2.1\n나. 1.05\n다. 2.3\n라. 1.9\n마. 20\n바. 18","h":"이산화탄소 분사헤드의 방사압력은 고압식 2.1MPa, 저압식 1.05MPa 이상이다. 저압식 저장용기의 압력경보장치는 2.3MPa 이상과 1.9MPa 이하에서 작동하고, 자동냉동기는 -20℃ 이상 -18℃ 이하로 유지한다.","t":"kan","칸":[{"a":"2.1","syn":["2.1MPa","2.1 MPa"],"l":"가"},{"a":"1.05","syn":["1.05MPa","1.05 MPa"],"l":"나"},{"a":"2.3","syn":["2.3MPa","2.3 MPa"],"l":"다"},{"a":"1.9","syn":["1.9MPa","1.9 MPa"],"l":"라"},{"a":"20","syn":["-20","영하20","20℃"],"l":"마"},{"a":"18","syn":["-18","영하18","18℃"],"l":"바"}],"순서무관":false},{"id":"2020-3-12","y":2020,"r":3,"n":12,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 제6류 위험물 중에서 위험물이 될 수 있는 조건을 쓰시오 (단, 없으면 없음이라 쓰시오).\n가. 과산화수소\n나. 과염소산\n다. 질산","a":"가. 농도 36중량퍼센트 이상\n나. 없음\n다. 비중 1.49 이상","h":"제6류에서 조건이 붙는 것은 과산화수소(36중량퍼센트 이상)와 질산(비중 1.49 이상)뿐이다. 과염소산에는 조건이 없다.","t":"kan","칸":[{"a":"농도 36중량퍼센트 이상","syn":["36","36wt%","36wt%이상","36중량%","36중량%이상","36중량퍼센트","36%","36% 이상","36 중량퍼센트 이상","36중량퍼센트 이상","농도 36중량퍼센트"],"l":"가"},{"a":"없음","syn":["없다","해당없음","해당 없음","-","없음."],"l":"나"},{"a":"비중 1.49 이상","syn":["1.49","1.49 이상","1.49이상","비중1.49","비중 1.49","비중1.49이상"],"l":"다"}],"순서무관":false},{"id":"2020-3-13","y":2020,"r":3,"n":13,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"과산화나트륨 1kg이 1atm, 350℃에서 분해할 때 생성되는 산소의 부피는 몇 L인가?","a":"① Na2O2 1,000g, 분자량 78, 1atm, 350℃(623K)\n② 2Na2O2 → 2Na2O + O2\n③ V = (1,000×0.082×623)/(1×78) × 1/2\n④ 327.47L","h":"과산화나트륨 2몰이 분해되어 산소 1몰이 나오므로 계수비 1/2를 곱한다. 온도는 350+273 = 623K다.","tp":"W01","t":"calc","e":1,"ka":"327.47"},{"id":"2020-3-14","y":2020,"r":3,"n":14,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물 중 아세트알데하이드에 대하여 다음 물음에 답하시오.\n가. 시성식\n나. 증기비중\n다. 산화 시 생성되는 물질","a":"가. CH3CHO\n나. 44/29 = 1.52\n다. 아세트산(초산)","h":"아세트알데하이드는 시성식 CH3CHO, 분자량 44이고 증기비중은 44/29 = 1.52다. 산화되면 아세트산이 된다.","t":"kan","칸":[{"a":"CH3CHO","syn":["아세트알데하이드","아세트알데히드","C2H4O","CH3CH=O"],"l":"가"},{"a":"1.52","e":0.01,"l":"나"},{"a":"아세트산","syn":["초산","CH3COOH","아세틱애시드","acetic acid","아세트산(초산)","초산(아세트산)"],"l":"다"}],"순서무관":false},{"id":"2020-3-15","y":2020,"r":3,"n":15,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"옥내저장소에 대한 다음 물음에 답하시오.\n가. 옥내저장소에 동일 품명의 위험물이더라도 자연발화할 우려가 있는 위험물 또는 재해가 현저하게 증대할 우려가 있는 위험물을 다량 저장하는 경우에는 지정수량의 10배 이하마다 ( ) 이상의 간격을 두어 저장하여야 한다.\n나. 기계에 의하여 하역하는 구조로 된 용기만을 겹쳐 쌓는 경우 ( )의 높이를 초과하지 아니하여야 한다.\n다. 제4류 위험물 중 제3석유류, 제4석유류 및 동식물유류를 수납하는 용기만을 겹쳐 쌓는 경우 ( )의 높이를 초과하지 아니하여야 한다.\n라. 그 밖의 경우에 있어서는 ( )의 높이를 초과하지 아니하여야 한다.\n마. 옥내저장소에서는 용기에 수납하여 저장하는 위험물의 온도가 ( )를 넘지 아니하도록 필요한 조치를 강구하여야 한다.","a":"가. 0.3m\n나. 6m\n다. 4m\n라. 3m\n마. 55℃","h":"옥내저장소에서 자연발화 우려가 있는 위험물은 지정수량 10배 이하마다 0.3m 이상 띄운다. 적재 높이는 기계 하역 6m, 제3·4석유류와 동식물유류 4m, 그 밖에는 3m 이하이고 용기 내 위험물 온도는 55℃를 넘지 않게 한다.","t":"kan","칸":[{"a":"0.3m","syn":["0.3","0.3미터","30cm"],"l":"가"},{"a":"6m","syn":["6","6미터"],"l":"나"},{"a":"4m","syn":["4","4미터"],"l":"다"},{"a":"3m","syn":["3","3미터"],"l":"라"},{"a":"55℃","syn":["55","55도","55℃ 이하"],"l":"마"}],"순서무관":false},{"id":"2020-3-16","y":2020,"r":3,"n":16,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제4류 위험물의 인화점에 대하여 다음 보기의 빈칸을 채우시오.\n가. 제1석유류 인화점 ( ) 미만\n나. 제2석유류 인화점 ( ) 이상 인화점 ( ) 미만\n다. 제3석유류 인화점 ( ) 이상 인화점 ( ) 미만\n라. 제4석유류 인화점 ( ) 이상 인화점 ( ) 미만","a":"가. 21℃\n나. 21℃, 70℃\n다. 70℃, 200℃\n라. 200℃, 250℃","h":"제1석유류는 인화점 21℃ 미만, 제2석유류는 21~70℃ 미만, 제3석유류는 70~200℃ 미만, 제4석유류는 200~250℃ 미만이다. 앞 구간의 상한이 다음 구간의 하한이 된다.","t":"kan","칸":[{"a":"21","syn":["21℃","21도"],"l":"가"},{"a":"21","syn":["21℃","21도"],"l":"나-1"},{"a":"70","syn":["70℃","70도"],"l":"나-2"},{"a":"70","syn":["70℃","70도"],"l":"다-1"},{"a":"200","syn":["200℃","200도"],"l":"다-2"},{"a":"200","syn":["200℃","200도"],"l":"라-1"},{"a":"250","syn":["250℃","250도"],"l":"라-2"}],"순서무관":false},{"id":"2020-3-17","y":2020,"r":3,"n":17,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"지하탱크저장소에 대한 물음에 답하시오.\n가. 탱크전용실의 두께는 몇 m 이상으로 하여야 하는지 쓰시오.\n나. 통기관은 지면으로부터 몇 m 이상의 높이에 설치하여야 하는지 쓰시오.\n다. 누유검사관을 몇 개소 이상 설치하여야 하는지 쓰시오.\n라. 탱크와 탱크전용실 사이의 공간을 어떤 물질로 채워야 하는지 쓰시오.\n마. 지하저장탱크의 윗부분은 지면으로부터 몇 m 이상 아래에 있어야 하는지 쓰시오.","a":"가. 0.3m 이상\n나. 4m 이상\n다. 4개소 이상\n라. 마른 모래 또는 습기 등에 의해 응고되지 않는 입자지름 5mm 이하의 마른 자갈분\n마. 0.6m 이상","h":"지하탱크저장소는 전용실 벽·바닥·뚜껑 두께 0.3m 이상, 통기관 높이 지면에서 4m 이상, 누유검사관 4개소 이상이다. 탱크 윗부분은 지면에서 0.6m 이상 아래에 두고, 탱크와 전용실 사이는 마른 모래나 입자지름 5mm 이하 마른 자갈분으로 채운다.","t":"kan","칸":[{"a":"0.3m","syn":["0.3","0.3미터","30cm"],"l":"가"},{"a":"4m","syn":["4","4미터"],"l":"나"},{"a":"4개소","syn":["4","4개","4곳","4개소 이상"],"l":"다"},{"a":"마른 모래","syn":["마른모래","모래","건조사","마른 자갈분","자갈분","마른자갈","자갈","마른 모래 또는 습기 등에 의해 응고되지 않는 입자지름 5mm 이하의 마른 자갈분","마른모래 또는 마른자갈분","마른 자갈"],"l":"라"},{"a":"0.6m","syn":["0.6","0.6미터","60cm"],"l":"마"}],"순서무관":false},{"id":"2020-3-18","y":2020,"r":3,"n":18,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제2류 위험물 중 황화인에 대한 물음에 답하시오.\n가. 삼황화인, 오황화인, 칠황화인 중에서 조해성이 있는 물질과 없는 물질을 구분하시오.\n나. 황화인의 종류 중 발화점이 가장 낮은 물질의 명칭을 쓰시오.\n다. 나의 물질에 대한 완전연소반응식을 쓰시오.","a":"가. 조해성 있음: 오황화인, 칠황화인 / 조해성 없음: 삼황화인\n나. 삼황화인\n다. P4S3 + 8O2 → 3SO2 + 2P2O5","h":"발화점은 삼황화인 약 100℃, 오황화인 142℃, 칠황화인 약 250℃이고, 조해성은 삼황화인만 없다. 칠황화인의 310℃는 녹는점이라 발화점과 헷갈리기 쉽다. 삼황화인이 타면 이산화황과 오산화인이 생기며, 인 4개가 P2O5 2분자로 나뉘는 것을 기준으로 계수를 맞춘다.","t":"kan","칸":[{"a":"오황화인, 칠황화인","k":[["오황화","P2S5"],["칠황화","P4S7"]],"l":"가-조해성 있음"},{"a":"삼황화인","syn":["삼황화사인","P4S3","삼황화 인"],"l":"가-조해성 없음"},{"a":"삼황화인","syn":["삼황화사인","P4S3","삼황화 인"],"l":"나"},{"a":"P4S3+8O2→3SO2+2P2O5","syn":["P4S3+8O2->3SO2+2P2O5","P4S3+8O2=3SO2+2P2O5","P4S3+8O2→2P2O5+3SO2","P4S3+8O2->2P2O5+3SO2"],"l":"다"}],"순서무관":false},{"id":"2020-3-19","y":2020,"r":3,"n":19,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제3류 위험물 중 물과 반응성이 없고 연소하여 흰 연기를 발생하는 물질에 대하여 다음 물음에 답하시오.\n가. 명칭\n나. 옥내저장소의 바닥면적\n다. 수산화칼륨과 같은 강알칼리성 용액과 반응하여 생성되는 맹독성 기체의 명칭","a":"가. 황린\n나. 1,000m2\n다. 포스핀","h":"물과 반응하지 않고 타면서 흰 연기(오산화인)를 내는 제3류 물질은 황린(P4)이며 지정수량은 20kg이다. 위험등급 I 이라 옥내저장소 바닥면적은 1,000m2 이하이다. 강알칼리 용액과는 P4 + 3KOH + 3H2O → PH3 + 3KH2PO2 로 반응해 포스핀(PH3)이 나온다.","t":"kan","칸":[{"a":"황린","syn":["백린","P4","황 린"],"l":"가"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"나"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine","호스핀"],"l":"다"}],"순서무관":false},{"id":"2020-3-20","y":2020,"r":3,"n":20,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물에 대하여 운반용기 외부에 표시하여야 하는 주의사항을 모두 쓰시오.\n가. 제2류 위험물 중 인화성 고체\n나. 제3류 위험물 중 금수성 물질\n다. 제4류 위험물\n라. 제5류 위험물\n마. 제6류 위험물","a":"가. 화기엄금\n나. 물기엄금\n다. 화기엄금\n라. 화기엄금, 충격주의\n마. 가연물접촉주의","h":"제2류는 인화성 고체만 화기엄금이고 철분·금속분·마그네슘은 화기주의·물기엄금, 나머지는 화기주의이다. 제3류는 자연발화성 물질이 화기엄금·공기접촉엄금, 금수성 물질이 물기엄금이다. 제4류는 화기엄금, 제5류는 화기엄금·충격주의, 제6류는 가연물접촉주의이며, 제1류는 가연물접촉주의·화기·충격주의에 알칼리금속 과산화물만 물기엄금이 더해진다.","t":"kan","칸":[{"a":"화기엄금","syn":["화기 엄금"],"l":"가"},{"a":"물기엄금","syn":["물기 엄금"],"l":"나"},{"a":"화기엄금","syn":["화기 엄금"],"l":"다"},{"a":"화기엄금, 충격주의","k":[["화기엄금","화기 엄금"],["충격"]],"l":"라"},{"a":"가연물접촉주의","syn":["가연물 접촉주의","가연물접촉 주의","가연물접촉"],"l":"마"}],"순서무관":false},{"id":"2020-4-01","y":2020,"r":4,"n":1,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 인화점이 낮은 것에서 높은 것 순서대로 쓰시오.\n다이에틸에터, 이황화탄소, 아세톤, 산화프로필렌","a":"다이에틸에터, 산화프로필렌, 이황화탄소, 아세톤","h":"제4류는 특수인화물, 제1석유류, 알코올류 순으로 인화점이 높아지므로 특수인화물 셋(다이에틸에터, 산화프로필렌, 이황화탄소)이 제1석유류인 아세톤보다 앞선다. 특수인화물끼리는 다이에틸에터, 아세트알데하이드, 산화프로필렌, 이황화탄소 순으로 인화점이 올라가 다이에틸에터가 가장 낮다.","t":"kan","칸":[{"a":"다이에틸에터","syn":["디에틸에터","다이에틸에테르","디에틸에테르","에터","에테르","C2H5OC2H5","에틸에터","에틸에테르"],"l":"1"},{"a":"산화프로필렌","syn":["프로필렌옥사이드","프로필렌옥시드","프로필렌 옥사이드","C3H6O","산화 프로필렌"],"l":"2"},{"a":"이황화탄소","syn":["CS2","이황화 탄소"],"l":"3"},{"a":"아세톤","syn":["Acetone","CH3COCH3","디메틸케톤"],"l":"4"}],"순서무관":false},{"id":"2020-4-02","y":2020,"r":4,"n":2,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물을 수납하는 운반용기 외부에 표시하여야 하는 주의사항을 쓰시오.\n가. 철분\n나. 황린\n다. 아닐린\n라. 질산칼륨\n마. 질산","a":"가. 화기주의, 물기엄금\n나. 화기엄금, 공기접촉엄금\n다. 화기엄금\n라. 가연물접촉주의, 화기·충격주의\n마. 가연물접촉주의","h":"철분은 제2류 철분이라 화기주의·물기엄금, 황린은 제3류 자연발화성 물질이라 화기엄금·공기접촉엄금이다. 아닐린은 제4류(제3석유류)라 화기엄금, 질산칼륨은 제1류 질산염류라 가연물접촉주의·화기·충격주의, 질산은 제6류라 가연물접촉주의이다. 제1류는 알칼리금속 과산화물일 때만 물기엄금이 붙으므로 질산칼륨에는 붙지 않는다.","t":"kan","칸":[{"a":"화기주의, 물기엄금","k":[["화기"],["물기"]],"l":"가"},{"a":"화기엄금, 공기접촉엄금","k":[["화기엄금","화기 엄금"],["공기접촉","공기 접촉"]],"l":"나"},{"a":"화기엄금","syn":["화기 엄금"],"l":"다"},{"a":"가연물접촉주의, 화기·충격주의","k":[["가연물"],["충격"]],"l":"라"},{"a":"가연물접촉주의","syn":["가연물 접촉주의","가연물접촉 주의","가연물접촉"],"l":"마"}],"순서무관":false},{"id":"2020-4-03","y":2020,"r":4,"n":3,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"옥외저장탱크에 제4류 위험물을 저장하고 주위에 방유제를 설치하였다. 각 물음에 답하시오.\n가. 방유제의 높이는 몇 m 이상 몇 m 이하로 하여야 하는가?\n나. 방유제 내의 면적은 몇 m2 이하로 하여야 하는가?\n다. 방유제 내에 설치하는 옥외저장탱크는 몇 기 이하로 하여야 하는가?","a":"가. 0.5m 이상 3m 이하\n나. 80,000m2 이하\n다. 10기 이하","h":"옥외탱크저장소 방유제는 높이 0.5m 이상 3m 이하, 면적 80,000m2 이하, 탱크 10기 이하이다. 두께는 0.2m 이상이고 50m마다 계단을 둔다. 용량은 옥외탱크저장소가 최대 탱크의 1.1배, 제조소는 최대 탱크의 0.5배에 나머지 탱크 합의 0.1배를 더한 값이다.","t":"kan","칸":[{"a":"0.5","syn":["0.5m","0.5미터","50cm"],"l":"가-하한"},{"a":"3","syn":["3m","3미터"],"l":"가-상한"},{"a":"80000","syn":["80,000","80000m2","80,000m2","80000㎡","80,000㎡","8만","8만m2"],"l":"나"},{"a":"10","syn":["10기","10기 이하","10개"],"l":"다"}],"순서무관":false},{"id":"2020-4-04","y":2020,"r":4,"n":4,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물을 운반용기 내용적의 몇 % 이하의 수납율로 수납하여야 하는지 쓰시오.\n가. 질산칼륨\n나. 과염소산\n다. 질산\n라. 알킬리튬\n마. 알킬알루미늄","a":"가. 95% 이하\n나. 98% 이하\n다. 98% 이하\n라. 90% 이하\n마. 90% 이하","h":"고체는 95% 이하, 액체는 98% 이하로 수납하고, 액체는 55℃에서도 새지 않도록 공간용적을 둔다. 질산칼륨은 제1류 고체이고 과염소산과 질산은 제6류 액체이다. 알킬알루미늄등(알킬리튬 포함)은 90% 이하로 담고 50℃에서 공간용적 5%를 유지한다.","t":"kan","칸":[{"a":"95","syn":["95%","95% 이하"],"l":"가"},{"a":"98","syn":["98%","98% 이하"],"l":"나"},{"a":"98","syn":["98%","98% 이하"],"l":"다"},{"a":"90","syn":["90%","90% 이하"],"l":"라"},{"a":"90","syn":["90%","90% 이하"],"l":"마"}],"순서무관":false},{"id":"2020-4-05","y":2020,"r":4,"n":5,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제2류 위험물의 위험물이 되는 기준에 대하여 다음 빈칸에 알맞은 말을 쓰시오.\n가. 황은 순도 ( )중량퍼센트 이상인 것을 말한다. 이 경우 순도측정에 있어서 불순물은 활석 등 불연성 물질과 수분에 한한다.\n나. 철분이라 함은 철의 분말로서 ( )㎛의 표준체를 통과하는 것이 ( )중량% 이상인 것을 말한다.\n다. 금속분이라 함은 구리 니켈을 제외한 금속의 분말로 ( )㎛의 표준체를 통과하는 것이 ( )중량% 이상인 것을 말한다.","a":"가. 60\n나. 53, 50\n다. 150, 50","h":"황은 순도 60중량% 이상이며 불순물은 활석 등 불연성 물질과 수분만 해당한다. 철분은 53㎛ 체, 금속분은 구리·니켈을 뺀 금속 분말로 150㎛ 체를 통과하는 것이 각각 50중량% 이상이다. 두 물질은 체 크기만 다르고 통과 비율은 같다.","t":"kan","칸":[{"a":"60","syn":["60중량퍼센트","60%","60wt%","60중량%"],"l":"가"},{"a":"53","syn":["53㎛","53μm","53um","53마이크로미터"],"l":"나-1"},{"a":"50","syn":["50%","50중량%","50wt%","50중량퍼센트"],"l":"나-2"},{"a":"150","syn":["150㎛","150μm","150um","150마이크로미터"],"l":"다-1"},{"a":"50","syn":["50%","50중량%","50wt%","50중량퍼센트"],"l":"다-2"}],"순서무관":false},{"id":"2020-4-06","y":2020,"r":4,"n":6,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"옥내소화전설비에서 압력수조를 이용한 가압송수장치를 사용할 때 필요한 압력을 구하는 공식으로 알맞은 내용을 골라 기호로 쓰시오.\nP = ( ) + ( ) + ( ) + ( )\n• A : 소방용 호스의 마찰손실수두(m)\n• B : 배관의 마찰손실수두(m)\n• C : 소방용 호스의 마찰손실수두압(MPa)\n• D : 배관의 마찰손실수두압(MPa)\n• E : 방수압력 환산수두(MPa)\n• F : 낙차의 환산수두압(MPa)\n• G : 낙차(m)\n• H : 0.35(MPa)\n• I : 35(m)","a":"C, D, F, H","h":"압력수조 방식의 필요 압력은 소방용 호스 마찰손실수두압 + 배관 마찰손실수두압 + 낙차 환산수두압 + 0.35MPa 이다. 단위가 MPa 이므로 m 단위인 A, B, G, I 는 들어가지 않는다. 고가수조와 펌프 방식은 단위가 m 이고 35m를 더한다.","t":"kan","칸":[{"a":"C","syn":["c","ⓒ","(C)"]},{"a":"D","syn":["d","ⓓ","(D)"]},{"a":"F","syn":["f","ⓕ","(F)"]},{"a":"H","syn":["h","ⓗ","(H)"]}],"순서무관":true},{"id":"2020-4-07","y":2020,"r":4,"n":7,"p":"계산","kw":"지정수량 배수","pt":5,"q":"다음 위험물의 지정수량 배수의 합을 구하시오.\n• 특수인화물 200L\n• 제1석유류 수용성 400L\n• 제2석유류 수용성 4,000L\n• 제3석유류 수용성 12,000L\n• 제4석유류 24,000L","a":"① 지정수량: 특수인화물 50L, 제1석유류 수용성 400L, 제2석유류 수용성 2,000L, 제3석유류 수용성 4,000L, 제4석유류 6,000L\n② 배수 = Σ(저장량 ÷ 지정수량)\n③ 200/50 + 400/400 + 4,000/2,000 + 12,000/4,000 + 24,000/6,000 = 4 + 1 + 2 + 3 + 4\n④ 14배","h":"각 품명의 저장량을 지정수량으로 나눠 모두 더하면 4+1+2+3+4 로 14배이다. 지정수량은 품명뿐 아니라 수용성 여부에 따라 달라지므로 문제에 적힌 수용성 표시대로 값을 골라 쓴다.","t":"calc","ka":"14"},{"id":"2020-4-08","y":2020,"r":4,"n":8,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"나트륨 화재 시 적응성이 있는 소화방법의 기호를 모두 쓰시오.\n가. 팽창질석\n나. 건조사\n다. 포소화설비\n라. 이산화탄소소화설비\n마. 인산염류분말소화기","a":"가, 나","h":"나트륨은 제3류 금수성 물질이라 물을 쓰는 소화나 포, 이산화탄소, 인산염류 분말은 쓰지 않는다. 마른 모래, 팽창질석, 팽창진주암, 탄산수소염류 분말이 적응성이 있어 보기에서는 팽창질석과 건조사가 해당한다.","t":"kan","칸":[{"a":"가","syn":["ㄱ","(가)","가.","팽창질석"]},{"a":"나","syn":["ㄴ","(나)","나.","건조사","마른 모래","마른모래"]}],"순서무관":true},{"id":"2020-4-09","y":2020,"r":4,"n":9,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 유별 중 위험등급 II인 품명을 쓰시오.\n가. 제1류 위험물\n나. 제2류 위험물\n다. 제4류 위험물","a":"가. 아이오딘산염류, 브로민산염류, 질산염류\n나. 황화인, 황, 적린\n다. 제1석유류, 알코올류","h":"위험등급 II 는 제1류의 브로민산염류·아이오딘산염류·질산염류(각 300kg)이다. 제2류는 황·황화인·적린(각 100kg), 제4류는 제1석유류와 알코올류이다. 제4류의 특수인화물은 I 이고 제2·3·4석유류와 동식물유류는 III 이다.","t":"kan","칸":[{"a":"아이오딘산염류","syn":["요오드산염류","옥소산염류","아이오딘산염","아이오딘산 염류"]},{"a":"브로민산염류","syn":["브롬산염류","브로민산염","브로민산 염류"]},{"a":"질산염류","syn":["질산염","질산 염류"]},{"a":"황화인","syn":["황화 인"]},{"a":"황","syn":["유황","sulfur","S"]},{"a":"적린","syn":["붉은인","적 린","red phosphorus"]},{"a":"제1석유류","syn":["1석유류","제 1석유류","제일석유류"]},{"a":"알코올류","syn":["알콜류","알코올","알콜"]}],"순서무관":true},{"id":"2020-4-10","y":2020,"r":4,"n":10,"p":"반응식","kw":"연소 반응","pt":5,"q":"에틸알코올에 대하여 다음 물음에 답하시오.\n가. 연소반응식\n나. 칼륨과 반응에서 발생하는 기체의 화학식\n다. 구조이성질체인 다이메틸에터의 시성식","a":"가. C2H5OH + 3O2 → 2CO2 + 3H2O\n나. H2\n다. CH3OCH3","h":"에탄올이 타면 이산화탄소와 물이 생기고, 칼륨과 만나면 2K + 2C2H5OH → 2C2H5OK + H2 로 수소가 나온다. 다이메틸에터(CH3OCH3)는 분자식 C2H6O 가 에탄올과 같고 원자의 연결만 다른 구조이성질체이다. 시성식은 에탄올 C2H5OH, 다이메틸에터 CH3OCH3 이다.","t":"kan","칸":[{"a":"C2H5OH+3O2→2CO2+3H2O","syn":["C2H5OH+3O2->2CO2+3H2O","C2H5OH+3O2=2CO2+3H2O","C2H5OH+3O2→3H2O+2CO2","C2H5OH+3O2->3H2O+2CO2"],"l":"가"},{"a":"H2","syn":["수소","수소가스","hydrogen"],"l":"나"},{"a":"CH3OCH3","syn":["CH3-O-CH3","C2H6O","(CH3)2O","다이메틸에터"],"l":"다"}],"순서무관":false},{"id":"2020-4-11","y":2020,"r":4,"n":11,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"1기압 30℃에서 다음 위험물이 물과 반응할 때 생성되는 기체의 몰수를 구하시오.\n가. 과산화나트륨 78g\n나. 수소화칼슘 42g","a":"가. ① Na2O2 78g = 1mol ② 2Na2O2 + 2H2O → 4NaOH + O2 ③ 1mol × 1/2 = 0.5 ④ 0.5mol\n나. ① CaH2 42g = 1mol ② CaH2 + 2H2O → Ca(OH)2 + 2H2 ③ 1mol × 2 = 2 ④ 2mol","h":"몰수는 온도·압력과 무관하므로 부피 공식 없이 반응식의 계수비로 구한다. 과산화나트륨은 2mol당 산소 1mol이 나오고, 수소화칼슘은 1mol당 수소 2mol이 나온다.","tp":"W01","t":"kan","칸":[{"a":"0.5","syn":["0.5mol","0.5 mol","0.5몰","1/2"],"l":"가"},{"a":"2","syn":["2mol","2 mol","2몰"],"l":"나"}],"순서무관":false},{"id":"2020-4-12","y":2020,"r":4,"n":12,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 품명과 지정수량을 쓰시오.\n가. HCN\n나. C2H4(OH)2\n다. CH3COOH\n라. C3H5(OH)3\n마. N2H4","a":"가. 제1석유류, 400L\n나. 제3석유류, 4,000L\n다. 제2석유류, 2,000L\n라. 제3석유류, 4,000L\n마. 제2석유류, 2,000L","h":"사이안화수소는 제1석유류(400L), 아세트산·하이드라진은 제2석유류(2,000L), 에틸렌글리콜·글리세린은 제3석유류(4,000L)이다. 다섯 물질 모두 수용성이라 수용성 칸의 지정수량을 쓴다.","t":"kan","칸":[{"a":"제1석유류, 400L","k":[["1석유류"],["400"]],"l":"가"},{"a":"제3석유류, 4000L","k":[["3석유류"],["4000","4,000"]],"l":"나"},{"a":"제2석유류, 2000L","k":[["2석유류"],["2000","2,000"]],"l":"다"},{"a":"제3석유류, 4000L","k":[["3석유류"],["4000","4,000"]],"l":"라"},{"a":"제2석유류, 2000L","k":[["2석유류"],["2000","2,000"]],"l":"마"}],"순서무관":false},{"id":"2020-4-13","y":2020,"r":4,"n":13,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"다음 물음에 답하시오.\n가. 고정주유설비와 부지경계선까지의 거리를 쓰시오.\n나. 고정급유설비와 부지경계선까지의 거리를 쓰시오.\n다. 고정주유설비와 도로경계선까지의 거리를 쓰시오.\n라. 고정급유설비와 도로경계선까지의 거리를 쓰시오.\n마. 고정주유설비와 개구부가 없는 벽까지의 거리를 쓰시오.","a":"가. 2m 이상\n나. 1m 이상\n다. 4m 이상\n라. 4m 이상\n마. 1m 이상","h":"도로경계선은 고정주유설비와 고정급유설비 모두 4m 이상이다. 부지경계선·담은 주유설비 2m, 급유설비 1m 이상이다. 개구부가 없는 벽은 둘 다 1m 이상이고, 개구부가 있는 건축물 벽은 둘 다 2m 이상이다.","t":"kan","칸":[{"a":"2","syn":["2m","2m 이상","2미터"],"l":"가"},{"a":"1","syn":["1m","1m 이상","1미터"],"l":"나"},{"a":"4","syn":["4m","4m 이상","4미터"],"l":"다"},{"a":"4","syn":["4m","4m 이상","4미터"],"l":"라"},{"a":"1","syn":["1m","1m 이상","1미터"],"l":"마"}],"순서무관":false},{"id":"2020-4-14","y":2020,"r":4,"n":14,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"인화칼슘에 대하여 다음 각 물음에 답하시오.\n가. 위험물의 유별\n나. 지정수량\n다. 물과의 화학반응식\n라. 물과 반응하여 생성되는 가스의 명칭","a":"가. 제3류 위험물\n나. 300kg\n다. Ca3P2 + 6H2O → 3Ca(OH)2 + 2PH3\n라. 포스핀(인화수소, PH3)","h":"인화칼슘(Ca3P2)은 제3류 금속인화합물로 지정수량 300kg이며, 물과 반응해 수산화칼슘과 포스핀을 낸다. 같은 300kg 품명인 탄화칼슘은 아세틸렌, 탄화알루미늄은 메테인을 내므로 발생 기체가 서로 다르다.","t":"kan","칸":[{"a":"제3류","syn":["3류","제3류 위험물","3류 위험물","제 3류"],"l":"가"},{"a":"300kg","syn":["300","300 kg"],"l":"나"},{"a":"Ca3P2+6H2O→3Ca(OH)2+2PH3","syn":["Ca3P2+6H2O->3Ca(OH)2+2PH3","Ca3P2+6H2O=3Ca(OH)2+2PH3","Ca3P2+6H2O→2PH3+3Ca(OH)2","Ca3P2+6H2O->2PH3+3Ca(OH)2"],"l":"다"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine"],"l":"라"}],"순서무관":false},{"id":"2020-4-15","y":2020,"r":4,"n":15,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"이황화탄소에 대하여 다음 물음에 답하시오.\n가. 연소반응식\n나. 품명\n다. 저장하는 철근콘크리트 수조의 최소 두께","a":"가. CS2 + 3O2 → CO2 + 2SO2\n나. 특수인화물\n다. 0.2m 이상","h":"이황화탄소는 제4류 특수인화물(50L)이며 비중 1.29로 물에 가라앉고 물과 반응하지 않아, 물을 채운 수조에 넣어 가연성 증기를 억제한다. 수조는 두께 0.2m 이상의 철근콘크리트로 한다. 연소하면 이산화탄소와 이산화황이 생긴다.","t":"kan","칸":[{"a":"CS2+3O2→CO2+2SO2","syn":["CS2+3O2->CO2+2SO2","CS2+3O2=CO2+2SO2","CS2+3O2→2SO2+CO2","CS2+3O2->2SO2+CO2"],"l":"가"},{"a":"특수인화물","syn":["특수 인화물"],"l":"나"},{"a":"0.2","syn":["0.2m","0.2m 이상","0.2미터","20cm"],"l":"다"}],"순서무관":false},{"id":"2020-4-16","y":2020,"r":4,"n":16,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제2류 위험물에 대한 설명 중 옳은 것의 기호를 모두 고르시오.\n가. 황화인, 적린, 황은 위험등급 II이다.\n나. 고형알코올은 지정수량이 1,000kg이고, 품명은 알코올류이다.\n다. 대부분 비중이 1보다 작다.\n라. 대부분 물에 녹는다.\n마. 산화성 물질이다.\n바. 제2류 위험물의 지정수량은 100kg, 500kg, 1,000kg 순이다.\n사. 제2류 위험물을 취급하는 제조소 게시판의 주의사항은 화기엄금과 화기주의 중 경우에 따라 한 개를 표기하여야 한다.","a":"가, 바, 사","h":"황·황화인·적린은 위험등급 II 이고, 지정수량은 100kg(황·황화인·적린), 500kg(철분·금속분·마그네슘), 1,000kg(인화성 고체) 순이다. 제2류는 대부분 비중이 1보다 크고 물에 녹지 않는 환원성 물질이라 다·라·마는 틀린다. 고형알코올은 알코올류가 아니라 인화성 고체이므로 나도 틀린다.","t":"kan","칸":[{"a":"가","syn":["ㄱ","(가)","가."]},{"a":"바","syn":["ㅂ","(바)","바."]},{"a":"사","syn":["ㅅ","(사)","사."]}],"순서무관":true},{"id":"2020-4-17","y":2020,"r":4,"n":17,"p":"반응식","kw":"열분해","pt":5,"q":"다음 물음에 답하시오.\n가. ANFO 폭약의 원료가 되는 위험물의 화학식을 쓰시오.\n나. 가.의 화학식이 분해하여 질소, 산소, 물이 되는 분해반응식을 쓰시오.","a":"가. NH4NO3\n나. 2NH4NO3 → 2N2 + O2 + 4H2O","h":"ANFO 는 질산암모늄(NH4NO3) 94%에 경유 6%를 기계적으로 섞은 폭약이다. 질산암모늄이 분해되면 질소, 산소, 수증기가 나오며 분자량은 80 이다.","t":"kan","칸":[{"a":"NH4NO3","syn":["질산암모늄","질산 암모늄"],"l":"가"},{"a":"2NH4NO3→2N2+O2+4H2O","syn":["2NH4NO3->2N2+O2+4H2O","2NH4NO3=2N2+O2+4H2O","NH4NO3→N2+1/2O2+2H2O","NH4NO3->N2+1/2O2+2H2O"],"l":"나"}],"순서무관":false},{"id":"2020-4-18","y":2020,"r":4,"n":18,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제3류 위험물에 대하여 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n칼륨 ( 가 )\n나트륨 ( 나 )\n알킬알루미늄 ( 다 )\n( 라 ) 10kg\n( 마 ) 20kg\n알칼리금속 및 알칼리토금속 ( 바 )\n유기금속화합물 ( 사 )","a":"가. 10kg\n나. 10kg\n다. 10kg\n라. 알킬리튬\n마. 황린\n바. 50kg\n사. 50kg","h":"제3류에서 지정수량 10kg은 알킬알루미늄·알킬리튬·칼륨·나트륨, 20kg은 황린이다. 알칼리금속 및 알칼리토금속과 유기금속화합물은 50kg이고, 금속수소화합물·금속인화합물·탄화물은 300kg이다.","t":"kan","칸":[{"a":"10kg","syn":["10","10 kg"],"l":"가"},{"a":"10kg","syn":["10","10 kg"],"l":"나"},{"a":"10kg","syn":["10","10 kg"],"l":"다"},{"a":"알킬리튬","syn":["알킬 리튬","알킬리듐"],"l":"라"},{"a":"황린","syn":["백린","P4","황 린"],"l":"마"},{"a":"50kg","syn":["50","50 kg"],"l":"바"},{"a":"50kg","syn":["50","50 kg"],"l":"사"}],"순서무관":false},{"id":"2020-4-19","y":2020,"r":4,"n":19,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"옥내저장소에서 동일한 실에 유별로 정리하면 1m 이상의 간격을 두어 함께 저장할 수 있다. 다음 위험물과 혼재 가능한 위험물을 보기에서 골라 쓰시오 (단, 없으면 없음이라 표기하시오).\n[보기]\n과염소산칼륨, 염소산칼륨, 과산화나트륨, 아세톤, 과염소산, 질산, 아세트산\n가. 질산메틸\n나. 인화성고체\n다. 황린","a":"가. 과염소산칼륨, 염소산칼륨\n나. 아세톤, 아세트산\n다. 과염소산칼륨, 염소산칼륨, 과산화나트륨","h":"1m 이상 띄워 같은 실에 둘 수 있는 조합은 제1류(알칼리금속 과산화물 제외)와 제5류, 제1류와 제6류, 제1류와 황린, 인화성 고체와 제4류 등이다. 질산메틸은 제5류 질산에스터류라 알칼리금속 과산화물이 아닌 과염소산칼륨·염소산칼륨과 묶인다. 인화성 고체는 제4류인 아세톤·아세트산과, 황린은 제1류 세 가지(과산화나트륨 포함)와 함께 둘 수 있다.","t":"kan","칸":[{"a":"과염소산칼륨, 염소산칼륨","k":[["과염소산칼륨","과염소산 칼륨"],["염소산칼륨","염소산 칼륨"]],"l":"가","no":["과산화나트륨","아세톤","아세트산","초산"]},{"a":"아세톤, 아세트산","k":[["아세톤"],["아세트산","초산"]],"l":"나","no":["칼륨","나트륨","질산"]},{"a":"과염소산칼륨, 염소산칼륨, 과산화나트륨","k":[["과염소산칼륨","과염소산 칼륨"],["염소산칼륨","염소산 칼륨"],["과산화나트륨","과산화 나트륨"]],"l":"다"}],"순서무관":false},{"id":"2020-4-20","y":2020,"r":4,"n":20,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"옥내저장탱크에 에틸알코올을 저장하는 2기의 탱크가 있다. 다음 물음에 답하시오.\n가. ①의 거리는 몇 m 이상으로 하여야 하는가? (탱크와 탱크전용실 벽 사이)\n나. ②의 거리는 몇 m 이상으로 하여야 하는가? (탱크와 탱크전용실 벽 사이)\n다. ③의 탱크 상호 간의 거리는 몇 m 이상으로 하여야 하는가?\n라. 옥내저장탱크 전체의 용량은 몇 L 이하로 하여야 하는가?","a":"가. 0.5m 이상\n나. 0.5m 이상\n다. 0.5m 이상\n라. 16,000L 이하 (에탄올 400L × 40배)","h":"옥내저장탱크와 전용실 벽의 간격, 탱크끼리의 간격은 모두 0.5m 이상이다. 용량 상한은 지정수량의 40배이고 에탄올은 알코올류(400L)라 400 × 40 = 16,000L이다. 제4석유류·동식물유류 외의 제4류는 40배 값이 20,000L를 넘으면 20,000L가 상한이다.","img":["2020-4-20.svg"],"t":"kan","칸":[{"a":"0.5","syn":["0.5m","0.5m 이상","0.5미터","50cm"],"l":"가"},{"a":"0.5","syn":["0.5m","0.5m 이상","0.5미터","50cm"],"l":"나"},{"a":"0.5","syn":["0.5m","0.5m 이상","0.5미터","50cm"],"l":"다"},{"a":"16000","syn":["16,000","16000L","16,000L","16000리터","16,000 L","16000L 이하","16,000L 이하"],"l":"라"}],"순서무관":false},{"id":"2020-5-01","y":2020,"r":5,"n":1,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제3류 위험물 중 지정수량이 10kg인 품명 4가지를 쓰시오.","a":"알킬알루미늄, 칼륨, 알킬리튬, 나트륨","h":"제3류에서 10kg 인 품명은 알킬알루미늄, 알킬리튬, 칼륨, 나트륨이고 황린은 20kg으로 따로 둔다. 알칼리금속·알칼리토금속과 유기금속화합물은 50kg, 금속수소화합물·금속인화합물·탄화물은 300kg이다.","t":"kan","칸":[{"a":"알킬알루미늄","syn":["알킬 알루미늄","알킬알미늄"]},{"a":"칼륨","syn":["K","포타슘","potassium"]},{"a":"알킬리튬","syn":["알킬 리튬","알킬리듐"]},{"a":"나트륨","syn":["Na","소듐","sodium"]}],"순서무관":true},{"id":"2020-5-02","y":2020,"r":5,"n":2,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"자체소방대에 관한 다음 물음에 답하시오.\n가. 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 3천배 이상 12만배 미만일 때, 자체소방대원 수\n나. 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 3천배 이상 12만배 미만일 때 소방자동차의 대수\n다. 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 48만배 이상일 때, 자체소방대원 수\n라. 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 48만배 이상일 때, 소방자동차의 대수","a":"가. 5인\n나. 1대\n다. 20인\n라. 4대","h":"제4류 최대수량이 지정수량의 3천배 이상이면 자체소방대를 둔다. 3천~12만배 미만은 1대·5인이고, 12만배씩 구간이 올라 48만배 이상이면 4대·20인이 된다. 옥외탱크저장소는 50만배 이상이 대상이며 2대·10인이다.","t":"kan","칸":[{"a":"5","syn":["5인","5명","5인 이상"],"l":"가"},{"a":"1","syn":["1대"],"l":"나"},{"a":"20","syn":["20인","20명","20인 이상"],"l":"다"},{"a":"4","syn":["4대"],"l":"라"}],"순서무관":false},{"id":"2020-5-03","y":2020,"r":5,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 인화점이 낮은 것에서 높은 순서대로 나열하시오.\n아세톤, 이황화탄소, 메틸알코올, 아닐린","a":"이황화탄소, 아세톤, 메틸알코올, 아닐린","h":"제4류는 특수인화물, 제1석유류, 알코올류, 제2석유류, 제3석유류 순으로 인화점이 높아진다. 이황화탄소(특수인화물, -30℃) < 아세톤(제1석유류, -18℃) < 메틸알코올(알코올류, 11℃) < 아닐린(제3석유류, 70℃) 이다.","t":"kan","칸":[{"a":"이황화탄소","syn":["CS2","이황화 탄소"],"l":"1"},{"a":"아세톤","syn":["Acetone","CH3COCH3","디메틸케톤"],"l":"2"},{"a":"메틸알코올","syn":["메탄올","메틸알콜","메틸 알코올","CH3OH","methanol"],"l":"3"},{"a":"아닐린","syn":["aniline","C6H5NH2"],"l":"4"}],"순서무관":false},{"id":"2020-5-04","y":2020,"r":5,"n":4,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"표준상태에서 AlP 580g이 물과 결합 시 발생되는 기체의 부피(L)를 구하시오.","a":"① AlP + 3H2O → Al(OH)3 + PH3, AlP 58g/mol, 580g = 10mol, P=1atm, T=273K\n② V = wRT/PM × (PH3 계수/AlP 계수)\n③ (580×0.082×273)/(1×58) × 1/1\n④ 223.86L","h":"인화알루미늄 1mol이 물과 반응하면 포스핀 1mol이 나오므로 AlP 의 몰수가 곧 기체의 몰수이다. 580g은 10mol이고, 표준상태 이상기체식으로 부피를 구한다. 인화칼슘처럼 금속인화물이 물을 만나면 포스핀이 나온다.","tp":"W01","t":"calc","e":1,"ka":"223.86"},{"id":"2020-5-05","y":2020,"r":5,"n":5,"p":"계산","kw":"지정수량 배수","pt":5,"q":"아세톤 20L 100개와 경유 200L 5드럼의 지정수량 배수를 구하시오.","a":"① 아세톤(제1석유류 수용성) 400L, 경유(제2석유류 비수용성) 1,000L\n② 배수 = Σ(저장량 ÷ 지정수량)\n③ (20×100)/400 + (200×5)/1,000 = 5 + 1\n④ 6배","h":"아세톤 총량 2,000L는 400L의 5배, 경유 총량 1,000L는 1,000L의 1배라 합이 6배이다. 용기 수와 용량을 곱해 총량부터 구한 뒤 지정수량으로 나눈다.","t":"calc","ka":"6"},{"id":"2020-5-06","y":2020,"r":5,"n":6,"p":"계산","kw":"탱크 용량","pt":5,"q":"위험물 제조소에 각각 200m3와 100m3의 탱크 2개가 있다. 방유제의 용량은 몇 m3인지 쓰시오.","a":"① 제조소 탱크 2개 이상: 최대 탱크 × 0.5 + 나머지 합 × 0.1\n② 최대 200m3, 나머지 100m3\n③ 200×0.5 + 100×0.1 = 100 + 10\n④ 110m3","h":"제조소의 방유제는 탱크가 둘 이상이면 최대 탱크의 50%에 나머지 탱크 합의 10%를 더한다. 옥외탱크저장소는 최대 탱크의 110%를 잡으므로 같은 탱크라도 값이 다르다.","tp":"W04","t":"calc","ka":"110"},{"id":"2020-5-07","y":2020,"r":5,"n":7,"p":"반응식","kw":"연소 반응","pt":5,"q":"알루미늄에 대한 다음 물음에 답을 쓰시오.\n가. 완전연소 반응식\n나. 염산과의 반응 시 생성가스\n다. 위험등급","a":"가. 4Al + 3O2 → 2Al2O3\n나. 수소(H2)\n다. III","h":"알루미늄은 제2류 금속분(500kg)으로 위험등급 III 이며, 타면 산화알루미늄이 된다. 염산과는 2Al + 6HCl → 2AlCl3 + 3H2 로 반응해 수소가 나온다.","t":"kan","칸":[{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3","2Al+3/2O2→Al2O3"],"l":"가"},{"a":"수소","syn":["H2","수소가스","hydrogen"],"l":"나"},{"a":"III","syn":["Ⅲ","3","III등급","Ⅲ등급","3등급","III 등급","Ⅲ 등급","Ⅲ급","3급"],"l":"다"}],"순서무관":false},{"id":"2020-5-08","y":2020,"r":5,"n":8,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제5류 위험물 중에서 규조토에 흡수시키면 다이너마이트를 만들 수 있는 위험물이 있다. 이 위험물에 대하여 다음 물음에 답하시오.\n가. 구조식\n나. 품명 및 지정수량\n다. 이산화탄소, 수증기, 질소, 산소가 발생하는 완전분해반응식","a":"가. 나이트로글리세린 C3H5(ONO2)3: 탄소 3개 사슬(H-C-C-C-H)의 각 탄소에 ONO2 가 하나씩 결합한 구조\n나. 질산에스터류, 10kg\n다. 4C3H5(ONO2)3 → 12CO2 + 10H2O + 6N2 + O2","h":"규조토에 흡수시켜 다이너마이트를 만드는 제5류 물질은 나이트로글리세린(질산에스터류, 제1종 10kg)이다. 글리세린에 질산을 황산 촉매로 반응시켜 만들며, 분해하면 이산화탄소, 수증기, 질소, 산소가 나온다.","ai":"2020-5-08_a.svg","t":"kan","칸":[{"a":"질산에스터류, 10kg","k":[["질산에스터","질산에스테르"],["10"]],"l":"나"},{"a":"4C3H5(ONO2)3→12CO2+10H2O+6N2+O2","syn":["4C3H5(ONO2)3->12CO2+10H2O+6N2+O2","4C3H5(ONO2)3=12CO2+10H2O+6N2+O2","4C3H5(ONO2)3→12CO2+6N2+O2+10H2O","4C3H5(ONO2)3->12CO2+6N2+O2+10H2O","4C3H5N3O9→12CO2+10H2O+6N2+O2"],"l":"다"}],"순서무관":false},{"id":"2020-5-09","y":2020,"r":5,"n":9,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"간이탱크저장소에 대하여 다음 물음에 답하시오.\n• 하나의 간이탱크저장소에 설치하는 간이저장탱크는 그 수를 3 이하로 한다.\n• 간이저장탱크는 움직이거나 넘어지지 아니하도록 지면 또는 가설대에 고정시키되, 옥외에 설치하는 경우에는 그 탱크의 주위에 너비 ( 가 )m 이상의 공지를 두고, 전용실 안에 설치하는 경우에는 탱크와 전용실의 벽과의 사이에 ( 나 )m 이상의 간격을 유지하여야 한다.\n• 간이저장탱크의 용량은 ( 다 )L 이하이어야 한다.\n• 간이저장탱크는 두께 ( 라 )mm 이상의 강판으로 흠이 없도록 제작하여야 하며, ( 마 )kPa의 압력으로 10분간의 수압시험을 실시하여 새거나 변형되지 아니하여야 한다.","a":"가. 1\n나. 0.5\n다. 600\n라. 3.2\n마. 70","h":"간이저장탱크는 한 저장소에 3개 이하, 용량은 600L 이하이다. 옥외에 둘 때는 주위에 너비 1m 이상의 공지를, 전용실 안이면 벽과 0.5m 이상의 간격을 둔다. 강판 두께는 3.2mm 이상이고 70kPa 로 10분간 수압시험을 한다.","t":"kan","칸":[{"a":"1","syn":["1m","1m 이상","1미터"],"l":"가"},{"a":"0.5","syn":["0.5m","0.5m 이상","0.5미터","50cm"],"l":"나"},{"a":"600","syn":["600L","600 L","600리터"],"l":"다"},{"a":"3.2","syn":["3.2mm","3.2 mm"],"l":"라"},{"a":"70","syn":["70kPa","70 kPa"],"l":"마"}],"순서무관":false},{"id":"2020-5-10","y":2020,"r":5,"n":10,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물인 아세트알데하이드에 대하여 다음 물음에 알맞은 답을 쓰시오.\n가. 시성식\n나. 에틸렌을 직접산화방식으로 반응시켰을 때 화학반응식을 쓰시오.\n다. 아세트알데하이드를 압력탱크 외의 탱크에 저장하는 경우 저장온도를 쓰시오.\n라. 아세트알데하이드를 압력탱크에 저장하는 경우 저장온도를 쓰시오.","a":"가. CH3CHO\n나. C2H4 + PdCl2 + H2O → CH3CHO + Pd + 2HCl\n다. 15℃ 이하\n라. 40℃ 이하","h":"아세트알데하이드(CH3CHO)는 제4류 특수인화물 수용성(50L)이고, 에틸렌을 염화팔라듐과 물로 산화해 만든다. 저장 온도는 압력탱크 외의 탱크가 15℃ 이하, 압력탱크가 40℃ 이하이다.","t":"kan","칸":[{"a":"CH3CHO","syn":["아세트알데하이드","아세트알데히드","C2H4O","CH3CH=O"],"l":"가"},{"a":"C2H4+PdCl2+H2O→CH3CHO+Pd+2HCl","syn":["C2H4+PdCl2+H2O->CH3CHO+Pd+2HCl","C2H4+PdCl2+H2O=CH3CHO+Pd+2HCl","C2H4+PdCl2+H2O→CH3CHO+2HCl+Pd","C2H4+PdCl2+H2O->CH3CHO+2HCl+Pd","2C2H4+O2→2CH3CHO","2C2H4+O2->2CH3CHO","2C2H4+O2=2CH3CHO","C2H4+1/2O2→CH3CHO","C2H4+1/2O2->CH3CHO"],"l":"나"},{"a":"15℃","syn":["15","15도","15℃ 이하","15도 이하"],"l":"다"},{"a":"40℃","syn":["40","40도","40℃ 이하","40도 이하"],"l":"라"}],"순서무관":false},{"id":"2020-5-11","y":2020,"r":5,"n":11,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"흑색화약의 원료 3가지 중 위험물인 것에 대하여 다음 표에 알맞은 답을 쓰시오.\n| 화학식 | 품명 | 지정수량 |\n| ( 가 ) | ( 나 ) | ( 다 ) |\n| ( 라 ) | ( 마 ) | ( 바 ) |","a":"가. KNO3\n나. 질산염류\n다. 300kg\n라. S\n마. 황\n바. 100kg","h":"흑색화약은 질산칼륨, 황, 탄소를 섞은 것이고 이 중 위험물은 질산칼륨과 황이다. 질산칼륨은 제1류 질산염류(300kg), 황은 제2류(100kg)이며 탄소는 위험물이 아니다.","t":"kan","칸":[{"a":"KNO3","syn":["질산칼륨","질산 칼륨"],"l":"가"},{"a":"질산염류","syn":["질산염","질산 염류"],"l":"나"},{"a":"300kg","syn":["300","300 kg"],"l":"다"},{"a":"S","syn":["s","황","유황","sulfur"],"l":"라"},{"a":"황","syn":["유황","sulfur","S"],"l":"마"},{"a":"100kg","syn":["100","100 kg"],"l":"바"}],"순서무관":false},{"id":"2020-5-12","y":2020,"r":5,"n":12,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"다음 물음에 답하시오.\n가. 아세트산과 과산화나트륨의 반응식을 쓰시오.\n나. 아세트산의 연소반응식을 쓰시오.","a":"가. 2CH3COOH + Na2O2 → 2CH3COONa + H2O2\n나. CH3COOH + 2O2 → 2CO2 + 2H2O","h":"무기과산화물인 과산화나트륨이 산을 만나면 과산화수소가 나오므로 아세트산과는 아세트산나트륨과 과산화수소가 생긴다. 아세트산이 타면 이산화탄소와 수증기가 생긴다.","t":"kan","칸":[{"a":"2CH3COOH+Na2O2→2CH3COONa+H2O2","syn":["2CH3COOH+Na2O2->2CH3COONa+H2O2","2CH3COOH+Na2O2=2CH3COONa+H2O2","Na2O2+2CH3COOH→2CH3COONa+H2O2","Na2O2+2CH3COOH->2CH3COONa+H2O2"],"l":"가"},{"a":"CH3COOH+2O2→2CO2+2H2O","syn":["CH3COOH+2O2->2CO2+2H2O","CH3COOH+2O2=2CO2+2H2O","CH3COOH+2O2→2H2O+2CO2","CH3COOH+2O2->2H2O+2CO2"],"l":"나"}],"순서무관":false},{"id":"2020-5-13","y":2020,"r":5,"n":13,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물 중 수용성인 위험물을 고르시오.\n사이안화수소, 아세톤, 클로로벤젠, 글리세린, 하이드라진","a":"사이안화수소, 아세톤, 글리세린, 하이드라진","h":"수용성인 것은 사이안화수소와 아세톤(제1석유류), 하이드라진(제2석유류), 글리세린(제3석유류)이다. 클로로벤젠만 비수용성 제2석유류(1,000L)이다.","t":"kan","칸":[{"a":"사이안화수소","syn":["시안화수소","청산","HCN","사이안화 수소","시안화 수소"]},{"a":"아세톤","syn":["Acetone","CH3COCH3","디메틸케톤"]},{"a":"글리세린","syn":["글리세롤","C3H5(OH)3","글리세린"]},{"a":"하이드라진","syn":["히드라진","하이드라진","N2H4","히드라진"]}],"순서무관":true},{"id":"2020-5-14","y":2020,"r":5,"n":14,"p":"반응식","kw":"물과 반응","pt":5,"q":"제3류 위험물인 탄화칼슘에 대하여 다음 물음에 답하시오.\n가. 탄화칼슘과 물의 반응식을 쓰시오.\n나. 가.의 반응에서 생성되는 기체의 명칭을 쓰시오.\n다. 나.에서 생성되는 기체의 완전연소반응식을 쓰시오.","a":"가. CaC2 + 2H2O → Ca(OH)2 + C2H2\n나. 아세틸렌\n다. 2C2H2 + 5O2 → 4CO2 + 2H2O","h":"탄화칼슘은 물과 반응해 수산화칼슘과 아세틸렌을 내고, 아세틸렌이 타면 이산화탄소와 물이 된다. 같은 탄화물인 탄화알루미늄은 아세틸렌이 아니라 메테인을 낸다.","t":"kan","칸":[{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"가"},{"a":"아세틸렌","syn":["C2H2","에틴","에타인","아세틸렌가스","acetylene"],"l":"나"},{"a":"2C2H2+5O2→4CO2+2H2O","syn":["2C2H2+5O2->4CO2+2H2O","2C2H2+5O2=4CO2+2H2O","C2H2+5/2O2→2CO2+H2O","C2H2+5/2O2->2CO2+H2O","C2H2+2.5O2→2CO2+H2O"],"l":"다"}],"순서무관":false},{"id":"2020-5-15","y":2020,"r":5,"n":15,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"제조소와의 안전거리 기준에 따라 다음 물음에 알맞은 답을 쓰시오.\n가. 제조소 외벽과 가연성 가스시설의 안전거리\n나. 제조소 외벽과 동일부지 외의 주거용 주택 안전거리\n다. 제조소 외벽과 특고압가공전선(50,000V)과의 안전거리","a":"가. 20m 이상\n나. 10m 이상\n다. 5m 이상","h":"제조소 외벽에서 주택까지는 10m, 가스 저장·취급 시설까지는 20m 이상이다. 특고압가공전선은 7,000V 초과 35,000V 이하가 3m, 35,000V 초과가 5m이므로 50,000V 는 5m이다. 학교·병원·극장은 30m, 지정문화유산은 50m 이상이다.","t":"kan","칸":[{"a":"20","syn":["20m","20m 이상","20미터"],"l":"가"},{"a":"10","syn":["10m","10m 이상","10미터"],"l":"나"},{"a":"5","syn":["5m","5m 이상","5미터"],"l":"다"}],"순서무관":false},{"id":"2020-5-16","y":2020,"r":5,"n":16,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물을 운반할 때 취급하는 위험물의 지정수량이 1/10을 초과할 경우 다음 각 유별에 따른 혼재가 가능한 위험물을 쓰시오.\n가. 제2류 위험물\n나. 제3류 위험물\n다. 제4류 위험물","a":"가. 제4류 위험물, 제5류 위험물\n나. 제4류 위험물\n다. 제2류 위험물, 제3류 위험물, 제5류 위험물","h":"혼재할 수 있는 조합은 제4류-제2류, 제4류-제3류, 제5류-제2류, 제5류-제4류, 제6류-제1류뿐이다. 그래서 제2류는 제4·5류, 제3류는 제4류, 제4류는 제2·3·5류와만 섞을 수 있다.","t":"kan","칸":[{"a":"제4류 위험물, 제5류 위험물","k":[["4류"],["5류"]],"l":"가"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"나"},{"a":"제2류 위험물, 제3류 위험물, 제5류 위험물","k":[["2류"],["3류"],["5류"]],"l":"다"}],"순서무관":false},{"id":"2020-5-17","y":2020,"r":5,"n":17,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"위험물 제조소의 보유공지 단축을 위한 방화벽 설치 기준이다. 빈칸을 알맞게 채우시오.\n가. 방화벽은 ( )로 할 것. 다만, 취급하는 위험물이 제6류 위험물인 경우 불연재료로 할 수 있다.\n나. 방화벽에 설치하는 출입구 및 창 등의 개구부는 가능한 한 최소로 하고, 출입구 및 창에는 자동폐쇄식의 ( )을 설치할 것\n다. 방화벽의 양단 및 상단이 외벽 또는 지붕으로부터 ( )cm 이상 돌출하도록 할 것","a":"가. 내화구조\n나. 60분+ 방화문·60분 방화문\n다. 50","h":"방화벽은 내화구조로 하되 제6류 위험물을 취급하면 불연재료도 가능하다. 출입구·창 같은 개구부는 최소로 하고 자동폐쇄식 60분+ 방화문 또는 60분 방화문을 단다. 양단과 상단은 외벽이나 지붕에서 50cm 이상 돌출시킨다.","t":"kan","칸":[{"a":"내화구조","syn":["내화 구조"],"l":"가"},{"a":"60분+방화문","syn":["60분+ 방화문","60분 방화문","60분방화문","방화문","갑종방화문","60분+방화문 또는 60분방화문","60분+방화문·60분방화문","60분+방화문 60분방화문"],"l":"나"},{"a":"50","syn":["50cm","50센티미터"],"l":"다"}],"순서무관":false},{"id":"2020-5-18","y":2020,"r":5,"n":18,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물 중에서 물과 반응하여 가연성가스를 발생하는 물질 3가지를 고르고, 물과의 반응식을 쓰시오.\n칼슘, 황린, 과염소산, 나트륨, 인화칼슘","a":"칼슘, 나트륨, 인화칼슘\n가. 칼슘: Ca + 2H2O → Ca(OH)2 + H2\n나. 나트륨: 2Na + 2H2O → 2NaOH + H2\n다. 인화칼슘: Ca3P2 + 6H2O → 3Ca(OH)2 + 2PH3","h":"물과 반응해 가연성 가스가 나오는 것은 칼슘과 나트륨(수소), 인화칼슘(포스핀)이다. 황린은 물과 반응하지 않아 물속에 저장하고, 과염소산도 물과 반응하지 않는다.","t":"kan","칸":[{"a":"칼슘","syn":["Ca","calcium"]},{"a":"나트륨","syn":["Na","소듐"]},{"a":"인화칼슘","syn":["Ca3P2","인화 칼슘"]},{"a":"Ca+2H2O→Ca(OH)2+H2","syn":["Ca+2H2O->Ca(OH)2+H2","Ca+2H2O=Ca(OH)2+H2"]},{"a":"2Na+2H2O→2NaOH+H2","syn":["2Na+2H2O->2NaOH+H2","2Na+2H2O=2NaOH+H2","Na+H2O→NaOH+1/2H2"]},{"a":"Ca3P2+6H2O→3Ca(OH)2+2PH3","syn":["Ca3P2+6H2O->3Ca(OH)2+2PH3","Ca3P2+6H2O=3Ca(OH)2+2PH3","Ca3P2+6H2O→2PH3+3Ca(OH)2","Ca3P2+6H2O->2PH3+3Ca(OH)2"]}],"순서무관":true,"nc":3},{"id":"2020-5-19","y":2020,"r":5,"n":19,"p":"물질·성상","kw":"소화약제","pt":5,"q":"다음 소화약제의 화학식을 쓰시오.\n가. 하론1301\n나. IG-100\n다. 제2종 분말소화약제","a":"가. CF3Br\n나. N2\n다. KHCO3","h":"하론 번호는 C, F, Cl, Br 의 개수 순이라 1301 은 CF3Br 이다. IG-100 은 질소 100%, IG-55 는 N2·Ar 각 50%, IG-541 은 N2 52%·Ar 40%·CO2 8%이다. 분말은 제1종 NaHCO3, 제2종 KHCO3, 제3종 NH4H2PO4(ABC), 제4종 KHCO3 + 요소이다.","t":"kan","칸":[{"a":"CF3Br","syn":["CBrF3","BrCF3","할론1301","Halon1301"],"l":"가"},{"a":"N2","syn":["질소","n2","질소가스"],"l":"나"},{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨","KHCO3"],"l":"다"}],"순서무관":false},{"id":"2020-5-20","y":2020,"r":5,"n":20,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"위험물에 따른 소화설비 적응성을 나타낸 표이다. 빈칸에 알맞은 말을 쓰시오.\n| 소화설비의 구분 | 건축물·그 밖의 공작물 | 전기설비 | 제1류 알칼리금속 과산화물등 | 제1류 그 밖의 것 | 제2류 철분·금속분·마그네슘등 | 제2류 인화성고체 | 제2류 그 밖의 것 | 제3류 금수성물질 | 제3류 그 밖의 것 | 제4류 | 제5류 | 제6류 |\n| ( 가 )소화전설비 또는 ( 나 )소화전설비 | ○ |   |   | ○ |   | ○ | ○ |   | ○ |   | ○ | ○ |\n| 스프링클러설비 | ○ |   |   | ○ |   | ○ | ○ |   | ○ | △ | ○ | ○ |\n| 물분무등소화설비 : ( 다 ) 소화설비 | ○ | ○ |   | ○ |   | ○ | ○ |   | ○ | ○ | ○ | ○ |\n| 물분무등소화설비 : ( 라 ) 소화설비 | ○ |   |   | ○ |   | ○ | ○ |   | ○ | ○ | ○ | ○ |\n| 물분무등소화설비 : 불활성가스소화설비 |   | ○ |   |   |   | ○ |   |   |   | ○ |   |\n| 물분무등소화설비 : 할로젠화합물소화설비 |   | ○ |   |   |   | ○ |   |   |   | ○ |   |\n| 물분무등소화설비 : ( 마 ) 소화설비 - 인산염류등 | ○ | ○ |   | ○ |   | ○ | ○ |   |   | ○ |   | ○ |\n| 물분무등소화설비 : ( 마 ) 소화설비 - 탄산수소염류등 |   | ○ | ○ |   | ○ | ○ |   | ○ |   | ○ |   |\n| 물분무등소화설비 : ( 마 ) 소화설비 - 그 밖의 것 |   |   | ○ |   | ○ |   |   | ○ |   |   |   |\n(○ 적응성 있음, △ 살수밀도에 따라 적응성 있음, 빈칸은 없음)","a":"가. 옥내\n나. 옥외\n다. 물분무\n라. 포\n마. 분말","h":"소화설비는 옥내·옥외소화전설비, 스프링클러설비, 물분무등소화설비로 나뉜다. 물분무등소화설비에는 물분무, 포, 불활성가스, 할로젠화합물, 분말소화설비가 속한다. 제4류의 스프링클러는 살수밀도에 따라 적응성이 달라 △로 표시한다.","t":"kan","칸":[{"a":"옥내","syn":["옥내소화전","옥내 소화전"],"l":"가"},{"a":"옥외","syn":["옥외소화전","옥외 소화전"],"l":"나"},{"a":"물분무","syn":["물분무소화","물 분무","물분무 소화"],"l":"다"},{"a":"포","syn":["포소화","폼","foam","포 소화","거품"],"l":"라"},{"a":"분말","syn":["분말소화","분말 소화","dry chemical"],"l":"마"}],"순서무관":false},{"id":"2021-1-01","y":2021,"r":1,"n":1,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"마그네슘 화재 시 이산화탄소를 이용한 소화가 불가능하다. 다음 물음에 답하시오.\n가. 화학반응식을 쓰시오.\n나. 이산화탄소를 이용한 소화가 불가능한 이유를 쓰시오.","a":"가. 2Mg + CO2 → 2MgO + C\n나. 가연성인 탄소가 발생해 화재가 확대되므로 소화할 수 없다.","h":"마그네슘은 이산화탄소 속에서도 산소를 빼앗아 산화마그네슘이 되고 탄소가 남는다. 이 탄소는 타는 물질이라 불이 더 번지므로 이산화탄소소화설비를 쓸 수 없다.","t":"kan","칸":[{"a":"2Mg+CO2→2MgO+C","syn":["2Mg+CO2->2MgO+C","2Mg+CO2=2MgO+C","2Mg+CO2→C+2MgO","2Mg+CO2->C+2MgO","Mg+CO2→MgO+CO","Mg+CO2->MgO+CO"],"l":"가"},{"a":"가연성인 탄소가 발생해 화재가 확대되므로 소화할 수 없다","k":[["탄소","일산화탄소","CO"],["가연","폭발","화재","연소","발생","생성"]],"l":"나"}],"순서무관":false},{"id":"2021-1-02","y":2021,"r":1,"n":2,"p":"반응식","kw":"열분해","pt":5,"q":"과산화수소에 이산화망가니즈를 촉매로 하여 분해 시켰다. 다음 물음에 답하시오.\n가. 화학반응식을 쓰시오.\n나. 발생하는 기체의 명칭을 쓰시오.","a":"가. 2H2O2 --(MnO2)--> 2H2O + O2\n나. 산소","h":"제6류 과산화수소는 이산화망가니즈가 촉매로 있으면 물과 산소로 분해된다. 발생 기체는 산소이다.","t":"kan","칸":[{"a":"2H2O2→2H2O+O2","syn":["2H2O2->2H2O+O2","2H2O2=2H2O+O2","2H2O2--(MnO2)-->2H2O+O2","2H2O2-(MnO2)->2H2O+O2","2H2O2-MnO2->2H2O+O2","2H2O2→(MnO2)2H2O+O2","2H2O2(MnO2)→2H2O+O2","2H2O2MnO2→2H2O+O2","2H2O2+MnO2→2H2O+O2+MnO2","H2O2→H2O+1/2O2","H2O2->H2O+1/2O2"],"l":"가"},{"a":"산소","syn":["O2","산소가스","oxygen"],"l":"나"}],"순서무관":false},{"id":"2021-1-03","y":2021,"r":1,"n":3,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"1기압 50℃에서 이황화탄소 5kg이 모두 증발할 때 기체의 부피(m3)를 구하시오.","a":"① P=1atm, T=50+273=323K, w=5kg, M(CS2)=76kg/kmol, R=0.082atm·m3/kmol·K\n② V = wRT/PM\n③ (5×0.082×323)/(1×76) = 1.7425\n④ 1.74m3","h":"이황화탄소의 분자량은 12 + 32×2 = 76 이다. 질량을 kg, 기체상수를 m3·kmol 단위로 맞추면 부피가 m3 로 나온다. 증발만 하고 반응은 없으므로 반응식 계수는 쓰지 않는다.","t":"calc","e":0.02,"ka":"1.74"},{"id":"2021-1-04","y":2021,"r":1,"n":4,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음 탱크의 내용적을 구하시오.\n(세로형 원통형 탱크 : 지름 10m, 높이 4m)","a":"① 세로형 원통: 반지름 5m, 높이 4m\n② V = πr2l\n③ π × 52 × 4 = 314.159\n④ 314.16m3","h":"지름이 10m이므로 반지름 5m를 대입한다. 세로형 원통의 내용적은 밑넓이 πr2 에 높이를 곱한 값이다.","tp":"W04","t":"calc","e":0.5,"ka":"314.16"},{"id":"2021-1-05","y":2021,"r":1,"n":5,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"메탄올 1몰 연소 시 화학반응식을 쓰고 생성물질의 몰수를 구하시오.","a":"① 2CH3OH + 3O2 → 2CO2 + 4H2O\n② 메탄올 2mol 당 생성물 2 + 4 = 6mol\n③ 메탄올 1mol 이면 6 ÷ 2 = 3\n④ 3몰","h":"탄소, 수소, 산소 수를 양쪽에서 맞추면 CH3OH : O2 : CO2 : H2O = 1 : 3/2 : 1 : 2 이고, 분수를 없애려 모두 2배 한다. 메탄올 1mol이 타면 이산화탄소 1mol과 물 2mol, 합쳐서 3mol이 생긴다.","tp":"W01","t":"kan","칸":[{"a":"2CH3OH+3O2→2CO2+4H2O","syn":["2CH3OH+3O2->2CO2+4H2O","2CH3OH+3O2=2CO2+4H2O","CH3OH+3/2O2→CO2+2H2O","CH3OH+3/2O2->CO2+2H2O","CH3OH+1.5O2→CO2+2H2O","2CH3OH+3O2→4H2O+2CO2"],"l":"반응식"},{"a":"3","syn":["3몰","3mol","3 mol"],"l":"몰수"}],"순서무관":false},{"id":"2021-1-06","y":2021,"r":1,"n":6,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"일반취급소 또는 제조소에서 취급하는 제4류 위험물의 최대수량의 합이 다음과 같을 때 사업소에 두는 자체소방대의 화학소방자동차 대수와 자체소방대원의 수를 각각 쓰시오.\n가. 3천배 이상 12만배 미만\n나. 12만배 이상 24만배 미만\n다. 24만배 이상 48만배 미만\n라. 48만배 이상","a":"가. 1대, 5인\n나. 2대, 10인\n다. 3대, 15인\n라. 4대, 20인","h":"제4류 최대수량이 지정수량의 3천배 이상이면 자체소방대를 둔다. 구간이 3천~12만배, 12만~24만배, 24만~48만배, 48만배 이상으로 올라갈 때마다 화학소방차는 1대씩, 대원은 5인씩 늘어 최대 4대·20인이다.","t":"kan","칸":[{"a":"1","syn":["1대"],"l":"가-대수"},{"a":"5","syn":["5인","5명"],"l":"가-인원"},{"a":"2","syn":["2대"],"l":"나-대수"},{"a":"10","syn":["10인","10명"],"l":"나-인원"},{"a":"3","syn":["3대"],"l":"다-대수"},{"a":"15","syn":["15인","15명"],"l":"다-인원"},{"a":"4","syn":["4대"],"l":"라-대수"},{"a":"20","syn":["20인","20명"],"l":"라-인원"}],"순서무관":false},{"id":"2021-1-07","y":2021,"r":1,"n":7,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"질산암모늄 중에서 다음 원소의 중량백분율을 구하시오.\n가. 질소\n나. 수소","a":"① NH4NO3 = 14 + 1×4 + 14 + 16×3 = 80\n② 중량% = 원소 질량 합 ÷ 분자량 × 100\n③ 가: (14×2)/80 × 100, 나: (1×4)/80 × 100\n④ 가. 35%, 나. 5%","h":"질산암모늄에는 질소 원자가 2개(NH4와 NO3에 하나씩), 수소 원자가 4개 들어 있다. 분자량 80 에서 질소 28 은 35%, 수소 4 는 5%이다.","t":"kan","칸":[{"a":"35","e":0.5,"l":"가"},{"a":"5","e":0.1,"l":"나"}],"순서무관":false},{"id":"2021-1-08","y":2021,"r":1,"n":8,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"위험물안전관리법령에서 정한 제조소 중 옥외탱크저장소에 소화난이도등급 I에 해당하는 항목을 모두 고르시오 (단, 해당 답이 없으면 없음이라 쓰시오).\n가. 질산 60,000kg을 저장하는 옥외탱크저장소\n나. 과산화수소 액표면적이 40m2 이상인 옥외탱크저장소\n다. 이황화탄소 500L를 저장하는 옥외탱크저장소\n라. 황 14,000kg을 저장하는 지중탱크\n마. 휘발유 100,000L를 저장하는 해상탱크","a":"라, 마","h":"옥외탱크저장소의 소화난이도등급 I 에서는 제6류 위험물 저장 탱크가 빠지므로 질산과 과산화수소(가·나)는 해당하지 않는다. 이황화탄소 500L는 지정수량 50L의 10배이고 지중·해상탱크도 아니라 제외된다. 황 14,000kg은 100kg의 140배인 지중탱크, 휘발유 100,000L는 200L의 500배인 해상탱크라 지정수량 100배 이상 조건에 든다.","t":"kan","칸":[{"a":"라","syn":["ㄹ","(라)","라.","지중탱크"]},{"a":"마","syn":["ㅁ","(마)","마.","해상탱크"]}],"순서무관":true},{"id":"2021-1-09","y":2021,"r":1,"n":9,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"다음은 옥내저장소의 격벽에 대한 설치기준이다. 빈칸을 알맞게 채우시오.\n저장창고는 ( 가 )m2 이내마다 격벽으로 완전하게 구획할 것. 이 경우 당해 격벽은 두께 ( 나 )cm 이상의 철근콘크리트조 또는 철골철근콘크리트조로 하거나 두께 ( 다 )cm 이상의 보강콘크리트블록조로 하고, 당해 저장창고의 양측 외벽으로부터 ( 라 )m 이상, 상부의 지붕으로부터 ( 마 )cm 이상 돌출하게 해야 한다.","a":"가. 150\n나. 30\n다. 40\n라. 1\n마. 50","h":"지정과산화물 옥내저장소의 저장창고는 150m2 이내마다 격벽으로 구획한다. 격벽 두께는 철근콘크리트조·철골철근콘크리트조 30cm 이상 또는 보강콘크리트블록조 40cm 이상이다. 양측 외벽에서 1m 이상, 지붕 위로 50cm 이상 돌출시킨다.","t":"kan","칸":[{"a":"150","syn":["150m2","150㎡"],"l":"가"},{"a":"30","syn":["30cm"],"l":"나"},{"a":"40","syn":["40cm"],"l":"다"},{"a":"1","syn":["1m","1미터"],"l":"라"},{"a":"50","syn":["50cm"],"l":"마"}],"순서무관":false},{"id":"2021-1-10","y":2021,"r":1,"n":10,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"제조소의 배출설비에 대한 기준이다. 빈칸에 들어갈 알맞은 말을 쓰시오.\n• 배출능력은 1시간당 배출장소 용적의 ( 가 )배 이상인 것으로 하여야 한다. 다만, 전역방식의 경우에는 바닥면적 1m2당 ( 나 )m3 이상으로 할 수 있다.\n• 배출구는 지상 ( 다 )m 이상으로서 연소의 우려가 없는 장소에 설치하고, ( 라 )가 관통하는 벽부분의 바로 가까이에 화재 시 자동으로 폐쇄되는 ( 마 )(화재 시 연기 등을 차단하는 장치)를 설치할 것","a":"가. 20\n나. 18\n다. 2\n라. 배출덕트\n마. 방화댐퍼","h":"배출설비는 국소방식이 원칙이고 능력은 1시간당 배출장소 용적의 20배 이상이다. 전역방식이면 바닥면적 1m2당 18m3 이상으로 할 수 있다. 배출구는 지상 2m 이상에 두고, 배출덕트가 벽을 관통하는 곳 가까이에 화재 시 자동으로 닫히는 방화댐퍼를 단다.","t":"kan","칸":[{"a":"20","syn":["20배"],"l":"가"},{"a":"18","syn":["18m3","18㎥"],"l":"나"},{"a":"2","syn":["2m","2미터"],"l":"다"},{"a":"배출덕트","syn":["덕트","배기덕트","배출 덕트","배출닥트","배기 덕트"],"l":"라"},{"a":"방화댐퍼","syn":["댐퍼","방화 댐퍼","방화대퍼","fire damper","FD"],"l":"마"}],"순서무관":false},{"id":"2021-1-11","y":2021,"r":1,"n":11,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 중 위험물과 지정수량이 알맞게 짝지어진 것을 고르시오.\n가. 테레핀유 2,000L\n나. 아닐린 2,000L\n다. 피리딘 400L\n라. 실린더유 6,000L\n마. 산화프로필렌 200L","a":"나, 다, 라","h":"아닐린은 제3석유류 비수용성 2,000L, 피리딘은 제1석유류 수용성 400L, 실린더유는 제4석유류 6,000L라서 짝이 맞는다. 산화프로필렌은 특수인화물이라 200L가 아니라 50L다. 테레핀유도 2,000L가 아니다. 스캔 해설은 동식물유류 10,000L로 적었고, 법령상 품명은 제2석유류(비수용성) 1,000L다.","t":"kan","칸":[{"a":"나","syn":["ㄴ","(나)","나.","아닐린"]},{"a":"다","syn":["ㄷ","(다)","다.","피리딘"]},{"a":"라","syn":["ㄹ","(라)","라.","실린더유"]}],"순서무관":true},{"id":"2021-1-12","y":2021,"r":1,"n":12,"p":"반응식","kw":"열분해","pt":5,"q":"분말소화약제의 1차 분해 반응식을 쓰시오.\n가. 제1종 분말소화약제\n나. 제2종 분말소화약제","a":"가. 2NaHCO3 → Na2CO3 + CO2 + H2O\n나. 2KHCO3 → K2CO3 + CO2 + H2O","h":"탄산수소나트륨과 탄산수소칼륨은 가열하면 각각 탄산염, 이산화탄소, 물로 갈라지고 계수는 둘 다 2 : 1 : 1 : 1 이다. 제1종은 Na2CO3, 제2종은 K2CO3 가 남는다.","t":"kan","칸":[{"a":"2NaHCO3→Na2CO3+CO2+H2O","syn":["2NaHCO3->Na2CO3+CO2+H2O","2NaHCO3=Na2CO3+CO2+H2O","2NaHCO3→Na2CO3+H2O+CO2","2NaHCO3->Na2CO3+H2O+CO2"],"l":"가"},{"a":"2KHCO3→K2CO3+CO2+H2O","syn":["2KHCO3->K2CO3+CO2+H2O","2KHCO3=K2CO3+CO2+H2O","2KHCO3→K2CO3+H2O+CO2","2KHCO3->K2CO3+H2O+CO2"],"l":"나"}],"순서무관":false},{"id":"2021-1-13","y":2021,"r":1,"n":13,"p":"반응식","kw":"물과 반응","pt":5,"q":"탄화칼슘과 물이 접촉하였다. 다음 물음에 답하시오.\n가. 화학반응식\n나. 발생하는 기체의 연소반응식","a":"가. CaC2 + 2H2O → Ca(OH)2 + C2H2\n나. 2C2H2 + 5O2 → 4CO2 + 2H2O","h":"탄화칼슘이 물을 만나면 수산화칼슘과 아세틸렌이 생긴다. 아세틸렌 1분자를 태우는 데 산소 2.5분자가 필요해 전체를 2배 하여 2C2H2 + 5O2 → 4CO2 + 2H2O 로 쓴다.","t":"kan","칸":[{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"가"},{"a":"2C2H2+5O2→4CO2+2H2O","syn":["2C2H2+5O2->4CO2+2H2O","2C2H2+5O2=4CO2+2H2O","C2H2+5/2O2→2CO2+H2O","C2H2+5/2O2->2CO2+H2O","C2H2+2.5O2→2CO2+H2O"],"l":"나"}],"순서무관":false},{"id":"2021-1-14","y":2021,"r":1,"n":14,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제1석유류 중 이소프로필알코올을 산화시켜 만든 것으로, 아이오딘폼반응을 하는 물질에 대하여 다음 물음에 답하시오.\n가. 물질명\n나. 아이오딘폼 화학식\n다. 아이오딘폼 반응 후 색 변화","a":"가. 아세톤\n나. CHI3\n다. 노란색","h":"이소프로필알코올(2차 알코올)을 산화하면 수소 2개가 빠져 아세톤(CH3COCH3)이 된다. 아세틸기(CH3CO-)가 있는 물질이 수산화알칼리와 아이오딘을 만나면 노란색 아이오딘폼(CHI3) 침전이 생긴다. 메틸알코올은 아세틸기가 없어 반응하지 않고, 에탄올·아세톤·아세트알데하이드 등은 반응한다.","t":"kan","칸":[{"a":"아세톤","syn":["CH3COCH3","프로파논","다이메틸케톤","디메틸케톤","디메틸 케톤","acetone","Acetone","C3H6O"],"l":"가"},{"a":"CHI3","syn":["아이오딘폼","요오드포름","요오드폼","아이오도폼","iodoform"],"l":"나"},{"a":"노란색","syn":["황색","노랑","노랑색","노란 색","yellow","담황색","연노랑"],"l":"다"}],"순서무관":false},{"id":"2021-1-15","y":2021,"r":1,"n":15,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"다음은 위험물의 성질에 따른 제조소의 특례이다. 빈칸에 들어갈 알맞은 말을 쓰시오.\n가. ( )을 취급하는 설비에는 불활성기체를 봉입하는 장치를 갖출 것\n나. ( )을 취급하는 설비는 은·수은·동·마그네슘 또는 이들을 성분으로 하는 합금으로 만들지 아니할 것\n다. ( )을 취급하는 설비에는 철이온 등의 혼입에 의한 위험한 반응을 방지하기 위한 조치를 강구할 것","a":"가. 알킬알루미늄등\n나. 아세트알데하이드등\n다. 하이드록실아민등","h":"제조소 특례는 물질에 따라 설비 조건이 달라진다. 알킬알루미늄등은 불활성기체 봉입 장치, 아세트알데하이드등은 은·수은·동·마그네슘 및 이들 합금 사용 금지, 하이드록실아민등은 철이온 혼입 방지 조치이다.","t":"kan","칸":[{"a":"알킬알루미늄등","syn":["알킬알루미늄","알킬알루미늄 등","알킬알미늄","알킬알루미늄 또는 알킬리튬","알킬알루미늄, 알킬리튬"],"l":"가"},{"a":"아세트알데하이드등","syn":["아세트알데하이드","아세트알데히드","아세트알데하이드 등","아세트알데이드","프로필렌옥사이드","산화프로필렌","산화프로필렌등"],"l":"나"},{"a":"하이드록실아민등","syn":["하이드록실아민","히드록실아민","하이드록실아민 등","하이드록시아민","하이드록실아민염류"],"l":"다"}],"순서무관":false},{"id":"2021-1-17","y":2021,"r":1,"n":17,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제2류 위험물의 위험물 기준에 대한 설명이다. 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n가. ( )는 고형 알코올, 그 밖에 1기압에서 인화점이 40℃ 미만인 고체를 말한다.\n나. 철분이라 함은 철의 분말로서 ( )㎛의 표준체를 통과하는 것이 ( )중량% 이상인 것을 말한다.","a":"가. 인화성고체\n나. 53, 50","h":"인화성고체는 고형알코올과 그 밖에 1기압에서 인화점이 40℃ 미만인 고체이다. 철분은 53㎛ 체를 통과하는 것이 50중량% 이상인 철의 분말이다. 금속분은 150㎛, 황은 순도 60중량% 이상이 기준이다.","t":"kan","칸":[{"a":"인화성고체","syn":["인화성 고체"],"l":"가"},{"a":"53","syn":["53㎛","53μm","53um","53마이크로미터"],"l":"나-1"},{"a":"50","syn":["50%","50중량%","50wt%","50중량퍼센트"],"l":"나-2"}],"순서무관":false},{"id":"2021-1-18","y":2021,"r":1,"n":18,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제4류 위험물 중 알코올류의 정의이다. 다음 빈칸에 알맞은 말을 쓰시오.\n알코올류라 함은 1분자를 구성하는 탄소원자의 수가 1개부터 ( 가 )개까지인 포화1가 알코올(변성알코올을 포함한다)을 말한다. 다만, 다음 각목의 1에 해당하는 것은 제외한다.\n• 1분자를 구성하는 탄소원자의 수가 1개 내지 3개의 포화1가 알코올의 함유량이 ( 나 )중량퍼센트 미만인 수용액\n• 가연성 액체량이 ( 다 )중량퍼센트 미만이고 인화점 및 연소점(태그개방식 인화점측정기에 의한 연소점을 말한다. 이하 같다)이 에틸알코올 60중량퍼센트 수용액의 인화점 및 연소점을 초과하는 것","a":"가. 3\n나. 60\n다. 60","h":"알코올류는 탄소 1~3개인 포화1가 알코올(변성알코올 포함)이다. 제외되는 경우는 알코올 함유량이 60중량% 미만인 수용액, 또는 가연성 액체량이 60중량% 미만이면서 인화점·연소점이 에틸알코올 60중량% 수용액보다 높은 것이다.","t":"kan","칸":[{"a":"3","syn":["3개","3개까지"],"l":"가"},{"a":"60","syn":["60중량퍼센트","60%","60wt%","60중량%"],"l":"나"},{"a":"60","syn":["60중량퍼센트","60%","60wt%","60중량%"],"l":"다"}],"순서무관":false},{"id":"2021-1-19","y":2021,"r":1,"n":19,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물의 운반용기 외부에 표시하여야 하는 주의사항을 쓰시오.\n가. 과산화나트륨\n나. 인화성고체\n다. 황린","a":"가. 가연물접촉주의, 화기·충격주의, 물기엄금\n나. 화기엄금\n다. 화기엄금, 공기접촉엄금","h":"과산화나트륨은 제1류 중 알칼리금속의 과산화물이라 가연물접촉주의·화기·충격주의에 물기엄금이 더해진다. 인화성고체는 제2류에서 유일하게 화기엄금이다. 황린은 제3류 자연발화성 물질이라 화기엄금·공기접촉엄금이다.","t":"kan","칸":[{"a":"가연물접촉주의, 화기·충격주의, 물기엄금","k":[["가연물"],["충격"],["물기"]],"l":"가"},{"a":"화기엄금","syn":["화기 엄금"],"l":"나"},{"a":"화기엄금, 공기접촉엄금","k":[["화기엄금","화기 엄금"],["공기접촉","공기 접촉"]],"l":"다"}],"순서무관":false},{"id":"2021-1-20","y":2021,"r":1,"n":20,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"다음은 위험물제조소등을 나타낸 표이다. 다음 물음에 답하시오.\n| 제조소 | 저장소 | 저장소 | 취급소 |\n| 위험물제조소 | 옥내저장소 | 지하탱크저장소 | 주유취급소 |\n| 옥외저장소 | ( ① ) | 판매취급소 |\n| 옥내탱크저장소 | 이동탱크저장소 | ( ② ) |\n| 옥외탱크저장소 | 암반탱크저장소 | 일반취급소 |\n가. 제조소, 저장소, 취급소를 모두 포함하는 명칭을 쓰시오.\n나. 위 빈칸에 들어갈 알맞은 말을 쓰시오.\n① \n② \n다. 위험물안전관리자를 선임하지 아니하여도 되는 저장소의 종류를 모두 쓰시오.\n라. 일반취급소 중 액체위험물을 용기에 옮겨 담는 취급소의 명칭을 쓰시오.","a":"가. 제조소등\n나. ① 간이탱크저장소, ② 이송취급소\n다. 이동탱크저장소\n라. 충전하는 일반취급소","h":"제조소 1종, 저장소 8종, 취급소 4종을 모두 합쳐 제조소등이라 부른다. 빈칸은 저장소의 간이탱크저장소와 취급소의 이송취급소이다. 안전관리자 선임 대상에서 빠지는 저장소는 이동탱크저장소이고, 액체위험물을 용기에 옮겨 담는 취급소는 충전하는 일반취급소이다.","t":"kan","칸":[{"a":"제조소등","syn":["제조소 등","제조소,저장소,취급소"],"l":"가"},{"a":"간이탱크저장소","syn":["간이탱크","간이 탱크 저장소","간이저장탱크저장소"],"l":"나-①"},{"a":"이송취급소","syn":["이송 취급소"],"l":"나-②"},{"a":"이동탱크저장소","syn":["이동탱크","이동 탱크 저장소"],"l":"다"},{"a":"충전하는 일반취급소","syn":["충전 일반취급소","충전하는일반취급소","충전하는 일반 취급소","충전 취급소","충전하는 취급소","충전일반취급소"],"l":"라"}],"순서무관":false},{"id":"2021-2-01","y":2021,"r":2,"n":1,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물을 운반할 때 취급하는 위험물의 지정수량이 1/10을 초과할 경우 다음 각 유별에 따른 혼재가 불가능한 위험물을 모두 쓰시오.\n가. 제1류 위험물 :\n나. 제2류 위험물 :\n다. 제3류 위험물 :\n라. 제4류 위험물 :\n마. 제5류 위험물 :","a":"가. 제2류, 제3류, 제4류, 제5류 위험물\n나. 제1류, 제3류, 제6류 위험물\n다. 제1류, 제2류, 제5류, 제6류 위험물\n라. 제1류, 제6류 위험물\n마. 제1류, 제3류, 제6류 위험물","h":"혼재할 수 있는 조합은 제4류-제2류, 제4류-제3류, 제5류-제2류, 제5류-제4류, 제6류-제1류뿐이다. 이 조합에 없는 유별이 혼재 불가이므로, 예컨대 제1류는 제6류만 가능하고 제2~5류는 불가이다.","t":"kan","칸":[{"a":"제2류, 제3류, 제4류, 제5류 위험물","k":[["2류"],["3류"],["4류"],["5류"]],"l":"가","no":["6류"]},{"a":"제1류, 제3류, 제6류 위험물","k":[["1류"],["3류"],["6류"]],"l":"나","no":["4류","5류"]},{"a":"제1류, 제2류, 제5류, 제6류 위험물","k":[["1류"],["2류"],["5류"],["6류"]],"l":"다","no":["4류"]},{"a":"제1류, 제6류 위험물","k":[["1류"],["6류"]],"l":"라","no":["2류","3류","5류"]},{"a":"제1류, 제3류, 제6류 위험물","k":[["1류"],["3류"],["6류"]],"l":"마","no":["2류","4류"]}],"순서무관":false},{"id":"2021-2-02","y":2021,"r":2,"n":2,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"덩어리 상태의 황 30,000kg을 300m2의 옥외저장소에 저장한다. 다음 물음에 답하시오.\n가. 나누어야 하는 구역은 몇 개인가?\n나. 경계표지의 간격을 몇 m 이상으로 하여야 하는가?","a":"가. 3개 (300m2 ÷ 100m2)\n나. 10m 이상 (30,000kg ÷ 100kg = 300배)","h":"황을 옥외저장소에 쌓을 때 하나의 경계구역은 100m2 이하라 300m2는 3개 구역이 된다. 황 30,000kg은 지정수량 100kg의 300배이고, 200배 이상이면 경계표지의 간격을 10m 이상 둔다.","t":"kan","칸":[{"a":"3","syn":["3개","3개 구역","3구역"],"l":"가"},{"a":"10","syn":["10m","10m 이상","10미터"],"l":"나"}],"순서무관":false},{"id":"2021-2-03","y":2021,"r":2,"n":3,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"옥내소화전에 대하여 다음 물음에 답하시오.\n가. 건축물의 층마다 당해 층의 각 부분에서 하나의 호스접속구까지의 수평거리가 몇 m 이내가 되도록 설치해야 하는가?\n나. 수원의 수량은 옥내소화전이 가장 많이 설치된 층의 옥내소화전 설치개수(설치개수가 5개 이상인 경우는 5개)에 몇 m3를 곱한 양 이상이 되도록 설치해야 하는가?\n다. 방수압력의 최소 기준은 몇 kPa인가?\n라. 방수량의 최소 기준은 1분당 몇 L인가?","a":"가. 25m 이내\n나. 7.8m3\n다. 350kPa\n라. 260L/min","h":"옥내소화전은 각 부분에서 호스접속구까지 수평거리 25m 이하가 되게 설치한다. 수원은 가장 많이 설치된 층의 개수(최대 5개)에 7.8m3를 곱한 양이고, 방수압력은 350kPa, 방수량은 분당 260L이다.","t":"kan","칸":[{"a":"25","syn":["25m","25m 이내","25미터"],"l":"가"},{"a":"7.8","syn":["7.8m3","7.8㎥"],"l":"나"},{"a":"350","syn":["350kPa","350 kPa"],"l":"다"},{"a":"260","syn":["260L","260L/min","260 L/min","260리터"],"l":"라"}],"순서무관":false},{"id":"2021-2-04","y":2021,"r":2,"n":4,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"표준상태이며, 공기 중 산소의 부피가 21%인 아세톤 200g이 완전 연소하였다. 다음 물음에 답을 쓰시오.\n가. 아세톤의 연소식을 작성하시오.\n나. 이것에 필요한 이론 공기량을 구하시오.\n다. 탄산가스의 부피(L)를 구하시오.","a":"가. CH3COCH3 + 4O2 → 3CO2 + 3H2O\n나. ① M=58, w=200g, P=1atm, T=273K ② V = wRT/PM × (O2 계수 4) ÷ 0.21 ③ (200×0.082×273)/(1×58) × 4 ÷ 0.21 ④ 1,470.34L\n다. ① 같은 조건 ② V = wRT/PM × (CO2 계수 3) ③ (200×0.082×273)/(1×58) × 3 ④ 231.58L","h":"아세톤 1mol이 완전히 타려면 산소 4mol이 필요하고 이산화탄소 3mol이 나온다. 이론 공기량은 필요한 산소 부피를 산소 비율 0.21 로 나눠 구하고, 이산화탄소는 아세톤 부피에 계수비 3 을 곱한다.","tp":"W01","t":"kan","칸":[{"a":"CH3COCH3+4O2→3CO2+3H2O","syn":["CH3COCH3+4O2->3CO2+3H2O","CH3COCH3+4O2=3CO2+3H2O","CH3COCH3+4O2→3H2O+3CO2","CH3COCH3+4O2->3H2O+3CO2","C3H6O+4O2→3CO2+3H2O","C3H6O+4O2->3CO2+3H2O"],"l":"가"},{"a":"1470.34","e":3,"l":"나"},{"a":"231.58","e":2,"l":"다"}],"순서무관":false},{"id":"2021-2-05","y":2021,"r":2,"n":5,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"질산암모늄 800g이 열분해되는 경우 발생기체의 부피는 1기압 600℃에서 몇 L인지 구하시오.","a":"① 2NH4NO3 → 2N2 + O2 + 4H2O (질산암모늄 2에 기체 7), M=80, T=600+273=873K\n② V = wRT/PM × 7/2\n③ (800×0.082×873)/(1×80) × 7/2\n④ 2,505.51L","h":"질산암모늄이 분해되면 질소, 산소, 수증기가 모두 기체라서 2mol이 7mol의 기체가 된다. 800g은 10mol이므로 기체 35mol이 나오고, 600℃(873K)에서 이상기체식으로 부피를 구한다.","tp":"W01","t":"calc","e":5,"ka":"2505.51"},{"id":"2021-2-06","y":2021,"r":2,"n":6,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"비중 1.51인 98중량퍼센트 질산수용액 100ml에 몇 그램의 물을 넣어야 64중량퍼센트 질산수용액으로 만들 수 있는가?","a":"① 용액 질량 100mL × 1.51g/mL = 151g, 질산 151 × 0.98 ≒ 148g, 물 3g\n② 148 ÷ (148 + 3 + x) × 100 = 64\n③ 151 + x = 231.25\n④ x = 80.25g","h":"물을 더해도 질산의 양은 148g으로 그대로이므로, 전체 질량이 148 ÷ 0.64 = 231.25g이 되게 맞춘다. 처음 용액이 151g이라 더 넣을 물은 80.25g이다.","t":"calc","e":1.5,"ka":"80.25"},{"id":"2021-2-07","y":2021,"r":2,"n":7,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물 중에서 염산과 반응하여 제6류 위험물을 생성하는 물질이 물과 반응하는 화학반응식을 쓰시오.\n과염소산암모늄, 과망가니즈산칼륨, 과산화나트륨, 마그네슘","a":"과산화나트륨\n2Na2O2 + 2H2O → 4NaOH + O2","h":"산과 반응해 과산화수소(제6류)를 내는 것은 제1류 무기과산화물인 과산화나트륨이다. 과망가니즈산칼륨과 과염소산암모늄은 이런 반응을 하지 않고, 마그네슘은 제2류이다. 과산화나트륨이 물을 만나면 수산화나트륨과 산소가 생긴다.","t":"kan","칸":[{"a":"과산화나트륨","syn":["Na2O2","과산화 나트륨"],"l":"물질"},{"a":"2Na2O2+2H2O→4NaOH+O2","syn":["2Na2O2+2H2O->4NaOH+O2","2Na2O2+2H2O=4NaOH+O2","Na2O2+H2O→2NaOH+1/2O2","Na2O2+H2O->2NaOH+1/2O2"],"l":"반응식"}],"순서무관":false},{"id":"2021-2-08","y":2021,"r":2,"n":8,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"칼륨과 다음 물질의 화학반응식을 쓰시오.\n가. 물\n나. 에탄올\n다. 이산화탄소","a":"가. 2K + 2H2O → 2KOH + H2\n나. 2K + 2C2H5OH → 2C2H5OK + H2\n다. 4K + 3CO2 → 2K2CO3 + C","h":"칼륨은 물과 에탄올에서 수소를 내며 각각 KOH, C2H5OK 가 된다. 이산화탄소와는 산소를 빼앗아 탄산칼륨과 탄소가 생겨 4K + 3CO2 → 2K2CO3 + C 이다.","t":"kan","칸":[{"a":"2K+2H2O→2KOH+H2","syn":["2K+2H2O->2KOH+H2","2K+2H2O=2KOH+H2","K+H2O→KOH+1/2H2"],"l":"가"},{"a":"2K+2C2H5OH→2C2H5OK+H2","syn":["2K+2C2H5OH->2C2H5OK+H2","2K+2C2H5OH=2C2H5OK+H2","K+C2H5OH→C2H5OK+1/2H2"],"l":"나"},{"a":"4K+3CO2→2K2CO3+C","syn":["4K+3CO2->2K2CO3+C","4K+3CO2=2K2CO3+C"],"l":"다"}],"순서무관":false},{"id":"2021-2-09","y":2021,"r":2,"n":9,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 설명하는 위험물에 대하여 물음에 답하시오.\n• 제3류 위험물\n• 공기와의 접촉을 금지할 것\n• 제2류 위험물에 동소체가 있는 위험물\n가. 위험등급\n나. 연소반응식\n다. 옥내저장소 저장 시 바닥면적","a":"가. I등급\n나. P4 + 5O2 → 2P2O5\n다. 1,000m2","h":"제2류 적린과 동소체이면서 공기 접촉을 피하는 제3류 물질은 황린(P4)이며 지정수량 20kg, 위험등급 I 이다. 타면 오산화인이 되고, 위험등급 I 위험물을 저장하는 옥내저장소의 바닥면적은 1,000m2 이하이다.","t":"kan","칸":[{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"가"},{"a":"P4+5O2→2P2O5","syn":["P4+5O2->2P2O5","P4+5O2=2P2O5","4P+5O2→2P2O5","4P+5O2->2P2O5","4P+5O2=2P2O5","4P+5O2→P4O10","P4+5O2→P4O10"],"l":"나"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"다"}],"순서무관":false},{"id":"2021-2-10","y":2021,"r":2,"n":10,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"옥외탱크저장소 주입구 기준이다. 다음 물음에 답하시오.\n( ① ), ( ② ) 그 밖에 정전기에 의한 재해가 발생할 우려가 있는 액체위험물의 옥외저장탱크의 주입구 부근에는 정전기를 유효하게 제거하기 위한 접지전극을 설치할 것\n가. ①에 들어갈 위험물의 명칭과 지정수량을 쓰시오.\n나. ②에 들어갈 위험물은 겨울철에 응고될 수 있고, 인화점이 -11℃인 방향족 탄화수소이다. 구조식을 쓰시오.","a":"가. 휘발유, 200L\n나. 벤젠(C6H6): 정육각형 고리에 단일결합과 이중결합이 번갈아 있는 구조","h":"주입구 부근에 접지전극을 두어야 하는 대표 물질은 휘발유와 벤젠이다. 휘발유는 제1석유류 비수용성으로 지정수량 200L이다. 인화점 -11℃의 방향족 탄화수소로 겨울에 굳을 수 있는 것은 벤젠이다.","ai":"2021-2-10_a.svg","t":"kan","칸":[{"a":"휘발유","syn":["가솔린","gasoline","휘발유(가솔린)"],"l":"가-명칭"},{"a":"200","syn":["200L","200 L","200리터"],"l":"가-지정수량"}],"순서무관":false},{"id":"2021-2-11","y":2021,"r":2,"n":11,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"소화의 종류에 대하여 다음 물음에 답하시오.\n가. 소화의 종류 4가지를 쓰시오.\n나. 가.의 소화 종류 중 불활성기체 등을 활용하여 산소의 농도를 낮추어 소화하는 방법을 쓰시오.\n다. 가.의 소화 종류 중 액체의 증발잠열을 이용하여 가연물의 온도를 낮추어 소화하는 방법을 쓰시오.\n라. 가.의 소화 종류 중 밸브 등을 차단하여 가연물을 없애 소화하는 방법을 쓰시오.","a":"가. 제거소화, 질식소화, 냉각소화, 억제소화\n나. 질식소화\n다. 냉각소화\n라. 제거소화","h":"소화 방법은 제거(가연물 제거), 질식(산소 차단), 냉각(열 제거), 억제(연쇄반응 차단)로 나뉜다. 불활성기체로 산소 농도를 낮추면 질식소화, 증발잠열로 온도를 낮추면 냉각소화, 밸브를 잠가 가연물을 없애면 제거소화이다. 억제소화는 할로젠원소를 쓰는 화학적 소화이다.","t":"kan","칸":[{"a":"제거소화, 질식소화, 냉각소화, 억제소화","k":[["제거"],["질식"],["냉각"],["억제","부촉매"]],"l":"가"},{"a":"질식소화","syn":["질식","질식 소화"],"l":"나"},{"a":"냉각소화","syn":["냉각","냉각 소화"],"l":"다"},{"a":"제거소화","syn":["제거","제거 소화"],"l":"라"}],"순서무관":false},{"id":"2021-2-12","y":2021,"r":2,"n":12,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"옥외탱크저장소의 보유공지에 대하여 다음 빈칸에 알맞은 것을 쓰시오.\n지정수량의 500배 이하 → ( 가 ) 이상\n지정수량의 500배 초과 1,000배 이하 → ( 나 ) 이상\n지정수량의 1,000배 초과 2,000배 이하 → ( 다 ) 이상\n지정수량의 2,000배 초과 3,000배 이하 → ( 라 ) 이상\n지정수량의 3,000배 초과 4,000배 이하 → ( 마 ) 이상","a":"가. 3m\n나. 5m\n다. 9m\n라. 12m\n마. 15m","h":"옥외탱크저장소의 보유공지는 지정수량 500배 이하 3m, 1,000배 이하 5m, 2,000배 이하 9m, 3,000배 이하 12m, 4,000배 이하 15m 이상으로 단계별로 커진다. 4,000배를 넘으면 별도 기준을 적용한다.","t":"kan","칸":[{"a":"3m","syn":["3","3 m","3미터"],"l":"가"},{"a":"5m","syn":["5","5 m","5미터"],"l":"나"},{"a":"9m","syn":["9","9 m","9미터"],"l":"다"},{"a":"12m","syn":["12","12 m","12미터"],"l":"라"},{"a":"15m","syn":["15","15 m","15미터"],"l":"마"}],"순서무관":false},{"id":"2021-2-13","y":2021,"r":2,"n":13,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령에 따른 위험물 저장·취급기준이다. 다음 빈칸을 채우시오.\n가. ( ) 위험물은 불티·불꽃·고온체와의 접근이나 과열·충격 또는 마찰을 피하여야 한다.\n나. ( ) 위험물은 가연물과의 접촉·혼합이나 분해를 촉진하는 물품과의 접근 또는 과열을 피하여야 한다.\n다. ( ) 위험물은 불티·불꽃·고온체와의 접근 또는 과열을 피하고, 함부로 증기를 발생시키지 아니하여야 한다.","a":"가. 제5류\n나. 제6류\n다. 제4류","h":"(가)는 접근·과열에 충격·마찰까지 피하라는 내용이라 제5류이다. (나)는 가연물 접촉과 분해 촉진 물품 접근, 과열만 피하라는 내용이라 제6류이며, 제1류는 여기에 충격·마찰이 더해진다. (다)는 증기를 함부로 발생시키지 말라는 내용이라 제4류이다.","t":"kan","칸":[{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"가"},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"나"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"다"}],"순서무관":false},{"id":"2021-2-14","y":2021,"r":2,"n":14,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"다음 위험물의 저장 온도를 쓰시오.\n가. 옥외저장탱크 중 압력탱크 외의 탱크에 산화프로필렌을 저장하는 경우\n나. 옥내저장탱크 중 압력탱크 외의 탱크에 아세트알데하이드를 저장하는 경우\n다. 지하저장탱크 중 압력탱크 외의 탱크에 다이에틸에터를 저장하는 경우\n라. 지하저장탱크 중 압력탱크에 다이에틸에터등을 저장하는 경우\n마. 옥외저장탱크 중 압력탱크에 산화프로필렌을 저장하는 경우","a":"가. 30℃ 이하\n나. 15℃ 이하\n다. 30℃ 이하\n라. 40℃ 이하\n마. 40℃ 이하","h":"압력탱크 외의 탱크에서는 산화프로필렌과 다이에틸에터가 30℃ 이하, 아세트알데하이드가 15℃ 이하이다. 압력탱크에서는 셋 모두 40℃ 이하이다. 옥외·옥내·지하 어느 저장탱크든 같은 기준이다.","t":"kan","칸":[{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"가"},{"a":"15℃","syn":["15","15도","15℃ 이하","15도 이하"],"l":"나"},{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"다"},{"a":"40℃","syn":["40","40도","40℃ 이하","40도 이하"],"l":"라"},{"a":"40℃","syn":["40","40도","40℃ 이하","40도 이하"],"l":"마"}],"순서무관":false},{"id":"2021-2-15","y":2021,"r":2,"n":15,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물을 보고 물음에 답하시오.\n아세톤, 아닐린, 클로로벤젠, 메틸에틸케톤, 메탄올\n가. 제1석유류를 모두 쓰시오.\n나. 인화점이 가장 낮은 위험물의 명칭을 쓰시오.\n다. 나. 위험물의 구조식을 쓰시오.","a":"가. 아세톤, 메틸에틸케톤\n나. 아세톤\n다. 아세톤 CH3COCH3: 가운데 탄소에 산소가 이중결합으로 붙고 양쪽에 메틸기가 하나씩 결합","h":"제1석유류는 아세톤과 메틸에틸케톤이고, 아닐린은 제3석유류, 클로로벤젠은 제2석유류, 메탄올은 알코올류이다. 인화점은 아세톤 -18℃, 메틸에틸케톤 -7℃, 메탄올 11℃, 클로로벤젠 27℃, 아닐린 70℃ 라서 아세톤이 가장 낮다.","ai":"2021-2-15_a.svg","t":"kan","칸":[{"a":"아세톤, 메틸에틸케톤","k":[["아세톤"],["메틸에틸케톤","메틸 에틸 케톤","MEK","에틸메틸케톤"]],"l":"가"},{"a":"아세톤","syn":["CH3COCH3","프로파논","다이메틸케톤","디메틸케톤","acetone"],"l":"나"}],"순서무관":false},{"id":"2021-2-16","y":2021,"r":2,"n":16,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"물속에 넣어 보관하는 제4류 위험물 중 특수인화물에 대하여 다음 물음에 답하시오.\n가. 연소 시 생성되는 유독성 물질의 화학식\n나. 증기비중\n다. 옥외탱크에 저장할 경우 철근콘크리트 수조의 두께","a":"가. SO2\n나. 2.62\n다. 0.2m 이상","h":"물속에 넣어 보관하는 제4류 특수인화물은 이황화탄소(CS2)이다. 타면 CS2 + 3O2 → CO2 + 2SO2 로 유독한 이산화황이 생기고, 증기비중은 분자량 76 ÷ 29 = 2.62 이다. 저장 수조는 두께 0.2m 이상의 철근콘크리트로 한다.","t":"kan","칸":[{"a":"SO2","syn":["이산화황","아황산가스","이산화 황","아황산","sulfur dioxide"],"l":"가"},{"a":"2.62","e":0.01,"l":"나"},{"a":"0.2","syn":["0.2m","0.2m 이상","0.2미터","20cm"],"l":"다"}],"순서무관":false},{"id":"2021-2-17","y":2021,"r":2,"n":17,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 위험물의 연소반응식을 쓰시오.\n가. 오황화인\n나. 알루미늄\n다. 마그네슘","a":"가. 2P2S5 + 15O2 → 10SO2 + 2P2O5\n나. 4Al + 3O2 → 2Al2O3\n다. 2Mg + O2 → 2MgO","h":"황화인이 타면 이산화황과 오산화인이 생기고, 알루미늄과 마그네슘은 각각 산화알루미늄, 산화마그네슘이 된다. 오황화인은 P 4개, S 10개를 기준으로 산소 원자 30개를 맞추면 O2 가 15분자이다.","t":"kan","칸":[{"a":"2P2S5+15O2→10SO2+2P2O5","syn":["2P2S5+15O2->10SO2+2P2O5","2P2S5+15O2=10SO2+2P2O5","2P2S5+15O2→2P2O5+10SO2","2P2S5+15O2->2P2O5+10SO2","P2S5+15/2O2→5SO2+P2O5","P2S5+15/2O2->5SO2+P2O5","P2S5+7.5O2→5SO2+P2O5"],"l":"가"},{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3","2Al+3/2O2→Al2O3"],"l":"나"},{"a":"2Mg+O2→2MgO","syn":["2Mg+O2->2MgO","2Mg+O2=2MgO","Mg+1/2O2→MgO"],"l":"다"}],"순서무관":false},{"id":"2021-2-18","y":2021,"r":2,"n":18,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"지정과산화물을 저장 또는 취급하는 옥내저장소에 대한 기준에 대하여 다음 물음에 답하시오.\n가. 지정과산화물의 위험등급\n나. 지정과산화물 옥내저장소의 바닥면적 몇 m2 이하\n다. 저장창고 외벽을 철근콘크리트조로 할 경우 두께 몇 cm 이상","a":"가. I등급\n나. 1,000m2 이하\n다. 20cm 이상","h":"지정과산화물은 제5류 중 유기과산화물이며 위험등급 I 이다. 위험등급 I 위험물을 저장하는 창고라 바닥면적은 1,000m2 이하이다. 저장창고 외벽은 철근콘크리트조·철골철근콘크리트조 20cm 이상, 보강콘크리트블록조 30cm 이상이다.","t":"kan","칸":[{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"가"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"나"},{"a":"20","syn":["20cm","20cm 이상","20센티미터"],"l":"다"}],"순서무관":false},{"id":"2021-2-19","y":2021,"r":2,"n":19,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"메틸알코올이 산화되어 포름알데하이드와 수소기체가 발생한다. 메틸알코올 320g이 산화되어 생성되는 포름알데하이드의 양(g)을 구하시오.","a":"① CH3OH → HCHO + H2, 메탄올 32g/mol, 320g = 10mol, 몰비 1 : 1\n② 질량 = 기체 부피 환산식, HCHO 30g/mol, 22.4L/mol\n③ (320×0.082×273)/(1×32) × 30/22.4\n④ 299.81g","h":"메탄올에서 포름알데하이드와 수소가 1 : 1 로 나오므로 메탄올 몰수가 곧 포름알데하이드 몰수이다. 320g은 10mol이고 포름알데하이드 분자량이 30 이라 약 300g이 된다.","tp":"W01","t":"calc","e":2,"ka":"299.81"},{"id":"2021-2-20","y":2021,"r":2,"n":20,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"제조소등에서의 위험물 저장 및 취급에 관한 기준이다. 다음 중 옳은 것을 모두 고르시오.\n① 옥내저장소에서는 용기에 수납하여 저장하는 위험물의 온도가 45℃가 넘지 아니하도록 필요한 조치를 강구하여야 한다.\n② 제3류 위험물 중 황린, 그 밖에 물속에 저장하는 물품과 금수성 물질은 동일한 저장소에 저장할 수 있다.\n③ 컨테이너식 이동탱크저장소 외의 이동탱크저장소에 있어서는 위험물을 저장한 상태로 이동저장탱크를 옮겨 싣지 아니하여야 한다.\n④ 이동취급소에서 위험물이 이송하기 위한 배관·펌프 및 이에 부속한 설비의 안전을 확인하기 위한 순찰을 행하고, 위험물을 이송하는 중에는 이송하는 위험물의 압력 및 유량을 항상 감시할 것\n⑤ 제조소등에서 규정에 의한 신고와 관련되는 품명 외의 위험물 또는 이러한 허가 및 신고와 관련되는 수량 또는 지정수량의 배수를 초과하는 위험물을 저장 또는 취급하지 아니하여야 한다.","a":"③, ⑤","h":"옥내저장소의 용기 저장 온도는 55℃를 넘지 않게 하므로 ①은 틀리다. 황린 같은 물속 저장 물품과 금수성 물질은 같은 저장소에 두지 않으므로 ②도 틀리다. ③과 ⑤는 기준 그대로이고, ④는 이송취급소의 기준인데 이동취급소로 적혀 있어 맞지 않는다.","t":"kan","칸":[{"a":"③","syn":["3","3번","(3)"]},{"a":"⑤","syn":["5","5번","(5)"]}],"순서무관":true},{"id":"2021-4-01","y":2021,"r":4,"n":1,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물의 물과의 화학반응식을 쓰시오.\n가. 탄화칼슘\n나. 탄화알루미늄","a":"가. CaC2 + 2H2O → Ca(OH)2 + C2H2\n나. Al4C3 + 12H2O → 4Al(OH)3 + 3CH4","h":"탄화칼슘은 아세틸렌, 탄화알루미늄은 메테인을 내며 둘 다 수산화물이 함께 생긴다. 탄화알루미늄은 Al 이 4개 들어 있어 Al4C3 + 12H2O → 4Al(OH)3 + 3CH4 로 물 12분자가 필요하다.","t":"kan","칸":[{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"가"},{"a":"Al4C3+12H2O→4Al(OH)3+3CH4","syn":["Al4C3+12H2O->4Al(OH)3+3CH4","Al4C3+12H2O=4Al(OH)3+3CH4","Al4C3+12H2O→3CH4+4Al(OH)3","Al4C3+12H2O->3CH4+4Al(OH)3"],"l":"나"}],"순서무관":false},{"id":"2021-4-02","y":2021,"r":4,"n":2,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"보기에서 설명하는 물질에 대하여 다음 물음에 답하시오.\n[보기]\n• 제3류 위험물 중 지정수량 300kg\n• 분자량 64\n• 비중 2.2\n• 질소와 반응하여 석회질소 생성\n가. 화학식\n나. 물과의 화학반응식\n다. 발생되는 기체의 완전 연소반응식","a":"가. CaC2\n나. CaC2 + 2H2O → Ca(OH)2 + C2H2\n다. 2C2H2 + 5O2 → 4CO2 + 2H2O","h":"제3류 300kg, 분자량 64, 비중 2.2 이고 질소와 반응해 석회질소를 만드는 물질은 탄화칼슘(CaC2)이다. 물과 반응하면 수산화칼슘과 아세틸렌이 나오고, 질소와는 CaC2 + N2 → CaCN2 + C 로 반응한다.","t":"kan","칸":[{"a":"CaC2","syn":["탄화칼슘","카바이드","칼슘카바이드","탄화 칼슘"],"l":"가"},{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"나"},{"a":"2C2H2+5O2→4CO2+2H2O","syn":["2C2H2+5O2->4CO2+2H2O","2C2H2+5O2=4CO2+2H2O","C2H2+5/2O2→2CO2+H2O","C2H2+5/2O2->2CO2+H2O","C2H2+2.5O2→2CO2+H2O"],"l":"다"}],"순서무관":false},{"id":"2021-4-03","y":2021,"r":4,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"금속나트륨에 대하여 다음 물음에 답하시오.\n가. 지정수량\n나. 저장방법\n다. 물과의 반응식","a":"가. 10kg\n나. 석유(등유, 경유, 유동파라핀) 속에 저장\n다. 2Na + 2H2O → 2NaOH + H2","h":"나트륨은 제3류 금수성 물질이며 지정수량은 10kg이다. 물과 닿지 않도록 석유(등유·경유·유동파라핀) 속에 저장한다. 물과 반응하면 수산화나트륨과 수소가 나온다.","t":"kan","칸":[{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"가"},{"a":"등유, 경유, 유동파라핀","k":[["등유","경유","파라핀","석유"]],"l":"나"},{"a":"2Na+2H2O→2NaOH+H2","syn":["2Na+2H2O->2NaOH+H2","2Na+2H2O=2NaOH+H2","Na+H2O→NaOH+1/2H2"],"l":"다"}],"순서무관":false},{"id":"2021-4-04","y":2021,"r":4,"n":4,"p":"계산","kw":"지정수량 배수","pt":5,"q":"다음 중 위험등급 II인 위험물의 지정수량 배수의 합을 구하시오.\n• 황 100kg\n• 질산염류 600kg\n• 나트륨 100kg\n• 철분 50kg\n• 등유 6,000L","a":"① 위험등급 II: 황(100kg), 질산염류(300kg)\n② 배수 = Σ(저장량 ÷ 지정수량)\n③ 100/100 + 600/300 = 1 + 2\n④ 3","h":"먼저 위험등급을 가린다. 황과 질산염류가 II, 나트륨은 I, 철분과 등유는 III 이다. II 인 둘만 지정수량으로 나눠 더하면 1 + 2 = 3 이다.","t":"calc","ka":"3"},{"id":"2021-4-05","y":2021,"r":4,"n":5,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 중 연소생성물이 같은 위험물을 고르고 연소반응식을 각각 쓰시오.\n적린, 삼황화인, 오황화인, 황, 철, 마그네슘","a":"삼황화인, 오황화인\nP4S3 + 8O2 → 2P2O5 + 3SO2\n2P2S5 + 15O2 → 2P2O5 + 10SO2","h":"삼황화인과 오황화인은 연소하면 둘 다 오산화인과 이산화황이 생긴다. 적린은 오산화인만, 황은 이산화황만 만들고 철과 마그네슘은 산화물이 된다.","t":"kan","칸":[{"a":"삼황화인","syn":["P4S3","삼황화사인","삼황화 인"]},{"a":"오황화인","syn":["P2S5","오황화이인","오황화 인"]},{"a":"P4S3+8O2→2P2O5+3SO2","syn":["P4S3+8O2->2P2O5+3SO2","P4S3+8O2=2P2O5+3SO2","P4S3+8O2→3SO2+2P2O5","P4S3+8O2->3SO2+2P2O5"]},{"a":"2P2S5+15O2→2P2O5+10SO2","syn":["2P2S5+15O2->2P2O5+10SO2","2P2S5+15O2=2P2O5+10SO2","2P2S5+15O2→10SO2+2P2O5","2P2S5+15O2->10SO2+2P2O5","P2S5+15/2O2→P2O5+5SO2","P2S5+15/2O2->P2O5+5SO2"]}],"순서무관":true},{"id":"2021-4-06","y":2021,"r":4,"n":6,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제6류 위험물 중 갈색 병에 저장하는 위험물에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 지정수량\n다. 위험물 기준\n라. 분해반응식","a":"가. HNO3\n나. 300kg\n다. 비중 1.49 이상\n라. 4HNO3 → 2H2O + 4NO2 + O2","h":"갈색 병에 두는 제6류 물질은 질산이며 지정수량은 300kg이다. 위험물이 되려면 비중이 1.49 이상이어야 한다. 빛에 분해되어 물, 이산화질소, 산소가 나오기 때문에 갈색 병에 담는다.","t":"kan","칸":[{"a":"HNO3","syn":["질산","hno3","nitric acid"],"l":"가"},{"a":"300kg","syn":["300","300 kg"],"l":"나"},{"a":"비중 1.49 이상","syn":["1.49","1.49 이상","1.49이상","비중1.49","비중 1.49","비중1.49이상"],"l":"다"},{"a":"4HNO3→2H2O+4NO2+O2","syn":["4HNO3->2H2O+4NO2+O2","4HNO3=2H2O+4NO2+O2","4HNO3→4NO2+2H2O+O2","4HNO3->4NO2+2H2O+O2","HNO3→1/2H2O+NO2+1/4O2"],"l":"라"}],"순서무관":false},{"id":"2021-4-07","y":2021,"r":4,"n":7,"p":"반응식","kw":"물과 반응","pt":5,"q":"트라이에틸알루미늄과 물을 반응시켰을 때 다음 물음에 답하시오.\n가. 화학반응식\n나. 발생하는 기체의 명칭","a":"가. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n나. 에테인","h":"트라이에틸알루미늄은 물과 반응해 수산화알루미늄과 에테인(C2H6)을 낸다. 에틸기 3개가 각각 수소를 얻어 에테인 3분자가 되므로 물도 3분자가 필요하다.","t":"kan","칸":[{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"가"},{"a":"에테인","syn":["에탄","C2H6","ethane","에테인가스","에탄가스"],"l":"나"}],"순서무관":false},{"id":"2021-4-08","y":2021,"r":4,"n":8,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"다음 중 위험도가 높은 위험물을 쓰고 위험도를 구하시오.\n메틸에틸케톤, 아세톤, 다이에틸에터, 아닐린\n가. 위험물\n나. 위험도","a":"가. 다이에틸에터\n나. 위험도 = (상한 − 하한) ÷ 하한 = (48 − 1.9) ÷ 1.9 = 24.26","h":"위험도는 (연소범위 상한 − 하한) ÷ 하한이다. 메틸에틸케톤 5.39, 아세톤 4.12, 아닐린 7.46 이고 연소범위가 1.9~48%로 넓은 다이에틸에터가 24.26 으로 가장 크다.","t":"kan","칸":[{"a":"다이에틸에터","syn":["디에틸에터","다이에틸에테르","디에틸에테르","에터","에테르","C2H5OC2H5","에틸에터","에틸에테르","(C2H5)2O"],"l":"가"},{"a":"24.26","e":0.1,"l":"나"}],"순서무관":false},{"id":"2021-4-09","y":2021,"r":4,"n":9,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"제4류 위험물 중 제1석유류를 이용하여 TNT를 만드는 화학반응식을 쓰시오.","a":"C6H5CH3 + 3HNO3 --(H2SO4)--> C6H2(NO2)3CH3 + 3H2O","h":"제1석유류 중 TNT 의 원료는 톨루엔이며, 황산을 촉매로 질산 3분자와 반응(나이트로화)하면 트라이나이트로톨루엔과 물 3분자가 나온다. 페놀, 글리세린, 에틸렌글리콜도 같은 방식으로 각각 트라이나이트로페놀, 나이트로글리세린, 나이트로글리콜이 된다.","t":"kan","칸":[{"a":"C6H5CH3+3HNO3→C6H2(NO2)3CH3+3H2O","syn":["C6H5CH3+3HNO3->C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3=C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3→C6H2CH3(NO2)3+3H2O","C6H5CH3+3HNO3->C6H2CH3(NO2)3+3H2O","C6H5CH3+3HNO3--(H2SO4)-->C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3-(H2SO4)->C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3-H2SO4->C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3→(H2SO4)C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3(H2SO4)→C6H2(NO2)3CH3+3H2O","C6H5CH3+3HNO3→C6H2(NO2)3CH3+3H2O(H2SO4)","C7H8+3HNO3→C7H5N3O6+3H2O","C7H8+3HNO3->C7H5N3O6+3H2O","C6H5CH3+3HNO3→C6H2CH3(NO2)3+3H2O"]}],"순서무관":false},{"id":"2021-4-10","y":2021,"r":4,"n":10,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"위험물 제조소에 다음 수량의 위험물을 저장할 때 필요한 최소 보유공지를 쓰시오.\n가. 지정수량의 1배\n나. 지정수량의 5배\n다. 지정수량의 10배\n라. 지정수량의 50배\n마. 지정수량의 200배","a":"가. 3m 이상\n나. 3m 이상\n다. 3m 이상\n라. 5m 이상\n마. 5m 이상","h":"제조소 보유공지는 지정수량 10배 이하이면 3m 이상, 10배를 넘으면 5m 이상으로 두 단계뿐이다. 그래서 1·5·10배는 3m, 50·200배는 5m이다.","t":"kan","칸":[{"a":"3m","syn":["3","3 m","3미터","3m 이상"],"l":"가"},{"a":"3m","syn":["3","3 m","3미터","3m 이상"],"l":"나"},{"a":"3m","syn":["3","3 m","3미터","3m 이상"],"l":"다"},{"a":"5m","syn":["5","5 m","5미터","5m 이상"],"l":"라"},{"a":"5m","syn":["5","5 m","5미터","5m 이상"],"l":"마"}],"순서무관":false},{"id":"2021-4-11","y":2021,"r":4,"n":11,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제1류 위험물의 공통적인 특성으로 옳은 것을 고르시오.\n무기화합물, 유기화합물, 산화제, 인화점이 0℃ 이상, 고체, 액체","a":"무기화합물, 산화제, 고체","h":"제1류는 산화성 고체로 무기화합물이며 강한 산화제이다. 유기화합물, 액체, 인화점 0℃ 이상 같은 항목은 제1류에 해당하지 않는다. 자신은 타지 않지만 다른 물질의 연소를 돕는 조연성이다.","t":"kan","칸":[{"a":"무기화합물","syn":["무기 화합물"]},{"a":"산화제","syn":["산화성","산화성물질","산화성 물질"]},{"a":"고체","syn":["고체상"]}],"순서무관":true,"nc":3},{"id":"2021-4-12","y":2021,"r":4,"n":12,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음은 위험물안전관리법령에 따른 위험물의 저장·취급에 관한 중요기준을 가지는 [보기] 위험물에 대하여 다음 물음에 답하시오.\n[보기]\n• 불티·불꽃·고온체와의 접근이나 과열·충격 또는 마찰을 피하여야 한다.\n• 옥내저장소에서는 용기에 수납하여 저장하는 위험물의 온도가 55℃를 넘지 아니하도록 필요한 조치를 강구하여야 한다.\n가. 운반용기 외부에 표시하여야 하는 주의사항\n나. 가장 지정수량이 작은 것의 품명\n다. 해당 위험물과 혼재가 가능한 위험물의 유별(단, 지정수량 10배 이하이다)","a":"가. 화기엄금, 충격주의\n나. 제1종인 제5류 위험물\n다. 제2류 위험물, 제4류 위험물","h":"불티·불꽃·고온체 접근과 충격·마찰을 피하라는 항목은 제5류의 저장·취급 기준이다. 제5류 운반용기에는 화기엄금·충격주의를 표시하고, 지정수량이 가장 작은 품명은 10kg 인 제1종이다. 혼재는 제2류·제4류와 가능하다.","t":"kan","칸":[{"a":"화기엄금, 충격주의","k":[["화기엄금","화기 엄금"],["충격"]],"l":"가"},{"a":"제1종인 제5류 위험물","k":[["5류","질산에스터","유기과산화물"],["1종","10kg","제일종"]],"l":"나"},{"a":"제2류 위험물, 제4류 위험물","k":[["2류"],["4류"]],"l":"다"}],"순서무관":false},{"id":"2021-4-13","y":2021,"r":4,"n":13,"p":"물질·성상","kw":"소화약제","pt":5,"q":"분말소화약제의 화학식을 쓰시오.\n가. 제1종 분말소화약제\n나. 제2종 분말소화약제\n다. 제3종 분말소화약제","a":"가. NaHCO3\n나. KHCO3\n다. NH4H2PO4","h":"제1종은 탄산수소나트륨 NaHCO3, 제2종은 탄산수소칼륨 KHCO3, 제3종은 인산암모늄 NH4H2PO4 이다. 제1·2종은 BC 화재, 제3종은 ABC 화재에 쓴다.","t":"kan","칸":[{"a":"NaHCO3","syn":["탄산수소나트륨","중탄산나트륨","중탄산소다","탄산수소소다"],"l":"가"},{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"나"},{"a":"NH4H2PO4","syn":["인산암모늄","제일인산암모늄","인산이수소암모늄","인산이수소 암모늄","(NH4)H2PO4"],"l":"다"}],"순서무관":false},{"id":"2021-4-14","y":2021,"r":4,"n":14,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"위험물안전관리법령상 수원의 수량을 구하시오.\n가. 옥외소화전 3개\n나. 옥외소화전 6개","a":"가. 옥외소화전 3개: 3×13.5m3 = 40.5m3 → 40.5m3\n나. 옥외소화전 6개: 4개 이상이면 4개로 계산, 4×13.5m3 = 54m3 → 54m3","h":"옥외소화전 수원은 설치 개수에 13.5m3를 곱하고, 개수가 4개를 넘으면 4개까지만 센다. 그래서 6개를 달아도 계산은 4개분인 54m3다. 옥내소화전은 개수에 7.8m3를 곱하고 상한이 5개다.","t":"kan","칸":[{"a":"40.5","e":0.1,"l":"가"},{"a":"54","e":0.1,"l":"나"}],"순서무관":false},{"id":"2021-4-15","y":2021,"r":4,"n":15,"p":"계산","kw":"탱크 용량","pt":5,"q":"공간용적이 5/100인 다음 탱크의 용량은 몇 L인가?\n(가로형 원통형 탱크 : 반지름 2m, 몸통 5m, 양쪽 경판 1.5m씩)","a":"① 반지름 r = 2m, 몸통 l = 5m, 경판 l1 = l2 = 1.5m, 공간용적 5%\n② 용량 = πr²(l + (l1+l2)/3) × (1 − 0.05)\n③ π×2²×(5 + (1.5+1.5)/3)×0.95 = 71.628m3\n④ 71.628m3 = 71,628.31L","h":"가로형 원통 탱크는 양쪽 경판이 볼록하게 나온 부피를 (l1+l2)/3 으로 더해 준다. 용량은 내용적에서 공간용적을 뺀 값이므로 5%면 0.95를 곱하고, 마지막에 m3를 L로 바꾸려고 1,000을 곱한다.","tp":"W04","t":"calc","e":100,"ka":"71628.31"},{"id":"2021-4-16","y":2021,"r":4,"n":16,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"지하탱크저장소에 대하여 다음 물음에 답하시오.\n• 탱크전용실은 지하의 가장 가까운 벽·피트·가스관 등의 시설물 및 대지경계선으로부터 ( 가 )m 이상 떨어진 곳에 설치하여야 한다.\n• 지하저장탱크의 윗부분은 지면으로부터 ( 나 )m 이상 아래에 있어야 한다.\n• 지하저장탱크를 2 이상 인접에 설치하는 경우에는 그 상호 간에 ( 다 )m(당해 2 이상의 지하저장탱크의 용량의 합계가 지정수량의 100배 이하인 때에는 ( 라 )m) 이상의 간격을 유지하여야 한다. 다만, 그 사이에 탱크전용실의 벽이나 두께 ( 마 )cm 이상의 콘크리트 구조물이 있는 경우에는 그러하지 아니하다.","a":"가. 0.1, 나. 0.6\n다. 1, 라. 0.5\n마. 20","h":"탱크전용실은 가까운 벽·피트·대지경계선에서 0.1m 이상 떨어뜨리고, 탱크 윗부분은 지면 아래 0.6m 이상에 둔다. 탱크끼리는 1m 이상이며, 두 탱크 용량 합계가 지정수량의 100배 이하면 0.5m 이상으로 줄고, 두께 20cm 이상 콘크리트 구조물이 사이에 있으면 간격 제한이 없다. 탱크와 전용실 안쪽 사이도 0.1m 이상 띄우고 입자 지름 5mm 이하의 마른 자갈분 등으로 채운다.","t":"kan","칸":[{"a":"0.1","syn":["0.1m","0.1미터","10cm"],"l":"가"},{"a":"0.6","syn":["0.6m","0.6미터","60cm"],"l":"나"},{"a":"1","syn":["1m","1미터"],"l":"다"},{"a":"0.5","syn":["0.5m","0.5미터","50cm"],"l":"라"},{"a":"20","syn":["20cm","20센티미터"],"l":"마"}],"순서무관":false},{"id":"2021-4-17","y":2021,"r":4,"n":17,"p":"시설·법령","kw":"운송·이동탱크","pt":5,"q":"위험물안전관리법에 따른 이동탱크저장소 주유호스 재질에 대하여 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n• 위험물이 샐 우려가 없고 화재예방상 안전한 구조로 할 것\n• 주입호스는 내경이 ( 가 )mm 이상이고, ( 나 )MPa 이상의 압력에 견딜 수 있는 것으로 하며, 필요 이상으로 길게 하지 아니할 것\n• 주입설비의 길이는 ( 다 )m 이내로 하고, 그 끝부분에 축적되는 ( 라 )를 유효하게 제거할 수 있는 장치를 할 것\n• 분당 배출량은 ( 마 )L 이하로 할 것","a":"가. 23, 나. 0.3\n다. 50, 라. 정전기\n마. 200","h":"주입호스는 내경 23mm 이상이고 0.3MPa 이상의 압력에 견뎌야 한다. 주입설비 길이는 50m 이내이며 끝부분에 쌓이는 정전기를 제거하는 장치를 달고, 분당 배출량은 200L 이하로 한다. 빈칸 순서가 23, 0.3, 50, 200이다.","t":"kan","칸":[{"a":"23","syn":["23mm","23 mm"],"l":"가"},{"a":"0.3","syn":["0.3MPa","0.3 MPa"],"l":"나"},{"a":"50","syn":["50m","50 m","50미터"],"l":"다"},{"a":"정전기","syn":["정전기 전하","static","정전하"],"l":"라"},{"a":"200","syn":["200L","200 L","200리터"],"l":"마"}],"순서무관":false},{"id":"2021-4-18","y":2021,"r":4,"n":18,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"옥외저장소에 저장할 수 있는 위험물의 품명 5가지를 쓰시오.","a":"황, 인화성고체(인화점 0℃ 이상), 제1석유류(인화점 0℃ 이상), 알코올류, 제2석유류, 제3석유류, 제4석유류, 동식물유류 중 5가지","h":"옥외저장소에는 제2류의 황·인화성고체, 제4류의 제1석유류·알코올류·제2석유류·제3석유류·제4석유류·동식물유류, 제6류를 저장할 수 있다. 제4류의 특수인화물은 들어가지 않고, 인화성고체와 제1석유류는 인화점 0℃ 이상인 것만 해당한다. 시·도 조례로 정한 제2류·제4류 위험물과 IMDG Code에 맞는 용기에 담긴 위험물도 저장할 수 있다.","t":"kan","칸":[{"a":"황","syn":["유황","sulfur"]},{"a":"인화성고체","syn":["인화성 고체"]},{"a":"제1석유류","syn":["1석유류","제 1석유류","제일석유류"]},{"a":"알코올류","syn":["알콜류","알코올","알콜"]},{"a":"제2석유류","syn":["2석유류","제 2석유류","제이석유류"]},{"a":"제3석유류","syn":["3석유류","제 3석유류","제삼석유류"]},{"a":"제4석유류","syn":["4석유류","제 4석유류","제사석유류"]},{"a":"동식물유류","syn":["동식물유","동 식물유류","동식물 유류"]},{"a":"제6류 위험물","syn":["제6류","6류","6류 위험물","질산","과산화수소","과염소산"]}],"순서무관":true,"nc":5},{"id":"2021-4-19","y":2021,"r":4,"n":19,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"위험물 옥내탱크저장소의 탱크전용실 및 펌프설비에 대하여 다음 물음에 답하시오.\n• 펌프실은 상층이 있는 경우에 있어서 상층의 바닥을 내화구조로 하고, 상층이 없는 경우에 있어서는 지붕을 ( 가 )로 하며 천장을 설치하지 아니할 것\n• 펌프실의 출입구에는 ( 나 )을 설치할 것(단, 제6류 위험물이 아니다)\n• 탱크전용실에 펌프설비를 설치하는 경우에는 견고한 기초 위에 고정한 다음 그 주위에는 불연재료로 된 턱을 ( 다 )m 이상의 높이로 설치하는 등 누설된 위험물이 유출되거나 유입되지 아니하도록 하는 조치를 할 것\n• 액상의 위험물의 옥내저장탱크를 설치하는 탱크전용실의 바닥은 위험물이 침투하지 아니하는 구조로 하고, 적당한 경사를 두는 한편, ( 라 )를 설치할 것\n• 탱크전용실의 창 또는 출입구에 유리를 이용하는 경우에는 ( 마 )로 할 것","a":"가. 불연재료\n나. 60분+ 방화문 또는 60분 방화문\n다. 0.2\n라. 집유설비\n마. 망입유리","h":"펌프실은 상층이 없으면 지붕을 불연재료로 하고 천장을 만들지 않으며, 출입구에는 60분+ 방화문 또는 60분 방화문을 단다(제6류 위험물 전용실만 30분 방화문도 가능). 펌프설비 주위에는 불연재료 턱을 0.2m 이상 높이로 두고, 액상 위험물 탱크전용실 바닥은 침투하지 않는 구조에 경사를 주어 집유설비를 둔다. 창·출입구에 유리를 쓰면 망입유리로 한다.","t":"kan","칸":[{"a":"불연재료","syn":["불연 재료"],"l":"가"},{"a":"60분+방화문","syn":["60분+ 방화문","60분 방화문","60분방화문","방화문","갑종방화문","60분+방화문 또는 60분방화문","60분+방화문·60분방화문","60분+방화문 60분방화문"],"l":"나"},{"a":"0.2","syn":["0.2m","0.2미터","20cm"],"l":"다"},{"a":"집유설비","syn":["집유 설비","집유"],"l":"라"},{"a":"망입유리","syn":["망 입 유리","망입 유리","철망유리"],"l":"마"}],"순서무관":false},{"id":"2021-4-20","y":2021,"r":4,"n":20,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음은 알코올류의 산화 환원 반응이다. 물음에 알맞은 답을 쓰시오.\nCH3OH --(산화 -2H)--> HCOH --(산화 +O)--> ( 가 )\nC2H5OH --(산화 -2H)--> ( 나 ) --(산화 +O)--> CH3COOH\n가. 물질명 및 화학식을 쓰시오.\n나. 물질명 및 화학식을 쓰시오.\n다. '가', '나' 물질 중에서 지정수량이 작은 물질의 연소반응식을 쓰시오.","a":"가. 포름산, HCOOH\n나. 아세트알데하이드, CH3CHO\n다. 지정수량이 작은 물질은 아세트알데하이드(50L)\n2CH3CHO + 5O2 → 4CO2 + 4H2O","h":"메탄올은 H가 빠져 포름알데하이드가 되고 O가 붙어 포름산이 된다. 에탄올은 H가 빠져 아세트알데하이드가 되고 O가 붙어 아세트산이 된다. 포름산은 제2석유류 수용성(2,000L), 아세트알데하이드는 특수인화물(50L)이므로 작은 쪽은 아세트알데하이드이고, 연소하면 CO2와 H2O가 나온다.","t":"kan","칸":[{"a":"포름산, HCOOH","k":[["포름산","개미산","의산"],["HCOOH","CH2O2"]],"l":"가"},{"a":"아세트알데하이드, CH3CHO","k":[["아세트알데하이드","아세트알데히드","아세트알데이드"],["CH3CHO","C2H4O"]],"l":"나"},{"a":"2CH3CHO+5O2→4CO2+4H2O","syn":["2CH3CHO+5O2->4CO2+4H2O","2CH3CHO+5O2=4CO2+4H2O","CH3CHO+5/2O2→2CO2+2H2O","CH3CHO+5/2O2->2CO2+2H2O","CH3CHO+2.5O2→2CO2+2H2O"],"l":"다"}],"순서무관":false},{"id":"2022-1-01","y":2022,"r":1,"n":1,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량 78, 인화점 -11℃인 위험물에 대하여 다음 물음에 답하시오.\n가. 위험물의 명칭\n나. 구조식\n다. 집유설비에 설치하여야 하는 장치","a":"가. 벤젠\n나. 정육각형 고리에 C가 6개, 각 C에 H가 하나씩 붙은 벤젠 구조식\n다. 유분리장치","h":"분자량 78에 인화점 -11℃인 제4류 위험물은 벤젠(C6H6)이다. 12×6+1×6 = 78이고, 제1석유류 비수용성으로 지정수량은 200L다. 물 100g에 1g 미만으로 녹는 위험물을 옥외설비에서 취급할 때는 배수구로 바로 흘러가지 않도록 집유설비에 유분리장치를 단다.","t":"kan","칸":[{"a":"벤젠","syn":["C6H6","benzene","벤졸","벤젠(C6H6)"],"l":"가"},{"a":"유분리장치","syn":["유분리 장치","기름분리장치","기름 분리 장치","유수분리장치","유수분리기","유분리기","oil separator"],"l":"다"}],"순서무관":false},{"id":"2022-1-02","y":2022,"r":1,"n":2,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"다음 위험물의 증기비중을 구하시오.\n가. 이황화탄소\n나. 산화프로필렌\n다. 벤젠","a":"가. CS2 분자량 76 → 76/29 = 2.62\n나. 산화프로필렌 C3H6O 분자량 58 → 58/29 = 2\n다. 벤젠 C6H6 분자량 78 → 78/29 = 2.69","h":"증기비중은 분자량을 공기의 평균 분자량 29로 나눈 값이다. 이황화탄소 76, 산화프로필렌 58, 벤젠 78이므로 각각 2.62, 2, 2.69가 나온다. 산화프로필렌은 58이 29의 정확히 두 배라 나눗셈이 필요 없다.","t":"kan","칸":[{"a":"2.62","e":0.01,"l":"가"},{"a":"2","e":0.02,"l":"나"},{"a":"2.69","e":0.01,"l":"다"}],"순서무관":false},{"id":"2022-1-03","y":2022,"r":1,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령상 동식물유류를 아이오딘값에 따라 분류하고 범위를 쓰시오.","a":"건성유: 130 이상\n반건성유: 100 이상 130 미만\n불건성유: 100 미만","h":"아이오딘값은 유지 100g에 흡수되는 아이오딘의 g수로, 클수록 공기 중에서 잘 굳는다. 130 이상이 건성유, 100 이상 130 미만이 반건성유, 100 미만이 불건성유다.","t":"kan","칸":[{"a":"130 이상","syn":["130이상","130","130이상이다"],"l":"건성유"},{"a":"100 이상 130 미만","k":[["100"],["130"]],"l":"반건성유"},{"a":"100 미만","syn":["100미만","100","100이하"],"l":"불건성유"}],"순서무관":false},{"id":"2022-1-04","y":2022,"r":1,"n":4,"p":"계산","kw":"지정수량 배수","pt":5,"q":"지하탱크저장소에 다음과 같이 위험물을 각각의 탱크에 저장하고자 한다. 두 탱크 사이의 최소 거리를 쓰시오.\n가. 경유 20,000L, 휘발유 8,000L\n나. 경유 8,000L, 휘발유 20,000L\n다. 경유 20,000L, 휘발유 20,000L","a":"가. 경유 20,000/1,000 + 휘발유 8,000/200 = 20 + 40 = 60배 (100배 이하) → 0.5m\n나. 경유 8,000/1,000 + 휘발유 20,000/200 = 8 + 100 = 108배 (100배 초과) → 1m\n다. 경유 20,000/1,000 + 휘발유 20,000/200 = 20 + 100 = 120배 (100배 초과) → 1m","h":"지하저장탱크 사이 간격은 1m 이상이고, 두 탱크의 지정수량 배수 합이 100 이하이면 0.5m 이상으로 줄어든다. 경유는 제2석유류 비수용성이라 1,000L, 휘발유는 제1석유류 비수용성이라 200L를 지정수량으로 쓴다. 가는 합이 60이라 0.5m, 나와 다는 합이 100을 넘어 1m다.","t":"kan","칸":[{"a":"0.5","syn":["0.5m","0.5m 이상","0.5미터","50cm"],"l":"가"},{"a":"1","syn":["1m","1m 이상","1미터"],"l":"나"},{"a":"1","syn":["1m","1m 이상","1미터"],"l":"다"}],"순서무관":false},{"id":"2022-1-05","y":2022,"r":1,"n":5,"p":"물질·성상","kw":"소화약제","pt":5,"q":"분말소화약제의 화학식을 쓰시오.\n가. 제1종 분말소화약제\n나. 제2종 분말소화약제\n다. 제3종 분말소화약제","a":"가. NaHCO3\n나. KHCO3\n다. NH4H2PO4","h":"제1종은 탄산수소나트륨 NaHCO3, 제2종은 탄산수소칼륨 KHCO3, 제3종은 인산암모늄 NH4H2PO4다. 제1·2종은 BC급이고 제3종만 ABC급이며, 제1·2종은 가열하면 탄산염과 CO2, H2O로 분해된다. 제4종은 KHCO3와 요소 (NH2)2CO를 섞은 BC급이고 시험에서는 화학식을 묻지 않는다.","t":"kan","칸":[{"a":"NaHCO3","syn":["탄산수소나트륨","중탄산나트륨","중탄산소다","탄산수소소다"],"l":"가"},{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"나"},{"a":"NH4H2PO4","syn":["인산암모늄","제일인산암모늄","인산이수소암모늄","인산이수소 암모늄","(NH4)H2PO4"],"l":"다"}],"순서무관":false},{"id":"2022-1-06","y":2022,"r":1,"n":6,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 [보기] 중에서 금수성 및 자연발화성 특징을 동시에 가지는 물질을 찾아 모두 쓰시오.\n황린, 나이트로글리세린, 칼륨, 트라이나이트로페놀, 수소화나트륨, 나이트로벤젠","a":"칼륨, 수소화나트륨","h":"물과 반응하는 금수성이면서 자연발화성도 갖는 물질을 고르면 제3류의 칼륨과 수소화나트륨이다. 황린은 물과 반응하지 않고 자연발화성만 있어 물속에 저장한다. 나이트로글리세린과 트라이나이트로페놀은 제5류 자기반응성 물질, 나이트로벤젠은 제4류다.","t":"kan","칸":[{"a":"칼륨","syn":["K","포타슘","potassium"]},{"a":"수소화나트륨","syn":["NaH","수소화 나트륨"]}],"순서무관":true},{"id":"2022-1-07","y":2022,"r":1,"n":7,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제2류 위험물 중 마그네슘에 대하여 다음 물음에 답하시오.\n가. 지름 ( )mm 이상의 막대모양 제외, 지름 ( )mm 미만의 마그네슘이 위험물에 해당된다.\n나. 위험등급\n다. 염산과의 화학반응식\n라. 물과의 화학반응식","a":"가. 2, 2\n나. III\n다. Mg + 2HCl → MgCl2 + H2\n라. Mg + 2H2O → Mg(OH)2 + H2","h":"마그네슘은 제2류 위험물로 위험등급 III, 지정수량 500kg이며, 지름 2mm 이상의 막대 모양은 위험물에서 제외한다. 염산과 반응하면 MgCl2와 H2, 물과 반응하면 Mg(OH)2와 H2가 나와 두 경우 모두 수소가 발생한다.","t":"kan","칸":[{"a":"2","syn":["2mm","2 mm"],"l":"가-1"},{"a":"2","syn":["2mm","2 mm"],"l":"가-2"},{"a":"III","syn":["Ⅲ","3","III등급","Ⅲ등급","3등급","III 등급","Ⅲ 등급","Ⅲ급","3급"],"l":"나"},{"a":"Mg+2HCl→MgCl2+H2","syn":["Mg+2HCl->MgCl2+H2","Mg+2HCl=MgCl2+H2"],"l":"다"},{"a":"Mg+2H2O→Mg(OH)2+H2","syn":["Mg+2H2O->Mg(OH)2+H2","Mg+2H2O=Mg(OH)2+H2"],"l":"라"}],"순서무관":false},{"id":"2022-1-08","y":2022,"r":1,"n":8,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제3류 위험물 중 위험등급 I인 위험물의 품명을 5가지 쓰시오.","a":"알킬알루미늄, 칼륨, 알킬리튬, 나트륨, 황린","h":"제3류에서 위험등급 I은 지정수량 10kg인 알킬알루미늄·칼륨·알킬리튬·나트륨과 20kg인 황린이다. 알칼리금속·알칼리토금속과 유기금속화합물(50kg)은 II, 금속수소화합물·금속인화합물·칼슘 또는 알루미늄의 탄화물(300kg)은 III이다.","t":"kan","칸":[{"a":"알킬알루미늄","syn":["알킬 알루미늄","알킬알미늄"]},{"a":"칼륨","syn":["K","포타슘","potassium"]},{"a":"알킬리튬","syn":["알킬 리튬","알킬리듐"]},{"a":"나트륨","syn":["Na","소듐","sodium"]},{"a":"황린","syn":["백린","P4","황 린"]}],"순서무관":true},{"id":"2022-1-09","y":2022,"r":1,"n":9,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물과 혼재 가능한 위험물을 모두 쓰시오 (단, 위험물 저장량은 지정수량의 1/10 초과이다).\n가. 제2류 위험물\n나. 제4류 위험물\n다. 제6류 위험물","a":"가. 제4류 위험물, 제5류 위험물\n나. 제2류 위험물, 제3류 위험물, 제5류 위험물\n다. 제1류 위험물","h":"혼재 가능한 조합은 4와 2·3, 5와 2·4, 6과 1이다. 그래서 제2류는 제4·5류, 제4류는 제2·3·5류, 제6류는 제1류와 함께 실을 수 있다. 이 표는 지정수량 1/10 초과일 때 적용한다.","t":"kan","칸":[{"a":"제4류 위험물, 제5류 위험물","k":[["4류"],["5류"]],"l":"가"},{"a":"제2류 위험물, 제3류 위험물, 제5류 위험물","k":[["2류"],["3류"],["5류"]],"l":"나"},{"a":"제1류","syn":["1류","제1류 위험물","1류 위험물","제 1류"],"l":"다"}],"순서무관":false},{"id":"2022-1-10","y":2022,"r":1,"n":10,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"주유취급소에 설치할 수 있는 탱크의 최대 용량을 쓰시오.\n가. 고정주유설비, 고정급유설비\n나. 보일러 전용탱크\n다. 자동차 점검·정비하는 작업장의 폐유탱크\n라. 고속국도의 도로변","a":"가. 50,000L 이하\n나. 10,000L 이하\n다. 2,000L 이하\n라. 60,000L 이하","h":"주유취급소 탱크는 고정주유설비·고정급유설비용이 50,000L 이하, 보일러 전용탱크가 10,000L 이하, 자동차 점검·정비 작업장의 폐유탱크 등이 2,000L 이하다. 고속국도 도로변 주유취급소만 60,000L 이하로 한도가 더 크다.","t":"kan","칸":[{"a":"50000","syn":["50,000","50000L","50,000L","5만","5만L","50000리터","50,000L 이하","50000L 이하"],"l":"가"},{"a":"10000","syn":["10,000","10000L","10,000L","1만","1만L","10000리터","10,000L 이하","10000L 이하"],"l":"나"},{"a":"2000","syn":["2,000","2000L","2,000L","2천","2천L","2000리터","2,000L 이하","2000L 이하"],"l":"다"},{"a":"60000","syn":["60,000","60000L","60,000L","6만","6만L","60000리터","60,000L 이하","60000L 이하"],"l":"라"}],"순서무관":false},{"id":"2022-1-11","y":2022,"r":1,"n":11,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"인화점이 섭씨 21도 이상 70도 미만이면서 수용성인 물질을 모두 쓰시오.\n메틸알코올, 아세트산, 포름산, 글리세린, 나이트로벤젠","a":"아세트산, 포름산","h":"인화점 21℃ 이상 70℃ 미만은 제2석유류이고, 그중 수용성은 아세트산과 포름산이다. 메틸알코올은 알코올류이고, 글리세린은 수용성 제3석유류, 나이트로벤젠은 비수용성 제3석유류라 조건에서 빠진다.","t":"kan","칸":[{"a":"아세트산","syn":["초산","CH3COOH","아세트 산"]},{"a":"포름산","syn":["개미산","의산","HCOOH","포름 산"]}],"순서무관":true},{"id":"2022-1-12","y":2022,"r":1,"n":12,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 위험물의 연소반응식을 쓰시오.\n가. 에틸알코올\n나. 메틸알코올","a":"가. C2H5OH + 3O2 → 2CO2 + 3H2O\n나. 2CH3OH + 3O2 → 2CO2 + 4H2O","h":"알코올이 연소하면 CO2와 H2O가 생긴다. 에탄올은 산소 3분자로 계수가 정수이고, 메탄올은 산소가 1.5분자 필요해 전체에 2를 곱한 2CH3OH + 3O2로 맞춘다.","t":"kan","칸":[{"a":"C2H5OH+3O2→2CO2+3H2O","syn":["C2H5OH+3O2->2CO2+3H2O","C2H5OH+3O2=2CO2+3H2O","C2H5OH+3O2→3H2O+2CO2","C2H5OH+3O2->3H2O+2CO2"],"l":"가"},{"a":"2CH3OH+3O2→2CO2+4H2O","syn":["2CH3OH+3O2->2CO2+4H2O","2CH3OH+3O2=2CO2+4H2O","CH3OH+3/2O2→CO2+2H2O","CH3OH+3/2O2->CO2+2H2O","CH3OH+1.5O2→CO2+2H2O","2CH3OH+3O2→4H2O+2CO2"],"l":"나"}],"순서무관":false},{"id":"2022-1-13","y":2022,"r":1,"n":13,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"위험물안전관리법에서 정하는 옥외저장소의 보유공지에 대하여 다음 빈칸에 알맞은 말을 쓰시오.\n지정수량의 10배 이하 — 제1석유류 ( 가 )m 이상 / 제2석유류 ( 나 )m 이상\n지정수량의 20배 초과 50배 이하 — 제2석유류 ( 다 )m 이상 / 제3석유류 ( 라 )m 이상 / 제4석유류 ( 마 )m 이상","a":"가. 3, 나. 3\n다. 9, 라. 9\n마. 3","h":"옥외저장소 보유공지는 지정수량 10배 이하 3m, 20배 이하 5m, 50배 이하 9m, 200배 이하 12m, 200배 초과 15m 이상이다. 20배 초과 50배 이하이면 제2석유류와 제3석유류는 9m다. 제4석유류와 제6류는 이 값의 1/3을 적용하므로 9m의 1/3인 3m 이상이다.","t":"kan","칸":[{"a":"3","syn":["3m","3m 이상","3미터"],"l":"가"},{"a":"3","syn":["3m","3m 이상","3미터"],"l":"나"},{"a":"9","syn":["9m","9m 이상","9미터"],"l":"다"},{"a":"9","syn":["9m","9m 이상","9미터"],"l":"라"},{"a":"3","syn":["3m","3m 이상","3미터"],"l":"마"}],"순서무관":false},{"id":"2022-1-14","y":2022,"r":1,"n":14,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물에 대한 유별과 지정수량을 알맞게 쓰시오.\n칼륨 ( 가 ) ( 나 )\n다이아조화합물 ( 다 ) ( 라 )\n나이트로화합물 ( 마 ) ( 바 )\n질산 ( 사 ) ( 아 )\n질산염류 ( 자 ) ( 차 )","a":"가. 제3류 위험물, 나. 10kg\n다. 제5류 위험물, 라. 제1종 10kg, 제2종 100kg\n마. 제5류 위험물, 바. 제1종 10kg, 제2종 100kg\n사. 제6류 위험물, 아. 300kg\n자. 제1류 위험물, 차. 300kg","h":"칼륨은 제3류 10kg, 질산은 제6류 300kg, 질산염류는 제1류 300kg이다. 다이아조화합물과 나이트로화합물은 제5류이며 제1종 10kg, 제2종 100kg으로 지정수량이 둘로 나뉜다.","t":"kan","칸":[{"a":"제3류","syn":["3류","제3류 위험물","3류 위험물","제 3류"],"l":"가"},{"a":"10kg","syn":["10","10 kg"],"l":"나"},{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"다"},{"a":"제1종 10kg, 제2종 100kg","k":[["1종"],["2종"],["100"]],"l":"라"},{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"마"},{"a":"제1종 10kg, 제2종 100kg","k":[["1종"],["2종"],["100"]],"l":"바"},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"사"},{"a":"300kg","syn":["300","300 kg"],"l":"아"},{"a":"제1류","syn":["1류","제1류 위험물","1류 위험물","제 1류"],"l":"자"},{"a":"300kg","syn":["300","300 kg"],"l":"차"}],"순서무관":false},{"id":"2022-1-15","y":2022,"r":1,"n":15,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"다음 위험물이 반응할 때 발생하는 유독가스의 명칭을 쓰시오 (단, 발생 유독 가스가 없으면 해당없음을 쓰시오).\n가. 황린의 연소반응식\n나. 황린과 수산화칼륨\n다. 인화칼슘과 물\n라. 아세트산의 연소반응식\n마. 과산화바륨과 물","a":"가. 오산화인\n나. 포스핀\n다. 포스핀\n라. 해당없음\n마. 해당없음","h":"황린의 연소(P4 + 5O2 → 2P2O5)에서는 유독한 오산화인이 나온다. 황린에 KOH 수용액을 가하는 경우와 인화칼슘이 물과 반응하는 경우에는 둘 다 포스핀(PH3)이 나온다. 아세트산 연소는 CO2와 수증기, 과산화바륨과 물의 반응은 산소만 내므로 해당없음이다.","t":"kan","칸":[{"a":"오산화인","syn":["P2O5","오산화이인","오산화 인"],"l":"가"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine"],"l":"나"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine"],"l":"다"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"마"}],"순서무관":false},{"id":"2022-1-16","y":2022,"r":1,"n":16,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"옥외탱크저장소에 설치한 방유제에 대하여 다음 물음에 답하시오.\n가. 방유제의 면적\n나. 제1석유류 15만리터 저장 시 설치할 수 있는 최대 탱크 수\n다. 방유제 내에 저장탱크의 개수를 제한하지 아니하여도 되는 인화점 기준","a":"가. 80,000m2 이하\n나. 10기 이하\n다. 인화점 200℃ 이상인 위험물을 저장 또는 취급하는 경우","h":"방유제는 높이 0.5m 이상 3m 이하, 두께 0.2m 이상, 면적 80,000m2 이하이고 탱크는 10기 이하다. 탱크 용량이 모두 20만L 이하이고 인화점이 70℃ 이상 200℃ 미만이면 20기까지 허용하며, 인화점 200℃ 이상 위험물은 개수 제한이 없다. 제1석유류는 인화점이 낮아 10기 이하가 적용된다.","t":"kan","칸":[{"a":"80000","syn":["80,000","80000m2","80,000m2","80000㎡","80,000㎡","8만","8만m2","80000m2 이하","80,000m2 이하"],"l":"가"},{"a":"10","syn":["10기","10기 이하","10개"],"l":"나"},{"a":"인화점 200℃ 이상","k":[["200"],["이상","초과"]],"l":"다"}],"순서무관":false},{"id":"2022-1-17","y":2022,"r":1,"n":17,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 보기에서 설명하는 위험물의 과산화물인 제1류 위험물에 대하여 다음 물음에 답하시오.\n• 불꽃 반응 시 보라색을 나타낸다.\n• 분자량 39, 인화점 -11℃인 무른 경금속이다.\n가. 물과의 화학반응식\n나. 이산화탄소와의 화학반응식\n다. 옥내저장소 바닥면적","a":"가. 2K2O2 + 2H2O → 4KOH + O2\n나. 2K2O2 + 2CO2 → 2K2CO3 + O2\n다. 1,000m2","h":"과산화칼륨(K2O2)은 제1류 무기과산화물로 지정수량 50kg, 위험등급 I이다. 물과 반응하면 KOH와 O2, 이산화탄소와 반응하면 K2CO3와 O2가 나와 두 경우 모두 산소가 발생한다. 옥내저장소는 위험등급 I 위험물이나 제4류의 위험등급 I·II 위험물을 저장하면 바닥면적 1,000m2 이하다.","t":"kan","칸":[{"a":"2K2O2+2H2O→4KOH+O2","syn":["2K2O2+2H2O->4KOH+O2","2K2O2+2H2O=4KOH+O2","K2O2+H2O→2KOH+1/2O2","K2O2+H2O->2KOH+1/2O2"],"l":"가"},{"a":"2K2O2+2CO2→2K2CO3+O2","syn":["2K2O2+2CO2->2K2CO3+O2","2K2O2+2CO2=2K2CO3+O2","K2O2+CO2→K2CO3+1/2O2","K2O2+CO2->K2CO3+1/2O2"],"l":"나"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"다"}],"순서무관":false},{"id":"2022-1-18","y":2022,"r":1,"n":18,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"에틸렌과 산소를 CuCl2 촉매하에서 생성된 물질로 인화점이 -38℃, 비점이 21℃, 연소범위가 4.1~57%인 특수인화물에 대하여 보기에 대한 답을 쓰시오 (단, 공기의 평균분자량은 약 29이다).\n가. 시성식\n나. 증기비중\n다. 보냉장치가 없는 이동탱크저장소에서 유지하여야 하는 온도는 몇 도 이하인가?","a":"가. CH3CHO\n나. 분자량 44 → 44/29 = 1.52\n다. 40℃ 이하","h":"에틸렌을 CuCl2 촉매로 산화해 얻는, 인화점 -38℃ 특수인화물은 아세트알데하이드다. 분자량이 12×2+1×4+16 = 44이므로 증기비중은 44/29 = 1.52다. 이동저장탱크는 보냉장치가 없으면 40℃ 이하, 있으면 비점 이하로 유지하고, 옥외·옥내 저장탱크(압력탱크 외)에서는 15℃ 이하다.","t":"kan","칸":[{"a":"CH3CHO","syn":["아세트알데하이드","아세트알데히드","C2H4O","CH3CH=O"],"l":"가"},{"a":"1.52","e":0.01,"l":"나"},{"a":"40℃","syn":["40","40도","40℃ 이하","40도 이하"],"l":"다"}],"순서무관":false},{"id":"2022-1-19","y":2022,"r":1,"n":19,"p":"계산","kw":"탱크 용량","pt":5,"q":"위험물안전관리법령상 다음 옥외저장탱크에 대하여 물음에 답하시오.\n(세로형 원통형 탱크 : 원통 부분 높이 8m, 지붕을 포함한 전체 높이 10m, 윗면에서 본 원의 반지름 10m)\n가. 공간용적 10%일 때 탱크의 용량(L)을 구하시오.\n나. 기술검토를 받아야 하는지 쓰시오.\n다. 완공검사를 받아야 하는지 쓰시오.\n라. 정기검사를 받아야 하는지 쓰시오.","a":"가. π×(10)²×8×(1−0.1) = 2,261.947m3 = 2,261,946.71L\n나. 받아야 함\n다. 받아야 함\n라. 받아야 함","h":"옥외탱크저장소는 저장용량이 50만L 이상이면 기초·지반, 탱크본체, 소화설비에 대해 기술검토를 받는다. 설치 허가를 받은 제조소등은 완공검사를 받고, 액체위험물 50만L 이상 옥외탱크저장소는 정기점검 대상이다. 용량 계산은 πr²l에 (1−공간용적 비율)을 곱하고 m3를 L로 바꾼다.","img":["2022-1-19.svg"],"tp":"W04","t":"kan","칸":[{"a":"2261946.71","e":100,"l":"가"},{"a":"받아야 함","syn":["받아야 한다","받아야한다","받아야함","받는다","받음","받아야","한다","필요하다","필요함","예","O"],"l":"나"},{"a":"받아야 함","syn":["받아야 한다","받아야한다","받아야함","받는다","받음","받아야","한다","필요하다","필요함","예","O"],"l":"다"},{"a":"받아야 함","syn":["받아야 한다","받아야한다","받아야함","받는다","받음","받아야","한다","필요하다","필요함","예","O"],"l":"라"}],"순서무관":false},{"id":"2022-1-20","y":2022,"r":1,"n":20,"p":"시설·법령","kw":"운송·이동탱크","pt":5,"q":"위험물안전관리법령상 위험물의 운송에 관한 내용이다. 다음 물음에 알맞은 답을 쓰시오.\n가. 운송책임자가 운전자를 감독 또는 지원하는 방법으로 옳은 것을 모두 고르시오 (단, 없으면 해당없음이라고 쓰시오).\n ① 이동탱크저장소에 동승한다.\n ② 사무실에 대기하면서 감독·지원한다.\n ③ 부득이한 경우 GPS로 감독·지원한다.\n ④ 다른 차량을 이용하여 따라 다니면서 지원, 감독한다.\n나. 위험물 운송 시 운전자가 장시간 운전할 경우 2명 이상의 운전자로 하여야 한다. 하지만 그러하지 않아도 되는 경우를 모두 고르시오 (단, 없으면 해당없음이라고 쓰시오).\n ① 운송책임자가 동승하는 경우\n ② 제2류 위험물을 운반하는 경우\n ③ 제4류 위험물 중 제1석유류를 운반하는 경우\n ④ 2시간 이내마다 20분 이상씩 휴식하는 경우\n다. 제4류 위험물 중 특수인화물 운송 시 이동탱크저장소에 비치하여야 하는 것을 모두 고르시오.\n ① 완공검사합격확인증\n ② 정기검사확인증\n ③ 설치허가확인증\n ④ 위험물안전관리카드","a":"가. ①, ②\n나. ①, ②, ③, ④\n다. ①, ④","h":"운송책임자는 이동탱크저장소에 동승하거나, 사무실에서 운송경로·연락체계를 갖추고 운전자의 안전 상황 확인과 응급처치 조언 등으로 감독·지원한다. 장거리(고속국도 340km 이상, 그 밖의 도로 200km 이상) 운송은 운전자 2명이 원칙이지만 운송책임자 동승, 제2류·제3류 중 탄화물·특수인화물을 뺀 제4류, 2시간마다 20분 이상 휴식하면 1명도 된다. 이동탱크저장소에는 완공검사합격확인증을 항상 두고, 특수인화물과 제1석유류를 운송할 때는 위험물안전카드를 휴대한다.","t":"kan","칸":[{"a":"①, ②","k":[["①","1"],["②","2"]],"l":"가","no":["③","④","3","4"]},{"a":"①, ②, ③, ④","k":[["①","1"],["②","2"],["③","3"],["④","4"]],"l":"나"},{"a":"①, ④","k":[["①","1"],["④","4"]],"l":"다","no":["②","③","2","3"]}],"순서무관":false},{"id":"2022-2-01","y":2022,"r":2,"n":1,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"나이트로셀룰로오스에 대하여 다음 물음에 답하시오.\n가. 원료 중심 제조 방법\n나. 품명\n다. 지정수량\n라. 운반용기 외부에 표시하여야 하는 주의사항","a":"가. 셀룰로오스를 진한 질산과 진한 황산의 혼산으로 나이트로화 반응시켜 제조\n나. 질산에스터류\n다. 10kg\n라. 화기엄금, 충격주의","h":"나이트로셀룰로오스는 셀룰로오스를 진한 질산과 진한 황산의 혼산으로 나이트로화해서 만든 제5류 질산에스터류이고 지정수량은 10kg이다. 같은 방법으로 페놀은 트라이나이트로페놀, 톨루엔은 트라이나이트로톨루엔, 글리세린은 나이트로글리세린, 에틸렌글리콜은 나이트로글리콜이 된다. 운반용기에는 화기엄금과 충격주의를 표시한다.","t":"kan","칸":[{"a":"셀룰로오스를 진한 질산과 진한 황산의 혼산으로 나이트로화 반응시켜 제조","k":[["셀룰로오스","셀룰로스","섬유소","면","cellulose"],["질산","황산","혼산","나이트로","니트로"]],"l":"가"},{"a":"질산에스터류","syn":["질산에스테르류","질산에스터","질산에스테르","질산 에스터류"],"l":"나"},{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"다"},{"a":"화기엄금, 충격주의","k":[["화기엄금","화기 엄금"],["충격"]],"l":"라"}],"순서무관":false},{"id":"2022-2-02","y":2022,"r":2,"n":2,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"아세트알데하이드를 산화시켜 얻을 수 있는 제4류 위험물에 대하여 다음 물음에 답하시오.\n가. 시성식\n나. 완전연소반응식\n다. 옥내저장소에 저장 시 바닥면적","a":"가. CH3COOH\n나. CH3COOH + 2O2 → 2CO2 + 2H2O\n다. 2,000m2","h":"아세트알데하이드를 산화하면 아세트산(CH3COOH)이 되며, 제4류 제2석유류 수용성으로 지정수량 2,000L, 위험등급 III이다. 연소하면 CO2와 수증기가 나오고 O2 계수는 2다. 옥내저장소에서 위험등급 III인 제4류 위험물을 저장하면 바닥면적은 2,000m2 이하다.","t":"kan","칸":[{"a":"CH3COOH","syn":["아세트산","초산","C2H4O2"],"l":"가"},{"a":"CH3COOH+2O2→2CO2+2H2O","syn":["CH3COOH+2O2->2CO2+2H2O","CH3COOH+2O2=2CO2+2H2O","CH3COOH+2O2→2H2O+2CO2","CH3COOH+2O2->2H2O+2CO2"],"l":"나"},{"a":"2000","syn":["2,000","2000m2","2,000m2","2000㎡","2,000㎡","2000m2 이하","2,000m2 이하"],"l":"다"}],"순서무관":false},{"id":"2022-2-03","y":2022,"r":2,"n":3,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"칼륨(제3류 위험물)과 다음 물질과의 반응식을 쓰시오.\n가. 이산화탄소\n나. 에탄올","a":"가. 4K + 3CO2 → 2K2CO3 + C\n나. 2K + 2C2H5OH → 2C2H5OK + H2","h":"칼륨은 이산화탄소와 반응해 탄산칼륨과 탄소가 생기므로 CO2 소화약제를 쓸 수 없다. 에탄올과는 OH의 수소가 칼륨으로 바뀌면서 칼륨에틸라이드(C2H5OK)와 수소가 나온다.","t":"kan","칸":[{"a":"4K+3CO2→2K2CO3+C","syn":["4K+3CO2->2K2CO3+C","4K+3CO2=2K2CO3+C"],"l":"가"},{"a":"2K+2C2H5OH→2C2H5OK+H2","syn":["2K+2C2H5OH->2C2H5OK+H2","2K+2C2H5OH=2C2H5OK+H2","K+C2H5OH→C2H5OK+1/2H2"],"l":"나"}],"순서무관":false},{"id":"2022-2-04","y":2022,"r":2,"n":4,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제1류 위험물 중 위험등급이 I등급인 위험물의 품명 3가지를 쓰시오.","a":"아염소산염류, 염소산염류, 과염소산염류, 무기과산화물 중 3가지","h":"제1류에서 위험등급 I은 지정수량 50kg인 무기과산화물·아염소산염류·과염소산염류·염소산염류다. 브로민산염류·아이오딘산염류·질산염류(300kg)는 II, 다이크로뮴산염류·과망가니즈산염류(1,000kg)는 III이다.","t":"kan","칸":[{"a":"아염소산염류","syn":["아염소산염","아염소산 염류"]},{"a":"염소산염류","syn":["염소산염","염소산 염류"]},{"a":"과염소산염류","syn":["과염소산염","과염소산 염류"]},{"a":"무기과산화물","syn":["무기 과산화물","무기과산화"]}],"순서무관":true,"nc":3},{"id":"2022-2-05","y":2022,"r":2,"n":5,"p":"반응식","kw":"물과 반응","pt":5,"q":"트라이에틸알루미늄과 물을 반응시켰을 때 다음 물음에 답하시오.\n가. 화학반응식\n나. 위에서 발생하는 가연성 기체의 연소반응식","a":"가. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n나. 2C2H6 + 7O2 → 4CO2 + 6H2O","h":"트라이에틸알루미늄은 물과 반응해 수산화알루미늄과 에테인(C2H6)을 낸다. 에틸기가 세 개라 에테인이 3분자 나오고, 이 에테인이 연소하면 CO2와 H2O가 되며 C2H6 2분자에 O2 7분자가 든다. 탄화알루미늄에서는 같은 물 반응이라도 메테인이 나온다.","t":"kan","칸":[{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"가"},{"a":"2C2H6+7O2→4CO2+6H2O","syn":["2C2H6+7O2->4CO2+6H2O","2C2H6+7O2=4CO2+6H2O","C2H6+7/2O2→2CO2+3H2O","C2H6+7/2O2->2CO2+3H2O","C2H6+3.5O2→2CO2+3H2O"],"l":"나"}],"순서무관":false},{"id":"2022-2-06","y":2022,"r":2,"n":6,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물 중 산화프로필렌에 대하여 다음 물음에 답하시오.\n가. 증기비중\n나. 위험등급\n다. 옥외저장탱크 중 압력탱크 외의 저장할 때 몇 도 이하로 저장해야 하는가?","a":"가. 58/29 = 2\n나. I\n다. 30℃","h":"산화프로필렌(C3H6O)은 분자량 58이라 증기비중이 58/29 = 2이고, 제4류 특수인화물로 지정수량 50L, 위험등급 I이다. 옥외·옥내·지하저장탱크(압력탱크 외)에 저장할 때 산화프로필렌은 30℃ 이하, 아세트알데하이드는 15℃ 이하로 유지한다.","t":"kan","칸":[{"a":"2","e":0.02,"l":"가"},{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"나"},{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"다"}],"순서무관":false},{"id":"2022-2-07","y":2022,"r":2,"n":7,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량 100.5, 비중 1.76이며 염소산 중에서 가장 산성이 강한 물질인 위험물에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 위험등급\n다. 위험물의 유별\n라. 제조소와 병원 사이의 안전거리\n마. 5,000kg을 취급하는 제조소의 보유공지 최소 너비","a":"가. HClO4\n나. I\n다. 제6류 위험물\n라. 안전거리 적용 제외\n마. 5,000kg ÷ 300kg = 16.67배 → 10배 초과이므로 5m 이상","h":"산의 세기는 HClO < HClO2 < HClO3 < HClO4 순이라 염소산 중 가장 센 것은 과염소산(HClO4, 분자량 100.5)이다. 제6류 위험물이며 지정수량 300kg, 위험등급 I이고, 제6류 위험물 제조소는 안전거리를 적용하지 않는다. 보유공지는 지정수량 10배 이하 3m, 10배 초과 5m인데 16.67배라 5m 이상이다.","t":"kan","칸":[{"a":"HClO4","syn":["과염소산","HCLO4","hclo4","perchloric acid"],"l":"가"},{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"나"},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"다"},{"a":"안전거리 적용 제외","syn":["제외","적용제외","적용 제외","없음","해당없음","해당 없음","안전거리 없음","적용하지 않음","안전거리 제외","안전거리제외"],"l":"라"},{"a":"5m","syn":["5","5m 이상","5미터","5 m"],"l":"마"}],"순서무관":false},{"id":"2022-2-08","y":2022,"r":2,"n":8,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"다음 소화설비의 능력단위 기준에 맞추어 빈칸에 알맞은 말을 쓰시오.\n소화전용물통 ( 가 ) / 0.3\n수조 + 물통 3개 80L / ( 나 )\n수조 + 물통 6개 190L / ( 다 )\n마른 모래 ( 라 ) / 0.5\n팽창질석, 팽창진주암 160L / ( 마 )","a":"가. 8L, 나. 1.5\n다. 2.5, 라. 50L\n마. 1.0","h":"능력단위는 소화전용 물통 8L가 0.3, 수조+물통 3개 80L가 1.5, 수조+물통 6개 190L가 2.5, 마른 모래 50L가 0.5, 팽창질석·팽창진주암 160L가 1.0이다. 수조 기준은 물통이 3개에서 6개로 늘면 용량이 80L에서 190L, 단위가 1.5에서 2.5로 커진다.","t":"kan","칸":[{"a":"8L","syn":["8","8 L","8리터"],"l":"가"},{"a":"1.5","syn":["1.5단위"],"l":"나"},{"a":"2.5","syn":["2.5단위"],"l":"다"},{"a":"50L","syn":["50","50 L","50리터"],"l":"라"},{"a":"1.0","syn":["1","1단위","1.0단위"],"l":"마"}],"순서무관":false},{"id":"2022-2-09","y":2022,"r":2,"n":9,"p":"반응식","kw":"물과 반응","pt":5,"q":"탄화알루미늄이 다음 물질과 반응하였을 때 화학반응식을 쓰시오.\n가. 물\n나. 염산","a":"가. Al4C3 + 12H2O → 4Al(OH)3 + 3CH4\n나. Al4C3 + 12HCl → 4AlCl3 + 3CH4","h":"탄화알루미늄은 물과 반응하면 수산화알루미늄과 메테인, 염산과 반응하면 염화알루미늄과 메테인을 낸다. 두 반응 모두 Al4C3 한 분자에 물 또는 HCl 12분자가 들어가고 메테인 3분자가 나온다. 탄화칼슘은 같은 반응에서 아세틸렌이 나오는 점이 다르다.","t":"kan","칸":[{"a":"Al4C3+12H2O→4Al(OH)3+3CH4","syn":["Al4C3+12H2O->4Al(OH)3+3CH4","Al4C3+12H2O=4Al(OH)3+3CH4","Al4C3+12H2O→3CH4+4Al(OH)3","Al4C3+12H2O->3CH4+4Al(OH)3"],"l":"가"},{"a":"Al4C3+12HCl→4AlCl3+3CH4","syn":["Al4C3+12HCl->4AlCl3+3CH4","Al4C3+12HCl=4AlCl3+3CH4","Al4C3+12HCl→3CH4+4AlCl3","Al4C3+12HCl->3CH4+4AlCl3"],"l":"나"}],"순서무관":false},{"id":"2022-2-10","y":2022,"r":2,"n":10,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물을 물과 반응시켰을 때 생성되는 기체의 명칭을 쓰시오 (단, 생성되는 기체가 없으면 해당없음을 쓰시오).\n가. 염소산칼륨\n나. 질산암모늄\n다. 과산화칼륨\n라. 인화칼슘\n마. 리튬","a":"가. 해당없음\n나. 해당없음\n다. 산소\n라. 포스핀\n마. 수소","h":"과산화칼륨은 물과 반응해 산소(2K2O2 + 2H2O → 4KOH + O2), 인화칼슘은 포스핀(Ca3P2 + 6H2O → 3Ca(OH)2 + 2PH3), 리튬은 수소(2Li + 2H2O → 2LiOH + H2)를 낸다. 염소산칼륨과 질산암모늄은 물에 반응하지 않아 해당없음이다.","t":"kan","칸":[{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"나"},{"a":"산소","syn":["O2","산소가스","oxygen"],"l":"다"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine"],"l":"라"},{"a":"수소","syn":["H2","수소가스","hydrogen"],"l":"마"}],"순서무관":false},{"id":"2022-2-11","y":2022,"r":2,"n":11,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"제1류 위험물인 염소산칼륨에 관한 내용이다. 다음 각 물음에 답을 쓰시오.\n가. 완전분해 반응식\n나. 염소산칼륨 24.5kg이 표준상태에서 완전 분해 시 생성되는 산소의 부피(m3) (단, 염소산칼륨의 분자량은 123이다)","a":"가. 2KClO3 → 2KCl + 3O2\n나. ① KClO3 24.5kg, 분자량 123, 표준상태(0℃, 1atm)\n② V = wRT/PM × (3O2/2KClO3)\n③ (24.5×0.082×273)/(1×123) × 3/2 = 6.688\n④ 6.69m3","h":"염소산칼륨 2kmol이 분해되면 산소 3kmol이 나오므로, 질량을 분자량 123으로 나눈 값에 3/2를 곱해 산소 몰수를 구한다. 표준상태는 0℃, 1기압이고, 질량을 kg으로 두면 R = 0.082atm·m3/kmol·K를 써서 부피가 m3로 나온다.","tp":"W01","t":"kan","칸":[{"a":"2KClO3→2KCl+3O2","syn":["2KClO3->2KCl+3O2","2KClO3=2KCl+3O2","KClO3→KCl+3/2O2","KClO3->KCl+3/2O2"],"l":"가"},{"a":"6.69","e":0.05,"l":"나"}],"순서무관":false},{"id":"2022-2-12","y":2022,"r":2,"n":12,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음과 같은 옥외탱크저장소가 있다. 저장 가능한 용량의 최대값과 최소값을 구하여라.\n(가로형 타원형 탱크 : 장축 5m, 단축 3m, 몸통 3m, 양쪽 경판 0.3m씩)","a":"① 장축 5m, 단축 3m, 몸통 3m, 경판 0.3m씩\n② 내용적 = (πab/4)×(l + (l1+l2)/3)\n③ (π×5×3/4)×(3 + 0.6/3) = 37.699m3\n④ 최대: 공간용적 5% → 37.699×0.95 = 35.81m3\n 최소: 공간용적 10% → 37.699×0.90 = 33.93m3\n최대값 35.81m3, 최소값 33.93m3","h":"공간용적은 내용적의 5% 이상 10% 이하다. 공간용적이 가장 작은 5%일 때 저장 용량이 최대이고, 가장 큰 10%일 때 최소가 된다. 타원형 탱크의 내용적은 πab/4에 몸통과 경판 항을 곱한 식이다.","tp":"W04","t":"kan","칸":[{"a":"35.81","e":0.05,"l":"최대값"},{"a":"33.93","e":0.05,"l":"최소값"}],"순서무관":false},{"id":"2022-2-13","y":2022,"r":2,"n":13,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"위험물안전관리법에서 정하는 위험물의 정의를 쓰시오.\n가. 인화성고체\n나. 철분\n다. 제2석유류","a":"가. 고형알코올 그 밖에 1기압에서 인화점이 섭씨 40도 미만인 고체\n나. 철의 분말로서 53마이크로미터의 표준체를 통과하는 것이 50중량퍼센트 미만인 것은 제외\n다. 등유, 경유 그 밖에 1기압에서 인화점이 섭씨 21도 이상 70도 미만인 것","h":"인화성고체는 인화점 40℃ 미만의 고체, 제2석유류는 인화점 21℃ 이상 70℃ 미만의 액체다. 철분은 53마이크로미터 체를 통과하는 것이 50중량% 미만이면 제외하고, 같은 제2류의 금속분은 150마이크로미터 체가 기준이라 체 크기가 다르다.","t":"kan","칸":[{"a":"고형알코올 그 밖에 1기압에서 인화점이 섭씨 40도 미만인 고체","k":[["고형알코올","고형 알코올"],["40"],["고체"]],"l":"가"},{"a":"철의 분말로서 53마이크로미터의 표준체를 통과하는 것이 50중량퍼센트 미만인 것은 제외","k":[["53"],["50"],["분말","표준체"]],"l":"나"},{"a":"등유, 경유 그 밖에 1기압에서 인화점이 섭씨 21도 이상 70도 미만인 것","k":[["등유","경유"],["21"],["70"]],"l":"다"}],"순서무관":false},{"id":"2022-2-14","y":2022,"r":2,"n":14,"p":"반응식","kw":"연소 반응","pt":5,"q":"삼황화인과 오황화인의 연소 시 공통적으로 생성되는 생성물의 화학식을 쓰시오.","a":"P2O5, SO2","h":"삼황화인(P4S3 + 8O2 → 2P2O5 + 3SO2)과 오황화인(2P2S5 + 15O2 → 2P2O5 + 10SO2)은 연소하면 모두 오산화인과 이산화황이 된다. 공통 생성물은 P2O5와 SO2다.","t":"kan","칸":[{"a":"P2O5","syn":["오산화인","오산화이인","오산화 인"]},{"a":"SO2","syn":["이산화황","아황산가스","이산화 황","아황산"]}],"순서무관":true},{"id":"2022-2-15","y":2022,"r":2,"n":15,"p":"계산","kw":"소요단위","pt":5,"q":"다음 제조소등의 소요단위를 계산하시오.\n가. 내화구조인 제조소 300m2\n나. 내화구조가 아닌 제조소 300m2\n다. 내화구조인 저장소 300m2","a":"가. 내화구조 제조소 300m2 ÷ 100m2 = 3\n나. 비내화구조 제조소 300m2 ÷ 50m2 = 6\n다. 내화구조 저장소 300m2 ÷ 150m2 = 2","h":"1소요단위의 면적은 제조소·취급소가 내화구조 100m2, 비내화구조 50m2이고, 저장소는 내화구조 150m2, 비내화구조 75m2다. 내화구조가 아니면 기준 면적이 절반이라 소요단위는 두 배가 된다. 위험물은 지정수량의 10배가 1소요단위다.","tp":"W06","t":"kan","칸":[{"a":"3","syn":["3단위","3소요단위"],"l":"가"},{"a":"6","syn":["6단위","6소요단위"],"l":"나"},{"a":"2","syn":["2단위","2소요단위"],"l":"다"}],"순서무관":false},{"id":"2022-2-16","y":2022,"r":2,"n":16,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"지정과산화물을 저장하는 옥내저장창고의 지붕에 관한 다음 내용을 보고 빈칸의 답을 채우시오.\n• 중도리 또는 서까래의 간격은 ( 가 )cm 이하로 할 것\n• 지붕의 아래쪽 면에는 한 변의 길이가 ( 나 )cm 이하의 환강(丸鋼)·경량형강(輕量形鋼) 등으로 된 강제(鋼製)의 격자를 설치할 것\n• 지붕의 아래쪽 면에 ( 다 )을 쳐서 불연재료의 도리·보 또는 서까래에 단단히 결합할 것\n• 두께 ( 라 )cm 이상, 너비 ( 마 )cm 이상의 목재로 만든 받침대를 설치할 것","a":"가. 30, 나. 45\n다. 철망, 라. 5\n마. 30","h":"지정과산화물 옥내저장창고의 지붕은 중도리·서까래 간격을 30cm 이하로 하고, 아래쪽 면에 한 변 45cm 이하의 강제 격자를 단다. 격자 아래에 철망을 쳐서 불연재료의 도리·보·서까래에 단단히 결합하며, 두께 5cm 이상, 너비 30cm 이상의 목재 받침대를 둔다.","t":"kan","칸":[{"a":"30","syn":["30cm","30cm 이하"],"l":"가"},{"a":"45","syn":["45cm","45cm 이하"],"l":"나"},{"a":"철망","syn":["철 망","와이어메시","금속망"],"l":"다"},{"a":"5","syn":["5cm","5cm 이상"],"l":"라"},{"a":"30","syn":["30cm","30cm 이상"],"l":"마"}],"순서무관":false},{"id":"2022-2-17","y":2022,"r":2,"n":17,"p":"물질·성상","kw":"소화약제","pt":5,"q":"불활성가스 소화약제에 대하여 다음 빈칸에 들어갈 말을 쓰시오.\n• IG-100 : ( 가 ) 100%\n• IG-541 : ( 나 ) 52%, ( 다 ) 40%, ( 라 ) 8%","a":"가. N2, 나. N2\n다. Ar, 라. CO2","h":"IG-100은 질소 100%, IG-55는 질소 50%와 아르곤 50%, IG-541은 질소 52%, 아르곤 40%, 이산화탄소 8%로 이뤄진다. 불활성가스 소화약제 성분은 N2, Ar, CO2 세 가지이고, 세 가지를 모두 쓰는 것은 IG-541뿐이다.","t":"kan","칸":[{"a":"N2","syn":["질소","n2","질소가스"],"l":"가"},{"a":"N2","syn":["질소","n2","질소가스"],"l":"나"},{"a":"Ar","syn":["아르곤","ar","AR","아르곤가스"],"l":"다"},{"a":"CO2","syn":["이산화탄소","co2","탄산가스"],"l":"라"}],"순서무관":false},{"id":"2022-2-18","y":2022,"r":2,"n":18,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"위험물안전관리법령상 옥내저장소의 위험물 저장 기준에 대하여 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n• 옥내저장소에서 동일 품명의 위험물이더라도 자연발화할 우려가 있는 위험물 또는 재해가 현저하게 증대할 우려가 있는 위험물을 다량 저장하는 경우에는 지정수량의 ( 가 )배 이하마다 ( 나 )m 이상의 간격을 두어 저장하여야 한다.\n• 기계에 의하여 하역하는 구조로 된 용기만을 겹쳐 쌓는 경우 높이는 ( 다 )m를 초과하지 아니하여야 한다.\n• 제4류 위험물 중 제3석유류, 제4석유류 및 동식물유류를 수납하는 용기만을 겹쳐 쌓는 경우 ( 라 )m를 초과하지 아니하여야 한다.\n• 그 밖의 경우에 있어서는 ( 마 )m를 초과하지 아니하여야 한다.","a":"가. 10, 나. 0.3\n다. 6, 라. 4\n마. 3","h":"자연발화나 재해 확대 우려가 있는 위험물을 옥내저장소에 다량 저장할 때는 지정수량 10배 이하마다 0.3m 이상 간격을 둔다. 용기를 겹쳐 쌓는 높이는 기계 하역 구조 용기만이면 6m, 제3석유류·제4석유류·동식물유류 용기만이면 4m, 그 밖에는 3m 이하다.","t":"kan","칸":[{"a":"10","syn":["10배"],"l":"가"},{"a":"0.3","syn":["0.3m","0.3미터","30cm"],"l":"나"},{"a":"6","syn":["6m","6미터"],"l":"다"},{"a":"4","syn":["4m","4미터"],"l":"라"},{"a":"3","syn":["3m","3미터"],"l":"마"}],"순서무관":false},{"id":"2022-2-19","y":2022,"r":2,"n":19,"p":"계산","kw":"탱크 용량","pt":5,"q":"이황화탄소를 제외한 제4류 위험물을 취급하는 제조소의 옥외저장탱크에 100만리터 1기, 50만리터 2기, 10만리터 3기가 있다. 이 중 50만리터 탱크 1기를 다른 방유제에 설치하고 나머지를 하나의 방유제에 설치할 경우 방유제 전체의 최소 용량의 합계(L)를 구하시오.","a":"방유제 1: 100만L 1기 + 50만L 1기 + 10만L 3기\n 최대 탱크 용량×0.5 + 나머지 합×0.1 = 1,000,000×0.5 + (500,000 + 300,000)×0.1 = 580,000L\n방유제 2: 50만L 1기\n 500,000×0.5 = 250,000L\n580,000 + 250,000 = 830,000L","h":"제조소 기준에서 방유제 용량은 탱크가 하나면 그 탱크 용량의 50%, 둘 이상이면 최대 탱크 용량의 50%에 나머지 탱크 합계의 10%를 더한 값이다. 방유제마다 따로 구해서 합친다. 옥외탱크저장소 기준은 최대 탱크 용량의 110%로 다르다.","tp":"W04","t":"word","syn":["830,000","830000L","830,000L","83만","83만L","830000리터","830,000리터"],"ka":"830000"},{"id":"2022-2-20","y":2022,"r":2,"n":20,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"위험물의 유별 및 지정수량에 대하여 빈칸에 알맞은 말을 쓰시오.\n제1류 위험물 - 산화성 고체\n 질산염류 300kg / 아이오딘산염류 ( 가 ) / 과망가니즈산염류 1,000kg / ( 나 ) 1,000kg\n제2류 위험물 - ( 다 )\n 철분 500kg / 금속분 500kg / 마그네슘 500kg / ( 라 ) 1,000kg\n제4류 위험물 - 인화성 액체\n 제2석유류 비수용성 ( 마 ) / 수용성 2,000L\n 제3석유류 비수용성 2,000L / 수용성 4,000L","a":"가. 300kg\n나. 다이크로뮴산염류\n다. 가연성 고체\n라. 인화성 고체\n마. 1,000L","h":"제1류의 아이오딘산염류는 300kg이고, 다이크로뮴산염류와 과망가니즈산염류는 1,000kg이다. 제2류는 가연성 고체로 인화성 고체의 지정수량은 1,000kg이다. 제2석유류는 비수용성 1,000L, 수용성 2,000L이고 제3석유류는 비수용성 2,000L, 수용성 4,000L로 수용성이 두 배다.","t":"kan","칸":[{"a":"300kg","syn":["300","300 kg"],"l":"가"},{"a":"다이크로뮴산염류","syn":["다이크로뮴산염","중크롬산염류","중크롬산염","다이크롬산염류","다이크로뮴산 염류","重크롬산염류","디크로뮴산염류","중크롬산 염류","다이크롬산염"],"l":"나"},{"a":"가연성 고체","syn":["가연성고체","가연성 고체류"],"l":"다"},{"a":"인화성 고체","syn":["인화성고체"],"l":"라"},{"a":"1000L","syn":["1000","1,000","1,000L","1000 L","1000리터"],"l":"마"}],"순서무관":false},{"id":"2022-4-01","y":2022,"r":4,"n":1,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"다음 소화설비 적응성 표에 소화가 가능한 경우 ○ 표시를 하시오.\n(소화설비의 구분 : 옥내소화전 또는 옥외소화전설비 / 물분무등소화설비 — 물분무소화설비 · 불활성가스소화설비 · 할로젠화합물소화설비)\n(대상물 구분 : 건축물·그 밖의 공작물 / 전기설비 / 제1류 위험물 — 알칼리금속 과산화물등 · 그 밖의 것 / 제2류 위험물 — 철분·금속분·마그네슘등 · 인화성고체 · 그 밖의 것 / 제3류 위험물 — 금수성물품 · 그 밖의 것 / 제4류 위험물 / 제5류 위험물 / 제6류 위험물)","a":"옥내소화전 또는 옥외소화전설비: 건축물○, 제1류 그 밖의 것○, 제2류 인화성고체○, 제2류 그 밖의 것○, 제3류 그 밖의 것○, 제5류○, 제6류○\n물분무소화설비: 건축물○, 전기설비○, 제1류 그 밖의 것○, 제2류 인화성고체○, 제2류 그 밖의 것○, 제3류 그 밖의 것○, 제4류○, 제5류○, 제6류○\n불활성가스소화설비: 전기설비○, 제2류 인화성고체○, 제4류○\n할로젠화합물소화설비: 전기설비○, 제2류 인화성고체○, 제4류○","h":"물분무소화설비는 주수 효과와 질식 효과를 함께 내서 적응 대상이 가장 넓다. 건축물·공작물은 주수소화가 되고, 전기설비는 포소화설비를 뺀 질식소화 설비가 쓰인다. 제4류 위험물에 스프링클러설비는 살수밀도에 따라 적응성이 갈려 △로 표시한다."},{"id":"2022-4-02","y":2022,"r":4,"n":2,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량이 34이며 표백작용과 살균작용이 있다. 농도 기준 따라 위험물이 되는 위험물로 운반용기 외부에 표시하여야 하는 주의사항은 가연물접촉주의인 이 위험물에 대하여 다음 물음에 답하시오.\n가. 명칭\n나. 화학식\n다. 열분해 시 생성되는 물질\n라. 주의사항 게시판 (단, 해당없으면 '해당없음'을 쓰시오)","a":"가. 과산화수소\n나. H2O2\n다. H2O, O2\n라. 해당없음","h":"분자량 34(1×2+16×2), 표백·살균 작용, 가연물접촉주의 표시는 제6류 위험물인 과산화수소(H2O2)다. 지정수량 300kg이고 농도 36중량% 이상인 것만 위험물이 된다. 분해하면 2H2O2 → 2H2O + O2로 물과 산소가 나오며, 제6류 위험물은 주의사항 게시판을 달지 않는다.","t":"kan","칸":[{"a":"과산화수소","syn":["H2O2","과산화 수소","hydrogen peroxide"],"l":"가"},{"a":"H2O2","syn":["과산화수소","h2o2"],"l":"나"},{"a":"H2O, O2","k":[["H2O","물","수증기"],["O2","산소"]],"l":"다","no":["H2O2"],"syn":["2H2O2→2H2O+O2"]},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"}],"순서무관":false},{"id":"2022-4-03","y":2022,"r":4,"n":3,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"크실렌의 이성질체 3가지에 대한 명칭과 구조식을 쓰시오.","a":"[명칭] o-크실렌, m-크실렌, p-크실렌\n[구조식] 벤젠고리에 CH3 두 개가 붙는 위치에 따라 1,2 자리(오르토), 1,3 자리(메타), 1,4 자리(파라)","h":"크실렌은 벤젠고리에 CH3 두 개가 붙은 C6H4(CH3)2이고, 붙는 자리에 따라 세 가지 이성질체가 있다. 오르토는 이웃한 자리(1,2), 메타는 한 칸 건너(1,3), 파라는 맞은편(1,4)이다.","t":"kan","칸":[{"a":"o-크실렌","syn":["오르토크실렌","오르쏘크실렌","ortho-xylene","o-자일렌","오르토자일렌","1,2-크실렌","1,2-다이메틸벤젠","오르토-크실렌","o크실렌","o-xylene"]},{"a":"m-크실렌","syn":["메타크실렌","meta-xylene","m-자일렌","메타자일렌","1,3-크실렌","1,3-다이메틸벤젠","메타-크실렌","m크실렌","m-xylene"]},{"a":"p-크실렌","syn":["파라크실렌","para-xylene","p-자일렌","파라자일렌","1,4-크실렌","1,4-다이메틸벤젠","파라-크실렌","p크실렌","p-xylene"]}],"순서무관":true,"nc":3},{"id":"2022-4-04","y":2022,"r":4,"n":4,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 [보기] 중 운반 시 방수성 및 차광성 덮개로 모두 덮어야 하는 위험물 품명을 고르시오.\n유기과산화물, 질산, 알칼리금속과산화물, 염소산염류","a":"알칼리금속과산화물","h":"방수성 덮개는 제1류 알칼리금속 과산화물, 제2류 철분·금속분·마그네슘, 제3류 금수성 물질에 쓰고, 차광성 덮개는 제1류, 제3류 자연발화성 물질, 제4류 특수인화물, 제5류, 제6류에 쓴다. 두 덮개를 모두 덮는 것은 제1류 알칼리금속 과산화물뿐이다. 유기과산화물(제5류), 질산(제6류), 염소산염류(제1류)는 차광성만 필요하다.","t":"word","syn":["알칼리금속의 과산화물","알칼리 금속 과산화물","알칼리금속 과산화물","알칼리금속의과산화물"],"ka":"알칼리금속과산화물"},{"id":"2022-4-05","y":2022,"r":4,"n":5,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 인화점이 낮은 것에서 높은 순서대로 나열하시오.\n글리세린, 클로로벤젠, 초산에틸, 이황화탄소","a":"이황화탄소, 초산에틸, 클로로벤젠, 글리세린","h":"제4류는 특수인화물, 제1석유류, 제2석유류, 제3석유류 순으로 인화점이 높아진다. 이황화탄소 -30℃(특수인화물), 초산에틸 -4℃(제1석유류), 클로로벤젠 27℃(제2석유류), 글리세린 160℃(제3석유류) 순이다. 같은 품명이면 비수용성이 수용성보다 인화점이 낮다.","t":"kan","칸":[{"a":"이황화탄소","syn":["CS2","이황화 탄소"],"l":"1"},{"a":"초산에틸","syn":["아세트산에틸","아세트산 에틸","초산 에틸","CH3COOC2H5","에틸아세테이트","아세트산에틸에스터"],"l":"2"},{"a":"클로로벤젠","syn":["염화벤젠","클로로 벤젠","클로르벤젠","C6H5Cl"],"l":"3"},{"a":"글리세린","syn":["글리세롤","C3H5(OH)3"],"l":"4"}],"순서무관":false},{"id":"2022-4-06","y":2022,"r":4,"n":6,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 설명 중 제4류 위험물 중 제2석유류에 대한 것으로 맞는 것을 모두 고르시오.\n① 등유와 경유는 대표적인 제2석유류이다.\n② 대부분이 수용성 물질이다.\n③ 비중이 1보다 크다.\n④ 산화제이다.\n⑤ 도료류 그 밖의 물품에 있어서는 가연성 액체량이 40중량% 이하이면서 인화점이 40℃ 이상인 동시에 연소점이 60℃ 이상인 것은 제외한다.","a":"①, ⑤","h":"제2석유류는 등유·경유 등으로 수용성과 비수용성이 모두 있고(②), 대부분 비중이 1보다 작으며(③), 환원제라 산화제가 아니다(④). 도료류에서 가연성 액체량 40중량% 이하, 인화점 40℃ 이상, 연소점 60℃ 이상이면 제외한다는 ⑤는 맞다. 산화제는 제1류, 제5류, 제6류의 특징이다.","t":"kan","칸":[{"a":"①","syn":["1","1번","(1)"]},{"a":"⑤","syn":["5","5번","(5)"]}],"순서무관":true},{"id":"2022-4-07","y":2022,"r":4,"n":7,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"트라이에틸알루미늄 228g이 물과 반응할 때의 식과 발생하는 가연성 가스의 부피는 표준상태에서 몇 L인지 쓰시오.\n가. 물과의 반응식\n나. 가연성 가스의 부피","a":"가. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n나. ① (C2H5)3Al 228g, 분자량 114, 표준상태(0℃, 1atm)\n② V = wRT/PM × (3C2H6/1(C2H5)3Al)\n③ (228×0.082×273)/(1×114) × 3 = 134.316\n④ 134.32L","h":"(C2H5)3Al의 분자량은 (12×2+1×5)×3+27 = 114라서 228g은 2mol이고, 1mol당 에테인이 3mol 나와 모두 6mol이 생긴다. 표준상태에서 6mol의 부피가 134.32L다. 발생하는 가연성 기체는 에테인이다.","tp":"W01","t":"kan","칸":[{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"가"},{"a":"134.32","e":1,"l":"나"}],"순서무관":false},{"id":"2022-4-08","y":2022,"r":4,"n":8,"p":"계산","kw":"소요단위","pt":5,"q":"위험물안전관리법령에서 정한 소화설비의 소요단위에 관한 내용이다. 다음 내용을 보고 물음에 답하시오.\n• 옥내탱크저장소\n• 내화구조\n• 연면적 1,500m2\n• 다이에틸에터 2,000L\n가. 옥내탱크저장소의 소요단위\n나. 위험물의 소요단위","a":"가. 내화구조 저장소 1소요단위 = 150m2 → 1,500m2 ÷ 150m2 = 10소요단위\n나. 다이에틸에터 지정수량 50L, 1소요단위 = 50L×10 = 500L → 2,000L ÷ 500L = 4소요단위","h":"저장소는 내화구조면 150m2가 1소요단위이고, 위험물은 지정수량의 10배가 1소요단위다. 다이에틸에터는 특수인화물로 지정수량이 50L라 500L마다 1소요단위가 된다.","tp":"W06","t":"kan","칸":[{"a":"10","syn":["10단위","10소요단위"],"l":"가"},{"a":"4","syn":["4단위","4소요단위"],"l":"나"}],"순서무관":false},{"id":"2022-4-09","y":2022,"r":4,"n":9,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 중 연소가 가능한 물질을 골라 완전연소 반응식을 쓰시오.\n과산화수소, 질산칼륨, 염소산암모늄, 알루미늄분, 다이에틸에터\n가. 연소가 가능한 물질을 모두 쓰시오.\n나. 가. 물질의 완전연소반응식을 쓰시오.","a":"가. 알루미늄분, 다이에틸에터\n나. 4Al + 3O2 → 2Al2O3\n C2H5OC2H5 + 6O2 → 4CO2 + 5H2O","h":"과산화수소(제6류), 질산칼륨·염소산암모늄(제1류)은 스스로 타지 않는 산화성 물질이고, 알루미늄분(제2류 금속분)과 다이에틸에터(제4류 특수인화물)는 탄다. 알루미늄은 산화알루미늄이 되고, 다이에틸에터는 CO2와 H2O가 된다.","t":"kan","칸":[{"a":"알루미늄분","syn":["알루미늄","Al","알루미늄 분"]},{"a":"다이에틸에터","syn":["디에틸에터","다이에틸에테르","디에틸에테르","에터","에테르","C2H5OC2H5","에틸에터","에틸에테르","(C2H5)2O"]},{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3","2Al+3/2O2→Al2O3"]},{"a":"C2H5OC2H5+6O2→4CO2+5H2O","syn":["C2H5OC2H5+6O2->4CO2+5H2O","C2H5OC2H5+6O2=4CO2+5H2O","(C2H5)2O+6O2→4CO2+5H2O","(C2H5)2O+6O2->4CO2+5H2O","C4H10O+6O2→4CO2+5H2O","C4H10O+6O2->4CO2+5H2O","C2H5OC2H5+6O2→5H2O+4CO2"]}],"순서무관":true},{"id":"2022-4-10","y":2022,"r":4,"n":10,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량이 227이며 폭약의 원료이며, 햇빛에 다갈색으로 변하고, 물에 안 녹고 벤젠과 아세톤에 녹는 물질에 대하여 답하시오.\n가. 화학식\n나. 지정수량\n다. 사용원료 중심으로 제조방법","a":"가. C6H2(NO2)3CH3\n나. 10kg\n다. 톨루엔에 질산과 황산을 반응시켜 나이트로화한다.","h":"분자량 227이고 폭약 원료이며 햇빛에 다갈색으로 변하는 물질은 트라이나이트로톨루엔이다. 제5류 나이트로화합물(제1종)로 지정수량 10kg이다. 톨루엔에 질산 3분자를 황산 촉매로 반응시켜 만들고 물 3분자가 나온다. 트라이나이트로페놀은 분자량이 229라 구분된다.","t":"kan","칸":[{"a":"C6H2(NO2)3CH3","syn":["C6H2CH3(NO2)3","CH3C6H2(NO2)3","C7H5N3O6","트라이나이트로톨루엔","트리니트로톨루엔","TNT","C6H2(CH3)(NO2)3"],"l":"가"},{"a":"10","syn":["10kg","10 kg","10킬로그램"],"l":"나"},{"a":"톨루엔에 질산과 황산을 반응시켜 나이트로화한다","k":[["톨루엔","toluene"],["질산","황산","혼산","나이트로","니트로"]],"l":"다"}],"순서무관":false},{"id":"2022-4-11","y":2022,"r":4,"n":11,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물안전관리법령에 따른 위험물 저장·취급 기준에 따라 유별을 달리하는 위험물은 동일 장소에 함께 저장할 수 없지만, 위험물안전관리법에 의해 동일 장소에 저장할 수 있는 위험물에 대하여 다음 보기의 빈칸을 알맞게 채우시오 (단, 위험물과의 거리는 1m 이상 간격을 둔다).\n가. ( ) 위험물은 불티·불꽃·고온체와의 접근이나 과열·충격 또는 마찰을 피하여야 한다.\n나. ( ) 위험물은 가연물과의 접촉·혼합이나 분해를 촉진하는 물품과의 접근 또는 과열을 피하여야 한다.\n다. ( ) 위험물은 불티·불꽃·고온체와의 접근 또는 과열을 피하고, 함부로 증기를 발생시키지 아니하여야 한다.\n라. 제1류 위험물과 ( ) 위험물\n마. 제2류 위험물 중 인화성고체와 ( ) 위험물","a":"가. 제5류\n나. 제6류\n다. 제4류\n라. 제6류\n마. 제4류","h":"유별이 달라도 1m 이상 간격을 두면 한 저장소에 함께 저장할 수 있는 조합은 제1류와 제5류(알칼리금속 과산화물 제외), 제1류와 제6류, 제2류 인화성고체와 제4류 등이다. 제5류는 불티·불꽃·고온체·과열·충격·마찰을, 제6류는 가연물 접촉·분해 촉진 물품 접근·과열을, 제4류는 불티·불꽃·고온체·과열을 피하고 함부로 증기를 발생시키지 않는다.","t":"kan","칸":[{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"가"},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"나"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"다"},{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"라"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"마"}],"순서무관":false},{"id":"2022-4-12","y":2022,"r":4,"n":12,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"금속 니켈의 촉매하에서 300℃로 가열 시 수소첨가 반응이 일어나서 시클로헥산이 생성되고, 분자량 78인 물질에 대해 다음 물음에 답을 쓰시오.\n가. 명칭\n나. 구조식\n다. 위험물안전카드의 휴대여부를 쓰시오.\n라. 장거리 운송 시에 운전자를 2명 이상으로 하여야 하는지 쓰시오 (단, 보기의 조건으로 알 수 없으면 '해당없음'을 쓰시오).","a":"가. 벤젠\n나. 정육각형 고리에 C가 6개, 각 C에 H가 하나씩 붙은 벤젠 구조식\n다. 휴대하여야 한다.\n라. 2명 이상으로 하지 않아도 된다.","h":"벤젠(C6H6)은 분자량이 78이고 수소 3분자가 붙으면 사이클로헥산(C6H12)이 된다. 제4류 중 제1석유류와 특수인화물을 운송할 때는 위험물안전카드를 휴대한다. 특수인화물을 뺀 제4류는 장거리 운송에서도 운전자 1명이 가능하다.","t":"kan","칸":[{"a":"벤젠","syn":["C6H6","benzene","벤졸","벤젠(C6H6)"],"l":"가"},{"a":"휴대하여야 한다","k":[["휴대"],["하여야","해야","한다"]],"l":"다"},{"a":"2명 이상으로 하지 않아도 된다","k":[["않아도","아니","불필요","필요없","필요 없","안 해도","안해도","없어도","하지 않","않는다"]],"l":"라"}],"순서무관":false},{"id":"2022-4-13","y":2022,"r":4,"n":13,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"금속나트륨에 대한 답을 쓰시오.\n가. 에탄올과의 반응식\n나. 반응식 발생하는 가스의 명칭\n다. 나. 물질의 연소범위\n라. 나. 물질의 위험도","a":"가. 2Na + 2C2H5OH → 2C2H5ONa + H2\n나. 수소\n다. 4~75%\n라. 위험도 = (75 − 4)/4 = 17.75","h":"나트륨은 에탄올과 반응해 나트륨에틸라이드(C2H5ONa)와 수소를 낸다. 수소의 연소범위는 4~75%이고, 위험도는 (상한 − 하한)/하한이라 (75−4)/4 = 17.75다.","t":"kan","칸":[{"a":"2Na+2C2H5OH→2C2H5ONa+H2","syn":["2Na+2C2H5OH->2C2H5ONa+H2","2Na+2C2H5OH=2C2H5ONa+H2","2Na+2C2H5OH→2C2H5ONa+H2↑","Na+C2H5OH→C2H5ONa+1/2H2"],"l":"가"},{"a":"수소","syn":["H2","수소가스","hydrogen"],"l":"나"},{"a":"4~75%","syn":["4-75","4~75","4∼75","4-75%","4~75 %","4% ~ 75%","4%~75%","4에서 75","4부터 75","4 ~ 75%","4 - 75%"],"l":"다"},{"a":"17.75","e":0.05,"l":"라"}],"순서무관":false},{"id":"2022-4-14","y":2022,"r":4,"n":14,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음 탱크의 최대 용량(L)을 구하시오.\n(가로형 원통형 탱크 : 반지름 2m, 몸통 5m, 양쪽 경판 1.5m씩)","a":"① 반지름 r = 2m, 몸통 l = 5m, 경판 l1 = l2 = 1.5m\n② 최대 용량은 공간용적이 가장 작은 5%일 때: πr²(l + (l1+l2)/3) × (1 − 0.05)\n③ π×2²×(5 + (1.5+1.5)/3)×0.95 = 71.628m3\n④ 71.628m3 = 71,628.31L","h":"탱크 용량은 내용적에서 공간용적을 뺀 값이다. 공간용적은 내용적의 5% 이상 10% 이하이므로 5%일 때 용량이 최대가 된다. m3를 L로 바꿀 때 ×1,000을 마지막에 곱한다.","tp":"W04","t":"calc","e":100,"ka":"71628.31"},{"id":"2022-4-15","y":2022,"r":4,"n":15,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"질산암모늄이 열분해되는 경우 다음 물음에 답하시오.\n가. 질산암모늄이 분해되어 N2, O2, H2O를 발생하는 분해반응식을 쓰시오.\n나. 질산암모늄 1몰이 0.9기압, 300℃에서 분해될 때 생성되는 H2O의 부피(L)를 구하시오.","a":"가. 2NH4NO3 → 2N2 + O2 + 4H2O\n나. ① NH4NO3 1mol, 0.9atm, 300℃ = 573K\n② V = nRT/P × (4H2O/2NH4NO3)\n③ (1×0.082×573)/0.9 × 2 = 104.413\n④ 104.41L","h":"질산암모늄 2몰이 분해되면 수증기가 4몰 나오므로 1몰에서는 2몰이 생긴다. 이상기체식 V = nRT/P에 T = 300+273 = 573K, P = 0.9atm을 넣고 H2O 몰수 2를 곱해 구한다.","tp":"W01","t":"kan","칸":[{"a":"2NH4NO3→2N2+O2+4H2O","syn":["2NH4NO3->2N2+O2+4H2O","2NH4NO3=2N2+O2+4H2O","NH4NO3→N2+1/2O2+2H2O","NH4NO3->N2+1/2O2+2H2O"],"l":"가"},{"a":"104.41","e":1.5,"l":"나"}],"순서무관":false},{"id":"2022-4-16","y":2022,"r":4,"n":16,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"제조소와의 안전거리 기준에 따라 다음 대상물과의 안전거리는 몇 m 이상으로 하여야 하는지 알맞은 답을 쓰시오.\n가. 제조소 외벽과 주거용 주택 안전거리\n나. 제조소 외벽과 병원 안전거리\n다. 제조소 외벽과 지정문화유산 및 천연기념물 안전거리\n라. 제조소 외벽과 가스저장시설 안전거리\n마. 제조소 외벽과 7,000V 초과 35,000V 이하의 특고압가공전선 안전거리","a":"가. 10m, 나. 30m\n다. 50m, 라. 20m\n마. 3m","h":"제조소 안전거리는 주택 10m, 학교·병원·극장 등 30m, 지정문화유산·천연기념물 50m, 가스 저장·취급시설 20m 이상이다. 특고압가공전선은 7,000V 초과 35,000V 이하가 3m, 35,000V 초과가 5m 이상이다.","t":"kan","칸":[{"a":"10","syn":["10m","10m 이상","10미터"],"l":"가"},{"a":"30","syn":["30m","30m 이상","30미터"],"l":"나"},{"a":"50","syn":["50m","50m 이상","50미터"],"l":"다"},{"a":"20","syn":["20m","20m 이상","20미터"],"l":"라"},{"a":"3","syn":["3m","3m 이상","3미터"],"l":"마"}],"순서무관":false},{"id":"2022-4-17","y":2022,"r":4,"n":17,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"칼륨과 다음 물질의 화학반응식을 쓰시오 (단, 반응하지 않으면 '해당없음'이라 쓰시오).\n가. 물\n나. 경유\n다. 이산화탄소","a":"가. 2K + 2H2O → 2KOH + H2\n나. 해당없음\n다. 4K + 3CO2 → 2K2CO3 + C","h":"칼륨은 물과 반응해 수산화칼륨과 수소를 내고, 이산화탄소와는 탄산칼륨과 탄소가 생긴다. 경유와는 반응하지 않아 칼륨과 나트륨은 경유·등유·파라핀 속에 보관한다.","t":"kan","칸":[{"a":"2K+2H2O→2KOH+H2","syn":["2K+2H2O->2KOH+H2","2K+2H2O=2KOH+H2","K+H2O→KOH+1/2H2"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"나"},{"a":"4K+3CO2→2K2CO3+C","syn":["4K+3CO2->2K2CO3+C","4K+3CO2=2K2CO3+C"],"l":"다"}],"순서무관":false},{"id":"2022-4-18","y":2022,"r":4,"n":18,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 물질의 시성식을 쓰시오.\n가. 아세톤\n나. 피크린산\n다. 아닐린\n라. 포름산\n마. 아세트에틸","a":"가. CH3COCH3, 나. C6H2(NO2)3OH\n다. C6H5NH2, 라. HCOOH\n마. CH3COOC2H5","h":"아세톤은 제1석유류 수용성(400L), 피크린산은 제5류 나이트로화합물(10kg), 아닐린은 제3석유류 비수용성(2,000L), 포름산은 제2석유류 수용성(2,000L), 아세트산에틸은 제1석유류 비수용성(200L)이다. 문제의 아세트에틸은 아세트산에틸을 가리킨다.","t":"kan","칸":[{"a":"CH3COCH3","syn":["C3H6O","CH3-CO-CH3","(CH3)2CO"],"l":"가"},{"a":"C6H2(NO2)3OH","syn":["C6H2OH(NO2)3","HOC6H2(NO2)3","C6H3N3O7","C6H2(OH)(NO2)3","OHC6H2(NO2)3"],"l":"나"},{"a":"C6H5NH2","syn":["C6H7N","C6H5-NH2"],"l":"다"},{"a":"HCOOH","syn":["CH2O2","H-COOH"],"l":"라"},{"a":"CH3COOC2H5","syn":["C4H8O2","CH3COOCH2CH3","CH3CO2C2H5","C2H5OCOCH3"],"l":"마"}],"순서무관":false},{"id":"2022-4-19","y":2022,"r":4,"n":19,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에 따른 안전교육의 과정, 기간과 그 밖의 교육의 실시에 관한 사항이다. 빈칸에 들어갈 말을 다음 [보기]에 골라서 쓰시오.\n[보기] 안전관리자, 위험물운반자, 위험물운송자, 탱크시험자\n(강습교육 : ( 가 )가 되려는 사람 24시간 / ( 나 )가 되려는 사람 8시간 / ( 다 )가 되려는 사람 16시간)\n(실무교육 : ( 가 ) 8시간 / ( 나 ) 4시간 / ( 다 ) 8시간 / ( 라 )의 기술인력 8시간)","a":"가. 안전관리자\n나. 위험물운반자\n다. 위험물운송자\n라. 탱크시험자","h":"강습교육은 안전관리자 24시간, 위험물운반자 8시간, 위험물운송자 16시간이다. 실무교육은 안전관리자 8시간, 운반자 4시간, 운송자 8시간, 탱크시험자의 기술인력 8시간이다. 안전관리자와 탱크시험자 기술인력은 처음 6개월 이내 이후 2년마다, 운반자와 운송자는 3년마다 받는다.","t":"kan","칸":[{"a":"안전관리자","syn":["위험물안전관리자","위험물 안전관리자"],"l":"가"},{"a":"위험물운반자","syn":["위험물 운반자","운반자"],"l":"나"},{"a":"위험물운송자","syn":["위험물 운송자","운송자"],"l":"다"},{"a":"탱크시험자","syn":["탱크 시험자"],"l":"라"}],"순서무관":false},{"id":"2022-4-20","y":2022,"r":4,"n":20,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"다음 위험물 제조소의 방화상 유효한 담의 높이(h)를 몇 m 이상으로 하여야 하는지 쓰시오.\n[조건]\n• D : 제조소등과 인근 건축물 또는 공작물과의 거리 10m\n• H : 인근 건축물 또는 공작물의 높이 40m\n• α : 제조소등의 외벽의 높이 30m\n• d : 제조소등과 방화상 유효한 담과의 거리 5m\n• h : 방화상 유효한 담의 높이\n• p : 상수 0.15\n[계산과정]\n[답]","a":"[계산과정]\n① D = 10m, H = 40m, α = 30m, d = 5m, p = 0.15\n② pD² + α 를 구해 H와 비교\n③ 0.15×10² + 30 = 45m ≥ H(40m)\n④ H ≤ pD² + α 이므로 h = 2\n[답] 2m","h":"H ≤ pD²+α 이면 담 높이는 2m이고, H > pD²+α 이면 h = H − p(D²−d²)다. 여기서는 pD²+α = 45m로 H = 40m보다 크므로 2m다. 먼저 pD²+α와 H를 비교해 쓸 식을 정한다.","t":"calc","ka":"2"},{"id":"2023-1-01","y":2023,"r":1,"n":1,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"섭씨 25도, 1기압에서 리튬 2몰이 물과 반응하였을 때, 다음 물음에 답하시오.\n가. 화학반응식\n나. 발생하는 가연성 기체의 부피(L)\n[계산과정]\n[답]","a":"가. 2Li + 2H2O → 2LiOH + H2\n나. [계산과정]\n① Li 2mol, 25℃ = 298K, 1atm\n② V = nRT/P × (1H2/2Li)\n③ (2×0.082×298)/1 × 1/2 = 24.436\n[답] 24.44L","h":"리튬 2몰이 반응하면 수소 1몰이 나오므로 수소 1몰의 부피를 구하면 된다. 25℃는 298K이고 R = 0.082atm·L/mol·K를 쓴다. 리튬은 제3류 알칼리금속이다.","tp":"W01","t":"kan","칸":[{"a":"2Li+2H2O→2LiOH+H2","syn":["2Li+2H2O->2LiOH+H2","2Li+2H2O=2LiOH+H2","Li+H2O→LiOH+1/2H2"],"l":"가"},{"a":"24.44","e":0.1,"l":"나"}],"순서무관":false},{"id":"2023-1-02","y":2023,"r":1,"n":2,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"[보기] 중 지정수량이 400L인 제4류 위험물과 물기엄금, 화기엄금을 동시에 가지는 물질을 골라 둘의 화학반응식을 적으시오 (단, 해당 없으면 해당없음으로 쓰시오).\n에틸알코올, 칼륨, 질산메틸, 톨루엔, 과산화나트륨","a":"칼륨과 에틸알코올의 반응\n2K + 2C2H5OH → 2C2H5OK + H2","h":"지정수량 400L인 제4류 위험물은 알코올류인 에틸알코올이다. 물기엄금(금수성)과 화기엄금(자연발화성)을 함께 표시하는 것은 제3류의 칼륨이다. 칼륨이 에탄올과 반응하면 칼륨에틸라이드(C2H5OK)와 수소가 나온다.","t":"kan","칸":[{"a":"2K+2C2H5OH→2C2H5OK+H2","syn":["2K+2C2H5OH->2C2H5OK+H2","2K+2C2H5OH=2C2H5OK+H2","K+C2H5OH→C2H5OK+1/2H2","2C2H5OH+2K→2C2H5OK+H2","2C2H5OH+2K->2C2H5OK+H2"]}],"순서무관":false},{"id":"2023-1-03","y":2023,"r":1,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"과산화수소에 대하여 다음 물음에 답하시오.\n가. 분해반응식\n나. 농도가 높을수록 위험하기 때문에 폭발을 방지하기 위해 사용하는 안정제의 명칭을 한 가지 쓰시오.\n다. 옥외저장소 저장 가능 여부","a":"가. 2H2O2 → 2H2O + O2\n나. 인산 또는 요산\n다. 저장 가능","h":"과산화수소는 분해하면 물과 산소가 나오며, 농도가 높을수록 위험해서 인산이나 요산을 안정제로 넣는다. 제6류 위험물은 옥외저장소에 저장할 수 있는 품목이라 저장 가능하다.","t":"kan","칸":[{"a":"2H2O2→2H2O+O2","syn":["2H2O2->2H2O+O2","2H2O2=2H2O+O2","H2O2→H2O+1/2O2","H2O2->H2O+1/2O2"],"l":"가"},{"a":"인산","syn":["요산","H3PO4","인산(H3PO4)","phosphoric acid","uric acid","인산 또는 요산","C5H4N4O3"],"l":"나"},{"a":"저장 가능","syn":["가능","저장가능","저장할 수 있다","가능하다","저장 가능하다","저장할수있다","저장할 수 있음","O","예","저장 할 수 있다"],"l":"다"}],"순서무관":false},{"id":"2023-1-04","y":2023,"r":1,"n":4,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"인화알루미늄 580g이 물과 반응하였다. 다음 물음에 답하시오.\n가. 화학반응식\n나. 발생하는 기체의 부피(L)\n[계산과정]\n[답]","a":"가. AlP + 3H2O → Al(OH)3 + PH3\n나. [계산과정]\n① AlP 580g, 분자량 27+31 = 58, 표준상태(0℃, 1atm)\n② V = wRT/PM × (1PH3/1AlP)\n③ (580×0.082×273)/(1×58) = 223.86\n[답] 223.86L","h":"인화알루미늄의 분자량은 58이라 580g은 10mol이고, 1mol당 포스핀(PH3) 1mol이 나온다. 표준상태에서 10mol의 부피가 223.86L다.","tp":"W01","t":"kan","칸":[{"a":"AlP+3H2O→Al(OH)3+PH3","syn":["AlP+3H2O->Al(OH)3+PH3","AlP+3H2O=Al(OH)3+PH3","AlP+3H2O→PH3+Al(OH)3","AlP+3H2O->PH3+Al(OH)3"],"l":"가"},{"a":"223.86","e":1,"l":"나"}],"순서무관":false},{"id":"2023-1-05","y":2023,"r":1,"n":5,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"다음은 주유취급소의 위치·구조 및 설비의 기준이다. 다음 중 각 특례에 해당되는 기호를 모두 쓰시오.\n[위치·구조 및 설비의 기준]\n① 주유공지를 확보하지 않아도 된다.\n② 지하저장탱크에 직접주유하는 경우 탱크 용량에 제한을 두지 않아도 된다.\n③ 고정주유설비 또는 고정급유설비의 주유관 길이에 제한을 두지 않아도 된다.\n④ 담 또는 벽을 설치하지 않아도 된다.\n⑤ 캐노피를 설치하지 않아도 된다.\n가. 항공기 주유취급소\n나. 자가용 주유취급소의 특례\n다. 선박 주유취급소의 특례","a":"가. ①, ②, ③, ④, ⑤\n나. ①\n다. ①, ②, ③, ④","h":"주유취급소 특례 중 항공기용이 가장 넓어 ①~⑤를 모두 적용하지 않는다. 자가용은 주유공지(①)만 적용하지 않고, 선박용은 ①~④를 적용하지 않지만 캐노피 규정(⑤)은 그대로 적용한다. 각 번호는 별표 13의 I 제1호, III 제1호, IV 제3호, VII, VIII에 해당한다.","t":"kan","칸":[{"a":"①, ②, ③, ④, ⑤","k":[["①","1"],["②","2"],["③","3"],["④","4"],["⑤","5"]],"l":"가"},{"a":"①","syn":["1","1번","(1)"],"l":"나"},{"a":"①, ②, ③, ④","k":[["①","1"],["②","2"],["③","3"],["④","4"]],"l":"다","no":["⑤","5"]}],"순서무관":false},{"id":"2023-1-06","y":2023,"r":1,"n":6,"p":"계산","kw":"소요단위","pt":5,"q":"위험물안전관리법령에서 정한 소화설비의 소요단위에 관한 내용이다. 다음 내용을 보고 물음에 답하시오.\n• 내화구조인 옥내저장소\n• 연면적 150m2\n• 에탄올 1,000L, 등유 1,500L, 동식물유류 20,000L, 특수인화물 500L\n가. 옥내저장소의 연면적 기준 소요단위\n나. 위험물 기준의 소요단위","a":"가. 내화구조 저장소 150m2 ÷ 150m2 = 1소요단위\n나. 에탄올 1,000/(400×10) = 0.25\n 등유 1,500/(1,000×10) = 0.15\n 동식물유류 20,000/(10,000×10) = 0.2\n 특수인화물 500/(50×10) = 1\n 합계 1.6소요단위","h":"저장소는 내화구조면 150m2가 1소요단위다. 위험물은 품명마다 (저장량 ÷ 지정수량×10)을 구해 더하고, 법령에 올림 규정이 없으니 합계를 그대로 쓴다. 지정수량은 알코올류 400L, 등유(제2석유류 비수용성) 1,000L, 동식물유류 10,000L, 특수인화물 50L다.","tp":"W06","t":"kan","칸":[{"a":"1","e":0.01,"l":"가"},{"a":"1.6","e":0.05,"l":"나"}],"순서무관":false},{"id":"2023-1-07","y":2023,"r":1,"n":7,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제4류 위험물 중 알코올류에 관한 설명 중 틀린 것을 고르고 바르게 고치시오.\n① 1분자를 구성하는 탄소원자의 수가 1개부터 3개까지인 포화1가 알코올(변성알코올을 포함한다)을 말한다.\n② 가연성액체량이 60vol% 미만이고 인화점 및 연소점이 에틸알코올 60vol% 수용액의 인화점 및 연소점을 초과하는 것은 제외한다.\n③ 지정수량 400L이다.\n④ 위험등급은 II이다.\n⑤ 옥내저장소에 저장 시 바닥면적 1,000m2 이하이다.","a":"②\nvol% → 중량퍼센트(wt%)로 고친다.","h":"알코올류는 탄소 1~3개의 포화1가 알코올로 지정수량 400L, 위험등급 II다. 수용액과 가연성액체량 기준은 모두 중량퍼센트(60중량% 미만)이므로 ②의 vol%가 틀렸다. 옥내저장소는 위험등급 I과 제4류의 위험등급 I·II를 저장하면 바닥면적 1,000m2 이하다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"],"l":"틀린 것"},{"a":"vol%를 중량퍼센트로 고친다","k":[["중량","wt","질량"]],"l":"고치기"}],"순서무관":false},{"id":"2023-1-08","y":2023,"r":1,"n":8,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"제조소등에 설치하는 배출설비에 대하여 다음 물음에 답하시오.\n가. 배출장소의 용적이 300m3일 경우 국소방출방식의 배출설비 1시간당 배출능력을 구하시오.\n나. 바닥면적이 100m2인 경우 전역방출방식의 배출설비 1m3당 배출능력을 구하시오.","a":"가. 국소방식: 배출장소 용적의 20배 이상\n 300m3×20 = 6,000m3/h → 6,000m3\n나. 전역방식: 바닥면적 1m2당 18m3 이상\n 100m2×18m3/m2 = 1,800m3/h → 1,800m3","h":"배출설비의 배출능력은 1시간당 배출장소 용적의 20배 이상이다. 전역방식만 바닥면적 1m2당 18m3 이상으로 할 수 있다. 가는 용적에 20, 나는 바닥면적에 18을 곱한다.","t":"kan","칸":[{"a":"6000","syn":["6,000","6000m3","6,000m3","6000㎥","6,000㎥","6000m3/h","6,000m3/h"],"l":"가"},{"a":"1800","syn":["1,800","1800m3","1,800m3","1800㎥","1,800㎥","1800m3/h","1,800m3/h","18"],"l":"나"}],"순서무관":false},{"id":"2023-1-09","y":2023,"r":1,"n":9,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령상 동식물유류에 관한 물음에 답을 쓰시오.\n가. 아이오딘값의 정의\n나. 동식물유류 아이오딘값에 따른 분류와 범위","a":"가. 유지 100g을 경화시키는 데 필요한 아이오딘의 g수\n나. 건성유: 130 이상\n 반건성유: 100 이상 130 미만\n 불건성유: 100 미만","h":"아이오딘값은 유지 100g에 흡수되는 아이오딘의 g수로, 클수록 불포화도가 커서 공기 중에서 잘 굳는다. 130 이상이 건성유, 100 이상 130 미만이 반건성유, 100 미만이 불건성유다.","t":"kan","칸":[{"a":"유지 100g에 흡수되는 아이오딘의 g수","k":[["100"],["아이오딘","요오드","옥소"]],"l":"가"},{"a":"130 이상","syn":["130이상","130","130이상이다"],"l":"건성유"},{"a":"100 이상 130 미만","k":[["100"],["130"]],"l":"반건성유"},{"a":"100 미만","syn":["100미만","100","100이하"],"l":"불건성유"}],"순서무관":false},{"id":"2023-1-10","y":2023,"r":1,"n":10,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제5류 위험물 중 트라이나이트로톨루엔과 관련하여 다음 물음에 답하시오.\n가. 구조식\n나. 재료를 포함한 제조방법","a":"가. 벤젠고리에 CH3 하나, NO2 세 개가 2,4,6 자리에 붙은 구조\n나. 톨루엔을 진한 질산과 진한 황산의 혼산으로 나이트로화 반응시켜 제조","h":"트라이나이트로톨루엔은 제5류 나이트로화합물(제1종)로 지정수량 10kg이다. 톨루엔(C6H5CH3)에 진한 질산 3분자를 황산 촉매로 반응시켜 만들고, 같은 방식으로 페놀은 트라이나이트로페놀, 글리세린은 나이트로글리세린, 에틸렌글리콜은 나이트로글리콜이 된다.","t":"kan","칸":[{"a":"톨루엔을 진한 질산과 진한 황산의 혼산으로 나이트로화 반응시켜 제조","k":[["톨루엔","toluene"],["질산","황산","혼산","나이트로","니트로"]],"l":"나"}],"순서무관":false},{"id":"2023-1-11","y":2023,"r":1,"n":11,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"옥외저장소에서 위험물을 수납한 용기를 저장하는 경우이다. 최대 저장 높이에 대하여 답하시오.\n가. 선반에 저장하는 경우\n나. 기계에 의하여 하역하는 구조로 된 용기의 경우\n다. 중유를 저장하는 경우","a":"가. 6m, 나. 6m, 다. 4m","h":"옥외저장소에서 용기를 선반에 저장하면 6m, 기계로 하역하는 구조의 용기를 겹쳐 쌓으면 6m 이하다. 제4류 중 제3석유류·제4석유류·동식물유류 용기는 4m, 그 밖에는 3m 이하이며, 중유는 제3석유류라 4m다.","t":"kan","칸":[{"a":"6","syn":["6m","6미터"],"l":"가"},{"a":"6","syn":["6m","6미터"],"l":"나"},{"a":"4","syn":["4m","4미터"],"l":"다"}],"순서무관":false},{"id":"2023-1-12","y":2023,"r":1,"n":12,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 위험물의 연소 반응식을 쓰시오.\n가. 메틸에틸케톤\n나. 메틸알코올\n다. 아세트산","a":"가. 2CH3COC2H5 + 11O2 → 8CO2 + 8H2O\n나. 2CH3OH + 3O2 → 2CO2 + 4H2O\n다. CH3COOH + 2O2 → 2CO2 + 2H2O","h":"세 물질 모두 완전연소하면 CO2와 H2O가 생긴다. 메틸에틸케톤은 산소 5.5분자, 메탄올은 1.5분자가 필요해 전체에 2를 곱해 정수로 맞춘다. 아세트산은 산소 2분자로 처음부터 정수다.","t":"kan","칸":[{"a":"2CH3COC2H5+11O2→8CO2+8H2O","syn":["2CH3COC2H5+11O2->8CO2+8H2O","2CH3COC2H5+11O2=8CO2+8H2O","CH3COC2H5+11/2O2→4CO2+4H2O","CH3COC2H5+11/2O2->4CO2+4H2O","2C4H8O+11O2→8CO2+8H2O","2C4H8O+11O2->8CO2+8H2O","C4H8O+11/2O2→4CO2+4H2O","2CH3COCH2CH3+11O2→8CO2+8H2O","2CH3COCH2CH3+11O2->8CO2+8H2O","CH3COCH2CH3+11/2O2→4CO2+4H2O","2CH3COC2H5+11O2→8H2O+8CO2"],"l":"가"},{"a":"2CH3OH+3O2→2CO2+4H2O","syn":["2CH3OH+3O2->2CO2+4H2O","2CH3OH+3O2=2CO2+4H2O","CH3OH+3/2O2→CO2+2H2O","CH3OH+3/2O2->CO2+2H2O","CH3OH+1.5O2→CO2+2H2O","2CH3OH+3O2→4H2O+2CO2"],"l":"나"},{"a":"CH3COOH+2O2→2CO2+2H2O","syn":["CH3COOH+2O2->2CO2+2H2O","CH3COOH+2O2=2CO2+2H2O","CH3COOH+2O2→2H2O+2CO2","CH3COOH+2O2->2H2O+2CO2"],"l":"다"}],"순서무관":false},{"id":"2023-1-13","y":2023,"r":1,"n":13,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 표에 황화인에 대한 화학식과 연소 생성물을 쓰시오.\n(명칭 / 화학식 / 연소생성물)\n삼황화인 ① / 오황화인 ② / 칠황화인 ③ — 연소생성물 ④ ⑤\n가. ①~⑤에 들어갈 알맞은 화학식을 쓰시오.\n나. 1몰 연소할 때 7.5몰의 산소가 필요한 황화인을 골라 연소반응식을 쓰시오.\n다. 황화인을 운반할 때 운반용기 외부에 표시하여야 하는 주의사항을 쓰시오.","a":"가. ① P4S3, ② P2S5, ③ P4S7, ④ P2O5, ⑤ SO2\n나. 2P2S5 + 15O2 → 2P2O5 + 10SO2\n다. 화기주의","h":"삼황화인(P4S3), 오황화인(P2S5), 칠황화인(P4S7)은 연소하면 모두 오산화인과 이산화황이 된다. 오황화인은 2몰에 산소 15몰이 필요해 1몰당 7.5몰이므로 나의 식은 오황화인이다. 황화인은 제2류 중 '그 외'에 해당해 운반용기에 화기주의를 표시한다.","t":"kan","칸":[{"a":"P4S3","syn":["삼황화인","삼황화사인"],"l":"①"},{"a":"P2S5","syn":["오황화인","오황화이인"],"l":"②"},{"a":"P4S7","syn":["칠황화인","칠황화사인"],"l":"③"},{"a":"P2O5, SO2","k":[["P2O5","오산화인","오산화이인"],["SO2","이산화황","아황산가스"]],"l":"④⑤","no":["→","P2S5","O2+","+O2"]},{"a":"2P2S5+15O2→2P2O5+10SO2","syn":["2P2S5+15O2->2P2O5+10SO2","2P2S5+15O2=2P2O5+10SO2","2P2S5+15O2→10SO2+2P2O5","2P2S5+15O2->10SO2+2P2O5","P2S5+15/2O2→P2O5+5SO2","P2S5+15/2O2->P2O5+5SO2","P2S5+7.5O2→P2O5+5SO2"],"l":"나"},{"a":"화기주의","syn":["화기 주의"],"l":"다"}],"순서무관":false},{"id":"2023-1-14","y":2023,"r":1,"n":14,"p":"반응식","kw":"연소 반응","pt":5,"q":"적린은 공기 중에서 연소할 수 있는 가연성 고체이다. 다음 물음에 답하시오.\n가. 연소반응식\n나. 생성되는 기체의 명칭\n다. 생성되는 기체의 색깔","a":"가. 4P + 5O2 → 2P2O5\n나. 오산화인\n다. 백색","h":"적린은 연소하면 오산화인(P2O5)이 되고, 이 기체는 흰색이다. 같은 인의 동소체인 황린도 연소하면 오산화인이 나온다.","t":"kan","칸":[{"a":"4P+5O2→2P2O5","syn":["4P+5O2->2P2O5","4P+5O2=2P2O5","P4+5O2→2P2O5","P4+5O2->2P2O5","4P+5O2→P4O10"],"l":"가"},{"a":"오산화인","syn":["P2O5","오산화이인","오산화 인","P4O10","십산화사인"],"l":"나"},{"a":"백색","syn":["흰색","하얀색","흰 색","하양","white"],"l":"다"}],"순서무관":false},{"id":"2023-1-15","y":2023,"r":1,"n":15,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"제조소의 특례에 관한 기준이다. 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n• ( 가 )등을 취급하는 제조소의 특례\n - 누설범위를 국한하기 위한 설비와 누설된 ( 가 )등을 안전한 장소에 설치된 저장실에 유입시킬 수 있는 설비를 갖출 것\n - 불활성기체를 봉입하는 장치를 갖출 것\n• ( 나 )등을 취급하는 제조소의 특례\n - 설비는 은·수은·동·마그네슘 또는 이들을 성분으로 하는 합금으로 만들지 아니할 것\n - 연소성 혼합기체의 생성에 의한 폭발을 방지하기 위한 불활성기체 또는 수증기를 봉입하는 장치를 갖출 것\n - 탱크에는 냉각장치 또는 보냉장치 및 불활성기체를 봉입하는 장치를 갖출 것\n• ( 다 )등을 취급하는 제조소의 특례\n - 지정수량 이상의 ( 다 )등을 취급하는 제조소의 위치는 D = 51.1×N^(1/3) 식에 의한 안전거리를 둘 것","a":"가. 알킬알루미늄\n나. 아세트알데하이드\n다. 하이드록실아민","h":"알킬알루미늄등(알킬알루미늄·알킬리튬)을 취급하는 제조소는 누설 범위를 국한하는 설비와 불활성기체 봉입 장치를 갖춘다. 아세트알데하이드등은 설비를 은·수은·동·마그네슘이나 이들의 합금으로 만들지 않고, 하이드록실아민등은 지정수량 이상을 취급하면 D = 51.1×N^(1/3) 식으로 안전거리를 구한다.","t":"kan","칸":[{"a":"알킬알루미늄","syn":["알킬알루미늄등","알킬알루미늄 등","알킬 알루미늄","알킬알미늄","알킬리튬","알킬알루미늄 또는 알킬리튬"],"l":"가"},{"a":"아세트알데하이드","syn":["아세트알데히드","아세트알데하이드등","아세트알데하이드 등","아세트알데이드","프로필렌옥사이드","산화프로필렌"],"l":"나"},{"a":"하이드록실아민","syn":["히드록실아민","하이드록실아민등","하이드록실아민 등","하이드록시아민","하이드록실아민염류"],"l":"다"}],"순서무관":false},{"id":"2023-1-16","y":2023,"r":1,"n":16,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"탱크에 저장하는 경우 저장 유지온도를 쓰시오.\n가. 옥내저장탱크 중 압력탱크 외의 탱크에 저장하는 산화프로필렌에 있어서는 ( ) 이하로 유지할 것\n나. 옥내저장탱크 중 압력탱크 외의 탱크에 저장하는 아세트알데하이드에 있어서는 ( ) 이하로 유지할 것\n다. 옥외저장탱크 중 압력탱크에 저장하는 아세트알데하이드는 ( ) 이하로 유지할 것\n라. 보냉장치가 있는 이동저장탱크에 저장하는 다이에틸에터등의 온도는 해당 위험물의 ( ) 이하로 유지할 것\n마. 보냉장치가 없는 이동저장탱크에 저장하는 다이에틸에터등의 온도는 ( ) 이하로 유지할 것","a":"가. 30℃, 나. 15℃\n다. 40℃, 라. 비점\n마. 40℃","h":"옥외·옥내·지하저장탱크 중 압력탱크 외의 탱크에서는 산화프로필렌과 다이에틸에터등이 30℃ 이하, 아세트알데하이드가 15℃ 이하다. 압력탱크에서는 모두 40℃ 이하이고, 이동저장탱크는 보냉장치가 있으면 비점 이하, 없으면 40℃ 이하다.","t":"kan","칸":[{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"가"},{"a":"15℃","syn":["15","15도","15℃ 이하","15도 이하"],"l":"나"},{"a":"40℃","syn":["40","40도","40℃ 이하","40도 이하"],"l":"다"},{"a":"비점","syn":["끓는점","비등점","비점이하","끓는 점","비점 이하"],"l":"라"},{"a":"40℃","syn":["40","40도","40℃ 이하","40도 이하"],"l":"마"}],"순서무관":false},{"id":"2023-1-17","y":2023,"r":1,"n":17,"p":"물질·성상","kw":"소화약제","pt":5,"q":"소화약제에 대하여 다음 물음에 답하시오.\n가. 제2종 분말소화약제의 화학식\n나. 제3종 분말소화약제의 화학식\n다. IG-55의 구성 성분과 용량비\n라. IG-541의 구성 성분과 용량비\n마. IG-100의 구성 성분과 용량비","a":"가. KHCO3\n나. NH4H2PO4\n다. N2 : Ar = 50 : 50\n라. N2 : Ar : CO2 = 52 : 40 : 8\n마. N2 100%","h":"제2종 분말은 탄산수소칼륨 KHCO3, 제3종 분말은 인산암모늄 NH4H2PO4다. 불활성가스 소화약제 중 IG-100은 질소 100%, IG-55는 질소와 아르곤 50:50, IG-541은 질소·아르곤·이산화탄소 52:40:8이다.","t":"kan","칸":[{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"가"},{"a":"NH4H2PO4","syn":["인산암모늄","제일인산암모늄","인산이수소암모늄","(NH4)H2PO4"],"l":"나"},{"a":"N2 : Ar = 50 : 50","k":[["N2","질소"],["Ar","아르곤"],["50"]],"l":"다"},{"a":"N2 : Ar : CO2 = 52 : 40 : 8","k":[["Ar","아르곤"],["CO2","이산화탄소"],["52"]],"l":"라"},{"a":"N2 100%","k":[["N2","질소"],["100"]],"l":"마"}],"순서무관":false},{"id":"2023-1-18","y":2023,"r":1,"n":18,"p":"반응식","kw":"물과 반응","pt":5,"q":"구리로 된 용기에 저장한 탄화칼슘이 수분과 접촉하였다. 다음 물음에 답하시오.\n가. 탄화칼슘과 수분의 화학반응식\n나. 가.에서 발생한 기체와 구리의 화학반응식\n다. 물과 반응한 탄화칼슘을 구리용기에 저장하면 안 되는 이유","a":"가. CaC2 + 2H2O → Ca(OH)2 + C2H2\n나. C2H2 + 2Cu → Cu2C2 + H2\n다. 아세틸렌이 구리와 반응하면 폭발성의 구리아세틸라이드를 만들기 때문이다.","h":"탄화칼슘이 물과 반응하면 수산화칼슘과 아세틸렌이 생긴다. 아세틸렌은 은·수은·구리·마그네슘 등과 반응해 폭발성의 아세틸라이드를 만들기 때문에 구리 용기에 저장하면 안 된다.","t":"kan","칸":[{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"가"},{"a":"C2H2+2Cu→Cu2C2+H2","syn":["C2H2+2Cu->Cu2C2+H2","C2H2+2Cu=Cu2C2+H2","C2H2+2Cu→H2+Cu2C2","C2H2+2Cu->H2+Cu2C2"],"l":"나"},{"a":"아세틸렌이 구리와 반응하면 폭발성의 구리아세틸라이드를 만들기 때문이다","k":[["아세틸렌","C2H2"],["구리","Cu"],["폭발"]],"l":"다"}],"순서무관":false},{"id":"2023-1-19","y":2023,"r":1,"n":19,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 보기에서 설명하는 위험물에 대한 각 물음에 답하시오.\n[보기]\n• 제1류 위험물\n• 분자량 158\n• 흑자색 결정\n• 물, 알코올, 아세톤에 녹는다.\n가. 지정수량\n나. 묽은 황산과 반응 시 생성되는 기체의 명칭\n다. 위험등급","a":"가. 1,000kg\n나. 산소\n다. III","h":"분자량 158의 흑자색 결정이며 물에 녹는 제1류 위험물은 과망가니즈산칼륨(KMnO4)이다. 과망가니즈산염류로 지정수량 1,000kg, 위험등급 III이다. 묽은 황산과는 4KMnO4 + 6H2SO4 → 2K2SO4 + 4MnSO4 + 6H2O + 5O2로 반응해 산소가 나온다.","t":"kan","칸":[{"a":"1000kg","syn":["1000","1,000","1,000kg","1000 kg"],"l":"가"},{"a":"산소","syn":["O2","산소가스","oxygen"],"l":"나"},{"a":"III","syn":["Ⅲ","3","III등급","Ⅲ등급","3등급","III 등급","Ⅲ 등급","Ⅲ급","3급"],"l":"다"}],"순서무관":false},{"id":"2023-1-20","y":2023,"r":1,"n":20,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"옥외저장탱크를 벽 및 바닥의 두께가 0.2m 이상이고 누수가 되지 아니하는 철근콘크리트의 수조에 넣어 보관하여야 하는 제4류 위험물에 대하여 다음 물음에 답하시오.\n가. 품명\n나. 연소반응식\n다. 다음 위험물 중 혼재 가능한 위험물 (단, 해당 없으면 해당없음으로 쓰시오)\n과염소산, 과산화나트륨, 과망가니즈산칼륨, 삼불화브로민","a":"가. 특수인화물\n나. CS2 + 3O2 → CO2 + 2SO2\n다. 해당없음","h":"벽과 바닥 두께 0.2m 이상의 철근콘크리트 수조에 보관하는 제4류 위험물은 이황화탄소(CS2)이고 특수인화물이다. 연소하면 CO2와 SO2가 나온다. 제4류와 혼재할 수 있는 것은 제2·3·5류인데, 보기는 제1류(과산화나트륨, 과망가니즈산칼륨)와 제6류(과염소산, 삼불화브로민)뿐이라 해당없음이다.","t":"kan","칸":[{"a":"특수인화물","syn":["특수 인화물"],"l":"가"},{"a":"CS2+3O2→CO2+2SO2","syn":["CS2+3O2->CO2+2SO2","CS2+3O2=CO2+2SO2","CS2+3O2→2SO2+CO2","CS2+3O2->2SO2+CO2"],"l":"나"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"다"}],"순서무관":false},{"id":"2023-2-01","y":2023,"r":2,"n":1,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"트라이에틸알루미늄에 대하여 다음 물음에 답하시오.\n가. 물과의 화학반응식\n나. 가.에서 1몰의 트라이에틸알루미늄이 반응했을 때 표준상태에서 발생한 기체의 부피(L)\n[계산과정]\n[답]\n다. 옥내저장소에 저장할 때 저장창고의 최대 바닥면적(m2)","a":"가. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n나. ① 1mol 반응하면 에테인(C2H6) 3mol 발생\n② V = nRT/P\n③ V = (3×0.082×273)/1\n④ 67.16L\n다. 1,000m2","h":"물과 닿으면 에테인이 나온다. 트라이에틸알루미늄 1mol에 에테인 3mol이므로 기체 몰수에 3을 곱해서 부피를 구한다. 알킬알루미늄은 위험등급 I이라 옥내저장소 바닥면적 상한이 1,000m2다.","tp":"W01","t":"kan","칸":[{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"가"},{"a":"67.16","e":1,"l":"나"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"다"}],"순서무관":false},{"id":"2023-2-02","y":2023,"r":2,"n":2,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"지하탱크저장소의 구조에 대한 설명이다. 다음 빈칸을 알맞게 채우시오.\n• 지하저장탱크의 윗부분은 지면으로부터 ( 가 )m 이상 아래에 있어야 한다.\n• 지하저장탱크를 2 이상 인접해 설치하는 경우에는 그 상호 간에 ( 나 )m 이상의 간격을 유지하여야 한다.\n• 지하저장탱크는 용량에 따라 다음 표에 정하는 기준에 적합하게 강철판 또는 동등 이상의 성능이 있는 금속재질로 ( 다 )용접 또는 ( 라 )용접으로 틈이 없도록 만드는 동시에, 압력탱크(최대상용압력이 46.7kPa 이상인 탱크를 말한다) 외의 탱크에 있어서는 70kPa의 압력으로, 압력탱크에 있어서는 최대상용압력의 ( 마 )배의 압력으로 각각 ( 바 )분간 수압시험을 실시하여 새거나 변형되지 아니하여야 한다.","a":"가. 0.6\n나. 1\n다. 완전용입\n라. 양면겹침이음\n마. 1.5\n바. 10","h":"지하저장탱크는 윗부분을 지면에서 0.6m 이상 내리고, 탱크끼리는 1m 이상 띄운다(용량 합계가 지정수량 100배 이하면 0.5m). 수압시험은 압력탱크 외에는 70kPa, 압력탱크는 최대상용압력의 1.5배로 10분간 한다. 용접은 완전용입 또는 양면겹침이음이다.","t":"kan","칸":[{"a":"0.6","syn":["0.6m","0.6미터","60cm"],"l":"가"},{"a":"1","syn":["1m","1미터"],"l":"나"},{"a":"완전용입, 양면겹침이음","k":[["완전용입","완전 용입"],["양면겹침","겹침이음","겹침"]],"l":"다·라"},{"a":"1.5","syn":["1.5배"],"l":"마"},{"a":"10","syn":["10분"],"l":"바"}],"순서무관":false},{"id":"2023-2-03","y":2023,"r":2,"n":3,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 설명하는 위험물에 대하여 물음에 답하시오.\n• 물, 알코올, 에터에 잘 녹는다.\n• 은거울반응과 펠링반응을 한다.\n• 산화하여 아세트산이 되기 쉽다.\n가. 명칭\n나. 시성식\n다. 지정수량\n라. 위험등급","a":"가. 아세트알데하이드\n나. CH3CHO\n다. 50L\n라. 위험등급 I","h":"은거울반응과 펠링반응을 하는 것은 알데하이드기(-CHO)가 있어서이고, 산화되면 아세트산이 된다. 에탄올을 산화하면 아세트알데하이드, 한 번 더 산화하면 아세트산이다. 특수인화물이라 지정수량 50L, 위험등급 I이다.","t":"kan","칸":[{"a":"아세트알데하이드","syn":["아세트알데히드","아세트알데이드","CH3CHO","acetaldehyde"],"l":"가"},{"a":"CH3CHO","syn":["아세트알데하이드","아세트알데히드","C2H4O","CH3CH=O"],"l":"나"},{"a":"50","syn":["50L","50 L","50리터"],"l":"다"},{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"라"}],"순서무관":false},{"id":"2023-2-04","y":2023,"r":2,"n":4,"p":"계산","kw":"지정수량 배수","pt":5,"q":"다음 위험물의 지정수량 배수의 합을 구하시오.\n툴루엔 1,000L, 스틸렌 2,000L, 아닐린 4,000L, 기어유 6,000L, 올리브유 20,000L","a":"① 지정수량: 톨루엔 200L, 스타이렌 1,000L, 아닐린 2,000L, 기어유 6,000L, 올리브유 10,000L\n② 배수의 합 = 각 저장량/지정수량\n③ 1,000/200 + 2,000/1,000 + 4,000/2,000 + 6,000/6,000 + 20,000/10,000 = 5 + 2 + 2 + 1 + 2\n④ 12","h":"품명부터 가른다. 톨루엔은 제1석유류, 스타이렌은 제2석유류, 아닐린은 제3석유류, 기어유는 제4석유류, 올리브유는 동식물유류(불건성유)다. 품명별 지정수량으로 각각 나눠 더하면 12배다.","t":"calc","ka":"12"},{"id":"2023-2-05","y":2023,"r":2,"n":5,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"인화점 측정방법(방식) 3가지를 쓰시오.","a":"가. 태그밀폐식\n나. 신속평형법\n다. 클리브랜드 개방컵","h":"인화점 측정기는 밀폐식과 개방식으로 나뉜다. 태그밀폐식은 시료 50cm3, 신속평형법은 시료 2mL를 쓰고, 클리브랜드 개방컵은 시료컵의 표선까지 시료를 채운다.","t":"kan","칸":[{"a":"태그밀폐식","syn":["태그 밀폐식","태그밀폐","태그식","tag"]},{"a":"신속평형법","syn":["신속평형","신속 평형법","신속평형법시험"]},{"a":"클리브랜드개방컵","syn":["클리브랜드 개방컵","클리블랜드개방컵","클리블랜드 개방컵","클리브랜드개방식","클리블랜드개방식","클리브랜드","클리블랜드"]}],"순서무관":true,"nc":3},{"id":"2023-2-06","y":2023,"r":2,"n":6,"p":"반응식","kw":"연소 반응","pt":5,"q":"탄화칼슘은 연소하여 산화칼슘과 이산화탄소를 생성한다. 또한 고온에서 질소와 반응할 수 있다. 다음 물음에 답하시오.\n가. 탄화칼슘의 연소반응식을 쓰시오.\n나. 탄화칼슘과 질소가 반응하여 생성되는 물질 2가지의 명칭을 쓰시오.","a":"가. 2CaC2 + 5O2 → 2CaO + 4CO2\n나. 석회질소(CaCN2), 탄소(C)","h":"탄화칼슘 연소는 CaO와 CO2가 나오고 계수는 2, 5, 2, 4다. 고온에서 질소와 만나면 CaC2 + N2 → CaCN2 + C로, 석회질소와 탄소가 생긴다.","t":"kan","칸":[{"a":"2CaC2+5O2→2CaO+4CO2","syn":["2CaC2+5O2->2CaO+4CO2","2CaC2+5O2=2CaO+4CO2","CaC2+5/2O2→CaO+2CO2","CaC2+5/2O2->CaO+2CO2","2CaC2+5O2→4CO2+2CaO"],"l":"가"},{"a":"석회질소","syn":["CaCN2","칼슘시안아미드","시안아미드칼슘","시안화칼슘","칼슘사이안아미드","석회 질소"],"l":"나-1"},{"a":"탄소","syn":["C","카본","그을음","carbon"],"l":"나-2"}],"순서무관":false},{"id":"2023-2-07","y":2023,"r":2,"n":7,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에서 정한 완공검사에 대한 내용이다. 다음 물음에 답하시오.\n가. 위험물을 저장 또는 취급하는 탱크로서 대통령령이 정하는 탱크가 있는 제조소등의 설치, 변경에 관하여 완공검사를 받기 전에 받아야 하는 검사는 무엇인지 쓰시오.\n나. 다음 시설의 완공검사 신청시기를 쓰시오.\n • 이동탱크저장소\n • 지하탱크가 있는 제조소등\n다. 완공검사를 실시한 결과 당해 제조소등이 규정에 의한 기술기준에 적합하다고 인정하는 때에 시·도지사는 어떤 서류를 교부해야 하는지 쓰시오.","a":"가. 탱크안전성능검사\n나. 이동탱크저장소: 이동저장탱크를 완공하고 상치장소를 확보한 후\n지하탱크가 있는 제조소등: 해당 지하탱크를 매설하기 전\n다. 완공검사합격확인증","h":"탱크가 있는 제조소등은 완공검사 전에 탱크안전성능검사를 먼저 받는다. 완공검사 신청은 지하탱크가 있으면 매설 전, 이동탱크저장소는 탱크를 완공하고 상치장소를 확보한 뒤다. 적합 판정을 받으면 시·도지사가 완공검사합격확인증을 내준다.","t":"kan","칸":[{"a":"탱크안전성능검사","syn":["탱크 안전성능검사","탱크안전성능","탱크안전성능 검사"],"l":"가"},{"a":"이동저장탱크를 완공하고 상치장소를 확보한 후","k":[["상치"],["완공","확보"]],"l":"나-이동탱크"},{"a":"지하탱크를 매설하기 전","k":[["매설","묻"],["전"]],"l":"나-지하탱크"},{"a":"완공검사합격확인증","syn":["완공검사합격증","완공검사 합격확인증","합격확인증","완공검사확인증"],"l":"다"}],"순서무관":false},{"id":"2023-2-08","y":2023,"r":2,"n":8,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 위험물을 운반할 때 각 운반용기 외부에 표시하여야 하는 주의사항을 쓰시오.\n가. 벤조일퍼옥사이드\n나. 마그네슘\n다. 과산화나트륨\n라. 인화성고체\n마. 기어유","a":"가. 화기엄금, 충격주의\n나. 화기주의, 물기엄금\n다. 가연물접촉주의, 화기·충격주의, 물기엄금\n라. 화기엄금\n마. 화기엄금","h":"벤조일퍼옥사이드는 제5류의 유기과산화물, 마그네슘은 제2류, 과산화나트륨은 알칼리금속의 과산화물이라 제1류 중 물기엄금이 붙는 쪽이다. 인화성고체는 제2류지만 화기엄금이고, 기어유는 제4류라 화기엄금이다.","t":"kan","칸":[{"a":"화기엄금, 충격주의","k":[["화기엄금","화기 엄금"],["충격"]],"l":"가","no":["물기","가연물"]},{"a":"화기주의, 물기엄금","k":[["화기"],["물기"]],"l":"나","no":["가연물","충격"]},{"a":"가연물접촉주의, 화기·충격주의, 물기엄금","k":[["가연물"],["충격"],["물기"]],"l":"다"},{"a":"화기엄금","syn":["화기 엄금"],"l":"라"},{"a":"화기엄금","syn":["화기 엄금"],"l":"마"}],"순서무관":false},{"id":"2023-2-09","y":2023,"r":2,"n":9,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"제1류 위험물인 염소산칼륨에 관한 내용이다. 다음 각 물음에 답을 쓰시오.\n가. 완전분해 반응식\n나. 염소산칼륨 1kg이 표준상태에서 완전 분해 시 생성되는 산소의 부피(m3) (단, 염소산칼륨의 분자량은 123이다)","a":"가. 2KClO3 → 2KCl + 3O2\n나. ① KClO3 1kg, 분자량 123, 표준상태\n② V = wRT/(PM) × (3O2/2KClO3)\n③ V = (1×0.082×273)/(1×123) × 3/2\n④ 0.27m3","h":"염소산칼륨은 분해되어 염화칼륨과 산소를 낸다. 반응식 계수비가 KClO3 2에 O2 3이므로 이상기체식으로 구한 부피에 3/2를 곱한다.","tp":"W01","t":"kan","칸":[{"a":"2KClO3→2KCl+3O2","syn":["2KClO3->2KCl+3O2","2KClO3=2KCl+3O2","KClO3→KCl+3/2O2","KClO3->KCl+3/2O2"],"l":"가"},{"a":"0.27","e":0.01,"l":"나"}],"순서무관":false},{"id":"2023-2-10","y":2023,"r":2,"n":10,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"클로로벤젠에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 품명\n다. 지정수량","a":"가. C6H5Cl\n나. 제2석유류\n다. 1,000L","h":"클로로벤젠은 벤젠 고리에 염소가 하나 붙은 물질이다. 비수용성 제2석유류라 지정수량은 1,000L다.","t":"kan","칸":[{"a":"C6H5Cl","syn":["염화벤젠","클로로벤젠","C6H5-Cl"],"l":"가"},{"a":"제2석유류","syn":["2석유류","제 2석유류","제이석유류"],"l":"나"},{"a":"1000","syn":["1,000","1000L","1,000L","1000 L","1000리터"],"l":"다"}],"순서무관":false},{"id":"2023-2-11","y":2023,"r":2,"n":11,"p":"반응식","kw":"열분해","pt":5,"q":"제1종 분말소화약제의 270℃에서의 열분해반응식을 쓰시오.","a":"2NaHCO3 → Na2CO3 + CO2 + H2O","h":"제1종 분말은 탄산수소나트륨(NaHCO3)이다. 270℃에서는 탄산나트륨, 이산화탄소, 물이 나오고 850℃에서는 Na2O와 CO2 2개, 물이 나온다. 문제가 온도를 지정하면 그 온도의 식을 쓴다.","t":"kan","칸":[{"a":"2NaHCO3→Na2CO3+CO2+H2O","syn":["2NaHCO3->Na2CO3+CO2+H2O","2NaHCO3=Na2CO3+CO2+H2O","2NaHCO3→Na2CO3+H2O+CO2","2NaHCO3->Na2CO3+H2O+CO2"]}],"순서무관":false},{"id":"2023-2-12","y":2023,"r":2,"n":12,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"흑색화약의 원료에 대하여 다음 빈칸에 알맞은 답을 쓰시오 (위험물이 아닐 경우 해당없음으로 표기).\n(구분 / 화학식 / 품명)\n가. 원료 1 / 나. 원료 2 / 다. 원료 3","a":"가. 원료 1: KNO3, 질산염류\n나. 원료 2: S, 황\n다. 원료 3: C, 해당없음","h":"흑색화약은 질산칼륨, 황, 숯(탄소)을 섞은 것이다. 질산칼륨은 제1류 질산염류(300kg), 황은 제2류 황(100kg)이고 탄소는 위험물이 아니다.","t":"kan","칸":[{"a":"KNO3","syn":["질산칼륨","질산 칼륨"],"l":"가-화학식"},{"a":"질산염류","syn":["질산염","질산 염류"],"l":"가-품명"},{"a":"S","syn":["s","황","유황","sulfur"],"l":"나-화학식"},{"a":"황","syn":["유황","sulfur","S"],"l":"나-품명"},{"a":"C","syn":["c","탄소","숯","목탄","카본"],"l":"다-화학식"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"다-품명"}],"순서무관":false},{"id":"2023-2-13","y":2023,"r":2,"n":13,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"아세트산과 과산화칼륨을 반응하여 생성되는 제6류 위험물에 대하여 다음 물음에 답하시오(해당 없으면 해당없음으로 표기).\n가. 가열 시 분해반응식\n나. 운반용기 외부에 표시하여야 할 주의사항\n다. 취급하는 제조소와 학교와의 안전거리(m)","a":"가. 2H2O2 → 2H2O + O2\n나. 가연물접촉주의\n다. 해당없음","h":"과산화칼륨에 아세트산을 가하면 K2O2 + 2CH3COOH → 2CH3COOK + H2O2로 과산화수소가 나온다. 제6류는 운반용기에 가연물접촉주의만 쓰고, 제6류를 취급하는 제조소는 안전거리 적용을 받지 않는다.","t":"kan","칸":[{"a":"2H2O2→2H2O+O2","syn":["2H2O2->2H2O+O2","2H2O2=2H2O+O2","H2O2→H2O+1/2O2","H2O2->H2O+1/2O2"],"l":"가"},{"a":"가연물접촉주의","syn":["가연물 접촉주의","가연물접촉 주의","가연물접촉","가연물 접촉 주의"],"l":"나"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다","안전거리 적용 제외","적용 제외","제외"],"l":"다"}],"순서무관":false},{"id":"2023-2-14","y":2023,"r":2,"n":14,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"각 유별에 따른 혼재가 불가능한 위험물을 모두 쓰시오(단, 위험물이 지정수량을 초과할 경우이다).\n가. 제1류 :\n나. 제2류 :\n다. 제3류 :\n라. 제4류 :\n마. 제5류 :","a":"가. 제1류: 제2류, 제3류, 제4류, 제5류\n나. 제2류: 제1류, 제3류, 제6류\n다. 제3류: 제1류, 제2류, 제5류, 제6류\n라. 제4류: 제1류, 제6류\n마. 제5류: 제1류, 제3류, 제6류","h":"혼재 가능한 쌍은 4와 2·3, 5와 2·4, 6과 1이다. 이 쌍만 지우고 나머지를 쓰면 혼재 불가 목록이 된다. 지정수량의 1/10 이하는 이 표를 적용하지 않는다.","t":"kan","칸":[{"a":"제2류, 제3류, 제4류, 제5류","k":[["2류"],["3류"],["4류"],["5류"]],"l":"가","no":["6류"]},{"a":"제1류, 제3류, 제6류","k":[["1류"],["3류"],["6류"]],"l":"나","no":["4류","5류"]},{"a":"제1류, 제2류, 제5류, 제6류","k":[["1류"],["2류"],["5류"],["6류"]],"l":"다","no":["4류"]},{"a":"제1류, 제6류","k":[["1류"],["6류"]],"l":"라","no":["2류","3류","5류"]},{"a":"제1류, 제3류, 제6류","k":[["1류"],["3류"],["6류"]],"l":"마","no":["2류","4류"]}],"순서무관":false},{"id":"2023-2-15","y":2023,"r":2,"n":15,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 보기에서 설명하는 제3류 위험물에 대하여 물음에 답하시오.\n• 비중이 0.534이다.\n• 불꽃 반응 시 붉은색을 나타낸다.\n• 은백색 광택이 있는 무른 경금속이다.\n가. 물과의 화학반응식\n나. 위험등급\n다. 이 위험물 1,000kg을 제조소에서 취급할 때 보유공지(m) (해당 없으면 해당없음을 쓰시오)","a":"가. 2Li + 2H2O → 2LiOH + H2\n나. II\n다. 5m 이상","h":"불꽃색이 붉은 알칼리금속은 리튬이다(나트륨 노랑, 칼륨 보라). 리튬은 지정수량 50kg이라 1,000kg이면 20배로, 10배를 넘으므로 보유공지는 5m 이상이다.","t":"kan","칸":[{"a":"2Li+2H2O→2LiOH+H2","syn":["2Li+2H2O->2LiOH+H2","2Li+2H2O=2LiOH+H2","Li+H2O→LiOH+1/2H2"],"l":"가"},{"a":"II","syn":["Ⅱ","2","II등급","Ⅱ등급","2등급","II 등급","Ⅱ 등급","Ⅱ급","2급"],"l":"나"},{"a":"5","syn":["5m","5m 이상","5미터","5 m"],"l":"다"}],"순서무관":false},{"id":"2023-2-16","y":2023,"r":2,"n":16,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"20℃ 물 10kg을 소화했을 때 100℃ 수증기로 만드는 데 흡수되는 에너지량(kcal)은 얼마인가?","a":"① 물 10kg, 20℃ → 100℃ 수증기. 비열 1kcal/kg·℃, 증발잠열 539kcal/kg\n② Q = cmΔT + λm\n③ Q = 1×10×(100-20) + 539×10 = 800 + 5,390\n④ 6,190kcal","h":"물이 수증기가 되는 열량은 100℃까지 올리는 현열과 100℃에서 증발시키는 잠열을 더한다. 현열은 비열×질량×온도차, 잠열은 539kcal/kg×질량이다.","t":"calc","e":5,"ka":"6190"},{"id":"2023-2-17","y":2023,"r":2,"n":17,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물의 소화방법에 대하여 옳은 것을 모두 고르시오.\n가. 제1류 위험물은 알칼리금속의 과산화물을 제외하고 경우에 따라 주수소화가 가능하다.\n나. 제6류 위험물을 저장 또는 취급하는 장소로서 폭발의 위험이 없는 경우 이산화탄소소화기는 적응성이 있다.\n다. 마그네슘 화재 시 물분무소화는 적응성이 없어 이산화탄소소화가 가능하다.\n라. 건조사는 모든 위험물에 소화적응성이 있다.\n마. 에탄올은 물보다 비중이 높아 주수소화 시 화재면이 확대되어 주수소화가 불가능하다.","a":"가, 나, 라","h":"알칼리금속의 과산화물만 빼면 제1류는 주수소화가 된다. 제6류는 폭발 위험이 없는 곳에서 이산화탄소가 적응성이 있다. 마른 모래는 전 유별에 쓰고, 마그네슘은 물과 이산화탄소 모두 쓸 수 없다. 에탄올은 물보다 가볍고 물에 녹아 희석소화가 된다.","t":"kan","칸":[{"a":"가","syn":["ㄱ","(가)","가.","제1류"]},{"a":"나","syn":["ㄴ","(나)","나.","제6류"]},{"a":"라","syn":["ㄹ","(라)","라.","건조사"]}],"순서무관":true},{"id":"2023-2-18","y":2023,"r":2,"n":18,"p":"계산","kw":"탱크 용량","pt":5,"q":"옥외탱크저장소가 12개 있다. 30만L 탱크는 2기, 나머지는 인화점 50℃인 위험물을 저장하는 용량 20만L 탱크이다. 다음 물음에 답하시오.\n가. 설치하여야 하는 방유제의 최소 개수\n나. 30만L 탱크 2기 20만L 탱크 4기를 별도의 방유제에 설치할 경우 방유제의 용량(L)\n[계산과정]\n[답]\n다. 제6류 위험물만을 저장할 때 방유제의 최소 개수","a":"가. 2개\n나. ① 최대 탱크 30만L, 옥외탱크저장소 방유제\n② 방유제 용량 = 최대 탱크 용량 × 1.1\n③ 300,000 × 1.1\n④ 33만L\n다. 2개","h":"방유제 하나에는 탱크를 10기까지 넣을 수 있어서 12기면 2개가 필요하다. 옥외탱크저장소 방유제 용량은 탱크가 여럿이어도 가장 큰 탱크 용량의 110%다. 제6류는 인화점이 없어 20기 완화 조건에 해당하지 않으므로 10기 기준으로 2개다.","tp":"W04","t":"kan","칸":[{"a":"2","syn":["2개","2기"],"l":"가"},{"a":"330000","syn":["330,000","330000L","330,000L","33만","33만L","330000리터","330,000리터"],"l":"나"},{"a":"2","syn":["2개","2기"],"l":"다"}],"순서무관":false},{"id":"2023-2-19","y":2023,"r":2,"n":19,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제5류 위험물 중 규조토에 흡수시키면 다이너마이트를 만들 수 있는 위험물에 대하여 다음 물음에 답하시오.\n가. 구조식\n나. 품명\n다. 지정수량\n라. 이산화탄소, 수증기, 질소, 산소가 발생하는 분해반응식","a":"가. (그림)\n나. 질산에스터류\n다. 10kg\n라. 4C3H5(ONO2)3 → 12CO2 + 10H2O + 6N2 + O2","h":"규조토에 흡수시켜 다이너마이트를 만드는 것은 나이트로글리세린이다. 제5류 질산에스터류(제1종)이고 지정수량은 10kg이다. 분해식은 탄소, 수소, 질소, 산소 순으로 맞추고 O2 계수가 1/4이 되므로 전체에 4를 곱한다.","ai":"2023-2-19_a.svg","t":"kan","칸":[{"a":"질산에스터류","syn":["질산에스테르류","질산에스터","질산에스테르","질산 에스터류"],"l":"나"},{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"다"},{"a":"4C3H5(ONO2)3→12CO2+10H2O+6N2+O2","syn":["4C3H5(ONO2)3->12CO2+10H2O+6N2+O2","4C3H5(ONO2)3=12CO2+10H2O+6N2+O2","4C3H5(ONO2)3→12CO2+6N2+O2+10H2O","4C3H5(ONO2)3->12CO2+6N2+O2+10H2O","4C3H5N3O9→12CO2+10H2O+6N2+O2"],"l":"라"}],"순서무관":false},{"id":"2023-2-20","y":2023,"r":2,"n":20,"p":"물질·성상","kw":"소화약제","pt":5,"q":"다음 소화약제의 화학식을 적으시오.\n가. 제2종 분말소화약제\n나. 하론 1301\n다. IG-100","a":"가. KHCO3\n나. CF3Br\n다. N2","h":"제2종 분말은 탄산수소칼륨이다. 하론 번호는 C, F, Cl, Br 개수를 차례로 읽으므로 1301은 CF3Br이다. IG-100은 질소 100%다.","t":"kan","칸":[{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"가"},{"a":"CF3Br","syn":["CBrF3","BrCF3","할론1301","Halon1301"],"l":"나"},{"a":"N2","syn":["질소","n2","질소가스"],"l":"다"}],"순서무관":false},{"id":"2023-4-01","y":2023,"r":4,"n":1,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"탄화칼슘 32g이 물과 반응하여 생성되는 기체가 완전 연소하기 위한 산소의 부피(L)를 구하시오.","a":"① CaC2 32g, 분자량 64 → C2H2 11.193L, 연소식 2C2H2 + 5O2 → 4CO2 + 2H2O\n② V = wRT/(PM)로 아세틸렌 부피를 구한 뒤 5/2배\n③ (32×0.082×273)/(1×64) × 5/2 = 11.193 × 2.5\n④ 27.98L","h":"탄화칼슘 1mol에서 아세틸렌 1mol이 나온다. 아세틸렌 연소식 2C2H2 + 5O2에서 산소는 아세틸렌의 2.5배이므로 아세틸렌 부피에 2.5를 곱한다.","tp":"W01","t":"calc","e":0.5,"ka":"27.98"},{"id":"2023-4-02","y":2023,"r":4,"n":2,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 보기의 동식물유를 건성유, 반건성유, 불건성유로 구분하시오.\n동유, 아마인유, 피마자유, 야자유, 면실유, 올리브유\n가. 건성유 :\n나. 반건성유 :\n다. 불건성유 :","a":"가. 건성유: 동유, 아마인유\n나. 반건성유: 면실유\n다. 불건성유: 피마자유, 야자유, 올리브유","h":"구분은 아이오딘값이 기준이다. 130 이상이 건성유, 100 이상 130 미만이 반건성유, 100 미만이 불건성유다. 동유와 아마인유가 건성유, 면실유가 반건성유, 피마자유·야자유·올리브유는 불건성유다.","t":"kan","칸":[{"a":"동유, 아마인유","k":[["동유","오동나무","유동"],["아마인","아마"]],"l":"가"},{"a":"면실유","k":[["면실","목화씨","목화"]],"l":"나"},{"a":"피마자유, 야자유, 올리브유","k":[["피마자","아주까리"],["야자"],["올리브"]],"l":"다"}],"순서무관":false},{"id":"2023-4-03","y":2023,"r":4,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 인화점이 낮은 것에서 높은 것 순서대로 쓰시오.\n에틸렌글리콜, 나이트로벤젠, 초산에틸, 메틸알코올","a":"초산에틸 - 메틸알코올 - 나이트로벤젠 - 에틸렌글리콜","h":"제4류는 품명 순서가 인화점 순서와 같다. 초산에틸은 제1석유류(-4℃), 메틸알코올은 알코올류(11℃), 나이트로벤젠은 제3석유류(88℃), 에틸렌글리콜은 제3석유류 수용성(111℃)이다.","t":"kan","칸":[{"a":"초산에틸","syn":["아세트산에틸","아세트산 에틸","초산 에틸","CH3COOC2H5","에틸아세테이트","아세트산에틸에스터"],"l":"1"},{"a":"메틸알코올","syn":["메탄올","메틸알콜","메틸 알코올","CH3OH","methanol"],"l":"2"},{"a":"나이트로벤젠","syn":["니트로벤젠","나이트로 벤젠","C6H5NO2","nitrobenzene"],"l":"3"},{"a":"에틸렌글리콜","syn":["에틸렌 글리콜","C2H4(OH)2","에틸렌글리콜"],"l":"4"}],"순서무관":false},{"id":"2023-4-04","y":2023,"r":4,"n":4,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"나트륨 화재 시 적응성이 있는 소화방법의 기호를 모두 쓰시오.\n가. 팽창질석\n나. 건조사\n다. 포소화설비\n라. 이산화탄소소화설비\n마. 인산염류분말소화기","a":"가, 나","h":"나트륨은 금수성 물질이라 물을 쓰는 소화설비는 안 되고 마른 모래, 팽창질석, 팽창진주암, 탄산수소염류 분말을 쓴다. 포와 이산화탄소, 인산염류 분말은 해당하지 않는다.","t":"kan","칸":[{"a":"가","syn":["ㄱ","(가)","가.","팽창질석"]},{"a":"나","syn":["ㄴ","(나)","나.","건조사","마른 모래","마른모래"]}],"순서무관":true},{"id":"2023-4-05","y":2023,"r":4,"n":5,"p":"물질·성상","kw":"소화약제","pt":5,"q":"할로젠화합물소화설비에 관하여 다음 물음에 답하시오.\n가. 할로젠화합물소화설비에 사용되는 소화약제 3가지만 쓰시오.\n나. 전역방출방식의 할로젠화합물소화설비에 사용되는 소화약제 한 가지만 쓰시오.\n다. 이동식 할로젠화합물소화설비의 소화약제를 모두 쓰시오.","a":"가. 하론 2402, 하론 1211, 하론 1301, HFC-23, HFC-125, HFC-227ea, FK-5-1-12 중 3가지\n나. 위 약제 중 1가지\n다. 하론 2402, 하론 1211, 하론 1301","h":"전역·국소방출식 할로젠화합물소화설비의 약제는 하론 2402·1211·1301과 HFC-23·125·227ea, FK-5-1-12다. 이동식은 이 중 하론 3종만 쓴다.","t":"kan","칸":[{"a":"하론2402","syn":["하론 2402","Halon2402","Halon 2402","할론2402","할론 2402","2402","하론1211","하론 1211","Halon1211","Halon 1211","할론1211","할론 1211","1211","하론1301","하론 1301","Halon1301","Halon 1301","할론1301","할론 1301","1301","HFC-23","HFC23","HFC 23","HFC-125","HFC125","HFC 125","HFC-227ea","HFC227ea","HFC 227ea","FK-5-1-12","FK5112","FK 5-1-12","HFC-236fa","HFC236fa","HCFC-124","HCFC124"],"l":"가-1"},{"a":"하론1211","syn":["하론 2402","Halon2402","Halon 2402","할론2402","할론 2402","2402","하론 1211","Halon1211","Halon 1211","할론1211","할론 1211","1211","하론1301","하론 1301","Halon1301","Halon 1301","할론1301","할론 1301","1301","HFC-23","HFC23","HFC 23","HFC-125","HFC125","HFC 125","HFC-227ea","HFC227ea","HFC 227ea","FK-5-1-12","FK5112","FK 5-1-12","HFC-236fa","HFC236fa","HCFC-124","HCFC124"],"l":"가-2"},{"a":"하론1301","syn":["하론 2402","Halon2402","Halon 2402","할론2402","할론 2402","2402","하론1211","하론 1211","Halon1211","Halon 1211","할론1211","할론 1211","1211","하론 1301","Halon1301","Halon 1301","할론1301","할론 1301","1301","HFC-23","HFC23","HFC 23","HFC-125","HFC125","HFC 125","HFC-227ea","HFC227ea","HFC 227ea","FK-5-1-12","FK5112","FK 5-1-12","HFC-236fa","HFC236fa","HCFC-124","HCFC124"],"l":"가-3"},{"a":"하론1301","syn":["하론 2402","Halon2402","Halon 2402","할론2402","할론 2402","2402","하론1211","하론 1211","Halon1211","Halon 1211","할론1211","할론 1211","1211","하론 1301","Halon1301","Halon 1301","할론1301","할론 1301","1301","HFC-23","HFC23","HFC 23","HFC-125","HFC125","HFC 125","HFC-227ea","HFC227ea","HFC 227ea","FK-5-1-12","FK5112","FK 5-1-12","HFC-236fa","HFC236fa","HCFC-124","HCFC124"],"l":"나"},{"a":"하론 2402, 하론 1211, 하론 1301","k":[["2402"],["1211"],["1301"]],"l":"다"}],"순서무관":false},{"id":"2023-4-06","y":2023,"r":4,"n":6,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"다음과 같이 옥내소화전이 설치되어 있을 때 필요한 수원의 수량(m3)을 쓰시오.\n가. 1층 2개, 2층 3개\n나. 1층 2개, 2층 6개","a":"가. ① 가장 많은 층의 설치 개수 3개\n② 수원 = 개수(최대 5) × 7.8m3\n③ 3 × 7.8\n④ 23.4m3 이상\n나. ① 가장 많은 층 6개 → 최대 5개 적용\n② 5 × 7.8\n③ 39m3 이상","h":"옥내소화전 수원은 층별로 가장 많이 설치된 층의 개수를 보고, 5개를 넘으면 5개로 센다. 개당 7.8m3를 곱하면 가는 3개라 23.4m3, 나는 6개지만 5개로 제한되어 39m3다.","t":"kan","칸":[{"a":"23.4","e":0.1,"l":"가"},{"a":"39","e":0.1,"l":"나"}],"순서무관":false},{"id":"2023-4-07","y":2023,"r":4,"n":7,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 [보기]에 물질을 연소 형태에 맞도록 나열하시오.\n나트륨, TNT, 에탄올, 금속분, 다이에틸에터, 피크린산\n가. 표면연소 :\n나. 증발연소 :\n다. 자기연소 :","a":"가. 표면연소: 나트륨, 금속분\n나. 증발연소: 에탄올, 다이에틸에터\n다. 자기연소: TNT, 피크린산","h":"금속은 표면에서 산소와 반응해 타는 표면연소다. 제4류 액체는 증발한 증기가 타는 증발연소이고, 제5류 중 TNT와 피크린산은 자기 산소로 타는 자기연소다.","t":"kan","칸":[{"a":"나트륨, 금속분","k":[["나트륨","Na"],["금속분","금속"]],"l":"가"},{"a":"에탄올, 다이에틸에터","k":[["에탄올","에틸알코올","에틸알콜"],["다이에틸에터","디에틸에터","다이에틸에테르","디에틸에테르","에터","에테르"]],"l":"나"},{"a":"TNT, 피크린산","k":[["TNT","트라이나이트로톨루엔","트리니트로톨루엔"],["피크린산","트라이나이트로페놀","트리니트로페놀","TNP"]],"l":"다"}],"순서무관":false},{"id":"2023-4-08","y":2023,"r":4,"n":8,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"하이드록실아민 1톤을 취급하는 제조소에 대하여 다음 물음에 답하시오.\n가. 제조소에 설치하여야 하는 주의사항 게시판의 바탕색과 문자색\n나. 학교와의 안전거리\n다. 토제의 경사면의 경사도","a":"가. 적색바탕 백색문자\n나. ① 하이드록실아민 지정수량 100kg, N = 1,000/100 = 10\n② D = 51.1 × ∛N\n③ D = 51.1 × ∛10\n④ 110.09m\n다. 60도 미만","h":"하이드록실아민은 제5류이고 제조소에는 화기엄금 게시판을 달며, 화기엄금은 적색바탕에 백색문자다. 안전거리는 D = 51.1×∛N으로 구하고, 담이나 토제는 외벽에서 2m 이상 띄우며 토제 경사면은 60도 미만으로 한다.","t":"kan","칸":[{"a":"적색바탕 백색문자","k":[["적색","붉은","빨간"],["백색","흰","하얀"]],"l":"가"},{"a":"110.09","e":0.5,"l":"나"},{"a":"60","syn":["60도","60도 미만","60° 미만","60°","60 미만","60도미만"],"l":"다"}],"순서무관":false},{"id":"2023-4-09","y":2023,"r":4,"n":9,"p":"반응식","kw":"연소 반응","pt":5,"q":"아세트알데하이드는 산화성과 환원성을 모두 가지고 있다. 산화 시 생성물질과 환원 시 생성물질에 대하여 다음 물음에 답하시오.\n가. 환원 시 생성물질\n- 물질명\n- 연소반응식\n나. 산화 시 생성물질\n- 물질명\n- 연소반응식","a":"가. 환원 시 생성물질\n물질명: 에틸알코올\n연소반응식: C2H5OH + 3O2 → 2CO2 + 3H2O\n나. 산화 시 생성물질\n물질명: 아세트산\n연소반응식: CH3COOH + 2O2 → 2CO2 + 2H2O","h":"아세트알데하이드에 수소를 더하면(환원) 에탄올, 산소를 더하면(산화) 아세트산이 된다. 연소 생성물은 둘 다 이산화탄소와 물이고, 원자 수를 맞추면 에탄올은 O2 3개, 아세트산은 O2 2개가 필요하다.","t":"kan","칸":[{"a":"에틸알코올","syn":["에탄올","에틸알콜","C2H5OH","에틸 알코올","에틸 알콜","ethanol"],"l":"환원-물질명"},{"a":"C2H5OH+3O2→2CO2+3H2O","syn":["C2H5OH+3O2->2CO2+3H2O","C2H5OH+3O2=2CO2+3H2O","C2H5OH+3O2→3H2O+2CO2","C2H5OH+3O2->3H2O+2CO2"],"l":"환원-연소식"},{"a":"아세트산","syn":["초산","CH3COOH","아세틱애시드","acetic acid","아세트 산"],"l":"산화-물질명"},{"a":"CH3COOH+2O2→2CO2+2H2O","syn":["CH3COOH+2O2->2CO2+2H2O","CH3COOH+2O2=2CO2+2H2O","CH3COOH+2O2→2H2O+2CO2","CH3COOH+2O2->2H2O+2CO2"],"l":"산화-연소식"}],"순서무관":false},{"id":"2023-4-10","y":2023,"r":4,"n":10,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물 저장량이 지정수량의 1/10 초과일 경우 혼재하면 안 되는 위험물을 모두 쓰시오.\n가. 제1류 :\n나. 제2류 :\n다. 제3류 :\n라. 제4류 :\n마. 제5류 :","a":"가. 제1류: 제2류, 제3류, 제4류, 제5류\n나. 제2류: 제1류, 제3류, 제6류\n다. 제3류: 제1류, 제2류, 제5류, 제6류\n라. 제4류: 제1류, 제6류\n마. 제5류: 제1류, 제3류, 제6류","h":"혼재 가능한 쌍은 4와 2·3, 5와 2·4, 6과 1이다. 이 쌍을 뺀 나머지가 혼재 불가이고, 지정수량 1/10 이하면 이 규정을 적용하지 않는다.","t":"kan","칸":[{"a":"제2류, 제3류, 제4류, 제5류","k":[["2류"],["3류"],["4류"],["5류"]],"l":"가","no":["6류"]},{"a":"제1류, 제3류, 제6류","k":[["1류"],["3류"],["6류"]],"l":"나","no":["4류","5류"]},{"a":"제1류, 제2류, 제5류, 제6류","k":[["1류"],["2류"],["5류"],["6류"]],"l":"다","no":["4류"]},{"a":"제1류, 제6류","k":[["1류"],["6류"]],"l":"라","no":["2류","3류","5류"]},{"a":"제1류, 제3류, 제6류","k":[["1류"],["3류"],["6류"]],"l":"마","no":["2류","4류"]}],"순서무관":false},{"id":"2023-4-11","y":2023,"r":4,"n":11,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량이 32이고 로켓의 원료로 사용되는 물질에 대하여 다음 물음에 답하시오.\n가. 품명\n나. 시성식\n다. 연소반응식","a":"가. 제2석유류\n나. N2H4\n다. N2H4 + O2 → N2 + 2H2O\n(또는 N2H4 + 3O2 → 2NO2 + 2H2O)","h":"분자량 32이고 로켓 연료로 쓰는 물질은 하이드라진(N2H4)이다. 제4류 제2석유류 수용성으로 지정수량 2,000L다. 연소하면 질소와 물이 나오고 산소 1분자면 계수가 맞는다.","t":"kan","칸":[{"a":"제2석유류","syn":["2석유류","제 2석유류","제이석유류"],"l":"가"},{"a":"N2H4","syn":["하이드라진","히드라진","n2h4","H2NNH2","NH2NH2"],"l":"나"},{"a":"N2H4+O2→N2+2H2O","syn":["N2H4+O2->N2+2H2O","N2H4+O2=N2+2H2O","N2H4+3O2→2NO2+2H2O","N2H4+3O2->2NO2+2H2O","N2H4+O2→2H2O+N2","N2H4+O2->2H2O+N2"],"l":"다"}],"순서무관":false},{"id":"2023-4-12","y":2023,"r":4,"n":12,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"주유취급소에 대한 설명 중 옳은 것을 모두 고르시오.\n① 압축수소를 충전하는 설비는 옥내주유취급소에 설치 가능하다.\n② 셀프용 고정주유설비를 고정주유설비로 신고 없이 변경할 수 있다.\n③ 옥내주유취급소는 건축물 내에 설치된 것만 해당한다.\n④ 태양광 발전설비의 집광판 및 그 부속설비는 캐노피의 상부 또는 건축물의 옥상에 설치하여야 한다.","a":"②, ④","h":"압축수소 충전설비는 옥내주유취급소 외의 주유취급소에만 둘 수 있다. 셀프가 아닌 설비를 셀프로 바꿀 때만 변경허가를 받으므로 반대로 바꾸는 것은 신고 없이 된다. 옥내주유취급소에는 캐노피 면적이 공지면적의 1/3을 넘는 경우도 포함되고, 태양광 집광판은 캐노피 상부나 건물 옥상에 설치한다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"]},{"a":"④","syn":["4","4번","(4)"]}],"순서무관":true},{"id":"2023-4-13","y":2023,"r":4,"n":13,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"다음은 소방대상물 또는 위험물의 구분에 따른 소화설비의 적응성을 나타낸 표이다. 빈칸에 적응성이 있는 경우 ○표시를 하시오.\n| 소화설비의 구분|제1류위험물 알칼리금속 과산화물등|제2류위험물 인화성고체|제3류위험물 그 밖의 것|제4류 위험물|제5류 위험물|제6류 위험물 |\n| 옥외소화전설비||||||\n| 물분무등소화설비 포소화설비||||||\n| 물분무등소화설비 불활성가스소화설비||||||","a":"소화설비의 구분|제1류위험물 알칼리금속 과산화물등|제2류위험물 인화성고체|제3류위험물 그 밖의 것|제4류 위험물|제5류 위험물|제6류 위험물\n옥외소화전설비||○|○||○|○\n물분무등소화설비 포소화설비||○|○|○|○|○\n물분무등소화설비 불활성가스소화설비||○||○||","h":"물을 쓰는 옥외소화전은 알칼리금속 과산화물(제1류)과 제4류에는 쓰지 못하고 나머지에는 된다. 포는 알칼리금속 과산화물을 뺀 나머지 유별에 적응하고, 불활성가스는 인화성고체와 제4류에만 적응한다."},{"id":"2023-4-14","y":2023,"r":4,"n":14,"p":"반응식","kw":"열분해","pt":5,"q":"다음 물질이 열분해하여 산소를 발생하는 반응식을 쓰시오.\n가. 아염소산나트륨\n나. 염소산나트륨\n다. 과염소산나트륨","a":"가. NaClO2 → NaCl + O2\n나. 2NaClO3 → 2NaCl + 3O2\n다. NaClO4 → NaCl + 2O2","h":"세 물질 모두 염화나트륨과 산소로 분해된다. 산소 원자 수가 2, 3, 4이므로 O2 계수는 각각 1, 3/2, 2이고, 염소산나트륨만 분수를 없애려고 전체에 2를 곱한다.","t":"kan","칸":[{"a":"NaClO2→NaCl+O2","syn":["NaClO2->NaCl+O2","NaClO2=NaCl+O2","2NaClO2→2NaCl+2O2","2NaClO2->2NaCl+2O2"],"l":"가"},{"a":"2NaClO3→2NaCl+3O2","syn":["2NaClO3->2NaCl+3O2","2NaClO3=2NaCl+3O2","NaClO3→NaCl+3/2O2","NaClO3->NaCl+3/2O2"],"l":"나"},{"a":"NaClO4→NaCl+2O2","syn":["NaClO4->NaCl+2O2","NaClO4=NaCl+2O2"],"l":"다"}],"순서무관":false},{"id":"2023-4-15","y":2023,"r":4,"n":15,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 보기에서 설명하는 위험물에 대하여 물음에 답하시오.\n• 비중이 1.26이다.\n• 지정수량 50L이다.\n• 옥외탱크저장소에 저장 시 벽 및 바닥의 두께 0.2m 이상의 콘크리트 수조에 넣어 보관하여야 한다.\n가. 시성식\n나. 연소반응식\n다. 위험물안전관리법령상 틀린 것을 골라 바르게 고치시오.\n① 통기관을 설치하지 않아도 된다.\n② 보유공지를 두어야 한다.\n③ 자동계량장치는 생략할 수 있다.","a":"가. CS2\n나. CS2 + 3O2 → CO2 + 2SO2\n다. 틀린 것은 ②. 보유공지는 생략할 수 있다.","h":"비중 1.26이고 지정수량 50L이며 수조에 넣어 저장하는 것은 이황화탄소다. 연소하면 이산화탄소와 이산화황이 나온다. 수조에 저장하는 이황화탄소 탱크는 보유공지·통기관·자동계량장치를 모두 생략할 수 있다.","t":"kan","칸":[{"a":"CS2","syn":["이황화탄소","이황화 탄소"],"l":"가"},{"a":"CS2+3O2→CO2+2SO2","syn":["CS2+3O2->CO2+2SO2","CS2+3O2=CO2+2SO2","CS2+3O2→2SO2+CO2","CS2+3O2->2SO2+CO2"],"l":"나"},{"a":"②","syn":["2","2번","(2)"],"l":"다-틀린 것"},{"a":"보유공지는 생략할 수 있다","k":[["보유공지","공지"],["생략","불필요","두지 않","않아도","필요 없","제외","없"]],"l":"다-고치기"}],"순서무관":false},{"id":"2023-4-16","y":2023,"r":4,"n":16,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물안전관리법령에서 정한 저장에 관한 중요 기준 중, 유별을 달리하는 위험물은 동일한 저장소에 저장하지 아니하여야 한다. 단, 옥내저장소 또는 옥외저장소 있어서 적절한 조치를 한 경우에는 저장이 가능하다. 옥내저장소에서 동일한 실에 저장할 수 있는 유별을 바르게 연결한 것을 골라 기호를 쓰시오.\n[보기]\n① 과산화나트륨 - 과산화벤조일\n② 질산염류 - 과염소산\n③ 황린 - 제1류 위험물\n④ 인화성고체 - 제1석유류\n⑤ 황 - 제4류 위험물","a":"②, ③, ④","h":"옥내저장소에서 1m 이상 띄우면 같이 둘 수 있는 쌍은 제1류(알칼리금속 과산화물 제외)와 제5류, 제1류와 제6류, 제1류와 황린, 인화성고체와 제4류 등이다. 과산화나트륨은 알칼리금속 과산화물이라 ①이 안 되고, 황(제2류)과 제4류는 인화성고체가 아니라서 ⑤도 안 된다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"]},{"a":"③","syn":["3","3번","(3)"]},{"a":"④","syn":["4","4번","(4)"]}],"순서무관":true},{"id":"2023-4-17","y":2023,"r":4,"n":17,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"위험물안전관리법령에서 정한 농도가 36wt% 미만일 경우 위험물에서 제외되는 제6류 위험물에 대하여 다음 물음에 답하시오.\n가. 산소가 생성되는 반응식\n나. 운반용기 외부에 표시하여야 할 주의사항\n다. 위험등급","a":"가. 2H2O2 → 2H2O + O2\n나. 가연물접촉주의\n다. I 등급","h":"36중량% 미만이면 위험물에서 빠지는 제6류는 과산화수소다. 분해하면 물과 산소가 나오고(MnO2 촉매), 제6류는 모두 위험등급 I이며 가연물접촉주의를 표시한다.","t":"kan","칸":[{"a":"2H2O2→2H2O+O2","syn":["2H2O2->2H2O+O2","2H2O2=2H2O+O2","H2O2→H2O+1/2O2","H2O2->H2O+1/2O2"],"l":"가"},{"a":"가연물접촉주의","syn":["가연물 접촉주의","가연물접촉 주의","가연물접촉","가연물 접촉 주의"],"l":"나"},{"a":"I등급","syn":["Ⅰ등급","1등급","I","Ⅰ","1","I 등급","1급","Ⅰ급"],"l":"다"}],"순서무관":false},{"id":"2023-4-18","y":2023,"r":4,"n":18,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 위험물이 연소할 때 생성물의 화학식을 쓰시오(단, 없으면 해당없음을 쓰시오).\n가. 마그네슘\n나. 질산칼륨\n다. 황\n라. 황린\n마. 과염소산","a":"가. MgO\n나. 해당없음\n다. SO2\n라. P2O5\n마. 해당없음","h":"마그네슘은 2Mg + O2 → 2MgO, 황은 S + O2 → SO2, 황린은 P4 + 5O2 → 2P2O5다. 질산칼륨(제1류)과 과염소산(제6류)은 산화성 물질이라 자기가 타지 않는다.","t":"kan","칸":[{"a":"MgO","syn":["산화마그네슘","mgo","산화 마그네슘"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"나"},{"a":"SO2","syn":["이산화황","so2","아황산가스","이산화 황","아황산"],"l":"다"},{"a":"P2O5","syn":["오산화인","오산화이인","p2o5","오산화 인"],"l":"라"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"마"}],"순서무관":false},{"id":"2023-4-19","y":2023,"r":4,"n":19,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"아세톤(제4류 위험물)에 대한 다음 물음에 답을 쓰시오.\n가. 시성식\n나. 품명, 지정수량\n다. 증기비중","a":"가. CH3COCH3\n나. 제1석유류, 400L\n다. ① 분자량 = 12×3 + 1×6 + 16 = 58\n② 증기비중 = 분자량/29\n③ 58/29\n④ 2","h":"아세톤은 수용성 제1석유류로 지정수량 400L다. 증기비중은 분자량을 공기 평균 분자량 29로 나눈 값이라 58/29 = 2다.","t":"kan","칸":[{"a":"CH3COCH3","syn":["C3H6O","CH3-CO-CH3","(CH3)2CO"],"l":"가"},{"a":"제1석유류, 400L","k":[["1석유류"],["400"]],"l":"나"},{"a":"2","e":0.02,"l":"다"}],"순서무관":false},{"id":"2023-4-20","y":2023,"r":4,"n":20,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령상 100만리터의 옥외저장탱크의 설치허가에 대하여 다음 물음에 답하시오.\n가. 다음은 설치허가와 관련된 절차이다. 순서대로 기호를 나열하시오.\n① 기술검토, ② 설치허가, ③ 완공검사합격확인증, ④ 완공검사, ⑤ 탱크안전성능검사\n나. 기술검토를 받아야 하는 주체\n다. 50만리터 이상의 옥외탱크저장소 설치 허가 시 제출하여야 하는 자료","a":"가. ① - ② - ⑤ - ④ - ③\n나. 한국소방산업기술원\n다. 기초·지반 및 탱크본체의 설계도서, 공사계획서, 공사공정표, 지질조사자료 등 기초·지반에 관한 자료, 용접부에 관한 설명서","h":"50만L 이상 옥외탱크는 설치허가 전에 한국소방산업기술원의 기술검토를 먼저 받는다. 이후 설치허가, 탱크안전성능검사, 완공검사, 완공검사합격확인증 순이다. 허가 신청 때는 기초·지반과 탱크본체 설계도서 등 탱크에 관한 자료를 낸다.","t":"kan","칸":[{"a":"①②⑤④③","syn":["①-②-⑤-④-③","①,②,⑤,④,③","①→②→⑤→④→③","①>②>⑤>④>③","①<②<⑤<④<③","1-2-5-4-3","1,2,5,4,3","12543","1→2→5→4→3","1<2<5<4<3","1>2>5>4>3","①②⑤④③"],"l":"가"},{"a":"한국소방산업기술원","syn":["소방산업기술원","KFI","한국 소방산업기술원"],"l":"나"},{"a":"기초·지반 및 탱크본체의 설계도서, 공사계획서, 공사공정표, 지질조사자료 등 기초·지반에 관한 자료, 용접부에 관한 설명서","k":[["설계도서","설계도"],["공사계획서","공사공정표","지질조사","용접부"]],"l":"다"}],"순서무관":false},{"id":"2024-1-01","y":2024,"r":1,"n":1,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 반응의 화학반응식을 쓰시오.\n가. 트라이메틸알루미늄과 물\n나. 트라이메틸알루미늄과 산소\n다. 트라이에틸알루미늄과 물\n라. 트라이에틸알루미늄과 산소","a":"가. (CH3)3Al + 3H2O → Al(OH)3 + 3CH4\n나. 2(CH3)3Al + 12O2 → 6CO2 + 9H2O + Al2O3\n다. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n라. 2(C2H5)3Al + 21O2 → 12CO2 + 15H2O + Al2O3","h":"알킬알루미늄이 물과 만나면 수산화알루미늄과 알케인이 나오고, 메틸은 메테인, 에틸은 에테인이다. 연소하면 CO2, H2O, Al2O3가 생기고, 물 또는 산소 계수가 분수로 나오므로 전체에 2를 곱해 정수로 만든다.","t":"kan","칸":[{"a":"(CH3)3Al+3H2O→Al(OH)3+3CH4","syn":["(CH3)3Al+3H2O->Al(OH)3+3CH4","(CH3)3Al+3H2O=Al(OH)3+3CH4","(CH3)3Al+3H2O→3CH4+Al(OH)3","(CH3)3Al+3H2O->3CH4+Al(OH)3"],"l":"가"},{"a":"2(CH3)3Al+12O2→6CO2+9H2O+Al2O3","syn":["2(CH3)3Al+12O2->6CO2+9H2O+Al2O3","2(CH3)3Al+12O2=6CO2+9H2O+Al2O3","2(CH3)3Al+12O2→Al2O3+6CO2+9H2O","2(CH3)3Al+12O2->Al2O3+6CO2+9H2O"],"l":"나"},{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"다"},{"a":"2(C2H5)3Al+21O2→12CO2+15H2O+Al2O3","syn":["2(C2H5)3Al+21O2->12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2=12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2→Al2O3+12CO2+15H2O","2(C2H5)3Al+21O2->Al2O3+12CO2+15H2O"],"l":"라"}],"순서무관":false},{"id":"2024-1-02","y":2024,"r":1,"n":2,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물 중에서 염산과 반응하여 제6류 위험물을 생성하는 물질이 물과 반응하는 화학반응식을 쓰시오.\n과염소산암모늄, 과망가니즈산칼륨, 과산화나트륨, 마그네슘","a":"2Na2O2 + 2H2O → 4NaOH + O2","h":"제1류 중 무기과산화물이 산과 만나면 과산화수소(제6류)가 나온다. 보기 중 이에 맞는 것은 과산화나트륨이다. 과산화나트륨은 물과 반응해 수산화나트륨과 산소를 내고 계수는 2, 2, 4, 1이다.","t":"kan","칸":[{"a":"2Na2O2+2H2O→4NaOH+O2","syn":["2Na2O2+2H2O->4NaOH+O2","2Na2O2+2H2O=4NaOH+O2","Na2O2+H2O→2NaOH+1/2O2","Na2O2+H2O->2NaOH+1/2O2"]}],"순서무관":false},{"id":"2024-1-03","y":2024,"r":1,"n":3,"p":"계산","kw":"탱크 용량","pt":5,"q":"톨루엔을 저장하는 위험물 옥외탱크저장소에 20만L, 30만L, 50만L의 탱크 3개가 있다. 방유제의 최소 용량(m3)을 구하시오.","a":"① 옥외탱크저장소, 탱크 3기(20만, 30만, 50만L): 최대 탱크 50만L 기준\n② 방유제 용량 = 최대 탱크 용량 × 1.1\n③ 500,000L × 1.1 = 550,000L\n④ 550m3","h":"옥외탱크저장소 방유제는 탱크가 몇 기든 가장 큰 탱크 용량의 110% 이상이어야 한다. 50만L의 1.1배인 55만L를 m3로 바꾸면 550m3다.","tp":"W04","t":"calc","e":1,"ka":"550"},{"id":"2024-1-04","y":2024,"r":1,"n":4,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 표에 위험물 운반에 관한 혼재기준에 맞게 ○와 ×를 채우시오.\n| 위험물의 구분|제1류|제2류|제3류|제4류|제5류|제6류 |\n| 제1류||||||\n| 제2류||||||\n| 제3류||||||\n| 제4류||||||\n| 제5류||||||\n| 제6류||||||","a":"위험물의 구분|제1류|제2류|제3류|제4류|제5류|제6류\n제1류||×|×|×|×|○\n제2류|×||×|○|○|×\n제3류|×|×||○|×|×\n제4류|×|○|○||○|×\n제5류|×|○|×|○||×\n제6류|○|×|×|×|×|","h":"혼재 가능한 쌍은 4와 2·3, 5와 2·4, 6과 1뿐이다. 이 쌍에만 ○를 하고 나머지는 ×로 채운다."},{"id":"2024-1-05","y":2024,"r":1,"n":5,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 인화점이 낮은 것에서 높은 것 순서대로 쓰시오(단, 인화점이 없는 위험물은 제외하시오).\n벤젠, 아세트알데하이드, 아세트산, 과염소산, 나이트로셀룰로오스","a":"아세트알데하이드 - 벤젠 - 나이트로셀룰로오스 - 아세트산","h":"과염소산은 제6류라 인화점이 없어 제외한다. 아세트알데하이드(특수인화물, -39℃), 벤젠(제1석유류, -11℃), 나이트로셀룰로오스(제5류, 13℃), 아세트산(제2석유류, 39℃) 순으로 높아진다.","t":"kan","칸":[{"a":"아세트알데하이드","syn":["아세트알데히드","아세트알데이드","CH3CHO"],"l":"1"},{"a":"벤젠","syn":["C6H6","benzene","벤졸"],"l":"2"},{"a":"나이트로셀룰로오스","syn":["니트로셀룰로오스","나이트로셀룰로스","니트로셀룰로스","질화면","NC"],"l":"3"},{"a":"아세트산","syn":["초산","CH3COOH","아세트 산"],"l":"4"}],"순서무관":false},{"id":"2024-1-06","y":2024,"r":1,"n":6,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물 중 지정수량의 단위를 L로 표기할 수 있는 위험물의 지정수량이 큰 것에서 작은 것 순서대로 쓰시오.\n다이나이트로아닐린, 하이드라진, 피리딘, 피크린산, 글리세린, 클로로벤젠","a":"글리세린 - 하이드라진 - 클로로벤젠 - 피리딘","h":"다이나이트로아닐린과 피크린산은 제5류라 지정수량이 kg 단위여서 뺀다. 남은 넷은 글리세린 4,000L, 하이드라진 2,000L, 클로로벤젠 1,000L, 피리딘 400L다.","t":"kan","칸":[{"a":"글리세린","syn":["글리세롤","C3H5(OH)3"],"l":"1"},{"a":"하이드라진","syn":["히드라진","N2H4","하이드라진"],"l":"2"},{"a":"클로로벤젠","syn":["염화벤젠","클로로 벤젠","C6H5Cl"],"l":"3"},{"a":"피리딘","syn":["C5H5N","피리진"],"l":"4"}],"순서무관":false},{"id":"2024-1-07","y":2024,"r":1,"n":7,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"다음 구분에 따라 필요한 자체소방대의 화학소방차 대수와 자체소방대원의 수를 쓰시오.\n| 사업소의 구분|화학소방자동차|자체소방대원의 수 |\n| 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 ( 가 )천배 이상 12만배 미만인 사업소|1대|5인 |\n| 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 12만배 이상 ( 나 )만배 미만인 사업소|2대|10인 |\n| 제조소 또는 일반취급소에서 취급하는 제4류 위험물의 최대수량의 합이 지정수량의 24만배 이상 ( 다 )만배 미만인 사업소|3대|15인 |\n| 옥외탱크저장소에 저장하는 제4류 위험물의 최대수량이 지정수량의 50만배 이상인 사업소|( 라 )대|( 마 )인 |","a":"가. 3\n나. 24\n다. 48\n라. 2\n마. 10","h":"제조소·일반취급소는 제4류 최대수량이 지정수량의 3천배 이상일 때부터 자체소방대를 둔다. 기준선은 3천, 12만, 24만, 48만배이고 화학소방차는 1, 2, 3, 4대, 대원은 5, 10, 15, 20인이다. 옥외탱크저장소는 50만배 이상이면 2대, 10인이다.","t":"kan","칸":[{"a":"3","syn":["3천","3천배"],"l":"가"},{"a":"24","syn":["24만","24만배"],"l":"나"},{"a":"48","syn":["48만","48만배"],"l":"다"},{"a":"2","syn":["2대"],"l":"라"},{"a":"10","syn":["10인","10명"],"l":"마"}],"순서무관":false},{"id":"2024-1-08","y":2024,"r":1,"n":8,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량이 227이며 폭약의 원료이며, 햇빛에 다갈색으로 변하고, 물에 안 녹고 벤젠과 아세톤에 녹는 물질에 대하여 답하시오.\n가. 구조식\n나. 운반용기 외부에 표시하여야 하는 주의사항\n다. 주의사항 게시판의 종류","a":"가. (그림)\n나. 화기엄금, 충격주의\n다. 화기엄금","h":"분자량 227이고 폭약 원료인 노란 결정은 트라이나이트로톨루엔(TNT)이다. 제5류 나이트로화합물(제1종)로 지정수량은 10kg이다. 제5류는 운반용기에 화기엄금·충격주의를 쓰고 게시판은 화기엄금이다.","ai":"2024-1-08_a.svg","t":"kan","칸":[{"a":"화기엄금, 충격주의","k":[["화기엄금","화기 엄금"],["충격"]],"l":"나"},{"a":"화기엄금","syn":["화기 엄금"],"l":"다"}],"순서무관":false},{"id":"2024-1-09","y":2024,"r":1,"n":9,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제5류 위험물 중 과산화벤조일에 대하여 다음 물음에 답하시오.\n가. 구조식\n나. 옥내저장소 바닥면적\n다. 위험등급","a":"가. (그림)\n나. 2,000m2\n다. II","h":"과산화벤조일은 제5류 유기과산화물(제2종)로 지정수량 100kg, 위험등급 II다. 위험등급 II·III 위험물은 옥내저장소 바닥면적이 2,000m2까지 허용된다.","ai":"2024-1-09_a.svg","t":"kan","칸":[{"a":"2000","syn":["2,000","2000m2","2,000m2","2000㎡","2,000㎡","2000m2 이하","2,000m2 이하"],"l":"나"},{"a":"II","syn":["Ⅱ","2","II등급","Ⅱ등급","2등급","II 등급","Ⅱ 등급","Ⅱ급","2급"],"l":"다"}],"순서무관":false},{"id":"2024-1-10","y":2024,"r":1,"n":10,"p":"반응식","kw":"열분해","pt":5,"q":"다음 위험물의 고온에서 열분해반응식을 쓰시오.\n과염소산나트륨, 과산화칼슘, 아염소산나트륨","a":"NaClO4 → NaCl + 2O2\n2CaO2 → 2CaO + O2\nNaClO2 → NaCl + O2","h":"과염소산나트륨과 아염소산나트륨은 염화나트륨과 산소로 분해되고 산소 원자 수가 4개, 2개라 O2 계수는 2, 1이다. 과산화칼슘은 산화칼슘과 산소로 분해되며 O2 계수가 1/2이 나와 전체에 2를 곱한다.","t":"kan","칸":[{"a":"NaClO4→NaCl+2O2","syn":["NaClO4->NaCl+2O2","NaClO4=NaCl+2O2"],"l":"과염소산나트륨"},{"a":"2CaO2→2CaO+O2","syn":["2CaO2->2CaO+O2","2CaO2=2CaO+O2","CaO2→CaO+1/2O2","CaO2->CaO+1/2O2"],"l":"과산화칼슘"},{"a":"NaClO2→NaCl+O2","syn":["NaClO2->NaCl+O2","NaClO2=NaCl+O2","2NaClO2→2NaCl+2O2","2NaClO2->2NaCl+2O2"],"l":"아염소산나트륨"}],"순서무관":false},{"id":"2024-1-11","y":2024,"r":1,"n":11,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물 중 동식물유류를 건성유와 불건성유로 구분하시오.\n기어유, 들기름, 동유, 야자유, 실린더유, 올리브유","a":"건성유: 동유, 들기름\n불건성유: 야자유, 올리브유","h":"기어유와 실린더유는 동식물유류가 아니라 제4석유류라 뺀다. 아이오딘값이 130 이상이면 건성유(동유, 들기름), 100 미만이면 불건성유(야자유, 올리브유)다.","t":"kan","칸":[{"a":"동유, 들기름","k":[["동유","오동나무","유동"],["들기름","들깨"]],"l":"건성유"},{"a":"야자유, 올리브유","k":[["야자"],["올리브"]],"l":"불건성유"}],"순서무관":false},{"id":"2024-1-12","y":2024,"r":1,"n":12,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"탄화알루미늄이 물과 반응하여 생성되는 기체에 대하여 다음 물음에 답하시오.\n가. 명칭\n나. 증기비중\n다. 연소반응식","a":"가. 메테인\n나. ① CH4 분자량 = 12 + 4 = 16\n② 증기비중 = 분자량/29\n③ 16/29\n④ 0.55\n다. CH4 + 2O2 → CO2 + 2H2O","h":"탄화알루미늄은 물과 반응해 메테인을 낸다(Al4C3 + 12H2O → 4Al(OH)3 + 3CH4). 탄화칼슘에서는 아세틸렌이 나온다. 메테인 연소는 산소 2분자가 필요하다.","t":"kan","칸":[{"a":"메테인","syn":["메탄","CH4","methane","메테인가스","메탄가스"],"l":"가"},{"a":"0.55","e":0.01,"l":"나"},{"a":"CH4+2O2→CO2+2H2O","syn":["CH4+2O2->CO2+2H2O","CH4+2O2=CO2+2H2O"],"l":"다"}],"순서무관":false},{"id":"2024-1-13","y":2024,"r":1,"n":13,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"보기에서 소화난이도등급 I 제조소등에 해당되는 것을 모두 고르시오(단, 해당사항이 없으면 없음으로 표기하시오).\n① 지하탱크저장소\n② 면적 1,000m2인 제조소\n③ 처마높이 6m인 옥내저장소\n④ 제2종 판매취급소\n⑤ 간이탱크저장소\n⑥ 이송취급소\n⑦ 이동탱크저장소","a":"②, ③, ⑥","h":"소화난이도 I은 제조소 연면적 1,000m2 이상, 옥내저장소 처마높이 6m 이상 단층, 이송취급소 전부가 해당한다. 지하탱크·간이탱크·이동탱크저장소는 III, 제2종 판매취급소는 II다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"]},{"a":"③","syn":["3","3번","(3)"]},{"a":"⑥","syn":["6","6번","(6)"]}],"순서무관":true},{"id":"2024-1-14","y":2024,"r":1,"n":14,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제4류 위험물 중 수조 속에 물을 채워 저장 가능한 위험물에 대하여 다음 물음에 답하시오.\n가. 연소반응식\n나. 품명\n다. 저장하는 철근콘크리트 수조의 최소 두께","a":"가. CS2 + 3O2 → CO2 + 2SO2\n나. 특수인화물\n다. 0.2m 이상","h":"물속에 저장하는 제4류는 이황화탄소다. 비중이 1.29로 물보다 무겁고 물과 반응하지 않아 수조에 넣어 증기 발생을 막는다. 연소하면 이산화탄소와 이산화황이 나온다.","t":"kan","칸":[{"a":"CS2+3O2→CO2+2SO2","syn":["CS2+3O2->CO2+2SO2","CS2+3O2=CO2+2SO2","CS2+3O2→2SO2+CO2","CS2+3O2->2SO2+CO2"],"l":"가"},{"a":"특수인화물","syn":["특수 인화물"],"l":"나"},{"a":"0.2","syn":["0.2m","0.2m 이상","0.2미터","20cm"],"l":"다"}],"순서무관":false},{"id":"2024-1-15","y":2024,"r":1,"n":15,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"지하탱크저장소에 대한 물음에 답하시오.\n가. 탱크전용실의 두께는 몇 m 이상으로 하여야 하는지 쓰시오.\n나. 통기관은 지면으로부터 몇 m 이상의 높이에 설치하여야 하는지 쓰시오.\n다. 누유검사관을 몇 개소 이상 설치하여야 하는지 쓰시오.\n라. 탱크와 탱크전용실 사이의 공간을 어떤 물질로 채워야 하는지 쓰시오.\n마. 지하저장탱크의 윗부분은 지면으로부터 몇 m 이상 아래에 있어야 하는지 쓰시오.","a":"가. 0.3m 이상\n나. 4m 이상\n다. 4개소 이상\n라. 마른 모래 또는 습기 등에 의해 응고되지 않는 입자지름 5mm 이하의 마른 자갈분\n마. 0.6m 이상","h":"지하탱크저장소는 전용실 벽·바닥·뚜껑 두께 0.3m 이상, 통기관 높이 지상 4m 이상, 탱크 윗부분 지하 0.6m 이상이다. 탱크와 전용실 사이는 0.1m 이상 띄우고 마른 모래나 5mm 이하 마른 자갈분으로 채우며, 누유검사관은 4개소 이상 둔다.","ai":"2024-1-15_a.svg","t":"kan","칸":[{"a":"0.3m","syn":["0.3","0.3미터","30cm"],"l":"가"},{"a":"4m","syn":["4","4미터"],"l":"나"},{"a":"4개소","syn":["4","4개","4곳","4개소 이상"],"l":"다"},{"a":"마른 모래","syn":["마른모래","모래","건조사","마른 자갈분","자갈분","마른자갈","자갈","마른 모래 또는 습기 등에 의해 응고되지 않는 입자지름 5mm 이하의 마른 자갈분","마른모래 또는 마른자갈분","마른 자갈"],"l":"라"},{"a":"0.6m","syn":["0.6","0.6미터","60cm"],"l":"마"}],"순서무관":false},{"id":"2024-1-16","y":2024,"r":1,"n":16,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 명칭, 화학식, 지정수량을 각각 알맞게 쓰시오.\n| 명칭|화학식|지정수량 |\n| ( 가 )|C6H2(NO2)3CH3|( 나 ) |\n| 과망가니즈산암모늄|( 다 )|1,000kg |\n| 인화아연|( 라 )|( 마 ) |","a":"가. 트라이나이트로톨루엔\n나. 10kg\n다. NH4MnO4\n라. Zn3P2\n마. 300kg","h":"C6H2(NO2)3CH3는 톨루엔에 나이트로기 3개가 붙은 트라이나이트로톨루엔이고 제5류 제1종이라 10kg이다. 과망가니즈산암모늄은 NH4MnO4, 인화아연은 Zn3P2이며 금속인화합물이라 300kg이다.","t":"kan","칸":[{"a":"트라이나이트로톨루엔","syn":["트리니트로톨루엔","TNT","트라이나이트로 톨루엔","트리나이트로톨루엔","트라이니트로톨루엔","트리니트로 톨루엔"],"l":"가"},{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"나"},{"a":"NH4MnO4","syn":["NH4(MnO4)","nh4mno4"],"l":"다"},{"a":"Zn3P2","syn":["Zn3 P2","Zn3(P)2","zn3p2"],"l":"라"},{"a":"300kg","syn":["300","300 kg"],"l":"마"}],"순서무관":false},{"id":"2024-1-17","y":2024,"r":1,"n":17,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"다음은 위험물제조소등을 나타낸 표이다. 다음 물음에 답하시오.\n| 제조소|저장소|저장소|취급소 |\n| 위험물제조소|옥내저장소|지하탱크저장소|주유취급소 |\n|옥외저장소|( ① )|판매취급소 |\n|옥내탱크저장소|이동탱크저장소|( ② ) |\n|옥외탱크저장소|암반탱크저장소|일반취급소 |\n가. 제조소, 저장소, 취급소를 모두 포함하는 명칭을 쓰시오.\n나. 위 빈칸에 들어갈 알맞은 말을 쓰시오.\n①\n②\n다. 위험물안전관리자를 선임하지 아니하여도 되는 저장소의 종류를 모두 쓰시오.\n라. 일반취급소 중 액체위험물을 용기에 옮겨 담는 취급소의 명칭을 쓰시오.","a":"가. 제조소등\n나. ① 간이탱크저장소\n② 이송취급소\n다. 이동탱크저장소\n라. 충전하는 일반취급소","h":"제조소 1, 저장소 8, 취급소 4가지를 합쳐 제조소등이라 한다. 저장소 8종 중 빠진 것은 간이탱크저장소, 취급소 중 빠진 것은 이송취급소다. 안전관리자는 이동탱크저장소와 허가 없는 시설을 제외하고 선임한다.","t":"kan","칸":[{"a":"제조소등","syn":["제조소 등","제조소,저장소,취급소"],"l":"가"},{"a":"간이탱크저장소","syn":["간이탱크","간이 탱크 저장소","간이저장탱크저장소"],"l":"나-①"},{"a":"이송취급소","syn":["이송 취급소"],"l":"나-②"},{"a":"이동탱크저장소","syn":["이동탱크","이동 탱크 저장소"],"l":"다"},{"a":"충전하는 일반취급소","syn":["충전 일반취급소","충전하는일반취급소","충전하는 일반 취급소","충전 취급소","충전하는 취급소","충전일반취급소"],"l":"라"}],"순서무관":false},{"id":"2024-1-18","y":2024,"r":1,"n":18,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"옥외탱크저장소의 지중탱크에 대하여 다음 물음에 답하시오.\n• 지중탱크 수평단면의 안지름 100m\n• 지중탱크의 밑판표면에서 지반면까지 높이 20m\n• 인화점 10℃인 제4류 위험물\n가. 옥외탱크저장소가 보유하는 부지의 경계선에서 지중탱크의 지반면의 옆판까지 사이의 거리를 구하시오.\n[계산과정]\n[답]\n나. 지중탱크 주위에 보유해야 할 보유공지 너비를 구하시오.\n[계산과정]\n[답]","a":"가. ① 안지름 100m, 지반면까지 높이 20m, 인화점 10℃\n② 안지름×0.5 = 50m 와 높이 20m 중 큰 값, 그리고 50m 중 큰 값\n③ 100×0.5 = 50\n④ 50m\n나. ① 안지름×0.5 = 50m, 높이 20m 중 큰 값\n② 100×0.5 = 50\n③ 50m","h":"지중탱크 부지 경계선 거리는 안지름×0.5(밑판에서 지반면까지 높이가 더 크면 그 높이)와 50m 중 큰 값이다. 인화점이 21℃ 미만이라 50m 쪽이 적용된다. 보유공지는 안지름×0.5와 높이 중 큰 값이라 50m다.","t":"kan","칸":[{"a":"50","syn":["50m","50 m","50미터"],"l":"가"},{"a":"50","syn":["50m","50 m","50미터"],"l":"나"}],"순서무관":false},{"id":"2024-1-19","y":2024,"r":1,"n":19,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"알루미늄에 대하여 다음 물음에 답하시오.\n가. 물과의 반응식\n나. 가.의 반응 시 발생하는 가스의 명칭\n다. 발생하는 가스의 위험도 계산","a":"가. 2Al + 6H2O → 2Al(OH)3 + 3H2\n나. 수소\n다. ① 수소 연소범위 4~75%\n② 위험도 = (상한 - 하한)/하한\n③ (75 - 4)/4\n④ 17.75","h":"알루미늄은 물과 반응해 수산화알루미늄과 수소를 낸다. 위험도는 연소범위 상한에서 하한을 뺀 값을 하한으로 나눈 것이다.","t":"kan","칸":[{"a":"2Al+6H2O→2Al(OH)3+3H2","syn":["2Al+6H2O->2Al(OH)3+3H2","2Al+6H2O=2Al(OH)3+3H2","Al+3H2O→Al(OH)3+3/2H2"],"l":"가"},{"a":"수소","syn":["H2","수소가스","hydrogen"],"l":"나"},{"a":"17.75","e":0.05,"l":"다"}],"순서무관":false},{"id":"2024-1-20","y":2024,"r":1,"n":20,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 반응에 대하여 생성되는 유독가스의 명칭을 쓰시오(단, 없으면 해당없음을 쓰시오).\n가. 과염소산나트륨과 염산과의 반응\n나. 염소산칼륨과 황산의 반응\n다. 과산화칼륨과 물의 반응\n라. 질산칼륨과 물의 반응\n마. 질산암모늄과 물의 반응","a":"가. 이산화염소\n나. 이산화염소\n다. 해당없음\n라. 해당없음\n마. 해당없음","h":"염소산염류에 강산을 가하면 유독한 이산화염소(ClO2)가 나온다. 과산화칼륨은 물과 반응해 산소가 나올 뿐 유독가스는 없고, 질산칼륨과 질산암모늄은 물에 녹기만 한다.","t":"kan","칸":[{"a":"이산화염소","syn":["ClO2","clo2","이산화 염소","이산화염소가스"],"l":"가"},{"a":"이산화염소","syn":["ClO2","clo2","이산화 염소","이산화염소가스"],"l":"나"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"다"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"마"}],"순서무관":false},{"id":"2024-2-01","y":2024,"r":2,"n":1,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"[보기] 중 물에는 녹지 않고 이황화탄소에 녹는 물질 중 연소하여 오산화인이 생성되는 물질에 대하여 다음 물음에 답하시오.\n[보기]\n적린, 황, 황화인, 황린, 인화칼슘, 인화알루미늄\n가. 해당 물질과 수산화칼륨 수용액이 반응할 경우 생성되는 기체를 화학식으로 쓰시오(단, 없으면 해당없음으로 쓰시오).\n나. 가.의 반응에서 생성되는 기체의 연소반응식을 쓰시오.\n다. 해당 물질을 옥내저장소에 저장할 경우 바닥 면적을 쓰시오.\n라. 해당 물질의 위험등급을 쓰시오.","a":"가. PH3\n나. 2PH3 + 4O2 → P2O5 + 3H2O\n다. 1,000m2\n라. I","h":"연소해 오산화인이 나오고 물에 안 녹으며 이황화탄소에 녹는 것은 황린이다. 황린은 제3류 자연발화성 물질로 지정수량 20kg, 위험등급 I이다. 강알칼리 수용액과 반응하면 포스핀(PH3)이 나오고, 포스핀을 태우면 P2O5와 물이 생긴다.","t":"kan","칸":[{"a":"PH3","syn":["포스핀","인화수소","ph3","phosphine"],"l":"가"},{"a":"2PH3+4O2→P2O5+3H2O","syn":["2PH3+4O2->P2O5+3H2O","2PH3+4O2=P2O5+3H2O","2PH3+4O2→3H2O+P2O5","2PH3+4O2->3H2O+P2O5","PH3+2O2→1/2P2O5+3/2H2O"],"l":"나"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"다"},{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"라"}],"순서무관":false},{"id":"2024-2-02","y":2024,"r":2,"n":2,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 보기의 위험물이 지정수량 1/10 초과할 때 혼재가 불가능한 위험물을 모두 쓰시오.\n가. 제1류 위험물\n나. 제3류 위험물\n다. 제6류 위험물","a":"가. 제1류: 제2류, 제3류, 제4류, 제5류\n나. 제3류: 제1류, 제2류, 제5류, 제6류\n다. 제6류: 제2류, 제3류, 제4류, 제5류","h":"혼재 가능한 쌍은 4와 2·3, 5와 2·4, 6과 1이다. 이 쌍에 없는 유별이 혼재 불가이므로 제1류는 6류만, 제3류는 4류만, 제6류는 1류만 같이 실을 수 있다.","t":"kan","칸":[{"a":"제2류, 제3류, 제4류, 제5류","k":[["2류"],["3류"],["4류"],["5류"]],"l":"가","no":["6류"]},{"a":"제1류, 제2류, 제5류, 제6류","k":[["1류"],["2류"],["5류"],["6류"]],"l":"나","no":["4류"]},{"a":"제2류, 제3류, 제4류, 제5류","k":[["2류"],["3류"],["4류"],["5류"]],"l":"다","no":["1류"]}],"순서무관":false},{"id":"2024-2-03","y":2024,"r":2,"n":3,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음 원통형 탱크의 각 변의 길이가 r = 60cm, l = 250cm, l1 = 30cm, l2 = 30cm일 때, 내용적(m3)을 구하시오.","a":"가. ① r = 0.6m, l = 2.5m, l1 = l2 = 0.3m\n② V = πr2(l + (l1+l2)/3)\n③ π×0.62×(2.5 + 0.6/3)\n④ 3.05m3\n나. ① r = 0.6m, l = 2.5m\n② V = πr2·l\n③ π×0.62×2.5\n④ 2.83m3","h":"길이가 cm로 주어져 있어서 m로 바꿔서 계산한다. 양 끝이 볼록한 가로형은 가운데 원통에 볼록부 평균 높이(양 끝 합의 1/3)를 더하고, 세로형은 πr2l이다.","img":["2024-2-03.svg"],"tp":"W04","t":"kan","칸":[{"a":"3.05","e":0.02,"l":"가"},{"a":"2.83","e":0.02,"l":"나"}],"순서무관":false},{"id":"2024-2-04","y":2024,"r":2,"n":4,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"위험물안전관리법령상 위험물을 취급함에 있어서 정전기가 발생할 우려가 있는 설비에는 법령에서 정하는 방법으로 정전기를 유효하게 제거할 수 있는 설비를 설치하여야 한다. 정전기 제거 방법 3가지 쓰시오.","a":"접지, 공기이온화, 상대습도 70% 이상","h":"정전기는 전하를 땅으로 보내거나(접지), 공기 중 이온으로 중화하거나(공기이온화), 습도를 70% 이상으로 높여서 제거한다.","t":"kan","칸":[{"a":"접지","syn":["접지에 의한 방법","접지하는 방법","어스","earth","접지시킨다","접지를 한다"]},{"a":"공기를 이온화","syn":["공기이온화","공기 이온화","공기를 이온화하는 방법","공기이온화 방법","이온화","공기를이온화"]},{"a":"상대습도 70% 이상","syn":["습도 70% 이상","상대습도를 70% 이상으로 한다","습도70%","상대습도 70퍼센트 이상","상대습도를 70%이상","습도를 70% 이상","상대습도 70%","상대습도 70","상대습도 70%이상","습도 70","습도를 70% 이상으로 한다","상대습도를 70% 이상으로 유지"]}],"순서무관":true,"nc":3},{"id":"2024-2-05","y":2024,"r":2,"n":5,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"피리딘에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 증기비중\n[계산과정]\n[답]","a":"가. C5H5N\n나. ① 분자량 = 12×5 + 1×5 + 14 = 79\n② 증기비중 = 분자량/29\n③ 79/29\n④ 2.72","h":"피리딘은 벤젠 고리의 탄소 하나가 질소로 바뀐 C5H5N이고 제1석유류 수용성이다. 증기비중은 분자량 79를 29로 나눈 2.72다.","t":"kan","칸":[{"a":"C5H5N","syn":["c5h5n","피리딘"],"l":"가"},{"a":"2.72","e":0.01,"l":"나"}],"순서무관":false},{"id":"2024-2-06","y":2024,"r":2,"n":6,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"아이소프로필알코올을 산화시켜 만든 것으로 아이오딘폼 반응을 하는 제1석유류에 대한 각 물음에 답을 쓰시오.\n가. 제1석유류 중 아이오딘폼 반응을 하는 것의 명칭\n나. 아이오딘폼 시성식\n다. 아이오딘폼 반응 후 색깔","a":"가. 아세톤\n나. CHI3\n다. 노란색","h":"2차 알코올인 아이소프로필알코올은 산화되면 케톤인 아세톤이 된다. 아세틸기(CH3CO-)가 있는 물질이 염기성에서 아이오딘과 반응하면 노란 침전인 아이오딘폼(CHI3)이 생긴다.","t":"kan","칸":[{"a":"아세톤","syn":["CH3COCH3","프로파논","다이메틸케톤","디메틸케톤","acetone","C3H6O"],"l":"가"},{"a":"CHI3","syn":["아이오딘폼","요오드포름","chi3","iodoform"],"l":"나"},{"a":"노란색","syn":["황색","노랑","노랑색","노란 색","yellow","담황색","연노랑"],"l":"다"}],"순서무관":false},{"id":"2024-2-07","y":2024,"r":2,"n":7,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"다음 위험물의 제조소 저장 및 취급 시 보유공지를 쓰시오.\n가. 아세톤 400L\n나. 사이안화수소 100,000L\n다. 톨루엔 15,000L\n라. 메탄올 8,000L\n마. 클로로벤젠 15,000L","a":"가. 3m 이상\n나. 5m 이상\n다. 5m 이상\n라. 5m 이상\n마. 5m 이상","h":"제조소 보유공지는 지정수량 10배 이하면 3m, 초과면 5m 이상이다. 아세톤 400L는 1배, 사이안화수소 100,000L는 250배, 톨루엔 15,000L는 75배, 메탄올 8,000L는 20배, 클로로벤젠 15,000L는 15배다.","t":"kan","칸":[{"a":"3m","syn":["3","3m 이상","3미터"],"l":"가"},{"a":"5m","syn":["5","5m 이상","5미터"],"l":"나"},{"a":"5m","syn":["5","5m 이상","5미터"],"l":"다"},{"a":"5m","syn":["5","5m 이상","5미터"],"l":"라"},{"a":"5m","syn":["5","5m 이상","5미터"],"l":"마"}],"순서무관":false},{"id":"2024-2-08","y":2024,"r":2,"n":8,"p":"계산","kw":"소요단위","pt":5,"q":"다음 소화설비의 능력단위 및 소요단위 기준에 맞추어 빈칸에 알맞은 말을 쓰시오.\n| 소화설비 | 용량 | 능력단위 |\n| 소화전용 물통 | ( 가 ) | 0.3 |\n| 수조+물통 3개 | 80L | ( 나 ) |\n| 수조+물통 6개 | ( 다 )L | 2.5 |\n라. 연면적 200m2으로 내화구조의 벽으로 된 제조소 ( 라 ) 소요단위\n마. 과산화수소 6,000kg ( 마 ) 소요단위","a":"가. 8\n나. 1.5\n다. 190\n라. ① 내화구조 제조소 1소요단위 = 100m2\n② 소요단위 = 연면적/100\n③ 200/100\n④ 2\n마. ① 과산화수소 지정수량 300kg, 1소요단위 = 지정수량×10\n② 소요단위 = 저장량/(지정수량×10)\n③ 6,000/(300×10)\n④ 2","h":"소화전용 물통은 8L가 0.3단위, 수조와 물통 3개는 80L가 1.5단위, 물통 6개는 190L가 2.5단위다. 소요단위 1은 내화구조 제조소 100m2이고 위험물은 지정수량의 10배다.","tp":"W06","t":"kan","칸":[{"a":"8","syn":["8L","8 L","8리터"],"l":"가"},{"a":"1.5","syn":["1.5단위"],"l":"나"},{"a":"190","syn":["190L","190 L","190리터"],"l":"다"},{"a":"2","syn":["2단위","2소요단위"],"l":"라"},{"a":"2","syn":["2단위","2소요단위"],"l":"마"}],"순서무관":false},{"id":"2024-2-09","y":2024,"r":2,"n":9,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"운반용기 외부에 표시하여야 할 주의사항을 모두 쓰시오.\n가. 제1류 중 알칼리금속의 과산화물\n나. 제3류 중 자연발화성 물질\n다. 제5류 위험물","a":"가. 가연물접촉주의, 화기·충격주의, 물기엄금\n나. 화기엄금, 공기접촉엄금\n다. 화기엄금, 충격주의","h":"알칼리금속의 과산화물은 산화성 주의사항에 물기엄금이 더 붙는다. 제3류 자연발화성 물질은 화기엄금과 공기접촉엄금, 제5류는 화기엄금과 충격주의다.","t":"kan","칸":[{"a":"가연물접촉주의, 화기·충격주의, 물기엄금","k":[["가연물"],["충격"],["물기"]],"l":"가"},{"a":"화기엄금, 공기접촉엄금","k":[["화기엄금","화기 엄금"],["공기접촉","공기 접촉"]],"l":"나"},{"a":"화기엄금, 충격주의","k":[["화기엄금","화기 엄금"],["충격"]],"l":"다"}],"순서무관":false},{"id":"2024-2-10","y":2024,"r":2,"n":10,"p":"시설·법령","kw":"운송·이동탱크","pt":5,"q":"위험물안전관리법에 따른 이동탱크저장소 주유호스 재질에 대하여 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n• 위험물이 샐 우려가 없고 화재예방상 안전한 구조로 할 것\n• 주입호스는 내경이 ( 가 )mm 이상이고, ( 나 )MPa 이상의 압력에 견딜 수 있는 것으로 하며, 필요 이상으로 길게 하지 아니할 것\n• 주입설비의 길이는 ( 다 )m 이내로 하고, 그 끝부분에 축적되는 ( 라 )를 유효하게 제거할 수 있는 장치를 할 것\n• 분당 배출량은 ( 마 )L 이하로 할 것","a":"가. 23\n나. 0.3\n다. 50\n라. 정전기\n마. 200","h":"이동탱크저장소 주입호스는 내경 23mm 이상, 0.3MPa 이상의 압력을 견뎌야 한다. 주입설비는 길이 50m 이내에 끝부분의 정전기를 없애는 장치를 달고, 분당 배출량은 200L 이하다.","t":"kan","칸":[{"a":"23","syn":["23mm","23 mm"],"l":"가"},{"a":"0.3","syn":["0.3MPa","0.3 MPa"],"l":"나"},{"a":"50","syn":["50m","50 m","50미터"],"l":"다"},{"a":"정전기","syn":["정전기 전하","static","정전하"],"l":"라"},{"a":"200","syn":["200L","200 L","200리터"],"l":"마"}],"순서무관":false},{"id":"2024-2-11","y":2024,"r":2,"n":11,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"인화성액체를 저장하는 위험물옥외탱크저장소의 탱크 주위에 설치하는 방유제에 대한 내용이다. 빈칸에 들어갈 말을 쓰시오.\n• 방유제의 용량은 방유제 안에 설치된 탱크가 하나인 때에는 그 탱크 용량의 ( 가 )% 이상, 2기 이상인 때에는 그 탱크 중 용량이 최대인 것의 용량의 ( 나 )% 이상으로 할 것\n• 방유제는 높이 0.5m 이상 ( 다 )m 이하, 두께 ( 라 )m 이상, 지하매설깊이 1m 이상으로 할 것\n• 방유제 내의 면적은 ( 마 )m2 이하로 할 것","a":"가. 110\n나. 110\n다. 3\n라. 0.2\n마. 8만","h":"옥외탱크저장소 방유제는 탱크가 1기든 여러 기든 가장 큰 탱크 용량의 110% 이상이다. 높이 0.5m 이상 3m 이하, 두께 0.2m 이상, 지하매설깊이 1m 이상이고 면적은 8만m2 이하다.","t":"kan","칸":[{"a":"110","syn":["110%"],"l":"가"},{"a":"110","syn":["110%"],"l":"나"},{"a":"3","syn":["3m","3미터"],"l":"다"},{"a":"0.2","syn":["0.2m","0.2미터","20cm"],"l":"라"},{"a":"80000","syn":["80,000","80000m2","80,000m2","80000㎡","80,000㎡","8만","8만m2"],"l":"마"}],"순서무관":false},{"id":"2024-2-12","y":2024,"r":2,"n":12,"p":"반응식","kw":"열분해","pt":5,"q":"다음 위험물이 열분해 할 경우 산소가 발생하는 반응식을 쓰시오. 산소가 발생하지 않을 경우 해당없음을 쓰시오.\n가. 과염소산칼륨\n나. 질산칼륨\n다. 과산화칼륨","a":"가. KClO4 → KCl + 2O2\n나. 2KNO3 → 2KNO2 + O2\n다. 2K2O2 → 2K2O + O2","h":"과염소산칼륨은 염화칼륨과 산소로, 질산칼륨은 아질산칼륨과 산소로, 과산화칼륨은 산화칼륨과 산소로 분해된다. 계수가 분수로 나오는 질산칼륨과 과산화칼륨은 전체에 2를 곱한다.","t":"kan","칸":[{"a":"KClO4→KCl+2O2","syn":["KClO4->KCl+2O2","KClO4=KCl+2O2"],"l":"가"},{"a":"2KNO3→2KNO2+O2","syn":["2KNO3->2KNO2+O2","2KNO3=2KNO2+O2","KNO3→KNO2+1/2O2","KNO3->KNO2+1/2O2"],"l":"나"},{"a":"2K2O2→2K2O+O2","syn":["2K2O2->2K2O+O2","2K2O2=2K2O+O2","K2O2→K2O+1/2O2","K2O2->K2O+1/2O2"],"l":"다"}],"순서무관":false},{"id":"2024-2-13","y":2024,"r":2,"n":13,"p":"반응식","kw":"열분해","pt":5,"q":"제5류 위험물에 대한 내용이다. [보기]를 참고하여 다음 물음에 답하시오.\n[보기]\n나이트로글리세린, 트라이나이트로톨루엔, 트라이나이트로페놀, 과산화벤조일, 다이나이트로벤젠\n가. 질산에스터류에 속하는 물질 모두 쓰시오\n나. 가. 중에서 상온에서는 액체이지만 겨울철에 동결하고, 폭발하면 분해하여 이산화탄소, 물, 질소, 산소를 발생하는 이 물질의 분해반응식을 쓰시오.","a":"가. 나이트로글리세린\n나. 4C3H5(ONO2)3 → 12CO2 + 10H2O + 6N2 + O2","h":"질산에스터류는 나이트로글리세린뿐이고 나머지는 나이트로화합물(TNT, 트라이나이트로페놀, 다이나이트로벤젠)이나 유기과산화물이다. 나이트로글리세린은 상온 액체로 겨울에 얼고, 분해하면 CO2, H2O, N2, O2가 나온다.","t":"kan","칸":[{"a":"나이트로글리세린","syn":["니트로글리세린","나이트로글리세롤","니트로글리세롤","NG","nitroglycerin","나이트로 글리세린"],"l":"가"},{"a":"4C3H5(ONO2)3→12CO2+10H2O+6N2+O2","syn":["4C3H5(ONO2)3->12CO2+10H2O+6N2+O2","4C3H5(ONO2)3=12CO2+10H2O+6N2+O2","4C3H5(ONO2)3→12CO2+6N2+O2+10H2O","4C3H5(ONO2)3->12CO2+6N2+O2+10H2O","4C3H5N3O9→12CO2+10H2O+6N2+O2"],"l":"나"}],"순서무관":false},{"id":"2024-2-14","y":2024,"r":2,"n":14,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제1류 위험물의 특징으로 옳은 것을 모두 고르시오.\n① 전부 탄소 성분이 있다.\n② 전부 산소를 포함하고 있다.\n③ 전부 가연성이다.\n④ 전부 물과 반응한다.\n⑤ 전부 고체이다.","a":"②, ⑤","h":"제1류는 산화성 고체로 산소를 품고 있어 다른 물질을 태우는 조연성이지 스스로 타지 않는다. 탄소가 없고, 물과 반응하는 것은 알칼리금속의 과산화물뿐이다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"]},{"a":"⑤","syn":["5","5번","(5)"]}],"순서무관":true},{"id":"2024-2-15","y":2024,"r":2,"n":15,"p":"반응식","kw":"물과 반응","pt":5,"q":"인화칼슘에 대하여 다음 각 물음에 답하시오.\n가. 위험물의 유별\n나. 지정수량\n다. 물과의 화학반응식\n라. 물과 반응하여 생성되는 가스의 명칭","a":"가. 제3류 위험물\n나. 300kg\n다. Ca3P2 + 6H2O → 3Ca(OH)2 + 2PH3\n라. 포스핀(인화수소)","h":"인화칼슘은 제3류 금속인화합물로 물과 반응해 수산화칼슘과 포스핀(PH3)을 낸다. 탄화칼슘은 아세틸렌, 탄화알루미늄은 메테인, 인화칼슘은 포스핀으로 갈린다.","t":"kan","칸":[{"a":"제3류","syn":["3류","제3류 위험물","3류 위험물","제 3류"],"l":"가"},{"a":"300kg","syn":["300","300 kg"],"l":"나"},{"a":"Ca3P2+6H2O→3Ca(OH)2+2PH3","syn":["Ca3P2+6H2O->3Ca(OH)2+2PH3","Ca3P2+6H2O=3Ca(OH)2+2PH3","Ca3P2+6H2O→2PH3+3Ca(OH)2","Ca3P2+6H2O->2PH3+3Ca(OH)2"],"l":"다"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine"],"l":"라"}],"순서무관":false},{"id":"2024-2-16","y":2024,"r":2,"n":16,"p":"반응식","kw":"물과 반응","pt":5,"q":"위험물안전관리법령에서 정한 제2류 위험물 중 황화인에 대한 내용이다. 다음 물음에 알맞은 답을 쓰시오.\n가. 오황화인과 물이 반응하는 반응식\n나. 오황화인이 물과 반응하여 생성되는 기체의 완전연소 반응식","a":"가. P2S5 + 8H2O → 2H3PO4 + 5H2S\n나. 2H2S + 3O2 → 2SO2 + 2H2O","h":"오황화인이 물과 반응하면 인산과 황화수소가 나온다. 황화수소를 완전연소시키면 이산화황과 물이 생기고 산소 계수는 3/2라 전체에 2를 곱한다.","t":"kan","칸":[{"a":"P2S5+8H2O→2H3PO4+5H2S","syn":["P2S5+8H2O->2H3PO4+5H2S","P2S5+8H2O=2H3PO4+5H2S","P2S5+8H2O→5H2S+2H3PO4","P2S5+8H2O->5H2S+2H3PO4"],"l":"가"},{"a":"2H2S+3O2→2SO2+2H2O","syn":["2H2S+3O2->2SO2+2H2O","2H2S+3O2=2SO2+2H2O","H2S+3/2O2→SO2+H2O"],"l":"나"}],"순서무관":false},{"id":"2024-2-17","y":2024,"r":2,"n":17,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물 중 지정수량이 같은 품명 3가지를 쓰시오.\n적린, 과염소산, 황화인, 황, 브로민산염류, 철분, 알칼리토금속, 황린","a":"황화인, 적린, 황","h":"적린, 황화인, 황은 모두 제2류 지정수량 100kg이다. 과염소산과 브로민산염류는 300kg, 철분은 500kg, 알칼리토금속은 50kg, 황린은 20kg이라 다르다.","t":"kan","칸":[{"a":"황화인","syn":["황화 인"]},{"a":"적린","syn":["붉은인","적 린","red phosphorus"]},{"a":"황","syn":["유황","sulfur","S"]}],"순서무관":true,"nc":3},{"id":"2024-2-18","y":2024,"r":2,"n":18,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"주유취급소에 대한 규정 중 항공기 주유취급소의 특례에 대한 기준이다. 다음 물음에 맞는 답을 쓰시오.\n가. 항공기의 연료탱크에 직접 주유하기 위한 주유설비를 갖춘 이동탱크저장소의 명칭을 쓰시오.\n나. 비행장에서 항공기, 비행장에 소속된 차량등에 주유하는 주유취급소에 대하여 특례가 적용이 가능한지 여부를 쓰시오.\n다. 다음 설명이 옳으면 O, 옳지 않으면 X를 쓰시오.\n① 주유호스차 또는 주유탱크차에 의하여 주유하는 때에는 주유호스의 끝부분을 항공기의 연료탱크의 급유구에 긴밀히 결합하여야 한다.\n② 고정주유설비에는 당해 주유설비에 접속한 전용탱크 또는 위험물을 저장 또는 취급하는 탱크의 배관 외의 것을 통하여서는 위험물을 주입하지 아니할 것.\n③ 주유호스차 또는 주유탱크차에 주유하는 때에는 주유호스차의 호스기기 또는 주유탱크차의 주유설비를 항공기와 전기적으로 결합할 것","a":"가. 주유탱크차\n나. 가능\n다. ① O, ② O, ③ O","h":"항공기 연료탱크에 바로 주유하는 이동탱크저장소를 주유탱크차라 한다. 비행장에서 항공기와 소속 차량에 주유하는 주유취급소는 특례를 적용받는다. 세 설명은 모두 항공기 주유 취급기준과 같다.","t":"kan","칸":[{"a":"주유탱크차","syn":["주유 탱크차","주유탱크 차"],"l":"가"},{"a":"가능","syn":["가능하다","적용 가능","특례 적용 가능","적용가능","O","예","가능함"],"l":"나"},{"a":"O","syn":["○","o","0","옳다","맞다","옳음"],"l":"다-①"},{"a":"O","syn":["○","o","0","옳다","맞다","옳음"],"l":"다-②"},{"a":"O","syn":["○","o","0","옳다","맞다","옳음"],"l":"다-③"}],"순서무관":false},{"id":"2024-2-19","y":2024,"r":2,"n":19,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 위험물을 인화점이 낮은 것에서 높은 순서대로 나열하시오.\n아세톤, 이황화탄소, 메틸알코올, 아닐린","a":"이황화탄소 - 아세톤 - 메틸알코올 - 아닐린","h":"이황화탄소는 특수인화물(-30℃), 아세톤은 제1석유류(-18℃), 메틸알코올은 알코올류(11℃), 아닐린은 제3석유류(70℃)다. 품명 순서대로 인화점이 높아지므로 품명을 먼저 확인하면 된다.","t":"kan","칸":[{"a":"이황화탄소","syn":["CS2","이황화 탄소"],"l":"1"},{"a":"아세톤","syn":["Acetone","CH3COCH3","디메틸케톤"],"l":"2"},{"a":"메틸알코올","syn":["메탄올","메틸알콜","메틸 알코올","CH3OH","methanol"],"l":"3"},{"a":"아닐린","syn":["aniline","C6H5NH2"],"l":"4"}],"순서무관":false},{"id":"2024-2-20","y":2024,"r":2,"n":20,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"불활성가스 소화설비가 적응성이 있는 위험물을 아래 보기에서 2가지 고르시오.\n가. 제1류 위험물 중 알칼리금속의 과산화물\n나. 제2류 위험물 중 인화성고체\n다. 제3류 위험물\n라. 제4류 위험물\n마. 제5류 위험물\n바. 제6류 위험물","a":"나. 제2류 위험물 중 인화성고체\n라. 제4류 위험물","h":"불활성가스 소화설비는 질식소화라서 질식소화가 통하는 제2류 인화성고체와 제4류에 쓴다. 제1류 알칼리금속 과산화물, 제3류, 제5류, 제6류에는 적응성이 없다.","t":"kan","칸":[{"a":"나","syn":["ㄴ","(나)","나.","제2류 위험물 중 인화성고체","인화성고체"]},{"a":"라","syn":["ㄹ","(라)","라.","제4류 위험물","제4류"]}],"순서무관":true},{"id":"2024-3-01","y":2024,"r":3,"n":1,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 보기 중에서 물음에 알맞은 위험물을 골라 쓰시오.\n[보기]\n뷰틸리튬, 황린, 나트륨, 인화알루미늄\n가. 이동탱크저장소로부터 꺼낼 때 200kPa의 불활성 기체를 봉입하여야 하는 것\n나. 옥내저장소에 저장 시 바닥면적 1,000m2인 것\n다. 물과 반응하여 수소기체를 발생하는 것","a":"가. 뷰틸리튬\n나. 뷰틸리튬, 황린, 나트륨\n다. 나트륨","h":"알킬알루미늄등을 이동탱크에서 꺼낼 때는 200kPa 이하의 불활성 기체를 함께 넣는다. 옥내저장소 바닥면적 1,000m2는 위험등급 I 위험물이 대상인데, 뷰틸리튬·황린·나트륨은 모두 등급 I 이고 인화알루미늄만 등급 III 이다. 황린은 물과 반응하지 않고, 나트륨은 2Na + 2H2O → 2NaOH + H2 로 수소를 낸다.","t":"kan","칸":[{"a":"뷰틸리튬","syn":["부틸리튬","n-부틸리튬","n-뷰틸리튬","노말뷰틸리튬","노말부틸리튬","뷰틸 리튬"],"l":"가"},{"a":"뷰틸리튬, 황린, 나트륨","k":[["뷰틸리튬","부틸리튬"],["황린","백린"],["나트륨","Na"]],"l":"나"},{"a":"나트륨","syn":["Na","소듐","sodium"],"l":"다"}],"순서무관":false},{"id":"2024-3-02","y":2024,"r":3,"n":2,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 품명을 쓰시오.\n가. n-부탄올\n나. 아이소프로필알코올\n다. t-부탄올\n라. 1-프로판올\n마. 아이소뷰틸알코올","a":"가. 제2석유류\n나. 알코올류\n다. 제1석유류\n라. 알코올류\n마. 제2석유류","h":"탄소가 1~3개인 포화 1가 알코올이 알코올류라서 이소프로필알코올과 1-프로판올이 여기에 든다. 탄소 4개짜리 부탄올은 이성질체마다 품명이 달라서, n-부탄올과 이소부탄올은 비수용성 제2석유류, t-부탄올은 수용성 제1석유류다.","t":"kan","칸":[{"a":"제2석유류","syn":["2석유류","제 2석유류","제이석유류"],"l":"가"},{"a":"알코올류","syn":["알콜류","알코올","알콜"],"l":"나"},{"a":"제1석유류","syn":["1석유류","제 1석유류","제일석유류"],"l":"다"},{"a":"알코올류","syn":["알콜류","알코올","알콜"],"l":"라"},{"a":"제2석유류","syn":["2석유류","제 2석유류","제이석유류"],"l":"마"}],"순서무관":false},{"id":"2024-3-03","y":2024,"r":3,"n":3,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"나트륨에 대하여 다음 물음에 답하시오.\n가. 지정수량\n나. 보호액\n다. 물과의 반응식","a":"가. 10kg\n나. 파라핀, 경유, 등유\n다. 2Na + 2H2O → 2NaOH + H2","h":"나트륨은 제3류 위험물이고 지정수량은 10kg이다. 물과 닿으면 수소가 나오기 때문에 파라핀·경유·등유 속에 담가 밀봉한다. 반응식은 Na 2개와 H2O 2개에서 NaOH 2개와 H2 1개가 나오는 꼴이다.","t":"kan","칸":[{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"가"},{"a":"등유","k":[["파라핀","경유","등유","석유"]],"l":"나"},{"a":"2Na+2H2O→2NaOH+H2","syn":["2Na+2H2O->2NaOH+H2","2Na+2H2O=2NaOH+H2","Na+H2O→NaOH+1/2H2"],"l":"다"}],"순서무관":false},{"id":"2024-3-04","y":2024,"r":3,"n":4,"p":"물질·성상","kw":"소화약제","pt":5,"q":"다음 할로젠화합물소화약제의 화학식을 쓰시오.\n가. 하론2402\n나. 하론1211\n다. HFC-23\n라. HFC-125\n마. FK-5-1-12","a":"가. C2F4Br2\n나. CF2ClBr\n다. CHF3\n라. C2HF5\n마. C2F5COCF(CF3)2 (= C2F5COC3F7)","h":"하론 번호는 앞에서부터 C, F, Cl, Br 의 개수다. 2402 는 C2F4Br2, 1211 은 CF2ClBr, 1301 은 CF3Br 이 된다. HFC-23 은 CHF3, HFC-125 는 C2HF5 이고, FK-5-1-12 는 C2F5COCF(CF3)2 이다.","t":"kan","칸":[{"a":"C2F4Br2","syn":["CF2BrCF2Br","BrCF2CF2Br","c2f4br2"],"l":"가"},{"a":"CF2ClBr","syn":["CBrClF2","BrCF2Cl","CF2BrCl","cf2clbr"],"l":"나"},{"a":"CHF3","syn":["chf3","HCF3"],"l":"다"},{"a":"C2HF5","syn":["CF3CHF2","CHF2CF3","CF3CF2H","c2hf5"],"l":"라"},{"a":"C2F5COCF(CF3)2","syn":["C2F5COC3F7","CF3CF2C(O)CF(CF3)2","CF3CF2C(=O)CF(CF3)2","C6F12O","C2F5C(O)CF(CF3)2","CF3CF2COCF(CF3)2"],"l":"마"}],"순서무관":false},{"id":"2024-3-05","y":2024,"r":3,"n":5,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"메틸알코올에 대하여 다음 물음에 답하시오.\n가. 연소반응식\n나. 옥내저장소에서 저장 시 바닥면적\n다. 산화 시 생성되는 제2석유류 위험물의 명칭","a":"가. 2CH3OH + 3O2 → 2CO2 + 4H2O\n나. 1,000m2\n다. 포름산","h":"메탄올은 제4류 알코올류이고 지정수량 400L, 위험등급 II 다. 산화하면 포름알데하이드를 거쳐 포름산(제2석유류)이 된다. 옥내저장소 바닥면적은 제4류 중 등급 I·II 이면 1,000m2 라서 메탄올도 1,000m2이다.","t":"kan","칸":[{"a":"2CH3OH+3O2→2CO2+4H2O","syn":["2CH3OH+3O2->2CO2+4H2O","2CH3OH+3O2=2CO2+4H2O","CH3OH+3/2O2→CO2+2H2O","CH3OH+3/2O2->CO2+2H2O","CH3OH+1.5O2→CO2+2H2O","2CH3OH+3O2→4H2O+2CO2"],"l":"가"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"나"},{"a":"포름산","syn":["개미산","의산","HCOOH","폼산","포름 산"],"l":"다"}],"순서무관":false},{"id":"2024-3-06","y":2024,"r":3,"n":6,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"에틸알코올에 대하여 다음 물음에 답하시오.\n가. 나트륨과 반응 시 생성되는 기체의 화학식\n나. 황산이 촉매작용하여 탈수축합 시 생성되는 위험물의 명칭\n다. 산화 시 특수인화물","a":"가. H2\n나. 다이에틸에터\n다. 아세트알데하이드","h":"에탄올은 나트륨과 2Na + 2C2H5OH → 2C2H5ONa + H2 로 반응해 수소를 낸다. 황산을 촉매로 에탄올 두 분자에서 물 한 분자가 빠져 합쳐지면 다이에틸에터가 된다. 산화하면 특수인화물인 아세트알데하이드를 거쳐 아세트산까지 간다.","ai":"2024-3-06_a.svg","t":"kan","칸":[{"a":"H2","syn":["수소","수소가스","hydrogen"],"l":"가"},{"a":"다이에틸에터","syn":["디에틸에터","다이에틸에테르","디에틸에테르","에터","에테르","C2H5OC2H5","에틸에터","에틸에테르","(C2H5)2O"],"l":"나"},{"a":"아세트알데하이드","syn":["아세트알데히드","아세트알데이드","CH3CHO","acetaldehyde"],"l":"다"}],"순서무관":false},{"id":"2024-3-07","y":2024,"r":3,"n":7,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제4류 위험물의 정의에 대하여 빈칸에 알맞은 값을 쓰시오.\n• 제1석유류 : 아세톤, 휘발유 그 밖에 1기압에서 인화점 섭씨 ( 가 )도 미만인 것을 말한다.\n• 제2석유류 : 등유, 경유 그 밖에 1기압에서 인화점이 섭씨 ( 가 )도 이상 ( 나 )도 미만인 것을 말한다. 다만, 도료류 그 밖의 물품에 있어서 가연성 액체량이 ( 다 )중량퍼센트 이하이면서 인화점이 섭씨 40도 이상인 동시에 연소점이 섭씨 60도 이상인 것은 제외한다.\n• 제3석유류 : 중유, 크레오소트유, 그 밖에 1기압에서 인화점이 섭씨 ( 나 )도 이상 ( 라 )도 미만인 것을 말한다. 다만, 도료류 그 밖의 물품은 가연성 액체량이 ( 다 )중량퍼센트 이하인 것은 제외한다.\n• 제4석유류 : 기어유, 실린더유, 그 밖에 1기압에서 인화점이 섭씨 ( 라 )도 이상 ( 마 )도 미만인 것을 말한다. 다만, 도료류 그 밖의 물품은 가연성 액체량이 40중량퍼센트 이하인 것은 제외한다.","a":"가. 21\n나. 70\n다. 40\n라. 200\n마. 250","h":"인화점은 제1석유류 21℃ 미만, 제2석유류 21℃ 이상 70℃ 미만, 제3석유류 70℃ 이상 200℃ 미만, 제4석유류 200℃ 이상 250℃ 미만이다. 앞 품명의 상한이 다음 품명의 하한과 같아서 21·70·200·250 네 수가 이어진다. 도료류 등은 가연성 액체량이 40중량퍼센트 이하이면 제외한다.","t":"kan","칸":[{"a":"21","syn":["21℃","21도"],"l":"가"},{"a":"70","syn":["70℃","70도"],"l":"나"},{"a":"40","syn":["40%","40중량%","40중량퍼센트"],"l":"다"},{"a":"200","syn":["200℃","200도"],"l":"라"},{"a":"250","syn":["250℃","250도"],"l":"마"}],"순서무관":false},{"id":"2024-3-08","y":2024,"r":3,"n":8,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에서 정한 안전관리자에 대한 내용이다. 다음 물음에 답하시오.\n가. 안전관리자를 선임하여야 하는 대상을 보기에서 1가지 고르시오 (단, 없으면 없음이라 표기하시오).\n제조소등의 관계인, 제조소등의 설치자, 소방서장, 소방청장, 시, 도지사\n나. 안전관리자 해임 후 재선임 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).\n다. 안전관리자 퇴직 후 재선임 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).\n라. 안전관리자 선임 후 신고 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).\n마. 안전관리자가 여행, 질병 그 밖의 사유로 인하여 일시적으로 직무를 수행할 수 없을 때 직무를 대행하는 기간을 쓰시오 (제한 없으면 제한 없음이라 표기).","a":"가. 제조소등의 관계인\n나. 30일\n다. 30일\n라. 14일\n마. 30일","h":"안전관리자는 제조소등의 관계인이 선임한다. 해임이나 퇴직 뒤 재선임은 30일 이내, 선임 뒤 신고는 14일 이내이고, 대리자가 직무를 대행하는 기간은 30일을 넘을 수 없다.","t":"kan","칸":[{"a":"제조소등의 관계인","syn":["관계인","제조소 등의 관계인","제조소등 관계인"],"l":"가"},{"a":"30일","syn":["30","30일 이내"],"l":"나"},{"a":"30일","syn":["30","30일 이내"],"l":"다"},{"a":"14일","syn":["14","14일 이내"],"l":"라"},{"a":"30일","syn":["30","30일 이내"],"l":"마"}],"순서무관":false},{"id":"2024-3-09","y":2024,"r":3,"n":9,"p":"계산","kw":"탱크 용량","pt":5,"q":"다음 탱크의 최대 용량과 최소 용량을 구하시오 (a = 1.5m, b = 2m, l = 3m, l1 = 0.3m, l2 = 0.3m이다).","a":"① 내용적 V = π × (a×b/4) × (l + (l1+l2)/3) = π × (1.5×2/4) × (3 + 0.6/3) = 7.54m3\n② 공간용적은 내용적의 5% 이상 10% 미만이므로 최대용량은 5%, 최소용량은 10% 를 뺀다.\n③ 최대용량 = 7.54 × 0.95 ≒ 7.16m3\n④ 최소용량 = 7.54 × 0.90 ≒ 6.79m3\n답: 최대용량 7.16m3, 최소용량 6.79m3","h":"탱크 용량은 내용적에서 공간용적을 뺀 값이다. 공간용적이 가장 작은 5% 일 때 용량이 최대, 가장 큰 10% 일 때 최소가 된다. 양 끝이 볼록한 가로형 탱크의 내용적은 π × (a×b/4) × (l + (l1+l2)/3) 로 구한다.","img":["2024-3-09.svg"],"tp":"W04","t":"kan","칸":[{"a":"7.16","e":0.05,"l":"최대용량"},{"a":"6.79","e":0.05,"l":"최소용량"}],"순서무관":false},{"id":"2024-3-10","y":2024,"r":3,"n":10,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"옥내저장소에서 위험물을 저장하는 경우이다. 각 물음에 답을 쓰시오.\n가. 기계에 의하여 하역하는 구조로 된 용기만을 겹쳐 쌓는 경우 몇 m를 초과하지 못하는가?\n나. 제4류 위험물 중 제3석유류를 수납하는 용기만을 겹쳐 쌓는 경우 몇 m를 초과하지 못하는가?\n다. 제4류 위험물 중 동식물유류를 수납하는 용기만을 겹쳐 쌓는 경우 몇 m를 초과하지 못하는가?","a":"가. 6m\n나. 4m\n다. 4m","h":"옥내저장소에서 용기만 겹쳐 쌓을 때 높이는 기계 하역 구조면 6m, 제3석유류·제4석유류·동식물유류면 4m, 그 밖에는 3m 까지다. 제4류라도 제1석유류와 제2석유류는 4m 칸에 들지 않고 3m이다.","t":"kan","칸":[{"a":"6","syn":["6m","6 m","6미터"],"l":"가"},{"a":"4","syn":["4m","4 m","4미터"],"l":"나"},{"a":"4","syn":["4m","4 m","4미터"],"l":"다"}],"순서무관":false},{"id":"2024-3-11","y":2024,"r":3,"n":11,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 보기의 위험물이 해당하는 위험물의 품명에 알맞게 쓰시오 (단, 없으면 해당없음을 쓰시오).\n[보기]\n나이트로메탄, 나이트로에탄, 다이나이트로벤젠, 나이트로글리콜, 나이트로셀룰로오스, 나이트로글리세린, 벤조일퍼옥사이드\n가. 유기과산화물\n나. 나이트로화합물\n다. 질산에스터류\n라. 아조화합물\n마. 하이드라진유도체","a":"가. 벤조일퍼옥사이드\n나. 나이트로메탄, 나이트로에탄, 다이나이트로벤젠\n다. 나이트로글리콜, 나이트로셀룰로오스, 나이트로글리세린\n라. 해당없음\n마. 해당없음","h":"나이트로메탄·나이트로에탄·다이나이트로벤젠은 나이트로화합물(제2종, 100kg), 나이트로글리콜·나이트로셀룰로오스·나이트로글리세린은 질산에스터류(제1종, 10kg), 벤조일퍼옥사이드는 유기과산화물(제2종, 100kg)이다. 아조화합물과 하이드라진유도체에 속하는 물질은 보기에 없다.","t":"kan","칸":[{"a":"벤조일퍼옥사이드","syn":["과산화벤조일","BPO","벤조일퍼옥시드","벤조일 퍼옥사이드","벤조일퍼옥사이드(BPO)","(C6H5CO)2O2"],"l":"가"},{"a":"나이트로메탄, 나이트로에탄, 다이나이트로벤젠","k":[["나이트로메탄","니트로메탄"],["나이트로에탄","니트로에탄"],["다이나이트로벤젠","디니트로벤젠","다이니트로벤젠","디나이트로벤젠"]],"l":"나"},{"a":"나이트로글리콜, 나이트로셀룰로오스, 나이트로글리세린","k":[["나이트로글리콜","니트로글리콜"],["나이트로셀룰로오스","니트로셀룰로오스","나이트로셀룰로스","니트로셀룰로스"],["나이트로글리세린","니트로글리세린"]],"l":"다"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"마"}],"순서무관":false},{"id":"2024-3-12","y":2024,"r":3,"n":12,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물 중에서 물과 반응하여 산소를 발생하며 열분해하여 산소를 발생하는 물질에 대하여 다음 물음에 답하시오.\n질산암모늄, 과산화나트륨, 과염소산나트륨, 과염소산암모늄\n가. 분해반응식\n나. 물과의 반응식","a":"가. 2Na2O2 → 2Na2O + O2\n나. 2Na2O2 + 2H2O → 4NaOH + O2","h":"열분해해도, 물과 반응해도 산소가 나오는 것은 무기과산화물인 과산화나트륨이다. 나머지 셋은 물과 반응해 산소를 내지 않는다. 두 식 모두 과산화나트륨 2분자에서 산소 1분자가 나온다.","t":"kan","칸":[{"a":"2Na2O2→2Na2O+O2","syn":["2Na2O2->2Na2O+O2","2Na2O2=2Na2O+O2","Na2O2→Na2O+1/2O2","Na2O2->Na2O+1/2O2","2Na2O2→2Na2O+O2↑"],"l":"가"},{"a":"2Na2O2+2H2O→4NaOH+O2","syn":["2Na2O2+2H2O->4NaOH+O2","2Na2O2+2H2O=4NaOH+O2","Na2O2+H2O→2NaOH+1/2O2","Na2O2+H2O->2NaOH+1/2O2"],"l":"나"}],"순서무관":false},{"id":"2024-3-13","y":2024,"r":3,"n":13,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 보기의 위험물을 인화점이 낮은 것에 높은 것 순서대로 쓰시오.\n스티렌, 톨루엔, 벤젠, 에틸벤젠","a":"벤젠 - 톨루엔 - 에틸벤젠 - 스티렌","h":"인화점은 벤젠 -11℃, 톨루엔 4℃, 에틸벤젠 15℃, 스티렌 32℃ 순으로 높아진다. 앞의 셋은 제1석유류이고 스티렌만 제2석유류라서 인화점이 가장 높다.","t":"kan","칸":[{"a":"벤젠","syn":["C6H6","benzene","벤졸"],"l":"1"},{"a":"톨루엔","syn":["툴루엔","C6H5CH3","toluene","메틸벤젠"],"l":"2"},{"a":"에틸벤젠","syn":["에틸 벤젠","C6H5C2H5","ethylbenzene"],"l":"3"},{"a":"스티렌","syn":["스타이렌","스틸렌","스티렌","C6H5CH=CH2","styrene"],"l":"4"}],"순서무관":false},{"id":"2024-3-14","y":2024,"r":3,"n":14,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"옥외탱크저장소의 보유공지에 알맞은 값을 쓰시오.\n| 저장 또는 취급하는 위험물의 최대 수량 | 공지의 너비 |\n| 지정수량의 500배 이하 | 3m 이상 |\n| 지정수량의 500배 초과 1,000배 이하 | ( 가 )m 이상 |\n| 지정수량의 1,000배 초과 2,000배 이하 | 9m 이상 |\n| 지정수량의 2,000배 초과 3,000배 이하 | ( 나 )m 이상 |\n| 지정수량의 3,000배 초과 ( 다 )배 이하 | 15m 이상 |\n| 지정수량의 ( 다 )배 초과 | 당해 탱크의 수평단면의 최대지름(가로형인 경우에는 긴 변)과 높이 중 큰 것과 같은 거리 이상. 다만, ( 라 )m 초과의 경우 ( 라 )m 이상, ( 마 )m 미만의 경우 ( 마 )m 이상 |","a":"가. 5\n나. 12\n다. 4,000\n라. 30\n마. 15","h":"공지의 너비는 500배 이하 3m, 1,000배 이하 5m, 2,000배 이하 9m, 3,000배 이하 12m, 4,000배 이하 15m로 커진다. 4,000배를 넘으면 탱크의 최대지름(가로형은 긴 변)과 높이 중 큰 값과 같은 거리를 두되, 30m를 넘으면 30m 이상으로 할 수 있고 15m에 못 미치면 15m 이상으로 한다.","t":"kan","칸":[{"a":"5","syn":["5m","5m 이상","5미터"],"l":"가"},{"a":"12","syn":["12m","12m 이상","12미터"],"l":"나"},{"a":"4000","syn":["4,000","4000배","4,000배"],"l":"다"},{"a":"30","syn":["30m","30m 이상","30미터"],"l":"라"},{"a":"15","syn":["15m","15m 이상","15미터"],"l":"마"}],"순서무관":false},{"id":"2024-3-15","y":2024,"r":3,"n":15,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"탄화알루미늄과 물이 반응하여 생성되는 기체에 대하여 다음 물음에 답하시오.\n가. 연소반응식\n나. 연소범위\n다. 위험도","a":"가. CH4 + 2O2 → CO2 + 2H2O\n나. 5~15%\n다. 위험도 = (상한 - 하한) / 하한 = (15 - 5) / 5 = 2","h":"탄화알루미늄은 Al4C3 + 12H2O → 4Al(OH)3 + 3CH4 로 반응해 메테인을 낸다. 같은 탄화물이어도 탄화칼슘은 아세틸렌이 나오므로 기체가 서로 다르다. 메테인의 연소범위는 5~15%이고 위험도는 (15-5)/5 = 2 이다.","t":"kan","칸":[{"a":"CH4+2O2→CO2+2H2O","syn":["CH4+2O2->CO2+2H2O","CH4+2O2=CO2+2H2O"],"l":"가"},{"a":"5~15%","syn":["5-15","5~15","5∼15","5-15%","5~15 %","5% ~ 15%","5%~15%","5에서 15","5부터 15","5 ~ 15%","5 - 15%"],"l":"나"},{"a":"2","e":0.01,"l":"다"}],"순서무관":false},{"id":"2024-3-16","y":2024,"r":3,"n":16,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 제6류 위험물 중에서 위험물이 될 수 있는 조건을 쓰시오 (단, 없으면 없음이라 쓰시오).\n가. 과산화수소\n나. 과염소산\n다. 질산","a":"가. 농도 36중량퍼센트 이상\n나. 없음\n다. 비중 1.49 이상","h":"과산화수소는 농도 36중량퍼센트 이상, 질산은 비중 1.49 이상일 때만 위험물이다. 과염소산은 농도나 비중 조건이 없다. 제6류는 모두 지정수량이 300kg이다.","t":"kan","칸":[{"a":"농도 36중량퍼센트 이상","syn":["36","36wt%","36wt%이상","36중량%","36중량%이상","36중량퍼센트","36%","36% 이상","36 중량퍼센트 이상","36중량퍼센트 이상","농도 36중량퍼센트"],"l":"가"},{"a":"없음","syn":["없다","해당없음","해당 없음","-","없음."],"l":"나"},{"a":"비중 1.49 이상","syn":["1.49","1.49 이상","1.49이상","비중1.49","비중 1.49","비중1.49이상"],"l":"다"}],"순서무관":false},{"id":"2024-3-17","y":2024,"r":3,"n":17,"p":"물질·성상","kw":"소화약제","pt":5,"q":"분말소화약제에 대하여 다음 빈칸에 알맞은 말을 쓰시오.\n| 종류 | 화학식 | 색상 | 적응화재 |\n| 제1종 분말소화약제 | NaHCO3 | 백색 | ( 가 ) |\n| 제2종 분말소화약제 | ( 나 ) | ( 다 ) | BC |\n| 제3종 분말소화약제 | ( 라 ) | 담홍색 | ( 마 ) |","a":"가. BC\n나. KHCO3\n다. 담회색\n라. NH4H2PO4\n마. ABC","h":"제1종은 NaHCO3 로 백색·BC, 제2종은 KHCO3 로 담회색·BC, 제3종은 NH4H2PO4 로 담홍색·ABC 이다. A급 화재(일반화재)까지 듣는 것은 인산염인 제3종뿐이다. 제2종의 담회색과 제3종의 담홍색은 글자가 비슷하니 화학식과 묶어서 외운다.","t":"kan","칸":[{"a":"BC","syn":["B,C","B C","BC급","B급 C급","B, C"],"l":"가"},{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"나"},{"a":"담회색","syn":["담 회색","회색","연회색","담회"],"l":"다"},{"a":"NH4H2PO4","syn":["인산암모늄","제일인산암모늄","인산이수소암모늄","(NH4)H2PO4"],"l":"라"},{"a":"ABC","syn":["A,B,C","A B C","ABC급","A, B, C","A급 B급 C급"],"l":"마"}],"순서무관":false},{"id":"2024-3-18","y":2024,"r":3,"n":18,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"위험물안전관리법령상 휘발유를 주입할 때 다음 물음에 답하시오.\n• 휘발유, 벤젠 그 밖에 정전기에 의한 재해가 발생할 우려가 있는 액체위험물의 옥외저장탱크의 주입구 부근에는 정전기를 유효하게 제거하기 위한 ( 가 )을 설치할 것\n• 셀프용고정주유설비의 1회의 연속주유량 및 주유시간의 상한을 미리 설정할 수 있는 구조일 것. 휘발유의 경우 연속주유량 ( 나 )L 이하, 주유시간 ( 다 )분 이하로 할 것\n• 등유 또는 경유를 저장하던 이동저장탱크에 휘발유를 주입할 때 정전기등에 의한 재해를 방지하기 위하여 이동저장탱크의 상부로부터 위험물을 주입할 때에는 위험물의 액표면이 주입관의 끝부분을 넘는 높이가 될 때까지 그 주입관 내의 유속을 초당 ( 라 )m 이하, 이동저장탱크의 밑부분으로부터 위험물을 주입할 때에는 위험물의 액표면이 주입관의 정상부분을 넘는 높이가 될 때까지 그 주입배관 내의 유속을 초당 ( 마 )m 이하로 할 것","a":"가. 접지전극\n나. 100\n다. 4\n라. 1\n마. 1","h":"휘발유처럼 정전기 재해 우려가 있는 액체위험물의 옥외저장탱크 주입구 부근에는 접지전극을 설치한다. 셀프 주유소의 1회 연속주유량은 휘발유 100L·4분 이하, 경유 600L·12분 이하다. 이동탱크에 휘발유를 넣을 때 주입관 속 유속은 위에서 넣든 밑에서 넣든 초당 1m 이하로 한다.","t":"kan","칸":[{"a":"접지전극","syn":["접지","접지 전극","접지설비","접지극","접지장치"],"l":"가"},{"a":"100","syn":["100L","100 L","100리터"],"l":"나"},{"a":"4","syn":["4분","4 분"],"l":"다"},{"a":"1","syn":["1m","1m/s","1미터"],"l":"라"},{"a":"1","syn":["1m","1m/s","1미터"],"l":"마"}],"순서무관":false},{"id":"2024-3-19","y":2024,"r":3,"n":19,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"제1류 위험물인 염소산칼륨에 관한 내용이다. 다음 각 물음에 답을 쓰시오.\n가. 완전분해 반응식\n나. 염소산칼륨 24.5kg이 표준상태에서 완전 분해 시 생성되는 산소의 부피(m3) (단, 염소산칼륨의 분자량은 123이다)","a":"가. 2KClO3 → 2KCl + 3O2\n나. ① 주어진 값: w = 24.5kg, M = 123kg/kmol, P = 1atm, T = 0 + 273 = 273K, R = 0.082atm·m3/kmol·K\n② 식: V = wRT/PM × (3O2 / 2KClO3)\n③ 대입: V = (24.5×0.082×273) / (1×123) × 3/2\n④ 답: 6.69m3","h":"KClO3 2분자가 분해되면 O2 3분자가 나오므로 산소 몰수는 염소산칼륨의 1.5배다. 표준상태에서 PV = (w/M)RT 에 24.5kg과 분자량 123 을 넣은 값에 3/2 를 곱하면 산소 부피가 나온다.","tp":"W01","t":"kan","칸":[{"a":"2KClO3→2KCl+3O2","syn":["2KClO3->2KCl+3O2","2KClO3=2KCl+3O2","KClO3→KCl+3/2O2","KClO3->KCl+3/2O2"],"l":"가"},{"a":"6.69","e":0.05,"l":"나"}],"순서무관":false},{"id":"2024-3-20","y":2024,"r":3,"n":20,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물 혼재 기준에 따라 다음 물음에 답하시오.\n가. 혼재 기준이 적용되지 않는 지정수량의 조건은 무엇인가?\n나. 다음 표에 위험물 운반에 관한 혼재기준에 맞게 ○와 ×를 채우시오.\n| 위험물의 구분 | 제1류 | 제2류 | 제3류 | 제4류 | 제5류 | 제6류 |\n| 제1류 | — |   |   |   |   |   |\n| 제2류 |   | — |   |   |   |   |\n| 제3류 |   |   | — |   |   |   |\n| 제4류 |   |   |   | — |   |   |\n| 제5류 |   |   |   |   | — |   |\n| 제6류 |   |   |   |   |   | — |","a":"가. 지정수량 배수의 1/10 이하\n나. 혼재할 수 있는 조합만 ○, 나머지는 ×\n제1류-제6류, 제2류-제4류, 제2류-제5류, 제3류-제4류, 제4류-제5류 (표는 대각선을 기준으로 대칭)","h":"지정수량의 1/10 을 넘을 때만 혼재 기준이 적용된다. 혼재할 수 있는 조합은 4류와 2·3류, 5류와 2·4류, 6류와 1류다. 표에서는 이 조합에만 ○ 를 쓰고 나머지 칸은 ×로 둔다.","t":"kan","칸":[{"a":"지정수량 배수의 1/10 이하","k":[["1/10","10분의 1","십분의 일","0.1","10분의1"],["이하"]],"l":"가"}],"순서무관":false},{"id":"2025-1-01","y":2025,"r":1,"n":1,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물을 운반할 때 취급하는 위험물의 지정수량이 1/10을 초과할 경우 다음 각 유별에 따른 혼재가 가능한 위험물을 쓰시오.\n가. 제2류 위험물\n나. 제3류 위험물\n다. 제4류 위험물","a":"가. 제4류 위험물, 제5류 위험물\n나. 제4류 위험물\n다. 제2류 위험물, 제3류 위험물, 제5류 위험물","h":"지정수량 1/10 초과 시 혼재 가능한 조합은 4류-2·3류, 5류-2·4류, 6류-1류다. 제2류는 4·5류, 제3류는 4류, 제4류는 2·3·5류와 섞을 수 있다.","t":"kan","칸":[{"a":"제4류 위험물, 제5류 위험물","k":[["4류"],["5류"]],"l":"가"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"나"},{"a":"제2류 위험물, 제3류 위험물, 제5류 위험물","k":[["2류"],["3류"],["5류"]],"l":"다"}],"순서무관":false},{"id":"2025-1-02","y":2025,"r":1,"n":2,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법에서 산화성고체 내의 다음 용어의 정의를 쓰시오.\n가. 액체의 정의\n나. 기체의 정의","a":"가. 1기압 및 섭씨 20도에서 액상인 것 또는 섭씨 20도 초과 섭씨 40도 이하에서 액상인 것\n나. 1기압 및 섭씨 20도에서 기상인 것","h":"법령상 액체는 1기압·20℃에서 액상이거나 20℃ 초과 40℃ 이하에서 액상인 것이고, 기체는 1기압·20℃에서 기상인 것이다. 고체는 이 둘에 들지 않는 것이다. 액상 여부는 안지름 30mm, 높이 120mm 시험관에 시료를 55mm 채워 눕혔을 때 액면 선단이 30mm 움직이는 데 90초 이내 걸리는지로 가른다.","t":"kan","칸":[{"a":"1기압 및 섭씨 20도에서 액상인 것 또는 섭씨 20도 초과 섭씨 40도 이하에서 액상인 것","k":[["20"],["40"],["액상"]],"l":"가"},{"a":"1기압 및 섭씨 20도에서 기상인 것","k":[["20"],["기상"]],"l":"나"}],"순서무관":false},{"id":"2025-1-03","y":2025,"r":1,"n":3,"p":"물질·성상","kw":"소화약제","pt":5,"q":"분말소화약제의 화학식을 쓰시오.\n가. 제1종 분말소화약제\n나. 제2종 분말소화약제\n다. 제3종 분말소화약제","a":"가. NaHCO3\n나. KHCO3\n다. NH4H2PO4","h":"제1종은 탄산수소나트륨 NaHCO3, 제2종은 탄산수소칼륨 KHCO3, 제3종은 인산암모늄 NH4H2PO4 이다. 제1·2종은 BC급, 제3종만 ABC급에 쓴다. 제1종 분해식은 2NaHCO3 → Na2CO3 + CO2 + H2O 이다.","t":"kan","칸":[{"a":"NaHCO3","syn":["탄산수소나트륨","중탄산나트륨","중탄산소다","탄산수소소다"],"l":"가"},{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"나"},{"a":"NH4H2PO4","syn":["인산암모늄","제일인산암모늄","인산이수소암모늄","인산이수소 암모늄","(NH4)H2PO4"],"l":"다"}],"순서무관":false},{"id":"2025-1-04","y":2025,"r":1,"n":4,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"위험물안전관리법령상 자동화재탐지설비 설치기준에 맞추어 다음 빈칸을 채우시오.\n• 자동화재탐지설비의 경계구역(화재가 발생한 구역을 다른 구역과 구분하여 식별할 수 있는 최소단위의 구역을 말한다. 이하 이 호에서 같다)은 건축물 그 밖의 공작물의 2 이상의 층에 걸치지 아니하도록 할 것. 다만, 하나의 경계구역의 면적이 ( 가 )m2 이하이면서 당해 경계구역이 두개의 층에 걸치는 경우이거나 계단·경사로·승강기의 승강로 그 밖에 이와 유사한 장소에 연기감지기를 설치하는 경우에는 그러하지 아니하다.\n• 하나의 경계구역의 면적은 ( 나 )m2 이하로 하고 그 한 변의 길이는 ( 다 )m(광전식분리형 감지기를 설치할 경우에는 ( 라 )m 이하로 할 것. 다만, 당해 건축물 그 밖의 공작물의 주요한 출입구에서 그 내부의 전체를 볼 수 있는 경우에 있어서는 그 면적을 ( 마 )m2 이하로 할 수 있다","a":"가. 500\n나. 600\n다. 50\n라. 100\n마. 1,000","h":"자동화재탐지설비 경계구역은 2개 층에 걸치지 않는 것이 원칙이며, 면적이 500m2 이하이면 두 층에 걸칠 수 있다. 한 경계구역은 600m2 이하, 한 변 50m 이하(광전식분리형 감지기는 100m 이하)이고, 출입구에서 내부 전체가 보이면 1,000m2까지 할 수 있다.","t":"kan","칸":[{"a":"500","syn":["500m2","500㎡"],"l":"가"},{"a":"600","syn":["600m2","600㎡"],"l":"나"},{"a":"50","syn":["50m"],"l":"다"},{"a":"100","syn":["100m"],"l":"라"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡"],"l":"마"}],"순서무관":false},{"id":"2025-1-05","y":2025,"r":1,"n":5,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"다음 위험물의 증기비중을 구하시오.\n가. 이황화탄소\n나. 아세트알데하이드\n다. 벤젠","a":"증기비중 = 분자량 / 29\n가. CS2 = 12 + 32×2 = 76 → 76/29 = 2.62\n나. CH3CHO = 44 → 44/29 = 1.52\n다. C6H6 = 78 → 78/29 = 2.69","h":"증기비중은 분자량을 공기의 평균 분자량 29 로 나눈 값이다. 이황화탄소 76, 아세트알데하이드 44, 벤젠 78 로 모두 1보다 커서 증기가 공기보다 무겁다.","t":"kan","칸":[{"a":"2.62","e":0.01,"l":"가"},{"a":"1.52","e":0.01,"l":"나"},{"a":"2.69","e":0.01,"l":"다"}],"순서무관":false},{"id":"2025-1-06","y":2025,"r":1,"n":6,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"제1류 위험물인 염소산칼륨에 관한 내용이다. 다음 각 물음에 답을 쓰시오.\n가. 완전분해 반응식\n나. 염소산칼륨 1kg이 표준상태에서 완전 분해 시 생성되는 산소의 부피(m3) (단, 염소산칼륨의 분자량은 123이다)","a":"가. 2KClO3 → 2KCl + 3O2\n나. ① 주어진 값: w = 1kg, M = 123kg/kmol, 표준상태 0℃ 1atm, R = 0.082atm·m3/kmol·K\n② 식: V = (wRT/PM) × (3/2)\n③ 대입: V = (1×0.082×273)/(1×123) × 3/2\n④ 답: 0.27m3 (0.273m3)","h":"KClO3 2몰에서 O2 3몰이 나오므로 KClO3 1몰당 O2 1.5몰이다. 1kg 기준으로 계산하면 0.273m3이다. 13.65m3는 50kg으로 계산한 값이다.","tp":"W01","t":"kan","칸":[{"a":"2KClO3→2KCl+3O2","syn":["2KClO3->2KCl+3O2","2KClO3=2KCl+3O2","KClO3→KCl+3/2O2","KClO3->KCl+3/2O2"],"l":"가"},{"a":"0.27","e":0.01,"l":"나"}],"순서무관":false},{"id":"2025-1-07","y":2025,"r":1,"n":7,"p":"시설·법령","kw":"취급소(주유·판매·이송)","pt":5,"q":"위험물안전관리법령상 주유취급소 기준에 따라 다음 물음에 답하시오.\n가. 고정주유설비와 도로경계선까지의 거리\n나. 고정급유설비와 도로경계선까지의 거리\n다. 고정주유설비와 부지경계선까지의 거리\n라. 고정급유설비와 부지경계선까지의 거리\n마. 고정주유설비와 개구부 없는 벽까지의 거리","a":"가. 4m 이상\n나. 4m 이상\n다. 2m 이상\n라. 1m 이상\n마. 1m 이상","h":"도로경계선까지는 고정주유설비·고정급유설비 모두 4m 이상이다. 부지경계선까지는 주유설비 2m, 급유설비 1m 이상이고, 개구부 없는 벽까지는 둘 다 1m 이상이다.","t":"kan","칸":[{"a":"4","syn":["4m","4m 이상","4미터"],"l":"가"},{"a":"4","syn":["4m","4m 이상","4미터"],"l":"나"},{"a":"2","syn":["2m","2m 이상","2미터"],"l":"다"},{"a":"1","syn":["1m","1m 이상","1미터"],"l":"라"},{"a":"1","syn":["1m","1m 이상","1미터"],"l":"마"}],"순서무관":false},{"id":"2025-1-08","y":2025,"r":1,"n":8,"p":"반응식","kw":"물과 반응","pt":5,"q":"보기에서 설명하는 물질에 대하여 다음 물음에 답하시오.\n[보기]\n• 제3류 위험물 중 지정수량 300kg\n• 분자량 64\n• 비중 2.2\n• 질소와 반응하여 석회질소 생성\n가. 화학식\n나. 물과의 화학반응식\n다. 발생되는 기체의 완전 연소반응식","a":"가. CaC2\n나. CaC2 + 2H2O → Ca(OH)2 + C2H2\n다. 2C2H2 + 5O2 → 4CO2 + 2H2O","h":"지정수량 300kg, 분자량 64, 질소와 반응해 석회질소가 되는 제3류 물질은 탄화칼슘이다. 물과는 아세틸렌을 내고, 그 아세틸렌의 연소식은 2C2H2 + 5O2 → 4CO2 + 2H2O 다. 탄화알루미늄은 같은 탄화물이지만 물과 반응하면 메테인이 나온다.","t":"kan","칸":[{"a":"CaC2","syn":["탄화칼슘","카바이드","칼슘카바이드","탄화 칼슘"],"l":"가"},{"a":"CaC2+2H2O→Ca(OH)2+C2H2","syn":["CaC2+2H2O->Ca(OH)2+C2H2","CaC2+2H2O=Ca(OH)2+C2H2","CaC2+2H2O→C2H2+Ca(OH)2","CaC2+2H2O->C2H2+Ca(OH)2"],"l":"나"},{"a":"2C2H2+5O2→4CO2+2H2O","syn":["2C2H2+5O2->4CO2+2H2O","2C2H2+5O2=4CO2+2H2O","C2H2+5/2O2→2CO2+H2O","C2H2+5/2O2->2CO2+H2O","C2H2+2.5O2→2CO2+H2O"],"l":"다"}],"순서무관":false},{"id":"2025-1-09","y":2025,"r":1,"n":9,"p":"반응식","kw":"물과 반응","pt":5,"q":"제3류 위험물 중 탄화알루미늄에 대하여 다음 물음에 답하시오.\n가. 물과의 반응식\n나. 가.에서 생성되는 가연성기체의 연소반응식","a":"가. Al4C3 + 12H2O → 4Al(OH)3 + 3CH4\n나. CH4 + 2O2 → CO2 + 2H2O","h":"탄화알루미늄은 물과 반응해 수산화알루미늄과 메테인이 된다. 메테인 연소는 CH4 + 2O2 → CO2 + 2H2O 다. 탄화칼슘은 물과 반응해 아세틸렌이 나오므로 생성 기체가 다르다.","t":"kan","칸":[{"a":"Al4C3+12H2O→4Al(OH)3+3CH4","syn":["Al4C3+12H2O->4Al(OH)3+3CH4","Al4C3+12H2O=4Al(OH)3+3CH4","Al4C3+12H2O→3CH4+4Al(OH)3","Al4C3+12H2O->3CH4+4Al(OH)3"],"l":"가"},{"a":"CH4+2O2→CO2+2H2O","syn":["CH4+2O2->CO2+2H2O","CH4+2O2=CO2+2H2O"],"l":"나"}],"순서무관":false},{"id":"2025-1-10","y":2025,"r":1,"n":10,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"위험물안전관리법령상 기계에 의하여 하역하는 구조로 된 운반용기의 기준이다. 다음 물음에 답하시오.\n가. 위험물안전관리법상 소방청장이 고시한 운반용기 시험 종류 3가지를 쓰시오.\n나. 가.의 시험을 적용하지 않아도 되는 위험물을 모두 고르시오.\n① 칼륨 ② 제3석유류 ③ 동식물유류\n④ 과산화수소 ⑤ 금속의 인화물 ⑥ 아조화합물","a":"가. 낙하시험, 기밀시험, 내압시험 (이 밖에 겹쳐쌓기시험, 아랫부분 인상시험, 윗부분 인상시험, 파열전파시험, 넘어뜨리기시험, 일으키기시험이 있다)\n나. ②, ③","h":"소방청장이 고시하는 운반용기 시험은 낙하·기밀·내압·겹쳐쌓기·아랫부분 인상·윗부분 인상·파열전파·넘어뜨리기·일으키기 시험이다. 제3석유류, 제4석유류, 동식물유류를 담는 용기는 이 시험을 하지 않아도 된다(제2석유류는 인화점 61℃ 이상인 것).","t":"kan","칸":[{"a":"낙하시험","syn":["낙하 시험","기밀시험","기밀 시험","내압시험","내압 시험","수압시험","겹쳐쌓기시험","겹쳐쌓기 시험","아랫부분인상시험","아랫부분 인상시험","윗부분인상시험","윗부분 인상시험","파열전파시험","파열전파 시험","넘어뜨리기시험","넘어뜨리기 시험","일으키기시험","일으키기 시험"],"l":"가-1"},{"a":"기밀시험","syn":["낙하시험","낙하 시험","기밀 시험","내압시험","내압 시험","수압시험","겹쳐쌓기시험","겹쳐쌓기 시험","아랫부분인상시험","아랫부분 인상시험","윗부분인상시험","윗부분 인상시험","파열전파시험","파열전파 시험","넘어뜨리기시험","넘어뜨리기 시험","일으키기시험","일으키기 시험"],"l":"가-2"},{"a":"내압시험","syn":["낙하시험","낙하 시험","기밀시험","기밀 시험","내압 시험","수압시험","겹쳐쌓기시험","겹쳐쌓기 시험","아랫부분인상시험","아랫부분 인상시험","윗부분인상시험","윗부분 인상시험","파열전파시험","파열전파 시험","넘어뜨리기시험","넘어뜨리기 시험","일으키기시험","일으키기 시험"],"l":"가-3"},{"a":"②, ③","k":[["②","2"],["③","3"]],"l":"나"}],"순서무관":false},{"id":"2025-1-11","y":2025,"r":1,"n":11,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 위험물의 연소반응식을 쓰시오.\n가. 삼황화인\n나. 오황화인\n다. 알루미늄분","a":"가. P4S3 + 8O2 → 3SO2 + 2P2O5\n나. 2P2S5 + 15O2 → 10SO2 + 2P2O5\n다. 4Al + 3O2 → 2Al2O3","h":"황화인은 연소하면 이산화황과 오산화인이 되고, 알루미늄은 산화알루미늄이 된다. O2 계수는 삼황화인 8, 오황화인 15, 알루미늄 3 이다. 오황화인과 알루미늄은 계수가 분수로 나와서 양변에 2 또는 4 를 곱해 정수로 맞춘다.","t":"kan","칸":[{"a":"P4S3+8O2→3SO2+2P2O5","syn":["P4S3+8O2->3SO2+2P2O5","P4S3+8O2=3SO2+2P2O5","P4S3+8O2→2P2O5+3SO2","P4S3+8O2->2P2O5+3SO2"],"l":"가"},{"a":"2P2S5+15O2→10SO2+2P2O5","syn":["2P2S5+15O2->10SO2+2P2O5","2P2S5+15O2=10SO2+2P2O5","2P2S5+15O2→2P2O5+10SO2","2P2S5+15O2->2P2O5+10SO2","P2S5+15/2O2→5SO2+P2O5","P2S5+15/2O2->5SO2+P2O5"],"l":"나"},{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3","2Al+3/2O2→Al2O3"],"l":"다"}],"순서무관":false},{"id":"2025-1-12","y":2025,"r":1,"n":12,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"제6류 위험물 중 한 물질이 하이드라진과 만나면 격렬히 반응하고 폭발한다. 다음 각 물음에 답을 쓰시오.\n가. 위험물일 조건\n나. 하이드라진과의 폭발반응식","a":"가. 36중량퍼센트 이상\n나. 2H2O2 + N2H4 → N2 + 4H2O","h":"과산화수소는 농도 36중량퍼센트 이상일 때 위험물이고, 하이드라진과 닿으면 2H2O2 + N2H4 → N2 + 4H2O 로 폭발한다. 생성물은 질소와 물뿐이다. 제6류 중 기준이 붙는 것은 과산화수소와 질산(비중 1.49 이상)이다.","t":"kan","칸":[{"a":"36중량퍼센트 이상","syn":["36","36wt%","36wt%이상","36중량%","36중량%이상","36중량퍼센트","36%","36% 이상","36 중량퍼센트 이상"],"l":"가"},{"a":"2H2O2+N2H4→N2+4H2O","syn":["2H2O2+N2H4->N2+4H2O","2H2O2+N2H4=N2+4H2O","N2H4+2H2O2→N2+4H2O","N2H4+2H2O2->N2+4H2O"],"l":"나"}],"순서무관":false},{"id":"2025-1-13","y":2025,"r":1,"n":13,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"제5류 위험물 중 유기과산화물(제1종)을 옥내저장소에 저장할 때 다음 기준에 알맞은 답을 쓰시오.\n가. 위험등급\n나. 바닥면적\n다. 철근콘크리트 구조로 된 외벽의 두께","a":"가. I\n나. 1,000m2\n다. 20cm","h":"유기과산화물(제1종)은 제5류 위험등급 I 이라 옥내저장소 바닥면적이 1,000m2 이하다. 지정과산화물 저장창고의 외벽은 두께 20cm 이상의 철근콘크리트조나 철골철근콘크리트조로 한다(보강콘크리트블록조는 30cm 이상). 격벽은 이보다 두꺼운 30cm 이상이다.","t":"kan","칸":[{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"가"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"나"},{"a":"20","syn":["20cm","20cm 이상","20센티미터"],"l":"다"}],"순서무관":false},{"id":"2025-1-14","y":2025,"r":1,"n":14,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 위험물에 대하여 시성식을 쓰시오.\n가. 나이트로글리세린\n나. 트라이나이트로톨루엔\n다. 트라이나이트로페놀\n라. 아조벤젠\n마. 질산메틸","a":"가. C3H5(ONO2)3\n나. C6H2(NO2)3CH3\n다. C6H2(NO2)3OH\n라. C6H5N=NC6H5\n마. CH3ONO2","h":"나이트로글리세린과 질산메틸은 질산에스터류, 트라이나이트로톨루엔과 트라이나이트로페놀은 나이트로화합물, 아조벤젠은 아조화합물이다. 벤젠고리에 NO2 세 개가 붙고 CH3 가 있으면 톨루엔 쪽, OH 가 있으면 페놀 쪽이다.","ai":"2025-1-14_a.svg","t":"kan","칸":[{"a":"C3H5(ONO2)3","syn":["C3H5N3O9","C3H5(NO3)3","CH2(ONO2)CH(ONO2)CH2(ONO2)"],"l":"가"},{"a":"C6H2(NO2)3CH3","syn":["C6H2CH3(NO2)3","CH3C6H2(NO2)3","C7H5N3O6","C6H2(CH3)(NO2)3"],"l":"나"},{"a":"C6H2(NO2)3OH","syn":["C6H2OH(NO2)3","HOC6H2(NO2)3","C6H3N3O7","C6H2(OH)(NO2)3","OHC6H2(NO2)3"],"l":"다"},{"a":"C6H5N=NC6H5","syn":["C6H5-N=N-C6H5","C12H10N2","C6H5NNC6H5"],"l":"라"},{"a":"CH3ONO2","syn":["CH3NO3","CH3-O-NO2","CH3(ONO2)"],"l":"마"}],"순서무관":false},{"id":"2025-1-15","y":2025,"r":1,"n":15,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물에 대하여 명칭과 지정수량을 쓰시오.\n가. CH3COCH3\n나. C6H5NO2\n다. C6H5Cl\n라. CH2=CHCOOH\n마. C6H12","a":"가. 아세톤, 400L\n나. 나이트로벤젠, 2,000L\n다. 클로로벤젠, 1,000L\n라. 아크릴산, 2,000L\n마. 사이클로헥세인, 200L","h":"아세톤(수용성)과 사이클로헥세인(비수용성)은 제1석유류, 클로로벤젠(비수용성)과 아크릴산(수용성)은 제2석유류, 나이트로벤젠은 제3석유류 비수용성이다. 지정수량은 제1석유류 비수용성 200L·수용성 400L, 제2석유류 비수용성 1,000L·수용성 2,000L, 제3석유류 비수용성 2,000L이다.","t":"kan","칸":[{"a":"아세톤, 400L","k":[["아세톤"],["400"]],"l":"가"},{"a":"나이트로벤젠, 2000L","k":[["나이트로벤젠","니트로벤젠"],["2000","2,000"]],"l":"나"},{"a":"클로로벤젠, 1000L","k":[["클로로벤젠","염화벤젠"],["1000","1,000"]],"l":"다"},{"a":"아크릴산, 2000L","k":[["아크릴산","acrylic"],["2000","2,000"]],"l":"라"},{"a":"사이클로헥세인, 200L","k":[["사이클로헥세인","사이클로헥산","시클로헥산","싸이클로헥세인","싸이클로헥산","시클로헥세인"],["200"]],"l":"마"}],"순서무관":false},{"id":"2025-1-16","y":2025,"r":1,"n":16,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제2류 위험물의 품명 및 지정수량을 알맞게 쓰시오.\n| 품명 | 지정수량 |\n| 철분 | 500kg |\n| ( 가 ) | 500kg |\n| 인화성고체 | ( 나 )kg |\n| 적린 | ( 다 )kg |\n| ( 라 ) | 100kg |\n| 황화인 | ( 마 )kg |\n| 금속분 | 500kg |","a":"가. 마그네슘\n나. 1,000\n다. 100\n라. 황\n마. 100","h":"제2류는 황·황화인·적린이 100kg, 철분·마그네슘·금속분이 500kg, 인화성고체가 1,000kg이다. 그래서 500kg 칸의 빈칸은 마그네슘, 100kg 칸의 빈칸은 황이다.","t":"kan","칸":[{"a":"마그네슘","syn":["Mg","마그네슘분"],"l":"가"},{"a":"1000","syn":["1,000","1000kg","1,000kg"],"l":"나"},{"a":"100","syn":["100kg"],"l":"다"},{"a":"황","syn":["유황","sulfur","S"],"l":"라"},{"a":"100","syn":["100kg"],"l":"마"}],"순서무관":false},{"id":"2025-1-17","y":2025,"r":1,"n":17,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"지하저장탱크 2기를 인접하여 설치하는 경우 그 상호 간의 거리는 몇 m 이상인지 쓰시오.","a":"가. 15,000/200 + 8,000/200 = 115배 → 지정수량 100배 초과이므로 1m 이상\n나. 14,000/1,000 + 8,000/200 = 54배 → 지정수량 100배 이하이므로 0.5m 이상","h":"지하저장탱크를 2기 이상 나란히 설치하면 탱크 사이를 1m 이상 띄우고, 용량 합계가 지정수량의 100배 이하이면 0.5m 이상으로 줄일 수 있다. 벤젠·톨루엔·휘발유는 지정수량 200L, 등유는 1,000L 라서 배수를 품명별로 계산해 더한다.","img":["2025-1-17.svg"],"ai":"2025-1-17_a.svg","t":"kan","칸":[{"a":"1","syn":["1m","1m 이상","1미터"],"l":"가"},{"a":"0.5","syn":["0.5m","0.5m 이상","0.5미터","50cm"],"l":"나"}],"순서무관":false},{"id":"2025-1-18","y":2025,"r":1,"n":18,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 위험물 중에서 물과 반응하여 산소를 생성하는 모든 물질에 대하여 물과 반응식을 쓰시오.\n과산화나트륨, 과염소산칼륨, 과산화바륨, 브로민산칼륨, 과망가니즈산칼륨","a":"과산화나트륨: 2Na2O2 + 2H2O → 4NaOH + O2\n과산화바륨: 2BaO2 + 2H2O → 2Ba(OH)2 + O2","h":"물과 반응해 산소를 내는 것은 무기과산화물인 과산화나트륨과 과산화바륨이다. 과염소산칼륨·브로민산칼륨·과망가니즈산칼륨은 물과 반응하지 않는다. 두 식 모두 과산화물 2분자가 물 2분자와 반응해 산소 1분자를 낸다.","t":"kan","칸":[{"a":"2Na2O2+2H2O→4NaOH+O2","syn":["2Na2O2+2H2O->4NaOH+O2","2Na2O2+2H2O=4NaOH+O2","Na2O2+H2O→2NaOH+1/2O2","Na2O2+H2O->2NaOH+1/2O2"]},{"a":"2BaO2+2H2O→2Ba(OH)2+O2","syn":["2BaO2+2H2O->2Ba(OH)2+O2","2BaO2+2H2O=2Ba(OH)2+O2","BaO2+H2O→Ba(OH)2+1/2O2","BaO2+H2O->Ba(OH)2+1/2O2"]}],"순서무관":true},{"id":"2025-1-19","y":2025,"r":1,"n":19,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"위험물안전관리법에 따른 불활성가스소화설비의 기준에 맞추어 다음 물음에 답하시오.\n• 가압용 또는 축압용 가스는 ( 가 ) 또는 이산화탄소로 할 것\n• 가압용 가스로 질소를 사용하는 것은 소화약제 1kg당 온도 35℃에서 0MPa의 상태로 환산한 체적 ( 나 )L 이상, 이산화탄소를 사용하는 것은 소화약제 1kg당 20g에 ( 다 )의 청소에 필요한 양을 더한 양 이상일 것\n• 축압용 가스로 질소가스를 사용하는 것은 소화약제 1kg당 온도 35℃에서 0MPa의 상태로 환산한 체적 ( 라 )L에 ( 다 )의 청소에 필요한 양을 더한 양 이상, 이산화탄소를 사용하는 것은 소화약제 1kg당 20g에 ( 다 )의 청소에 필요한 양을 더한 양 이상일 것","a":"가. 질소\n나. 40\n다. 배관\n라. 10","h":"불활성가스소화설비의 가압용·축압용 가스는 질소 또는 이산화탄소다. 질소는 가압용이 약제 1kg당 35℃, 0MPa 환산 40L 이상, 축압용이 10L에 배관 청소에 필요한 양을 더한 양 이상이다. 이산화탄소는 약제 1kg당 20g에 배관 청소에 필요한 양을 더한다.","t":"kan","칸":[{"a":"질소","syn":["N2","질소가스","질소(N2)","n2"],"l":"가"},{"a":"40","syn":["40L","40 L","40리터"],"l":"나"},{"a":"배관","syn":["배관 청소","파이프","관","배관류"],"l":"다"},{"a":"10","syn":["10L","10 L","10리터"],"l":"라"}],"순서무관":false},{"id":"2025-1-20","y":2025,"r":1,"n":20,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 보기에서 설명하는 제4류 위험물에 대하여 알맞은 답을 쓰시오.\n• 분자량 76\n• 비중 1.26\n• 비점 46℃\n• 물에 녹지 않는다.\n• 불쾌한 냄새가 난다.\n가. 명칭\n나. 화학식\n다. 연소반응식","a":"가. 이황화탄소\n나. CS2\n다. CS2 + 3O2 → CO2 + 2SO2","h":"분자량 76, 비점 46℃, 물에 녹지 않고 불쾌한 냄새가 나는 제4류 위험물은 이황화탄소다. 물보다 무겁고 물과 반응하지 않아 수조에 담가 보관하며 가연성 증기를 막는다. 연소하면 이산화탄소와 이산화황이 나온다.","t":"kan","칸":[{"a":"이황화탄소","syn":["CS2","이황화 탄소"],"l":"가"},{"a":"CS2","syn":["이황화탄소","cs2"],"l":"나"},{"a":"CS2+3O2→CO2+2SO2","syn":["CS2+3O2->CO2+2SO2","CS2+3O2=CO2+2SO2","CS2+3O2→2SO2+CO2","CS2+3O2->2SO2+CO2"],"l":"다"}],"순서무관":false},{"id":"2025-2-01","y":2025,"r":2,"n":1,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"옥내저장소에서 서로 1m 이상 간격을 두는 경우 동일한 저장소 내에 저장할 수 있다. 이 규정에 맞추어 빈칸을 알맞게 채우시오.\n• 제1류 위험물과 ( 가 ) 위험물\n• 제1류 위험물(알칼리금속의 과산화물 또는 이를 함유한 것 제외)과 ( 나 ) 위험물\n• 제2류 위험물 중 인화성고체와 ( 다 ) 위험물\n• 제3류 위험물 중 알킬알루미늄등과 ( 라 ) 위험물(알킬알루미늄 또는 알킬리튬을 함유한 것)\n• ( 마 ) 위험물 중 유기과산화물 또는 이를 함유한 것과 제5류 위험물 중 유기과산화물 또는 이를 함유한 것","a":"가. 제6류\n나. 제5류\n다. 제4류\n라. 제4류\n마. 제4류","h":"옥내저장소에서 1m 이상 띄우면 한 저장소에 같이 둘 수 있는 조합은 1류-5류(알칼리금속 과산화물 제외), 1류-6류, 1류-3류 중 황린, 2류 인화성고체-4류, 3류 알킬알루미늄등-4류, 4류 유기과산화물-5류 유기과산화물이다. 운반할 때의 혼재 기준과는 따로 외운다.","t":"kan","칸":[{"a":"제6류","syn":["6류","제6류 위험물","6류 위험물","제 6류"],"l":"가"},{"a":"제5류","syn":["5류","제5류 위험물","5류 위험물","제 5류"],"l":"나"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"다"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"라"},{"a":"제4류","syn":["4류","제4류 위험물","4류 위험물","제 4류"],"l":"마"}],"순서무관":false},{"id":"2025-2-02","y":2025,"r":2,"n":2,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"벤젠(C6H6) 16g이 완전 증발 시 1atm, 90℃에서 부피는 몇 L인지 쓰시오.","a":"① 주어진 값: w = 16g, M = 78g/mol, P = 1atm, T = 90 + 273 = 363K, R = 0.082atm·L/mol·K\n② 식: V = wRT / PM\n③ 대입: V = (16×0.082×363) / (1×78)\n④ 답: 6.11L","h":"화학반응 없이 증발만 하므로 반응식 없이 PV = (w/M)RT 만 쓴다. 벤젠 C6H6 의 분자량은 78 이고 온도는 섭씨에 273 을 더한 363K로 넣는다. 질량이 g, R 이 atm·L 단위라서 부피가 L 로 나온다.","t":"calc","e":0.05,"ka":"6.11"},{"id":"2025-2-03","y":2025,"r":2,"n":3,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"다음 위험물의 화학식과 지정수량을 쓰시오.\n가. 과염소산\n나. 염화아세틸\n다. 수소화칼슘","a":"가. 화학식 HClO4, 지정수량 300kg\n나. 화학식 CH3COCl, 지정수량 200L\n다. 화학식 CaH2, 지정수량 300kg","h":"과염소산 HClO4 는 제6류로 300kg, 염화아세틸 CH3COCl 은 제4류 제1석유류 비수용성으로 200L, 수소화칼슘 CaH2 는 제3류 금속의 수소화물로 300kg이다. 제4류만 지정수량 단위가 L 이다.","t":"kan","칸":[{"a":"HClO4","syn":["과염소산","hclo4"],"l":"가-화학식"},{"a":"300kg","syn":["300","300 kg"],"l":"가-지정수량"},{"a":"CH3COCl","syn":["염화아세틸","C2H3ClO","ch3cocl","CH3-CO-Cl"],"l":"나-화학식"},{"a":"200L","syn":["200","200 L","200리터"],"l":"나-지정수량"},{"a":"CaH2","syn":["수소화칼슘","cah2"],"l":"다-화학식"},{"a":"300kg","syn":["300","300 kg"],"l":"다-지정수량"}],"순서무관":false},{"id":"2025-2-04","y":2025,"r":2,"n":4,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"트라이나이트로페놀에 대한 다음 물음에 답하시오.\n가. 구조식\n나. 품명\n다. 지정수량(제1종)","a":"가. (그림)\n나. 나이트로화합물\n다. 10kg","h":"트라이나이트로페놀은 제5류 나이트로화합물이고 제1종의 지정수량은 10kg이다. 벤젠고리에 NO2 가 세 개 붙고 위쪽에 OH 가 있으면 트라이나이트로페놀, CH3 가 있으면 트라이나이트로톨루엔이다.","ai":"2025-2-04_a.svg","t":"kan","칸":[{"a":"나이트로화합물","syn":["니트로화합물","나이트로 화합물","니트로 화합물"],"l":"나"},{"a":"10kg","syn":["10","10 kg","10킬로그램"],"l":"다"}],"순서무관":false},{"id":"2025-2-05","y":2025,"r":2,"n":5,"p":"계산","kw":"지정수량 배수","pt":5,"q":"다음 위험물 중 수용성인 위험물을 골라 지정수량 배수의 합을 구하시오.\n• 아세톤 1,200L\n• 폼산메틸 1,200L\n• 피리딘 2,000L\n• 에틸알코올 1,600L\n• 휘발유 1,800L","a":"① 수용성: 아세톤, 폼산메틸, 피리딘, 에틸알코올 (휘발유는 비수용성이라 제외)\n② 아세톤 1,200/400 = 3, 폼산메틸 1,200/400 = 3, 피리딘 2,000/400 = 5, 에틸알코올 1,600/400 = 4\n③ 합계 3 + 3 + 5 + 4 = 15\n답: 15배","h":"수용성인 네 가지는 지정수량이 모두 400L이고, 휘발유는 비수용성(200L)이라 계산에서 뺀다. 배수는 저장량을 지정수량으로 나눈 값이고 품목이 여럿이면 더한다.","t":"calc","ka":"15"},{"id":"2025-2-06","y":2025,"r":2,"n":6,"p":"물질·성상","kw":"소화약제","pt":5,"q":"할로젠화합물 소화약제의 한글 명칭을 각 소화약제에 맞추어 기호를 쓰시오.\n① 브로모클로로다이플루오로메탄\n② 다이브로모테트라플루오로에탄\n③ 펜타플루오로에탄\n④ 트라이플루오로메탄\n⑤ 브로모트라이플루오로메탄\n가. Halon 2402\n나. Halon 1211\n다. Halon 1301\n라. HFC-23\n마. HFC-125","a":"가. ②\n나. ①\n다. ⑤\n라. ④\n마. ③","h":"하론 번호는 C, F, Cl, Br 개수 순이다. 2402 는 C2F4Br2(다이브로모테트라플루오로에탄), 1211 은 CF2ClBr(브로모클로로다이플루오로메탄), 1301 은 CF3Br(브로모트라이플루오로메탄)이다. HFC-23 은 CHF3(트라이플루오로메탄), HFC-125 는 C2HF5(펜타플루오로에탄)이다.","t":"kan","칸":[{"a":"②","syn":["2","2번","(2)"],"l":"가"},{"a":"①","syn":["1","1번","(1)"],"l":"나"},{"a":"⑤","syn":["5","5번","(5)"],"l":"다"},{"a":"④","syn":["4","4번","(4)"],"l":"라"},{"a":"③","syn":["3","3번","(3)"],"l":"마"}],"순서무관":false},{"id":"2025-2-07","y":2025,"r":2,"n":7,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"위험물 옥내저장소에 다음 위험물을 저장할 때 하나의 저장창고의 바닥면적은 몇 m2 이하로 하여야 하는지 쓰시오.\n가. 염소산염류\n나. 제2석유류\n다. 유기과산화물(제1종)","a":"가. 1,000m2 이하\n나. 2,000m2 이하\n다. 1,000m2 이하","h":"옥내저장소 바닥면적은 위험등급 I 위험물과 제4류 중 등급 I·II 는 1,000m2, 그 밖의 등급 II·III 위험물과 제4류 중 등급 III 은 2,000m2 이하다. 염소산염류는 제1류 등급 I, 제2석유류는 제4류 등급 III, 유기과산화물(제1종)은 제5류 등급 I 이다.","t":"kan","칸":[{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"가"},{"a":"2000","syn":["2,000","2000m2","2,000m2","2000㎡","2,000㎡","2000m2 이하","2,000m2 이하"],"l":"나"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"다"}],"순서무관":false},{"id":"2025-2-08","y":2025,"r":2,"n":8,"p":"계산","kw":"반응량(기체 부피·질량)","pt":5,"q":"과산화나트륨 1kg이 물과 반응할 때 생성되는 기체의 부피는 1atm, 350℃에서 몇 L인가?","a":"반응식: 2Na2O2 + 2H2O → 4NaOH + O2\n① 주어진 값: w = 1kg = 1,000g, M = 78g/mol, P = 1atm, T = 350 + 273 = 623K, R = 0.082atm·L/mol·K\n② 식: V = wRT/PM × (1O2 / 2Na2O2)\n③ 대입: V = (1,000×0.082×623) / (1×78) × 1/2\n④ 답: 327.47L","h":"과산화나트륨 2분자가 물과 반응해 산소 1분자가 나오므로 산소 몰수는 과산화나트륨의 절반이다. 질량 1kg은 1,000g으로, 온도 350℃는 623K로 바꿔 넣는다. Na2O2 의 분자량은 78 이다.","tp":"W01","t":"calc","e":1,"ka":"327.47"},{"id":"2025-2-09","y":2025,"r":2,"n":9,"p":"반응식","kw":"열분해","pt":5,"q":"다음 중 열분해하여 산소를 발생하는 위험물의 반응식을 쓰시오 (단, 없으면 해당없음을 쓰시오).\n가. 과산화나트륨\n나. 다이크로뮴산칼륨\n다. 질산암모늄","a":"가. 2Na2O2 → 2Na2O + O2\n나. 4K2Cr2O7 → 4K2CrO4 + 2Cr2O3 + 3O2\n다. 2NH4NO3 → 2N2 + O2 + 4H2O","h":"세 물질 모두 열분해하면 산소가 나온다. 과산화나트륨은 산화나트륨과 산소, 다이크로뮴산칼륨은 크로뮴산칼륨·산화크로뮴·산소로 갈라진다. 질산암모늄은 산소 외에 질소와 물도 생긴다.","t":"kan","칸":[{"a":"2Na2O2→2Na2O+O2","syn":["2Na2O2->2Na2O+O2","2Na2O2=2Na2O+O2","Na2O2→Na2O+1/2O2","Na2O2->Na2O+1/2O2","2Na2O2→2Na2O+O2↑"],"l":"가"},{"a":"4K2Cr2O7→4K2CrO4+2Cr2O3+3O2","syn":["4K2Cr2O7->4K2CrO4+2Cr2O3+3O2","4K2Cr2O7=4K2CrO4+2Cr2O3+3O2","4K2Cr2O7→4K2CrO4+2Cr2O3+3O2↑","K2Cr2O7→K2CrO4+1/2Cr2O3+3/4O2"],"l":"나"},{"a":"2NH4NO3→2N2+O2+4H2O","syn":["2NH4NO3->2N2+O2+4H2O","2NH4NO3=2N2+O2+4H2O","NH4NO3→N2+1/2O2+2H2O","NH4NO3->N2+1/2O2+2H2O"],"l":"다"}],"순서무관":false},{"id":"2025-2-10","y":2025,"r":2,"n":10,"p":"반응식","kw":"물과 반응","pt":5,"q":"트라이에틸알루미늄과 물을 반응시켰을 때 다음 물음에 답하시오.\n가. 화학반응식\n나. 발생하는 기체의 명칭","a":"가. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n나. 에테인","h":"트라이에틸알루미늄은 물과 반응해 수산화알루미늄과 에테인을 낸다. 에틸기 세 개가 각각 수소를 받아 에테인 세 분자가 된다. 트라이메틸알루미늄이면 메테인이 나온다.","t":"kan","칸":[{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"가"},{"a":"에테인","syn":["에탄","C2H6","ethane","에테인가스","에탄가스"],"l":"나"}],"순서무관":false},{"id":"2025-2-11","y":2025,"r":2,"n":11,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"제조소의 배출설비에 대한 기준이다. 빈칸에 들어갈 알맞은 말을 쓰시오.\n• 배출능력은 1시간당 배출장소 용적의 ( 가 )배 이상인 것으로 하여야 한다. 다만, 전역방식의 경우에는 바닥면적 1m2당 ( 나 )m3 이상으로 할 수 있다.\n• 배출구는 지상 ( 다 )m 이상으로서 연소의 우려가 없는 장소에 설치하고, ( 라 )가 관통하는 벽부분의 바로 가까이에 화재 시 자동으로 폐쇄되는 ( 마 )(화재 시 연기 등을 차단하는 장치)를 설치할 것","a":"가. 20\n나. 18\n다. 2\n라. 배출덕트\n마. 방화댐퍼","h":"제조소의 배출설비는 국소방식이고 배출능력은 1시간당 배출장소 용적의 20배 이상이며, 전역방식이면 바닥면적 1m2당 18m3 이상으로 할 수 있다. 배출구는 지상 2m 이상에 두고 배출덕트가 벽을 관통하는 곳 가까이에 방화댐퍼를 단다.","t":"kan","칸":[{"a":"20","syn":["20배"],"l":"가"},{"a":"18","syn":["18m3","18㎥"],"l":"나"},{"a":"2","syn":["2m","2미터"],"l":"다"},{"a":"배출덕트","syn":["덕트","배기덕트","배출 덕트","배출닥트","배기 덕트"],"l":"라"},{"a":"방화댐퍼","syn":["댐퍼","방화 댐퍼","방화대퍼","fire damper","FD"],"l":"마"}],"순서무관":false},{"id":"2025-2-12","y":2025,"r":2,"n":12,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제3류 위험물 중 물과 반응성이 없고 연소하여 흰 연기를 발생하는 물질에 대하여 다음 물음에 답하시오.\n가. 명칭\n나. 옥내저장소의 바닥면적\n다. 수산화칼륨과 같은 강알칼리성 용액과 반응하여 생성되는 맹독성 기체의 명칭","a":"가. 황린\n나. 1,000m2\n다. 포스핀","h":"물과 반응하지 않고 연소해 흰 연기(오산화인)를 내는 제3류 물질은 황린 P4 이다. 지정수량 20kg의 위험등급 I 이라 옥내저장소 바닥면적은 1,000m2 이하다. 수산화칼륨 같은 강알칼리와는 P4 + 3KOH + 3H2O → PH3 + 3KH2PO2 로 반응해 포스핀이 나온다.","t":"kan","칸":[{"a":"황린","syn":["백린","P4","황 린"],"l":"가"},{"a":"1000","syn":["1,000","1000m2","1,000m2","1000㎡","1,000㎡","1000m2 이하","1,000m2 이하"],"l":"나"},{"a":"포스핀","syn":["인화수소","PH3","포스핀가스","phosphine","호스핀"],"l":"다"}],"순서무관":false},{"id":"2025-2-13","y":2025,"r":2,"n":13,"p":"시설·법령","kw":"제조소·저장소 구조","pt":5,"q":"위험물안전관리법령상 위험물의 성질에 따른 제조소의 특례이다. 빈칸에 알맞은 말을 쓰시오.\n• 제4류 위험물 중 특수인화물의 아세트알데하이드·( 가 ) 또는 이 중 어느 하나 이상을 함유하는 것(이하 \"아세트알데하이드등\"이라 한다)\n• 아세트알데하이드등을 취급하는 설비에는 연소성 혼합기체의 생성에 의한 폭발을 방지하기 위한 ( 나 ) 또는 ( 다 )를 봉입하는 장치를 갖출 것\n• 아세트알데하이드등을 취급하는 탱크(옥외에 있는 탱크 또는 옥내에 있는 탱크로서 그 용량이 지정수량의 5분의 1 미만의 것을 제외한다)에는 ( 라 ) 또는 저온을 유지하기 위한 장치(이하 \"( 마 )\"라 한다) 및 연소성 혼합기체의 생성에 의한 폭발을 방지하기 위한 불활성기체를 봉입하는 장치를 갖출 것. 다만, 지하에 있는 탱크가 아세트알데하이드등의 온도를 저온으로 유지할 수 있는 구조인 경우에는 ( 라 ) 및 ( 마 )를 갖추지 아니할 수 있다.","a":"가. 산화프로필렌\n나. 불활성기체\n다. 수증기\n라. 냉각장치\n마. 보냉장치","h":"아세트알데하이드등은 아세트알데하이드와 산화프로필렌이다. 취급 설비에는 불활성기체 또는 수증기를 봉입하는 장치를 갖추고, 탱크에는 냉각장치 또는 보냉장치와 불활성기체 봉입 장치를 둔다. 설비는 은·수은·동·마그네슘이나 이들의 합금으로 만들지 않는다.","t":"kan","칸":[{"a":"산화프로필렌","syn":["프로필렌옥사이드","프로필렌옥시드","프로필렌 옥사이드","C3H6O","산화 프로필렌"],"l":"가"},{"a":"불활성기체, 수증기","k":[["불활성","불연성","질소","아르곤"],["수증기"]],"l":"나·다"},{"a":"냉각장치","syn":["냉각 장치","냉각기","냉각설비"],"l":"라"},{"a":"보냉장치","syn":["보냉 장치","보냉기","보냉설비"],"l":"마"}],"순서무관":false},{"id":"2025-2-14","y":2025,"r":2,"n":14,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 보기에서 설명하는 제6류 위험물에 대하여 물음에 답하시오.\n• 햇빛에 분해되어 적갈색의 증기를 발생한다.\n• 자극성, 부식성이 강한 휘발성 액체\n• 목탄분, 천, 실, 솜, 나무조각, 톱밥 등에 스며들어 방치하면 자연발화한다.\n• 갈색 병에 넣어 직사일광을 피하고 서늘한 곳에 저장한다.\n가. 분해되어 산소를 발생하는 화학반응식을 쓰시오.\n나. 옥내저장소에 3,000kg을 저장하는 경우 안전거리를 쓰시오.","a":"가. 4HNO3 → 2H2O + 4NO2 + O2\n나. 해당없음","h":"햇빛에 분해되어 적갈색 증기를 내고 갈색 병에 보관하는 제6류는 질산이다. 분해식은 4HNO3 → 2H2O + 4NO2 + O2 이다. 제6류는 안전거리 기준이 적용되지 않으므로 옥내저장소에 3,000kg을 저장해도 안전거리는 해당없음이다.","t":"kan","칸":[{"a":"4HNO3→2H2O+4NO2+O2","syn":["4HNO3->2H2O+4NO2+O2","4HNO3=2H2O+4NO2+O2","4HNO3→4NO2+2H2O+O2","4HNO3->4NO2+2H2O+O2","HNO3→1/2H2O+NO2+1/4O2"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다","안전거리 적용 제외","적용 제외","제외"],"l":"나"}],"순서무관":false},{"id":"2025-2-15","y":2025,"r":2,"n":15,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"다음 보기의 가연물을 화재별로 구분하여 나열하시오 (단, 없으면 해당없음을 쓰시오).\n[보기] 종이, 나무, 고무, 일반섬유, 등유, 알코올\n가. A급 화재\n나. B급 화재\n다. C급 화재","a":"가. 종이, 나무, 고무, 일반섬유\n나. 등유, 알코올\n다. 해당없음","h":"A급은 일반화재(백색), B급은 유류화재(황색), C급은 전기화재(청색), D급은 금속화재(무색)다. 종이·나무·고무·일반섬유는 A급, 등유와 알코올은 인화성 액체라 B급이다. 보기에 전기 관련 항목이 없어 C급은 해당없음이다.","t":"kan","칸":[{"a":"종이, 나무, 고무, 일반섬유","k":[["종이"],["나무"],["고무"],["섬유"]],"l":"가"},{"a":"등유, 알코올","k":[["등유"],["알코올","알콜"]],"l":"나"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"다"}],"순서무관":false},{"id":"2025-2-16","y":2025,"r":2,"n":16,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"다음 설명하는 위험물에 대하여 물음에 답하시오.\n이 위험물의 옥외저장탱크는 벽 및 바닥의 두께가 0.2m 이상이고 누수가 되지 아니하는 철근콘크리트의 수조에 넣어 보관하여야 한다. 이 경우 보유공지·통기관 및 자동계량장치는 생략할 수 있다.\n가. 연소반응식\n나. 방유제 설치 여부를 쓰시오.","a":"가. CS2 + 3O2 → CO2 + 2SO2\n나. 해당없음","h":"벽과 바닥 두께 0.2m 이상의 철근콘크리트 수조에 넣어 보관하는 옥외저장탱크의 위험물은 이황화탄소다. 물보다 무겁고 물과 반응하지 않아 물속에 두어 증기를 막는다. 방유제 규정은 이황화탄소를 제외한 인화성 액체에 적용되므로 이 경우 설치 대상이 아니다.","t":"kan","칸":[{"a":"CS2+3O2→CO2+2SO2","syn":["CS2+3O2->CO2+2SO2","CS2+3O2=CO2+2SO2","CS2+3O2→2SO2+CO2","CS2+3O2->2SO2+CO2"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다","불필요","설치하지 않는다","설치하지 않음","설치 안 함","필요없음","필요 없음"],"l":"나"}],"순서무관":false},{"id":"2025-2-17","y":2025,"r":2,"n":17,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"다음 중 무기과산화물을 골라 제시된 물질과 반응하는 화학반응식을 쓰시오 (단, 반응하지 않으면 해당없음을 쓰시오).\n[보기] BaO2  NH4NO3  KMnO4  KIO3  Pb(NO3)2\n가. HCl\n나. O2","a":"가. BaO2 + 2HCl → BaCl2 + H2O2\n나. 해당없음","h":"보기 중 무기과산화물은 BaO2(과산화바륨)이다. 염산과는 BaO2 + 2HCl → BaCl2 + H2O2 로 반응한다. 제1류 위험물은 스스로 연소하지 않으므로 산소와의 반응식은 해당없음이다.","t":"kan","칸":[{"a":"BaO2+2HCl→BaCl2+H2O2","syn":["BaO2+2HCl->BaCl2+H2O2","BaO2+2HCl=BaCl2+H2O2","BaO2+2HCl→H2O2+BaCl2","BaO2+2HCl->H2O2+BaCl2"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"나"}],"순서무관":false},{"id":"2025-2-18","y":2025,"r":2,"n":18,"p":"반응식","kw":"연소 반응","pt":5,"q":"다음 위험물의 연소반응식을 쓰시오.\n가. 오황화인\n나. 알루미늄\n다. 마그네슘","a":"가. 2P2S5 + 15O2 → 10SO2 + 2P2O5\n나. 4Al + 3O2 → 2Al2O3\n다. 2Mg + O2 → 2MgO","h":"오황화인은 이산화황과 오산화인을, 알루미늄은 산화알루미늄을, 마그네슘은 산화마그네슘을 만든다. 오황화인과 알루미늄은 O2 계수가 분수로 나와서 정수가 되게 양변을 키운다.","t":"kan","칸":[{"a":"2P2S5+15O2→10SO2+2P2O5","syn":["2P2S5+15O2->10SO2+2P2O5","2P2S5+15O2=10SO2+2P2O5","2P2S5+15O2→2P2O5+10SO2","2P2S5+15O2->2P2O5+10SO2","P2S5+15/2O2→5SO2+P2O5","P2S5+15/2O2->5SO2+P2O5","P2S5+7.5O2→5SO2+P2O5"],"l":"가"},{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3","2Al+3/2O2→Al2O3"],"l":"나"},{"a":"2Mg+O2→2MgO","syn":["2Mg+O2->2MgO","2Mg+O2=2MgO","Mg+1/2O2→MgO"],"l":"다"}],"순서무관":false},{"id":"2025-2-19","y":2025,"r":2,"n":19,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물 중 산화프로필렌에 대하여 다음 물음에 답하시오.\n가. 증기비중\n나. 위험등급\n다. 옥외저장탱크 중 압력탱크 외의 저장할 때 몇 도 이하로 저장해야 하는가?","a":"가. 2 (= 58/29)\n나. I\n다. 30℃","h":"산화프로필렌은 제4류 특수인화물로 지정수량 50L, 위험등급 I 이다. 분자량 58 을 29 로 나누면 증기비중 2 가 나온다. 압력탱크 외의 옥외·옥내·지하저장탱크에 저장할 때 산화프로필렌은 30℃ 이하, 아세트알데하이드는 15℃ 이하다.","t":"kan","칸":[{"a":"2","e":0.02,"l":"가"},{"a":"I","syn":["Ⅰ","1","I등급","Ⅰ등급","1등급","I 등급","Ⅰ 등급","Ⅰ급","1급"],"l":"나"},{"a":"30℃","syn":["30","30도","30℃ 이하","30도 이하"],"l":"다"}],"순서무관":false},{"id":"2025-2-20","y":2025,"r":2,"n":20,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제3류 위험물에 대하여 다음 빈칸에 들어갈 알맞은 말을 쓰시오.\n| 품명 | 지정수량 |\n| 칼륨 | ( 가 ) |\n| 나트륨 | ( 나 ) |\n| 알킬알루미늄 | ( 다 ) |\n| ( 라 ) | 10kg |\n| ( 마 ) | 20kg |\n| 알칼리금속 및 알칼리토금속 | ( 바 ) |\n| 유기금속화합물 | ( 사 ) |","a":"가. 10kg\n나. 10kg\n다. 10kg\n라. 알킬리튬\n마. 황린\n바. 50kg\n사. 50kg","h":"제3류에서 칼륨·나트륨·알킬알루미늄·알킬리튬은 10kg, 황린은 20kg, 알칼리금속 및 알칼리토금속과 유기금속화합물은 50kg, 수소화물·인화물·탄화물은 300kg이다. 빈칸 중 10kg 칸은 알킬리튬, 20kg 칸은 황린이다.","t":"kan","칸":[{"a":"10kg","syn":["10","10 kg"],"l":"가"},{"a":"10kg","syn":["10","10 kg"],"l":"나"},{"a":"10kg","syn":["10","10 kg"],"l":"다"},{"a":"알킬리튬","syn":["알킬 리튬","알킬리듐"],"l":"라"},{"a":"황린","syn":["백린","P4","황 린"],"l":"마"},{"a":"50kg","syn":["50","50 kg"],"l":"바"},{"a":"50kg","syn":["50","50 kg"],"l":"사"}],"순서무관":false},{"id":"2025-3-01","y":2025,"r":3,"n":1,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제2류 위험물 중 황화인에 대하여 다음 빈칸에 알맞은 말을 쓰시오.\n| 명칭 | 화학식 | 조해성 |\n| 삼황화인 | P4S3 | ( 다 ) |\n| 오황화인 | ( 가 ) | ( 라 ) |\n| 칠황화인 | ( 나 ) | ( 마 ) |","a":"가. P2S5\n나. P4S7\n다. 조해성 없음\n라. 조해성 있음\n마. 조해성 있음","h":"삼황화인은 P4S3, 오황화인은 P2S5, 칠황화인은 P4S7이다. 조해성이 없는 것은 삼황화인뿐이고 오황화인과 칠황화인은 있다. 발화점은 삼황화인 약 100℃, 오황화인 142℃, 칠황화인 약 250℃이다(칠황화인 310℃는 녹는점).","t":"kan","칸":[{"a":"P2S5","syn":["오황화인","p2s5","오황화이인"],"l":"가"},{"a":"P4S7","syn":["칠황화인","p4s7","칠황화사인"],"l":"나"},{"a":"조해성 없음","syn":["없음","없다","없음.","조해성이 없다","조해성없음","조해성 없다","X","x"],"l":"다"},{"a":"조해성 있음","syn":["있음","있다","있음.","조해성이 있다","조해성있음","조해성 있다","O","o","○"],"l":"라"},{"a":"조해성 있음","syn":["있음","있다","있음.","조해성이 있다","조해성있음","조해성 있다","O","o","○"],"l":"마"}],"순서무관":false},{"id":"2025-3-02","y":2025,"r":3,"n":2,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"제조소등에서 위험물의 저장 및 취급에 관한 기준에 관한 내용이다. 다음 빈칸을 채우시오.\n가. 위험물을 저장 또는 취급하는 건축물 그 밖의 공작물 또는 설비는 당해 위험물의 성질에 따라 차광 또는 ( )를 실시하여야 한다.\n나. 위험물은 온도계, 습도계, 압력계 그 밖의 계기를 감시하여 당해 위험물의 성질에 맞는 적정한 온도, 습도 또는 ( )을 유지하도록 저장 또는 취급하여야 한다.\n다. 위험물을 용기에 수납하여 저장 또는 취급할 때에는 그 용기는 당해 위험물의 성질에 적응하고 파손·( )·균열 등이 없는 것으로 하여야 한다.\n라. ( )의 액체·증기 또는 가스가 새거나 체류할 우려가 있는 장소 또는 가연성의 미분이 현저하게 부유할 우려가 있는 장소에서는 전선과 전기기구를 완전히 접속하고 불꽃을 발하는 기계·기구·공구·신발 등을 사용하지 아니하여야 한다.\n마. 위험물을 ( ) 중에 보존하는 경우에는 당해 위험물이 보호액으로부터 노출되지 아니하도록 하여야 한다.","a":"가. 환기\n나. 압력\n다. 부식\n라. 가연성\n마. 보호액","h":"저장·취급 기준에는 차광 또는 환기, 온도·습도 또는 압력의 유지, 용기의 파손·부식·균열 방지가 들어간다. 가연성 증기가 체류할 우려가 있는 곳에서는 전선과 전기기구를 완전히 접속하고 불꽃을 내는 기구를 쓰지 않는다. 보호액에 보존하는 위험물은 보호액 밖으로 노출되지 않게 한다.","t":"kan","칸":[{"a":"환기","l":"가"},{"a":"압력","l":"나"},{"a":"부식","l":"다"},{"a":"가연성","syn":["가연성 증기","가연성가스"],"l":"라"},{"a":"보호액","l":"마"}],"순서무관":false},{"id":"2025-3-03","y":2025,"r":3,"n":3,"p":"반응식","kw":"물과 반응","pt":5,"q":"다음 반응의 화학반응식을 쓰시오.\n가. 트라이메틸알루미늄과 물\n나. 트라이메틸알루미늄과 산소\n다. 트라이에틸알루미늄과 물\n라. 트라이에틸알루미늄과 산소","a":"가. (CH3)3Al + 3H2O → Al(OH)3 + 3CH4\n나. 2(CH3)3Al + 12O2 → 6CO2 + 9H2O + Al2O3\n다. (C2H5)3Al + 3H2O → Al(OH)3 + 3C2H6\n라. 2(C2H5)3Al + 21O2 → 12CO2 + 15H2O + Al2O3","h":"트라이메틸알루미늄은 물과 반응해 메테인을, 트라이에틸알루미늄은 에테인을 낸다. 산소와는 둘 다 이산화탄소, 물, 산화알루미늄이 되고 O2 계수는 각각 12, 21 이다. 산화알루미늄 Al2O3 의 Al 이 2개라서 알킬알루미늄 계수가 2 가 된다.","t":"kan","칸":[{"a":"(CH3)3Al+3H2O→Al(OH)3+3CH4","syn":["(CH3)3Al+3H2O->Al(OH)3+3CH4","(CH3)3Al+3H2O=Al(OH)3+3CH4","(CH3)3Al+3H2O→3CH4+Al(OH)3","(CH3)3Al+3H2O->3CH4+Al(OH)3"],"l":"가"},{"a":"2(CH3)3Al+12O2→6CO2+9H2O+Al2O3","syn":["2(CH3)3Al+12O2->6CO2+9H2O+Al2O3","2(CH3)3Al+12O2=6CO2+9H2O+Al2O3","2(CH3)3Al+12O2→Al2O3+6CO2+9H2O","2(CH3)3Al+12O2->Al2O3+6CO2+9H2O"],"l":"나"},{"a":"(C2H5)3Al+3H2O→Al(OH)3+3C2H6","syn":["(C2H5)3Al+3H2O->Al(OH)3+3C2H6","(C2H5)3Al+3H2O=Al(OH)3+3C2H6","(C2H5)3Al+3H2O→3C2H6+Al(OH)3","(C2H5)3Al+3H2O->3C2H6+Al(OH)3"],"l":"다"},{"a":"2(C2H5)3Al+21O2→12CO2+15H2O+Al2O3","syn":["2(C2H5)3Al+21O2->12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2=12CO2+15H2O+Al2O3","2(C2H5)3Al+21O2→Al2O3+12CO2+15H2O","2(C2H5)3Al+21O2->Al2O3+12CO2+15H2O"],"l":"라"}],"순서무관":false},{"id":"2025-3-04","y":2025,"r":3,"n":4,"p":"시설·법령","kw":"운반·혼재·표시","pt":5,"q":"다음 보기 중 운반 시 방수성 및 차광성 덮개로 모두 덮어야 하는 위험물 품명을 고르시오.\n[보기] 유기과산화물, 질산, 알칼리금속과산화물, 염소산염류","a":"알칼리금속과산화물","h":"방수성과 차광성 덮개를 둘 다 씌우는 것은 제1류 중 알칼리금속의 과산화물이다. 유기과산화물(제5류), 질산(제6류), 염소산염류(제1류 그 밖의 것)는 차광성 덮개만 쓴다. 방수성 덮개는 물과 반응하는 금수성물질과 철분·금속분·마그네슘에도 쓴다.","t":"word","syn":["알칼리금속의 과산화물","알칼리 금속 과산화물","알칼리금속 과산화물","알칼리금속의과산화물"],"ka":"알칼리금속과산화물"},{"id":"2025-3-05","y":2025,"r":3,"n":5,"p":"반응식","kw":"산·기타 반응","pt":5,"q":"알루미늄에 대한 다음 각 물음에 알맞은 답을 하시오.\n가. 염산과 반응식\n나. 연소반응식\n다. 물과 반응식","a":"가. 2Al + 6HCl → 2AlCl3 + 3H2\n나. 4Al + 3O2 → 2Al2O3\n다. 2Al + 6H2O → 2Al(OH)3 + 3H2","h":"알루미늄은 염산과도 물과도 반응해 수소를 낸다. 두 식 모두 Al 2에 H2 3 이 나오는 꼴이고, 연소하면 4Al + 3O2 → 2Al2O3 가 된다.","t":"kan","칸":[{"a":"2Al+6HCl→2AlCl3+3H2","syn":["2Al+6HCl->2AlCl3+3H2","2Al+6HCl=2AlCl3+3H2","Al+3HCl→AlCl3+3/2H2"],"l":"가"},{"a":"4Al+3O2→2Al2O3","syn":["4Al+3O2->2Al2O3","4Al+3O2=2Al2O3","2Al+3/2O2→Al2O3"],"l":"나"},{"a":"2Al+6H2O→2Al(OH)3+3H2","syn":["2Al+6H2O->2Al(OH)3+3H2","2Al+6H2O=2Al(OH)3+3H2","Al+3H2O→Al(OH)3+3/2H2"],"l":"다"}],"순서무관":false},{"id":"2025-3-06","y":2025,"r":3,"n":6,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"위험물안전관리법령상 동식물유류에 관한 물음에 답을 쓰시오.\n가. 아이오딘값의 정의\n나. 동식물유류 아이오딘값에 따른 분류와 범위","a":"가. 유지 100g 을 경화시키는 데 필요한 아이오딘의 g수\n나. 건성유 : 130 이상\n반건성유 : 100 이상 130 미만\n불건성유 : 100 미만","h":"아이오딘값은 유지 100g에 반응하는 아이오딘의 g수로, 클수록 불포화도가 높아 잘 굳는다. 130 이상이면 건성유, 100 이상 130 미만이면 반건성유, 100 미만이면 불건성유다.","t":"kan","칸":[{"a":"유지 100g을 경화시키는 데 필요한 아이오딘의 g수","k":[["100"],["아이오딘","요오드","옥소"]],"l":"가"},{"a":"130 이상","syn":["130이상","130","130이상이다"],"l":"건성유"},{"a":"100 이상 130 미만","k":[["100"],["130"]],"l":"반건성유"},{"a":"100 미만","syn":["100미만","100","100이하"],"l":"불건성유"}],"순서무관":false},{"id":"2025-3-07","y":2025,"r":3,"n":7,"p":"물질·성상","kw":"소화약제","pt":5,"q":"다음 분말소화약제의 화학식을 쓰시오.\n가. 제1종 분말소화약제\n나. 제2종 분말소화약제","a":"가. NaHCO3\n나. KHCO3","h":"제1종은 탄산수소나트륨 NaHCO3, 제2종은 탄산수소칼륨 KHCO3 다. 둘 다 B·C급 화재에 쓴다. 분해식은 2NaHCO3 → Na2CO3 + CO2 + H2O, 2KHCO3 → K2CO3 + CO2 + H2O 로 생김새가 같다.","t":"kan","칸":[{"a":"NaHCO3","syn":["탄산수소나트륨","중탄산나트륨","중탄산소다","탄산수소소다"],"l":"가"},{"a":"KHCO3","syn":["탄산수소칼륨","중탄산칼륨"],"l":"나"}],"순서무관":false},{"id":"2025-3-08","y":2025,"r":3,"n":8,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"위험물 중 인화점이 21℃ 이상 70℃ 미만이며 수용성인 물질을 다음 보기에서 모두 고르시오.\n[보기] 아세트산, 글리세린, 니트로벤젠, 메틸알코올, 포름산","a":"포름산, 아세트산","h":"인화점 21℃ 이상 70℃ 미만은 제2석유류이고, 그중 수용성은 포름산과 아세트산이다. 글리세린은 수용성이어도 제3석유류, 니트로벤젠은 비수용성 제3석유류, 메틸알코올은 알코올류다.","t":"kan","칸":[{"a":"포름산","syn":["개미산","의산","HCOOH","폼산","포름 산"]},{"a":"아세트산","syn":["초산","CH3COOH","아세트 산"]}],"순서무관":true},{"id":"2025-3-09","y":2025,"r":3,"n":9,"p":"시설·법령","kw":"안전거리·보유공지","pt":5,"q":"위험물 제조소에 다음 수량의 위험물을 저장할 때 필요한 최소 보유공지를 쓰시오.\n가. 지정수량의 1배\n나. 지정수량의 5배\n다. 지정수량의 10배\n라. 지정수량의 50배\n마. 지정수량의 200배","a":"가. 3m 이상\n나. 3m 이상\n다. 3m 이상\n라. 5m 이상\n마. 5m 이상","h":"제조소의 보유공지는 지정수량 10배 이하면 3m 이상, 10배를 넘으면 5m 이상이다. 1배·5배·10배는 3m, 50배·200배는 5m에 해당한다.","t":"kan","칸":[{"a":"3m","syn":["3","3 m","3미터","3m 이상"],"l":"가"},{"a":"3m","syn":["3","3 m","3미터","3m 이상"],"l":"나"},{"a":"3m","syn":["3","3 m","3미터","3m 이상"],"l":"다"},{"a":"5m","syn":["5","5 m","5미터","5m 이상"],"l":"라"},{"a":"5m","syn":["5","5 m","5미터","5m 이상"],"l":"마"}],"순서무관":false},{"id":"2025-3-10","y":2025,"r":3,"n":10,"p":"시설·법령","kw":"탱크저장소","pt":5,"q":"옥외탱크저장소에 설치한 방유제에 대하여 다음 물음에 답하시오.\n가. 방유제의 면적\n나. 제1석유류 15만리터 저장 시 설치할 수 있는 최대 탱크 수\n다. 방유제 내에 저장탱크의 개수를 제한하지 아니하여도 되는 인화점 기준","a":"가. 80,000m2 이하\n나. 10기 이하\n다. 인화점 200℃ 이상인 위험물을 저장 또는 취급하는 경우","h":"방유제 면적은 80,000m2 이하이고 안에 둘 수 있는 탱크는 10기 이하다. 용량이 모두 20만L 이하이고 인화점이 70℃ 이상 200℃ 미만이면 20기까지 되고, 인화점 200℃ 이상이면 개수 제한이 없다. 제1석유류는 인화점이 낮아 이 예외에 들지 않는다.","t":"kan","칸":[{"a":"80000","syn":["80,000","80000m2","80,000m2","80000㎡","80,000㎡","8만","8만m2","80000m2 이하","80,000m2 이하"],"l":"가"},{"a":"10","syn":["10기","10기 이하","10개"],"l":"나"},{"a":"인화점 200℃ 이상","k":[["200"],["이상","초과"]],"l":"다"}],"순서무관":false},{"id":"2025-3-11","y":2025,"r":3,"n":11,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제5류 위험물 중 트라이나이트로톨루엔(제1종)에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 위험물 1,000kg을 저장할 때 지정수량 배수","a":"가. C6H2(NO2)3CH3\n나. 1,000kg / 10kg = 100배","h":"트라이나이트로톨루엔은 제5류 나이트로화합물이고 제1종 지정수량은 10kg이다. 톨루엔을 황산 촉매 아래 질산과 반응시키는 나이트로화로 C6H2(NO2)3CH3 가 만들어진다. 배수는 1,000kg을 10kg으로 나눈 100배다.","ai":"2025-3-11_a.svg","t":"kan","칸":[{"a":"C6H2(NO2)3CH3","syn":["C6H2CH3(NO2)3","CH3C6H2(NO2)3","C7H5N3O6","트라이나이트로톨루엔","트리니트로톨루엔","TNT","C6H2(CH3)(NO2)3"],"l":"가"},{"a":"100","syn":["100배"],"l":"나"}],"순서무관":false},{"id":"2025-3-12","y":2025,"r":3,"n":12,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제4류 위험물 중 메틸알코올과 에틸알코올을 비교할 때 알맞은 말을 쓰시오.\n가. 분자량이 큰 것\n나. 증기비중이 큰 것\n다. 연소범위가 넓은 것\n라. 끓는점이 높은 것\n마. 발화점이 높은 것","a":"가. 에틸알코올\n나. 에틸알코올\n다. 메틸알코올\n라. 에틸알코올\n마. 메틸알코올","h":"에틸알코올은 분자량과 증기비중(메틸 1.1, 에틸 1.59)이 크고 끓는점도 높다(메틸 64.7℃, 에틸 80℃). 메틸알코올은 연소범위가 7.3~36%로 더 넓고 발화점도 464℃로 높다(에틸 423℃).","t":"kan","칸":[{"a":"에틸알코올","syn":["에탄올","에틸알콜","C2H5OH","에틸 알코올","에틸 알콜","ethanol"],"l":"가"},{"a":"에틸알코올","syn":["에탄올","에틸알콜","C2H5OH","에틸 알코올","에틸 알콜","ethanol"],"l":"나"},{"a":"메틸알코올","syn":["메탄올","메틸알콜","CH3OH","메틸 알코올","메틸 알콜","methanol"],"l":"다"},{"a":"에틸알코올","syn":["에탄올","에틸알콜","C2H5OH","에틸 알코올","에틸 알콜","ethanol"],"l":"라"},{"a":"메틸알코올","syn":["메탄올","메틸알콜","CH3OH","메틸 알코올","메틸 알콜","methanol"],"l":"마"}],"순서무관":false},{"id":"2025-3-13","y":2025,"r":3,"n":13,"p":"시설·법령","kw":"안전관리·행정","pt":5,"q":"위험물안전관리법령에 따른 자체소방대에 관한 내용이다. 다음 물음에 알맞은 답을 쓰시오.\n가. 자체소방대를 두어야 하는 경우를 [보기]에서 모두 쓰시오.\n[보기]\n① 염소산염류 250톤 제조소\n② 염소산염류 250톤 일반취급소\n③ 특수인화물 250kL 제조소\n④ 특수인화물 250kL 충전하는 일반취급소\n나. 자체소방대에 두는 화학소방자동차 1대당 필요한 소방대원 인원수는 몇 명인지 쓰시오.\n다. 다음 중 틀린 것을 고르시오 (단, 없으면 없음이라고 표기하시오).\n[보기]\n① 다른 사업소 등과 상호협정을 체결한 경우 그 모든 사업소를 하나의 사업소로 본다.\n② 포수용액 방사차에는 소화약액탱크 및 소화약액혼합장치를 비치할 것\n③ 포수용액 방사차는 자체 소방차 대수의 2/3 이상이어야 하고 포수용액의 방사능력은 3,000L 이상일 것\n④ 10만L 이상의 포수용액을 방사할 수 있는 양의 소화약제를 비치할 것\n라. 자체소방대를 설치하지 않은 제조소등의 관계인의 벌칙을 쓰시오.","a":"가. ③\n나. 5명\n다. ③\n라. 1년 이하의 징역 또는 1천만원 이하의 벌금","h":"자체소방대는 제4류 위험물을 지정수량 3천배 이상 취급하는 제조소·일반취급소에 둔다. 특수인화물 250kL는 5,000배인데, 이동탱크에 주입하는 일반취급소는 설치 제외 대상이고 염소산염류는 제1류라 해당하지 않아 ③ 만 대상이다. 화학소방자동차 1대마다 5명을 두고, 포수용액 방사차의 방사능력은 매분 2,000L 이상이라 ③ 이 틀리며, 자체소방대를 두지 않은 관계인은 1년 이하의 징역 또는 1천만원 이하의 벌금을 받는다.","t":"kan","칸":[{"a":"③","syn":["3","3번","(3)"],"l":"가"},{"a":"5","syn":["5명","5인","5명 이상"],"l":"나"},{"a":"③","syn":["3","3번","(3)"],"l":"다"},{"a":"1년 이하의 징역 또는 1천만원 이하의 벌금","k":[["1년"],["1천만","1000만","1,000만","천만"]],"l":"라"}],"순서무관":false},{"id":"2025-3-14","y":2025,"r":3,"n":14,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"제1류 위험물 중에서 분해 폭발 시 화학반응식이다. 빈칸에 들어갈 위험물에 대하여 물음에 답하시오.\n2(        ) → 2N2 + O2 + 4H2O\n가. (    ) 물질의 명칭을 쓰시오.\n나. (    ) 물질의 화학식을 쓰시오.\n다. 흡열반응인지 발열반응인지 구별하여 쓰시오.\n라. 위험물 제조소에 저장할 경우 주의사항 게시판에 기재하여야 할 주의사항을 모두 쓰시오 (단, 없으면 해당없음으로 기재하시오).","a":"가. 질산암모늄\n나. NH4NO3\n다. 발열반응\n라. 해당없음","h":"2NH4NO3 → 2N2 + O2 + 4H2O 로 분해·폭발하는 제1류 물질은 질산암모늄이다. 분해·폭발은 열을 내는 발열반응이고, 물에 녹을 때 열을 빼앗는 흡열과 헷갈리기 쉽다(일부 복원 답안은 흡열로 적었다). 알칼리금속의 과산화물이 아닌 제1류라 주의사항 게시판은 없다.","t":"kan","칸":[{"a":"질산암모늄","syn":["NH4NO3","질산 암모늄","초안","질안"],"l":"가"},{"a":"NH4NO3","syn":["질산암모늄","nh4no3"],"l":"나"},{"a":"발열반응","syn":["발열","발열 반응","발열 반응이다","발열반응이다"],"l":"다"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"}],"순서무관":false},{"id":"2025-3-15","y":2025,"r":3,"n":15,"p":"계산","kw":"증기비중·위험도·기타 계산","pt":5,"q":"용적 100m3인 제조소등에 설치하는 국소방식의 배출설비의 1시간당 배출능력을 구하시오.\n[계산과정]\n[답]","a":"① 국소방식 배출능력 = 배출장소 용적 × 20배/h\n② 100m3 × 20 = 2,000m3\n답: 2,000m3/h","h":"국소방식 배출설비는 1시간당 배출장소 용적의 20배 이상을 배출해야 한다. 용적이 100m3이면 100 × 20 = 2,000m3이다. 전역방식이면 바닥면적 1m2당 18m3 기준을 쓰므로 방식부터 확인한다.","t":"word","syn":["2,000","2000m3","2,000m3","2000㎥","2,000㎥","2000m3/h","2,000m3/h","2000m3/hr","2,000m3/hr"],"ka":"2000"},{"id":"2025-3-16","y":2025,"r":3,"n":16,"p":"시설·법령","kw":"소화·경보설비","pt":5,"q":"적응성이 있는 소화설비를 모두 쓰시오 (단, 없으면 해당 없음을 쓰시오).\n[보기] 옥내소화전설비, 옥외소화전설비, 불활성가스소화설비, 스프링클러소화설비\n가. 탄화칼슘\n나. 과산화나트륨\n다. 인화성고체\n라. 철분\n마. 과산화수소","a":"가. 해당없음\n나. 해당없음\n다. 옥내소화전설비, 옥외소화전설비, 불활성가스소화설비, 스프링클러소화설비\n라. 해당없음\n마. 옥내소화전설비, 옥외소화전설비, 스프링클러소화설비","h":"탄화칼슘(금수성물질), 과산화나트륨(알칼리금속과산화물), 철분은 보기의 네 설비 중 어느 것도 적응성이 없다. 인화성고체는 네 설비 모두 쓸 수 있다. 제6류인 과산화수소는 물을 쓰는 옥내·옥외소화전과 스프링클러는 되고 불활성가스는 안 된다.","t":"kan","칸":[{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"가"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"나"},{"a":"옥내소화전설비, 옥외소화전설비, 불활성가스소화설비, 스프링클러소화설비","k":[["옥내"],["옥외"],["불활성"],["스프링클러"]],"l":"다"},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"},{"a":"옥내소화전설비, 옥외소화전설비, 스프링클러소화설비","k":[["옥내"],["옥외"],["스프링클러"]],"l":"마","no":["불활성"]}],"순서무관":false},{"id":"2025-3-17","y":2025,"r":3,"n":17,"p":"물질·성상","kw":"물질 맞히기","pt":5,"q":"분자량이 34이며 표백작용과 살균작용이 있다. 농도 기준 따라 위험물이 되는 위험물로 운반용기 외부에 표시하여야 하는 주의사항은 가연물접촉주의인 이 위험물에 대하여 다음 물음에 답하시오.\n가. 명칭\n나. 화학식\n다. 열분해 시 생성되는 물질\n라. 주의사항 게시판 (단, 해당없으면 '해당없음'을 쓰시오)","a":"가. 과산화수소\n나. H2O2\n다. H2O, O2\n라. 해당없음","h":"표백·살균 작용이 있고 농도 기준에 따라 위험물이 되며 가연물접촉주의를 표시하는 제6류는 과산화수소 H2O2 다. 열분해하면 2H2O2 → 2H2O + O2 로 물과 산소가 나온다. 제6류는 게시판이 없으므로 주의사항 게시판은 해당없음이다.","t":"kan","칸":[{"a":"과산화수소","syn":["H2O2","과산화 수소","hydrogen peroxide"],"l":"가"},{"a":"H2O2","syn":["과산화수소","h2o2"],"l":"나"},{"a":"H2O, O2","k":[["H2O","물","수증기"],["O2","산소"]],"l":"다","no":["H2O2"],"syn":["2H2O2→2H2O+O2"]},{"a":"해당없음","syn":["해당 없음","없음","없다","x","해당없다"],"l":"라"}],"순서무관":false},{"id":"2025-3-18","y":2025,"r":3,"n":18,"p":"계산","kw":"소요단위","pt":5,"q":"위험물안전관리법령에서 정한 소화설비의 소요단위에 관한 내용이다. 다음 내용을 보고 물음에 답하시오.\n• 내화구조인 옥내저장소\n• 연면적 150m2\n• 에탄올 1,000L, 등유 1,500L, 동식물유류 20,000L, 특수인화물 500L\n가. 옥내저장소의 연면적 기준 소요단위\n나. 위험물 기준의 소요단위","a":"가. 150m2 / 150m2 = 1소요단위\n나. 에탄올 1,000/(400×10) = 0.25\n등유 1,500/(1,000×10) = 0.15\n동식물유류 20,000/(10,000×10) = 0.2\n특수인화물 500/(50×10) = 1.0\n합계 1.6소요단위","h":"내화구조 저장소는 연면적 150m2가 1소요단위이고, 위험물은 지정수량의 10배가 1소요단위다. 품목마다 저장량을 (지정수량 × 10)으로 나눠 더하면 1.6이고, 법령에 올림 규정이 없으니 1.6이 답이다.","tp":"W06","t":"kan","칸":[{"a":"1","e":0.01,"l":"가"},{"a":"1.6","e":0.05,"l":"나"}],"순서무관":false},{"id":"2025-3-19","y":2025,"r":3,"n":19,"p":"물질·성상","kw":"유별·지정수량·등급","pt":5,"q":"제1류 위험물 중 염소산칼륨에 대하여 다음 물음에 답하시오.\n가. 화학식\n나. 지정수량\n다. 분해 시 발생하는 기체의 명칭\n라. 분해반응식","a":"가. KClO3\n나. 50kg\n다. 산소\n라. 2KClO3 → 2KCl + 3O2","h":"염소산칼륨 KClO3 는 제1류 염소산염류이고 지정수량은 50kg이다. 분해하면 염화칼륨과 산소가 나오며 식은 2KClO3 → 2KCl + 3O2 다.","t":"kan","칸":[{"a":"KClO3","syn":["염소산칼륨","kclo3","염소산 칼륨"],"l":"가"},{"a":"50kg","syn":["50","50 kg","50킬로그램"],"l":"나"},{"a":"산소","syn":["O2","산소가스","oxygen"],"l":"다"},{"a":"2KClO3→2KCl+3O2","syn":["2KClO3->2KCl+3O2","2KClO3=2KCl+3O2","KClO3→KCl+3/2O2","KClO3->KCl+3/2O2"],"l":"라"}],"순서무관":false},{"id":"2025-3-20","y":2025,"r":3,"n":20,"p":"물질·성상","kw":"성질·저장·소화","pt":5,"q":"제3류 위험물 중 황린에 대한 설명으로 옳은 것을 고르시오.\n① 무색무취의 고체이다.\n② 물과 아세톤에 녹는다.\n③ 공기 차단 후 260℃ 가열하면 적린을 얻을 수 있다.\n④ 증기비중이 1보다 작다.\n⑤ 연소 시 유독성의 포스핀가스를 발생한다.","a":"③","h":"황린에 대해 옳은 것은 ③ 하나다. 황린은 백색 또는 담황색 고체이고 물에 녹지 않으며 증기비중은 124÷29 ≈ 4.28로 1보다 크다. 연소하면 포스핀이 아니라 오산화인이 나오고, 공기를 막고 약 260℃로 가열하면 적린이 된다.","t":"word","syn":["3","3번","(3)"],"ka":"③"}],"모의":[{"세트":1,"제목":"실전 모의 1","n":20},{"세트":2,"제목":"실전 모의 2","n":20},{"세트":3,"제목":"실전 모의 3","n":20},{"세트":4,"제목":"실전 모의 4","n":20},{"세트":5,"제목":"실전 모의 5","n":20}],"연습":[{"이름":"반응식 쓰기","설명":"반응물을 보고 생성물과 계수를 직접 써 본다","href":"banung.html"},{"이름":"지정수량 배수·소요단위","설명":"물질을 골라 넣으면 배수·소요단위를 단계별로 계산","href":"wcalc.html"}],"화학식":true};
